window.POEM_DB=window.POEM_DB||{};POEM_DB["song_017"]={"n":"李纲","dyn":"宋","poems":[{"t":"三姑石","f":"七言绝句","c":["风舞芳林鬓脚垂，朝云行雨湿仙衣。","不知当日缘何事，化石山头更不归。"]},{"t":"大隐屏","f":"七言绝句","c":["高峰崛起翠微屏，何事呼为大隐名。","自是市朝人不到，非关洞户锁峥嵘。"]},{"t":"天柱峰","f":"七言律诗","c":["巉巉千丈插烟空，始见天南一柱峰。","绝顶雾开擎日月，半岩云暝噫雷风。","俯临万壑林芿秀，高压群山气象雄。","谁道共工曾触折，断鳌端是女娲功。"]},{"t":"病牛","f":"七言绝句","c":["耕犁千亩实千箱，力尽筋疲谁复伤。","但愿众生皆得饱，不辞羸病卧残阳。"]},{"t":"望庐山","f":"七言古诗","c":["多年不省庐山面，江上初从望中见。","秀骨苍颜五老人，顾我欣然如素善。","香炉峰顶紫烟浮，瀑布遥看银汉流。","云舒霞卷互明灭，倏忽变态无停留。","却疑清梦寻丘壑，风物何为宛如昨。","纵令真是梦中看，梦未觉时良不恶。","平生所愿今乃偿，宽著日月游山房。","青鞋布袜久已办，百钱挂杖聊徜徉。"]},{"t":"一剪梅","f":"词","c":["数点梅花玉雪娇。","烟水篱边，半袅青梢。","横斜疏影月黄昏，谁使天香，暗淡飘飘。","半醉佳人酒未消。","宝髻偏时，插更斜袅。","尊前还唱早梅词，琼醑何如，□□□□。"]},{"t":"丑奴儿/采桑子 其二","f":"词","c":["枝头万点妆金蕊，十里清香。","十里清香。","解引幽人雅思长。","玉壶贮水花难老，净几明窗。","净几明窗。","褪下残英蔌蔌黄。"]},{"t":"丑奴儿/采桑子 其一 木犀","f":"词","c":["幽芳不为春光发，直待秋风。","直待秋风。","香比馀花分外浓。","步摇金翠人如玉，吹动珑璁。","吹动珑璁。","恰似瑶台月下逢。"]},{"t":"六么令 次韵和贺方回金陵怀古，鄱阳席上作","f":"词","c":["长江千里，烟淡水云阔。","歌沉玉树，古寺空有疏钟发。","六代兴亡如梦，苒苒惊时月。","兵戈凌灭。","豪华销尽，几见银蟾自圆缺。","潮落潮生波渺，江树森如发。","谁念迁客归来，老大伤名节。","纵使岁寒途远，此志应难夺。","高楼谁设。","倚阑凝望，独立渔翁满江雪。"]},{"t":"水龙吟 太宗临渭上","f":"词","c":["古来夷狄难驯，射飞择肉天骄子。","唐家建国，北边雄盛，无如颉利。","万马崩腾，皂旗毡帐，远临清渭。","向郊原驰突，凭陵仓卒，知战守、难为计。","须信君王神武。","觇虏营、只从七骑。","长弓大箭，据鞍诘问，单于非义。","戈甲鲜明，旌麾光彩，六军随至。","怅敌情震骇，鱼循鼠伏，请坚盟誓。"]},{"t":"水龙吟 次韵和质夫、子瞻杨花词","f":"词","c":["晚春天气融和，乍惊密雪烟空坠。","因风飘荡，千门万户，牵情惹思。","青眼初开，翠眉才展，小园长闭。","又谁知化作，琼花玉屑，共榆荚、漫天起。","深院美人慵困，乱云鬟、尽从妆缀。","小廊回处，氍毹重叠，轻拈却碎。","飞入楼台，舞穿帘幕，总归流水。","怅青春又过，年年此恨，满东风泪。"]},{"t":"水龙吟 上巳日出郊，呈知宗安抚、张参、观文汪相二首 其二","f":"词","c":["莫春清淑之初，赏心最乐惟修禊。","兰亭序饮，泛觞流咏，萧然适意。","旧弼宗英，文章贤牧，肯临坰外。","向碧山深处，寻花问柳，有佳气、随旌旆。","寥落幽人寓止。","借僧园、缭云萦水。","栽花种竹，凿池开径，渊明岂愧。","美景良辰，玉颜方老，欲留何计。","对残红嫩绿，开怀笑语，且须同醉。"]},{"t":"水龙吟 其二 光武战昆阳","f":"词","c":["汉家炎运中微，坐令闰位馀分据。","南阳自有，真人膺历，龙翔虎步。","初起昆城，旋驱乌合，块然当路。","想莽军百万，旌旗千里，应道是、探囊取。","豁达刘郎大度。","对勍敌、安恬无惧。","提兵夹击，声喧天壤，雷风借助。","虎豹哀嗥，戈鋋委地，一时休去。","早复收旧物，扫清氛祲，作中兴主。"]},{"t":"水龙吟 其一","f":"词","c":["笑不知天命，明珠玉斗，漫撞令碎。"]},{"t":"水龙吟 其一 次韵任世初送林商叟海道还闽中","f":"词","c":["际天云海无涯，径从一叶舟中渡。","天容海色，浪平风稳，何尝有飓。","鳞甲千山，笙镛群籁，了无遮护。","笑读君佳阕，追寻往事，须信道、忘来去。","闻说钓鲸公子，为才名、鹗书交举。","高怀澹泊，柏台兰省，留连莫住。","万里闽山，不从海道，寄声何处。","怅七年契阔，无因握手，与开怀语。"]},{"t":"水调歌头 上巳日出郊，呈知宗安抚、张参、观文汪相二首","f":"词","c":["花径不曾扫，蓬户为君开。","元戎小队，清晓佳客与同来。","我为衰迟多病，且恁浇花艺药，随分葺池台。","多谢故人意，迂访白云隈。","暮春月，修禊事，会兰斋。","一觞一咏，何愧当日畅幽怀。","况是茂林修竹，映带清流湍激，山色碧崔嵬。","勿复叹陈迹，且为醉金杯。"]},{"t":"水调歌头 其二 与李致远、似之、张柔直会饮","f":"词","c":["如意始身退，此事古难谐。","中年醉饮，多病闲去正当才。","长爱兰亭公子，弋钓溪山娱适，甘旨及朋侪。","衰疾卧江海，鸥鸟莫惊猜。","酒初熟，招我友，共一杯。","碧天云卷，高挂明月照人怀。","我醉欲眠君去，醉醒君如有意，依旧抱琴来。","尚有一壶酒，当复为君开。"]},{"t":"水调歌头 其三 似之、申伯、叔阳皆作，再次前韵","f":"词","c":["物我本虚幻，世事若俳谐。","功名富贵，当得须是个般才。","幸有山林云水，造物端如有意，分付与吾侪。","寄语旧猿鹤，不用苦相猜。","醉中适，一杯尽，复一杯。","坐间有客，超诣言笑可忘怀。","况是清风明月，如会幽人高意，千里自飞来。","共笑陶彭泽，空对菊花开。"]},{"t":"水调歌头 和李似之横山对月","f":"词","c":["秋杪暑方退，清若玉壶冰。","高楼对月，天上宫殿不曾扃。","散下凄然风露，影照江山如昼，浑觉俗缘轻。","弋者欲何慕，鸿羽正冥冥。","世间法，唯此事，最堪凭。","太虚心量，聊假梨枣制颓龄。","但使心安身健，静看草根泉际，吟蚓与飞萤。","一坐小千劫，无念契无生。"]},{"t":"水调歌头 李太白画象","f":"词","c":["太白乃吾祖，逸气薄青云。","开元有道，聊复乘兴一来宾。","天子呼来方醉，洒面清泉微醒，馀吐拭龙巾。","词翰不加点，歌阕满宫春。","笔风雨，心锦绣，极清新。","大儿中令，神契兼有坐忘人。","不识将军高贵，醉里指污吾足，乃敢尚衣嗔。","千载已仙去，图象耸风神。"]},{"t":"水调歌头 其一 同德久诸季小饮，出示所作，即席答之","f":"词","c":["律吕自相召，韶頀不难谐。","致君泽物，古来何世不须才。","幸可山林高卧，袖手何妨闲处，醇酒醉朋侪。","千里故人驾，不怕物情猜。","秋夜永，更秉烛，且衔杯。","五年离索，谁谓谈笑豁幽怀。","况我早衰多病，屏迹云山深处，俗客不曾来。","此日扫花径，蓬户为君开。"]},{"t":"永遇乐 秋夜有感","f":"词","c":["秋色方浓，好天凉夜，风雨初霁。","缺月如钩，微云半掩，的烁星河碎。","爽来轩户，凉生枕簟，夜永悄然无寐。","起徘徊，凭栏凝伫，片时万情千意。","江湖倦客，年来衰病，坐叹岁华空逝。","往事成尘，新愁似锁，谁是知心底。","五陵萧瑟，中原杳杳，但有满襟清泪。","烛兰缸，呼童取酒，且图径醉。"]},{"t":"玉蝴蝶","f":"词","c":["万古秣陵江国，舣舟烟岸，千里云林。","故垒高楼，凝望远水遥岑。","景阳钟、那闻旧响，玉树唱、空有馀音。","感春心。","六朝遗事，萧索难寻。","甘泉法从弟兄芝玉，顾我情深。","契阔相思，岂知今日共登临。","对尊俎、休辞痛饮，伤志节、须且高吟。","柳摇金。","断霞轻霭，残照西沈。"]},{"t":"江城子 其一 新酒初熟","f":"词","c":["老饕嗜酒若鸱夷。","拣珠玑。","自蒸炊。","篘尽云腴，浮蚁在瑶卮。","有客相过同一醉，无客至，独中之。","曲生风味有谁知。","豁心脾。","展愁眉。","玉颊红潮，还似少年时。","醉倒不知天地大，浑忘却，是和非。"]},{"t":"江城子 瀑布","f":"词","c":["琉璃滑处玉花飞。","溅珠玑。","喷霏微。","谁遣银河，一派九天垂。","昨夜白虹来涧饮，留不去，许多时。","幽人独坐石嵚崎。","赏清奇。","濯涟漪。","不怕深沈，潭底有蛟螭。","澒洞但闻金石奏，猿鸟乐，共忘归。"]},{"t":"江城子 其二 九日与诸季登高","f":"词","c":["客中重九共登高。","逼烟霄。","见秋毫。","云涌群山，山外海翻涛。","回首中原何处是，天似幕，碧周遭。","茱萸蕊绽菊方苞。","左倾醪。","右持螯。","莫把闲愁，空使寸心劳。","会取八荒皆我室，随节物，且游遨。"]},{"t":"江城子 其二 池阳泛舟作","f":"词","c":["春来江上打头风。","吼层空。","卷飞蓬。","多少云涛，雪浪暮江中。","早是客情多感慨，烟漠漠，雨濛濛。","梁溪只在太湖东。","长儿童。","学庞翁。","谁信家书，三月不曾通。","见说浙河金鼓震，何日到，羡归鸿。"]},{"t":"江城子 其一 再游武夷，至晞真馆，与道士泛月而归","f":"词","c":["武夷山里一溪横。","晚风清。","断霞明。","行至晞真、馆下月华生。","仙迹灵踪知几许，云缥缈，石峥嵘。","羽人同载小舟轻。","玉壶倾。","荐芳馨。","酣饮高歌，时作步虚声。","一梦游仙非偶尔，回棹远，翠烟凝。"]},{"t":"江城子","f":"词","c":["去年九日在衡阳。","满林霜。","俯潇湘。","回雁峰头，依约雁南翔。","遥想茱萸方遍插，唯少我，一枝香。","今年佳节幸相将。","陟层冈。","举华觞。","地暖风和，犹未菊开黄。","此会明年知健否，判酩酊，醉秋光。"]},{"t":"江城子 其三","f":"词","c":["晓来江口转南风。","静烟空。","整云蓬。","满眼高帆，隐映画图中。","呕轧数声离岸橹，云暗淡，雪溟濛。","扁舟归去五湖东。","狎樵童。","侣渔翁。","不管人间，荣辱与穷通。","试作五噫歌汉室，从隐遁，作梁鸿。"]},{"t":"西江月 赠友人家侍儿名莺莺者","f":"词","c":["意态何如涎涎，轻盈只恐飞飞。","华堂偏傍主人栖。","好与安巢稳戏。","揽断楼中风月，且看掌上腰支。","谪仙词赋少陵诗。","万语千言总记。"]},{"t":"苏武令","f":"词","c":["塞上风高，渔阳秋早。","惆怅翠华音杳。","驿使空驰，征鸿归尽，不寄双龙消耗。","念白衣、金殿除恩，归黄阁、未成图报。","谁信我、致主丹衷，伤时多故，未作救民方召。","调鼎为霖，登坛作将，燕然即须平扫。","拥精兵十万，横行沙漠，奉迎天表。"]},{"t":"念奴娇 宪宗平淮西","f":"词","c":["晚唐姑息，有多少方镇，飞扬跋扈。","淮蔡雄藩联四郡，千里公然旅拒。","同恶相资，潜伤宰辅，谁敢分明语。","媕婀群议，共云旄节应付。","于穆天子英明，不疑不贰处，登庸裴度。","往督全师威令使，擒贼功名归诉。","半夜衔枚，满城深雪，忽已亡悬瓠。","明堂坐治，中兴高映千古。"]},{"t":"念奴娇 中秋独坐","f":"词","c":["暮云四卷，淡星河、天影茫茫垂碧。","皓月浮空，人尽道，端的清圆如璧。","丹桂扶疏，银蟾依约，千古佳今夕。","寒光委照，有人独坐秋色。","怅念老子平生，粗令婚嫁了，超然闲适。","误缚簪缨遭世故，空有当时胸臆。","苒苒流年，春鸿秋燕，来往终何益。","云山深处，这回真是休息。"]},{"t":"念奴娇 汉武巡朔方","f":"词","c":["茂陵仙客，算真是、天与雄才宏略。","猎取天骄驰卫霍，如使鹰鹯驱雀。","鏖战皋兰，犁庭龙碛，饮至行勋爵。","中华疆盛，坐令夷狄衰弱。","追想当日巡行，勒兵十万骑，横临边朔。","亲总貔貅谈笑看，黠虏心惊胆落。","寄语单于，两君相见，何苦逃沙漠。","英风如在，卓然千古高著。"]},{"t":"雨霖铃 明皇幸西蜀","f":"词","c":["蛾眉修绿。","正君王恩宠，曼舞丝竹。","华清赐浴瑶甃，五家会处，花盈山谷。","百里遗簪堕珥，尽宝钿珠玉。","听突骑、鼙鼓声喧，寂寞霓裳羽衣曲。","金舆还幸匆匆速。","奈六军不发人争目。","明眸皓齿难恋，肠断处、绣囊犹馥。","剑阁峥嵘，何况铃声，带雨相续。","谩留与、千古伤神，尽入生绡幅。"]},{"t":"减字木兰花","f":"词","c":["龟台金母。","绀发芳容超夐古。","绛节霓旌。","青鸟传言若可凭。","瑶池罢宴。","零落碧桃香片片。","八骏西巡。","更有何人继后尘。"]},{"t":"减字木兰花","f":"词","c":["仙姝丽绝。","被服红绡肤玉雪。","火齐堆盘。","常得杨妃带笑看。","劳生重马。","远贡长为千古话。","林下甘芳。","却准幽人餍饫尝。"]},{"t":"减字木兰花 其一 读神仙传","f":"词","c":["茫茫云海。","方丈蓬壶何处在。","拟泛轻舟。","一到金鳌背上游。","琼楼珠室。","千岁蟠桃初结实。","月冷风清。","试倩双成吸玉笙。"]},{"t":"减字木兰花 荔枝二首 其一","f":"词","c":["华清赐浴。","宝瓮温泉浇腻玉。","笑靥开时。","一骑红尘献荔枝。","明珠乍剖。","自擘轻红香满手。","锦袜罗囊。","犹瘗当年驿路旁。"]},{"t":"望江南/忆江南","f":"词","c":["新雨足，一夜满南塘。","粳稻向成初吐秀，芰荷虽败尚馀香。","爽气入轩窗。","澄霁后，远岫更青苍。","两部蛙声鸣鼓吹，一天星月浸光芒。","秋色陡凄凉。"]},{"t":"望江南/忆江南 其五","f":"词","c":["烟艇稳，浦溆正清秋。","风细波平宜进楫，月明江静好沈钩。","横笛起汀洲。","鲈鳜美，新酿蚁醅浮。","休问六朝兴废事，白蘋红蓼正凝愁。","千古一渔舟。"]},{"t":"望江南/忆江南","f":"词","c":["新月出，清影尚苍茫。","学扇欲生青海上，如钩先挂碧霄傍。","星斗焕文章。","林下客，把酒浥孤光。","斟酌嫦娥怜我老，故窥书幌照人床。","此意自难忘。"]},{"t":"望江南/忆江南 其一","f":"词","c":["新阁就，向日借清光。","广厦生风非我志，小窗容膝正相当。","聊此傲羲皇。","狨尾拂，高挂木绳床。","老病维摩谁问疾，散花天女为焚香。","恰好细商量。"]},{"t":"望江南/忆江南 其六","f":"词","c":["江上雪，独立钓渔翁。","箬笠但闻冰散响，蓑衣时振玉花空。","图画若为工。","云水暮，归去远烟中。","茅舍竹篱依小屿，缩鳊圆鲫入轻笼。","欢笑有儿童。"]},{"t":"望江南/忆江南","f":"词","c":["新酒熟，云液满香篘。","溜溜清声归小瓮，温温玉色照瓷瓯。","饮兴浩难收。","嘉客至，一酌散千忧。","顾我老方齐物论，与君同作醉乡游。","万事总休休。"]},{"t":"望江南 其一 过分水岭","f":"词","c":["征骑远，千里别沙阳。","泛碧斋傍凝翠阁，栖云寺里印心堂。","回首意茫茫。","分水岭，烟雨正凄凉。","南望瓯闽连海峤，北归吴越过江乡。","极目暮云长。"]},{"t":"望江南/忆江南","f":"词","c":["云岭水，南北自分流。","触目澜翻飞雪浪，赴溪盘屈转琼钩。","呜咽不胜愁。","归去客，征骑远闽州。","路入江南春信未，日行北陆冷光浮。","还揽旧貂裘。"]},{"t":"望江南/忆江南","f":"词","c":["清昼永，幽致夏来多。","远岸参差风扬柳，平湖清浅露翻荷。","移棹钓烟波。","凉一霎，飞雨洒轻蓑。","满眼生涯千顷浪，放怀乐事一声歌。","不醉欲如何。"]},{"t":"望江南 池阳道中","f":"词","c":["归去客，迂骑过江乡。","茅店鸡声寒逗月，板桥人迹晓凝霜。","一望楚天长。","春信早，山路野梅香。","映水酒帘斜扬日，隔林渔艇静鸣榔。","杳杳下残阳。"]},{"t":"望江南/忆江南","f":"词","c":["云棹远，南浦绿波春。","日暖风和初解冻，饵香竿袅好垂纶。","一钓得金鳞。","风乍起，吹皱碧渊沦。","红脍斫来龙更美，白醪酤得旨兼醇。","一醉武陵人。"]},{"t":"渔家傲 九月将尽，菊花始有开者","f":"词","c":["木落霜清秋色霁。","菊苞渐吐金英碎。","佳节不随东去水。","谁得会。","黄花开日重阳至。","三径旧栽烟水外。","故园凝望空流泪。","香色向人如有意。","挼落蕊。","金尊满满从教醉。"]},{"t":"喜迁莺 其二 塞上词","f":"词","c":["边城寒早。","对漠漠暮秋，霜风烟草。","战□长闲，刁斗无声，空使荷戈人老。","陇头立马极目，万里长城古道。","感怀处，问仲宣云乐，从军多少。","缥缈。","云岭外，夕烽一点，塞上传光小。","玉帐尊罍，青油谈笑，肯把壮怀销了。","画楼数声残角，吹彻梅花霜晓。","愿岁岁静烟尘，羌虏常修邻好。"]},{"t":"喜迁莺 真宗幸澶渊","f":"词","c":["边城寒早。","恣骄虏、远牧甘泉丰草。","铁马嘶风，毡裘凌雪，坐使一方云扰。","庙堂折冲无策，欲幸坤维江表。","叱群议，赖寇公力挽，亲行天讨。","缥缈。","銮辂动，霓旌龙旆，遥指澶渊道。","日照金戈，云随黄伞，径渡大河清晓。","六军万姓呼舞，箭发敌酋难保。","虏情慑，誓书来，从此年年修好。"]},{"t":"喜迁莺 其一 自池阳泛舟","f":"词","c":["江天霜晓。","对万顷雪浪，云涛弥渺。","远岫参差，烟树微茫，阅尽往来人老。","浅沙别浦极望，满目馀霞残照。","暮云敛，放一轮明月，窥人怀抱。","杳杳。","千里恨，玉人一别，梦断无音耗。","手捻江梅，枝头春信，欲寄算应难到。","画船片帆浮碧，更值风高波浩。","几时得向尊前，销却许多烦恼。"]},{"t":"喜迁莺 晋师胜淝上","f":"词","c":["长江千里，限南北，雪浪云涛无际。","天险难逾，人谋克壮，索虏岂能吞噬！","阿坚百万南牧，倏忽长驱吾地。","破强敌，在谢公处画，从容颐指。","奇伟！","淝水上，八千戈甲，结阵当蛇豕。","鞭弭周旋，旌旗麾动，坐却北军风靡。","夜闻数声鸣鹤，尽道王师将至。","延晋祚，庇烝民，周雅何曾专美。"]},{"t":"感皇恩 枕上","f":"词","c":["西阁夜初寒，炉烟轻袅。","竹枕绸衾素屏小。","片时清梦，又被木鱼惊觉。","半窗残月影，天将晓。","幻境去来，胶胶扰扰。","追想平生发孤笑。","壮怀消散，尽付败荷衰草。","个中还得趣，从他老。"]},{"t":"感皇恩","f":"词","c":["九日菊花迟，茱萸却早。","嫩蕊浓香自妍好。","一簪华发，只恐西风吹帽。","细看还遍插，人忘老。","千古此时，清欢多少。","铁马台空但荒草。","旅愁如海，须把金尊销了。","暮天秋影碧，云如扫。"]},{"t":"诸刹以水激硙磨殊可观为赋此诗","f":"五言古诗","c":["叠石壅寒派，湍流泻回溪。","谁将方便智，成此妙圆机。","轮辐互高下，波涛郁翻飞。","磨牙递旋斡，硙杵纷昂低。","玉粒已粲粲，琼花亦霏霏。","虽存机械巧，利泽成博施。","试语汉阴老，使知浑沌非。","惟当善用心，功与天地齐。"]},{"t":"十二咏 其七 桂亭","f":"七言绝句","c":["团团双桂拂茅斋，虚幌疏棂尽日开。","会待秋高风露下，清香飘泛月中来。"]},{"t":"送士特兄下第之衡湘","f":"七言古诗","c":["都城三月春暮时，通津两岸杨花飞。","送君结束适南楚，使我叹息生长悲。","男儿功名致须早，夫子声誉久已驰。","文章黼黻虽自许，时运龃龉将安施。","霜蹄暂蹶未为失，云翮高举终非迟。","人生且求适意处，天命会有不否期。","潇湘千里渺烟浪，浮家早逐秋鸿归。","娥英事实素难考，来时为读黄陵碑。"]},{"t":"子房","f":"七言绝句","c":["汉楚存亡谈笑中，子房初不有其功。","闭门辟谷思轻举，肯叹淮阴犬与弓。"]},{"t":"读楚元王传","f":"七言绝句","c":["设醴当年为穆生，偶忘微礼便辞荣。","固知申白无先见，衣赭髡钳始自惊。"]},{"t":"谒告迎奉闻亲闱有醴泉之除不胜庆抃作诗寄叔易季言二弟","f":"五言古诗","c":["薄宦便甘旨，两载官南徐。","江山富佳致，足以为亲娱。","昆弟尽在傍，承颜欢有馀。","宁知驿书召，结束趋征途。","旅食寓京华，梦想怀庭除。","宸恩赐清燕，天语闻都俞。","兰省幸备员，匪才惭冒居。","思亲动归兴，谒告之东吴。","晓出通津门，轻舠泛汴渠。","莺花已烂熳，榆柳正扶疏。","去去指苕霅，行行远神都。","中途闻吉语，动色观除书。","天子隆孝治，朝廷优老儒。","犬马志欲养，获此伸区区。","丘山恩施重，蝼蚁轻捐躯。","寓书东飞鸿，早早达吾庐。","季也在亲侧，援琴方舞雩。","聆音想慰怿，具驾无踟蹰。","会言亦近止，期以薰风初。"]},{"t":"奉酬胡俊明博士见寄","f":"七言律诗","c":["载笔螭坳侍九天，谪来山泽作臞仙。","鸣冈敢并喈喈凤，感气聊同嘒嘒蝉。","引义每惭爰叔直，著鞭常恐祖生先。","庭闱一去三千里，自叹飘零曷日还。"]},{"t":"用前韵留别诸弟","f":"七言律诗","c":["久陪鸳鹭日朝天，却爱江湖作散仙。","但有园林种松菊，便胜冠冕著貂蝉。","棣华春早相辉映，雁序风高自后先。","暂此睽离休怅望，为荒三径徯予还。"]},{"t":"同叔易季言游虎丘寺邂逅何得之","f":"五言古诗","c":["理棹适闽粤，虎丘聊舣航。","霜林正摇落，翠柏森成行。","入门蹑磴道，乔木间疏篁。","秦帝试剑石，破瓜分路傍。","生公雨花台，说法今不亡。","苍藓衣峭壁，枯荷响回塘。","遂游剑池上，毛发森以张。","沈沈下无底，疑有虬龙藏。","镌削露天巧，胚胎劳混茫。","清奇俨图画，秘怪叵测量。","薜荔叠秀色，枇杷吐幽香。","行行造梵宇，金碧相荧煌。","危脊耸古殿，长腰曼脩廊。","凭虚架云阁，凿险通禅房。","开轩俯吴会，蜂窠缭池隍。","风烟寄远目，心逐征鸿翔。","列岫霭遥碧，平湖湛孤光。","追寻殊未倦，策杖登崇冈。","幽独诗句苦，阖庐丘冢荒。","五圣瞻象设，羽泉酌甘芳。","西庵何闲寂，修竹自苍苍。","脱履足生茧，解衣汗如浆。","却携二三子，置酒白云堂。","念旧已悽恻，感时增慨慷。","况我方远涉，狷介怀刚肠。","一杯且相属，世事都茫茫。","冠冕志已冷，山林兴偏长。","逝将脱羁束，超然傲羲皇。","斯游信清绝，去去何时忘。"]},{"t":"吴江五首 其一","f":"七言律诗","c":["重过松江忆旧游，依然风景照行舟。","危桥跨水虹垂影，高阁凭虚蜃吐楼。","渺渺冲烟归钓艇，轻轻点浪舞沙鸥。","暮天横笛江村起，激烈能令逐客愁。"]},{"t":"吴江五首 其二","f":"七言律诗","c":["木落水寒天气清，江湖合处一桥横。","波涛万顷琉璃滑，栏槛千寻螮蝀明。","茶灶笔床随陆子，莼羹鲈鲙忆张生。","他时若我归来后，定向江头事钓耕。"]},{"t":"吴江五首 其三","f":"七言律诗","c":["返照澄波彻底明，江边弭棹若为情。","风烟漠漠无今古，舟楫纷纷尽利名。","潮落片帆归浦屿，云寒一雁过江城。","孤臣放逐三千里，此去龙津尚几程。"]},{"t":"吴江五首 其四","f":"七言律诗","c":["系缆江头日脚沈，鲈肥酒美只孤斟。","长桥千步风涛稳，横笛一声烟水深。","契阔离亲宁素愿，迂愚报国祗丹心。","远游自是男儿事，更把离骚细细寻。"]},{"t":"吴江五首 其五","f":"五言律诗","c":["鲈乡宜旷望，烟霭起层阴。","讴轧橹声急，苍茫江色深。","归潮寒入浦，宿鸟暝投林。","谁识登临意，愁来遽不禁。"]},{"t":"过吴江阻风游宁境寺","f":"五言古诗","c":["扁舟渡松江，惨淡天色恶。","胜游得禅房，旷望倚虚阁。","轩楹俯巨浸，云水互参错。","长风驾惊浪，飞雪相喷薄。","未应神龙怒，端有蛟鼍作。","片帆天际来，飘忽如陨箨。","波涛浩无涯，撑突殊不愕。","奈何操我舟，惴慄缆添索。","蜚廉也世情，逐客正落寞。","深夜始归眠，蓬窗听鸣铎。"]},{"t":"松江第四桥","f":"五言古诗","c":["松江第四桥，风雨不可过。","下有百尺蛟，蜿蜒枕桥卧。","窟宅据要津，口腹长饥饿。","每凭波涛势，能作舟楫祸。","安得佽飞手，坐使神奸破。","往来水无虞，时鼓清江柁。"]},{"t":"操舟","f":"五言古诗","c":["吴儿便操舟，衣服皆楚制。","出没波涛中，端如履平地。","江湖渺千里，鼓柁等游戏。","临深讵保身，涉险惟射利。","天风难与期，飘骤出非意。","倾覆瞬息间，永为鱼鳖饵。","愿言戒畏涂，巧手不可恃。"]},{"t":"杂兴四首 其一","f":"五言律诗","c":["邑犬惊行客，林乌啼晓霜。","山村云冉冉，泽国水茫茫。","移棹轻舟稳，钩帘野兴长。","谁知因谪宦，得到水云乡。"]},{"t":"杂兴四首 其二","f":"五言律诗","c":["肃肃岁华暮，霏霏烟霭深。","轻冰依浅渚，寒日映疏林。","故邑怀亲日，扁舟去国心。","凝眸无限景，愁绝不成吟。"]},{"t":"杂兴四首 其三","f":"五言律诗","c":["片帆随鸟翼，离恨满江乡。","风细云衣薄，日斜波影光。","牧童寒哨笛，渔艇静鸣榔。","景物正清绝，桑榆还夕阳。"]},{"t":"杂兴四首 其四","f":"五言律诗","c":["暮天来远色，行客尚贪行。","棹急浪花碎，月高云缕轻。","巢乌栖更起，渔火暗还明。","独寝不成梦，夜寒闻雁声。"]},{"t":"韩贾","f":"五言古诗","c":["退之守潮阳，戚嗟见章表。","贾生傅长沙，自广托鵩鸟。","拘达言虽殊，均为未能了。","今我谪龙津，管库素所晓。","粗令职事办，便觉溪山好。","燕坐一室间，妄念悉除扫。","岂复计穷通，端亦忘寿夭。","回观古人心，颇叹二子小。"]},{"t":"田家四首 其一","f":"五言律诗","c":["江村烟水远，茅屋两三家。","断岸垂衰柳，疏篁隐细沙。","田畴剩粳稻，网罟足鱼虾。","不识宦游味，见人还叹嗟。"]},{"t":"田家四首 其二","f":"五言律诗","c":["场圃事方毕，稻粱成已勤。","儿童自逐逐，鸡犬亦欣欣。","啼鸟霜林暮，卧牛烟草昏。","田夫乐岁稔，斗酒共醺醺。"]},{"t":"田家四首 其三","f":"五言律诗","c":["柴门临小浦，竹径绕幽庄。","雨剪葵韭滑，夜舂粳稻香。","年丰饱妻子，日夕下牛羊。","谁识田家乐，拂衣归兴长。"]},{"t":"田家四首 其四","f":"五言律诗","c":["谁谓田家苦，田家乐甚真。","鸡豚燕同社，箫鼓祭瘟神。","高廪方有岁，西畴行复春。","但令租赋足，终老得相亲。"]},{"t":"嘉禾道中遇夏侯子阳","f":"七言古诗","c":["京华契阔已再冬，扁舟野岸欣相逢。","天寒水远飞霜风，谈笑坐觉回春容。","年踰七十两颊红，真气上溯泥丸宫。","剖符南海窥祝融，欲求丹砂访葛洪。","问予执笔侍九重，胡为谪堕溪山中。","迂愚久合亲耕农，君恩未报徒忡忡。","飘零孤迹随断蓬，他日相忆看云鸿。"]},{"t":"初到临平见山二首 其一","f":"七言律诗","c":["我见青山若故人，峰峦照眼自相亲。","只应今日爱山意，便是他时傲世因。","点缀白云春缥渺，萦回绿水晚奫沦。","君恩若许归田里，定卜山间老此身。"]},{"t":"初到临平见山二首 其二","f":"七言律诗","c":["孤舟渺渺两山间，终日钩帘只看山。","落日半衔霞未散，疏林远暝乌初还。","悽凉离恨谁能寄，浩荡诗愁自莫删。","赖有青山可人意，与君相对且开颜。"]},{"t":"小雨","f":"五言律诗","c":["小雨晚初急，暝云深不收。","霏霏暗烟树，索索响篷舟。","山色增远翠，渔蓑生暮愁。","凄凉苏季子，寒觅敝貂裘。"]},{"t":"将次钱塘","f":"五言律诗","c":["岁晚飘零日，舟行杳霭间。","江乡多雾雨，风物近湖山。","独鹤徊翔久，飞云自在閒。","远游殊未已，萧飒鬓毛斑。"]},{"t":"灵隐宫","f":"七言古诗","c":["我昔曾游飞来峰，白猿昼挂峰上松。","晔然灵光如彩虹，钟磬自响金仙宫。","宦游漂泊西复东，虽欲再到无由从。","帝居钧天陋瀛蓬，螭坳载笔侍重瞳。","逆鳞聊试摩神龙，谪堕剑浦山重重。","征鞍来此寻旧踪，恍如梦落烟霞中。","朱楼宝殿飞玲珑，寒泉幽石欣相逢。","门前池馆虚含风，一洗尘虑清心胸。","明朝南去随征鸿，惆怅胜游回首空。"]},{"t":"望潮","f":"七言律诗","c":["樟亭一望浙江潮，震地凌空气象骄。","十万军声来海峤，三千银界混烟霄。","素车白马纵横骛，翔鹭飞鸥散漫飘。","好是波平风稳后，一帆千里不崇朝。"]},{"t":"自哂","f":"五言律诗","c":["自哂何为者，南游亦偶然。","未登离垢地，端有散花天。","遇境聊为戏，安心不离禅。","幽怀谁与共，深炷一炉烟。"]},{"t":"张南仲置酒心渊堂值雨","f":"七言律诗","c":["自别西湖日置怀，却因谪宦得重来。","云深不见孤山寺，风急难乘摇碧斋。","未放幽情穷水石，且将离恨泥樽罍。","胜游须遍山南北，何日晴天为一开。"]},{"t":"北望","f":"五言律诗","c":["迢迢休北望，汩汩正南迁。","出处岂无意，阨穷那问天。","销愁凭酒盏，遣兴赖诗篇。","诗酒吾家事，从今号谪仙。"]},{"t":"长至","f":"七言律诗","c":["黄钟之宫萌一阳，万汇滋发犹潜藏。","书云讵复别祥异，揆景渐可知舒长。","闭关不行著易象，客子倦游悲故乡。","周南太史长太息，禋祀无因陪祼将。"]},{"t":"渡浙江","f":"五言古诗","c":["理棹适桐江，随潮过鱼浦。","山寒雪犹积，江迥月初吐。","御气凌烟霄，乘槎渡星渚。","空濛老龙吟，髣髴翠蛟舞。","境清人自愁，夜静气尤古。","独坐不成眠，霜晴听津鼓。"]},{"t":"桐江行赠江致一少府","f":"七言古诗","c":["放浪江湖乃吾乐，羁束轩冕非所荣。","谪官去为剑浦吏，鼓柁遂作桐江行。","舣舟浙岸候潮至，百越微茫烟水外。","波横天际海倒流，喷雪惊雷声震地。","须臾风软潮已平，片帆去逐飞鸿轻。","棹讴四起日西落，暮天杳杳惟参横。","江山苍苍负残雪，江水茫茫浸寒月。","谁云逐客苦悽凉，今我斯游最奇绝。","清晨弭棹桐君庐，溪光山色世所无。","故人见我一笑粲，杀鸡为黍聊相娱。","嗟予仕宦等游戏，断梗飘蓬本无蒂。","但令景物供吟哦，出处穷通何足计。","此行幽讨殊未阑，满目叠叠皆云山。","鹭飞鱼跃石齿齿，今夜且宿严陵滩。"]},{"t":"觉度寺","f":"五言古诗","c":["夕发富春渚，朝次桐君庐。","桐君采药地，今作僧家居。","石磴上窈窕，林芿下扶疏。","山根二江合，清波见游鱼。","霜晴响钟磬，日落归樵渔。","客从何方来，弭棹聊踟蹰。","清景难久驻，怅然还问途。"]},{"t":"严陵滩下作二首 其一","f":"七言律诗","c":["世祖龙飞万国朝，故人依旧隐蓬蒿。","羊裘肯换貂冠贵，钓石终齐凤阙高。","共宿客星亲帝座，贻书直气压时豪。","东京臣子多名节，皆自先生铸此曹。"]},{"t":"严陵滩下作二首 其二","f":"七言绝句","c":["帝座高悬汉客星，樵渔今亦想英声。","钓台直下三千尺，谁谓先生只钓名。"]},{"t":"兰溪访吴圣与不遇","f":"五言律诗","c":["夕次兰溪县，溪山照眼明。","云端双塔耸，烟际一桥横。","久旅易悽感，旧游如隔生。","故人寻不值，飘泊若为情。"]},{"t":"陆行","f":"七言律诗","c":["水落石出溪难行，舍舟束装趋路程。","徒御諠呶乌雀噪，衣冠瑰伟儿童惊。","天寒野迥怯霜露，日暮途远伤蓬萍。","我生胡为浪自苦，浊酒且向灯前倾。"]},{"t":"水硙","f":"七言律诗","c":["凿木为机运不休，溪边叠石駃溪流。","但知随水能旋转，肯道舂粮不自由。","轮辐讵为君子器，机关端与小人谋。","方知抱瓮汉阴老，混沌何须是假脩。"]},{"t":"戏为吴语","f":"七言律诗","c":["莫问侬家作底愁，细思今古事悠悠。","只因读得数行字，便觉分为一世忧。","问舍求田须更以，济时泽物且能休。","梁溪幸有閒泉石，正好归来作故侯。"]},{"t":"绝句","f":"七言绝句","c":["殷侯左降惟书字，陆相南迁不著书。","今我新诗三百首，坐令二子觉区区。"]},{"t":"次退之蓝关韵","f":"七言律诗","c":["奏疏螭坳上九天，谪官剑浦路三千。","披陈肝胆成微志，跋涉山川赖壮年。","缅邈寄书黄犬后，凄凉陟岵白云前。","君恩欲报知无所，清梦时时到日边。"]},{"t":"三衢道中","f":"五言古诗","c":["行色虚无里，人声烟霭间。","浪纹来縠水，地势逼柯山。","浅濑通舟涩，飞桥跨石弯。","风高云冉冉，滩急水潺潺。","野迥松篁秀，境幽鸡犬閒。","轻装因路险，隐耳觉言蛮。","村酿酤来薄，溪鳞买得悭。","浦晴鸣雁浴，林暝舞鸦还。","寺僻殿阁古，堂虚苔藓斑。","僧房清夜宿，幽梦到乡关。"]},{"t":"杂兴三首 其一","f":"七言律诗","c":["日出霜晴鸟雀呼，束装还复戒征途。","黄牛傍岸将孤犊，花鸭浮溪引众雏。","桥断水寒寻野艇，路迷山曲问田夫。","远游看尽溪山景，待向龙津书作图。"]},{"t":"杂兴三首 其二","f":"七言律诗","c":["岁晚南迁殊未央，晓寒霜霰湿征裳。","烟笼山彩远增翠，风皱溪澜细漾光。","岭雪未销宫頞粉，野梅初发御炉香。","谁怜飘泊螭坳史，曾向钧天侍紫皇。"]},{"t":"杂兴三首 其三","f":"七言律诗","c":["尽日篮舆山水中，每逢佳处慰飘蓬。","拂云古木阴阴日，夹岸脩篁细细风。","远岫长溪千里碧，断霞残照半天红。","殊方景物随时好，却恨登临无与同。"]},{"t":"戏成绝句三首 其一","f":"五言绝句","c":["山色黛眉远，溪声玉佩珊。","溪山怜逐客，故为结清欢。"]},{"t":"戏成绝句三首 其二","f":"五言绝句","c":["粼粼溪底石，五色粲坚圆。","安得女娲手，鍊之将补天。"]},{"t":"戏成绝句三首 其三","f":"五言绝句","c":["小艇渡行旅，往来终日操。","但令人利涉，宁复计劬劳。"]},{"t":"偶题","f":"七言绝句","c":["日照溪光碧起鳞，溪头雁鹜自成群。","可怜独鹤归何处，万里相随一片云。"]},{"t":"玉山道中五首 其一","f":"七言律诗","c":["悠悠征骑渡溪岩，跋涉艰难分所甘。","泉石几时归水北，风烟今夕过江南。","日轮杳杳衔青嶂，天影茫茫浸碧潭。","猿鸟不知迁客恨，云间啼叫满松楠。"]},{"t":"玉山道中五首 其二","f":"五言律诗","c":["石路凝霜白，山村落月纤。","溪头一桥小，烟外数峰尖。","高亩层成级，寒沙软胜盐。","江南风景好，无那旅愁添。"]},{"t":"玉山道中五首 其三","f":"五言律诗","c":["乍入江南境，登临慰所怀。","山林自平远，水石巧萦回。","风暖鸟声媚，日斜云影开。","故人千里别，欲寄一枝梅。"]},{"t":"玉山道中五首 其四","f":"五言律诗","c":["石藓红依日，岩松翠耐霜。","入溪看岫色，和月认梅香。","岁暮旅情恶，夜寒灯影光。","劳生真一梦，回首意茫茫。"]},{"t":"玉山道中五首 其五","f":"五言律诗","c":["行李远瀫水，禅扉依玉山。","烟岚数峰秀，云水一溪弯。","小市晚犹合，疏钟寒自还。","旧游如昨日，屈指十年间。"]},{"t":"望龟峰","f":"五言律诗","c":["何日清江使，来为碧落趺。","凝眸望霄汉，曳尾谢泥涂。","霜晓疑曝甲，云横如负图。","前知傥可仗，吾欲问玄夫。"]},{"t":"述怀","f":"五言古诗","c":["早游文翰圃，误齿缙绅涂。","兰省为郎久，霜台奋舌孤。","荷知诚特达，励志敢踌躇。","屡赐枫宸对，亲蒙御笔除。","月卿论钜礼，柱史进寒儒。","黼座当阳日，螭坳载笔初。","明堂颁政事，路寝集簪裾。","绣案横雕槛，天香夹御炉。","翠华来宝辇，清跸警嵩呼。","法驾临真馆，芳尘从属车。","重瞳瞻日月，粹色仰琼瑜。","侍立亲龙衮，书言粲帝谟。","视朝崇政罢，劝讲迩英馀。","丽日明金殿，轻风响佩琚。","漏声寒淅沥，槐影绿扶疏。","紫橐陪时彦，黄扉寓直庐。","仙游疑阆苑，清梦岂华胥。","遇事肯怀禄，衔恩宁惜躯。","惟惭涉道浅，岂恨与时迂。","犬马知爱主，龟蛇思报珠。","未终青史志，一奏皂囊书。","谁谓爰丝直，端同汲黯愚。","谪官来剑浦，襆被出神都。","感激心独苦，飘零岁已徂。","悽悽念终养，冉冉叹征途。","四海尽蒙泽，孤臣方向隅。","愿回天上照，一起辙中枯。"]},{"t":"短歌","f":"七言律诗","c":["周家柱史本吾祖，唐室谪仙尤所许。","垂世空馀道德经，傲时且以诗酒名。","我今去作龙津客，学道吟诗真自适。","也胜骑马听朝鸡，晴压尘埃雨压泥。"]},{"t":"遣兴 其一","f":"七言律诗","c":["游戏清都不记年，谪来犹作地行仙。","龙墀叩额真率尔，石马系门非偶然。","野寺山庄随意宿，溪鱼村酿不论钱。","男儿本有四方志，出处安时休问天。"]},{"t":"遣兴 其二","f":"七言律诗","c":["冲涉脩途仆已疲，今宵聊复宿沙溪。","心怀浙右家无耗，身在江南路欲迷。","孤鹜断霞晴杳杳，暝烟荒草晚悽悽。","登临谁会悠然意，寒日无言又向西。"]},{"t":"遣兴 其三","f":"五言律诗","c":["风景正高洁，岁律忽峥嵘。","岸竹森如束，山田漫已耕。","溪寒幽石出，岫远暮云横。","试问螭头吏，谁令向此行。"]},{"t":"江南六咏 其一","f":"词","c":["江南山，秀色晴光杳霭间。","一带平凝愁翠黛，数峰孤绝耸烟鬟。"]},{"t":"江南六咏 其二","f":"词","c":["江南云，片片飞来湘水滨。","愁绝苍梧鼓瑟女，怅望阳台行雨神。"]},{"t":"江南六咏 其三","f":"词","c":["江南月，依然照我伤离别。","故人千里共清光，玉臂云鬟香未歇。"]},{"t":"江南六咏 其四","f":"词","c":["江南竹，霜霰岁寒依旧绿。","谁向溪边养箨龙，滴露摇风一林玉。"]},{"t":"江南六咏 其五","f":"词","c":["江南梅，昨夜溪头玉雪开。","赠远欲传千里恨，和烟为折一枝来。"]},{"t":"江南六咏 其六","f":"词","c":["江南客，鬓发苍浪不堪摘。","明时迁逐念前非，一夜愁吟霜月白。"]},{"t":"宿信州景德寺禅月堂","f":"七言律诗","c":["野寺虚堂倚翠微，云山极目望中疑。","溪寒连舰栏干直，日暮高楼鼓角悲。","倒景星河光破碎，乱萤灯火影参差。","贯休髣髴英灵在，应笑登临强赋诗。"]},{"t":"岩石村店有石泉梅橘幽雅可爱","f":"七言律诗","c":["岩下鸣泉淅沥飞，谁知山店亦幽奇。","已过野橘分金日，未见寒梅喷雪时。","旋洗云粳炊白玉，自挑霜菔缕青丝。","慇勤赋咏留岩石，他日重来觅旧诗。"]},{"t":"上饶道中杂咏三首 其一","f":"七言律诗","c":["半世区区何所求，南来岂为稻粱谋。","烟岚远近浓还淡，石濑萦回咽更流。","云外钩辀听处好，溪头略彴渡时幽。","何须更论他年事，且把风光慰旅愁。"]},{"t":"上饶道中杂咏三首 其二","f":"七言律诗","c":["鬓毛萧飒寸馀冠，蒙犯风霜却岁寒。","但使孤忠能感激，岂辞远谪备艰难。","苍苍云木留深景，渺渺深溪泻暮湍。","独坐苦吟山寺冷，照人孤月正团栾。"]},{"t":"上饶道中杂咏三首 其三","f":"七言律诗","c":["漠漠烟村一笛风，溪山都在夕阳中。","遥看天色暮云碧，渐见山头野烧红。","闽岭风烟知已近，浙江书问恨难通。","暝投山寺凭虚阁，隐耳犹听响暮钟。"]},{"t":"过鹅湖留赠昌长老二首 其一","f":"七言律诗","c":["云山深处到鹅湖，万木森森一径纡。","日落风高钟倍响，烟寒林暝鸟相呼。","宗风振起人能继，祖道流传德不孤。","须信山林真隐地，纷纷朝市更何如。"]},{"t":"过鹅湖留赠昌长老二首 其二","f":"七言律诗","c":["谪宦去为剑浦吏，税驾且作鹅湖游。","沈沈梵宇殿阁古，寂寂胜地林泉幽。","祖师道场谁继嗣，妙峰德云真比丘。","夜寒灯下接软语，却恨行客难淹留。"]},{"t":"昌老询予来历以诗答之","f":"五言律诗","c":["休问西来意，吾行日向南。","悽悽达磨忏，历历善财参。","旧事已不忆，新交宁易谈。","维摩本无语，非是学三缄。"]},{"t":"题石井慈济泉二首 其一","f":"七言律诗","c":["谁将石洞当泉池，馀溜溅溅落水陂。","山骨凿开苍玛瑙，云腴凝贮碧琉璃。","龟浮水面寒光动，竹舞岩端翠影垂。","泉石幽奇天下少，秘藏休使北人知。"]},{"t":"题石井慈济泉二首 其二","f":"七言律诗","c":["岩石嵌空湛碧泉，酌甘鉴静意萧然。","幽深端有神龙穴，虚迥疑藏古洞天。","云影漾波光璀璀，石渠飞溜响涓涓。","会须掬取岩中水，洒作膏霖遍八埏。"]},{"t":"铅山道中","f":"五言律诗","c":["行李踰江峤，风烟接武夷。","地灵嘉木秀，天阔暝云垂。","泉石日相乐，雪霜寒自迟。","寄声山下士，扫壁待题诗。"]},{"t":"小溪","f":"七言律诗","c":["脉脉寒溪彻底明，临流聊复濯吾缨。","风微静爱琉璃色，竹密遥闻环佩声。","漾月下摇金潋滟，涵虚不动镜澄泓。","自怜逐客难淹泊，不为溪山景太清。"]},{"t":"过紫溪值雪","f":"七言律诗","c":["明时报国敢怀安，远谪方知行路难。","云隔江乡来雁寂，雪飞闽岭敝貂寒。","韩诗解道蓝关恨，贾赋聊凭鵩鸟宽。","谁念紫皇香案吏，飘零已觉鬓毛乾。"]},{"t":"雪中过分水岭六首 其一","f":"七言律诗","c":["寒云漠漠雪霏霏，正是行人度岭时。","密洒峰峦开玉府，乱妆林木发琼枝。","步高渐入烟霄路，望远都迷涧壑姿。","回首江乡何处是，断蓬飘梗不胜悲。"]},{"t":"雪中过分水岭六首 其二","f":"七言律诗","c":["闽山高处却无风，密雪飞云堕晓空。","去路似从银色界，此身疑到广寒宫。","落梅飘絮来琼树，涌浪崩云叠玉峰。","景色幽奇无似雪，平生观雪此为雄。"]},{"t":"雪中过分水岭六首 其三","f":"七言律诗","c":["蔼蔼层阴送雪来，乱山深处白皑皑。","积岩错认蓝田玉，著树全疑庾岭梅。","光射九霄来夜月，冷凝千嶂蛰春雷。","武夷路近须晴霁，为卷风云一饷开。"]},{"t":"雪中过分水岭六首 其四","f":"七言律诗","c":["一夜同云凝不开，晓寒整辔马虺尵。","千岩万壑萦纡处，密雪回风散漫来。","愁里溪声琴的历，望中山色玉崔嵬。","溪山得雪尤奇绝，模写无工恨不才。"]},{"t":"雪中过分水岭六首 其五","f":"七言律诗","c":["瑶妃游戏水晶房，故剪冰花试晓妆。","坐见初平岩畔石，化为元放陇头羊。","培堆积玉寒光瑩，顷刻开梅冷艳香。","好是碧天云散后，野蟾来助一轮光。"]},{"t":"雪中过分水岭六首 其六","f":"七言律诗","c":["玉龙耕种素芝田，误入飞琼小洞天。","璧月珠星争璀璨，瑶环瑜珥斗婵娟。","水晶宫阙云腴滑，白玉楼台雾彩鲜。","骨冷魂清难久驻，恍然昆阆梦游仙。"]},{"t":"次大安驿雪霁","f":"七言律诗","c":["雪霁烟村风满林，暮天垂影碧沉沉。","一轮明月光相射，千里白云寒更深。","寂寞樽盈陶令酒，飘零泪满仲宣襟。","灯残夜永不成寐，庄舄悽然自越吟。"]},{"t":"山家","f":"七言律诗","c":["青山掩映野人家，翠竹苍松一径斜。","夜对月钩沉浅浦，晓看鸟篆印平沙。","溪头驯畜多宜鹜，园里灵苗可种茶。","占尽溪山幽胜处，自将风物向人誇。"]},{"t":"将次武夷","f":"七言律诗","c":["行行路近武夷山，秀气蜿蜒百里间。","苍石插天云缥缈，碧溪通壑水弯环。","神仙恍惚谁能识，洞府深沉自不关。","我向湖中如得路，便应脱屣谢尘寰。"]},{"t":"崇安宰见示武夷山图记","f":"七言律诗","c":["征轩欲作武夷游，先借图经次第求。","须信神仙真窟宅，故令峰岫巧雕锼。","四时花木千岩秀，一水波澜九曲流。","明日泛舟山下去，按图细细问踪由。"]},{"t":"自入闽境值雪默祷武夷君游山日雪霁有感","f":"七言律诗","c":["鄙陋安能到古人，寸心潜格武夷君。","誓辞叱散蛮溪雾，诗句驱开衡岳云。","忠谠自应惭吏部，精诚何敢并将军。","氛霾卷尽留残雪，妆点峰峦意更勤。"]},{"t":"趋真亭","f":"七言绝句","c":["烟霞深处一亭閒，石磴萦纡紫翠间。","但觉峰峦劳顾揖，不知身到武夷山。"]},{"t":"游仙溪","f":"七言绝句","c":["一溪九曲贯群峰，演漾轻舠浅碧中。","杳如误入武陵去，落花流水山重重。"]},{"t":"武夷山","f":"七言律诗","c":["百里云山碧玉林，雕锼融结见天心。","幔亭会散笙箫远，天柱风高烟雾深。","画鹤独留青嶂表，林花常发紫岩阴。","梦魂清切先曾到，故使飘零特特临。"]},{"t":"幔亭峰","f":"七言律诗","c":["燕罢虹桥绝世氛，曾孙谁见武夷君。","更无裀幕空中举，时有笙竽静处闻。","猿鸟夜啼千嶂月，松篁寒锁一溪云。","洞天杳杳知何处，翠石苍崖日欲曛。"]},{"t":"洞天穴","f":"七言律诗","c":["沈沈幽穴閟云烟，玉宇琼楼锁洞天。","自向壶中飞日月，更于物外起山川。","刘公隐后今谁继，张湛仙来不记年。","紫府若容幽客到，诛茅欲卜隐屏前。"]},{"t":"换骨岩","f":"七言绝句","c":["玄化升真十六天，灵仙蝉脱翠岩前。","金坚玉润留馀骨，密锁烟霞几百年。"]},{"t":"龙潭","f":"七言绝句","c":["百丈清潭合两溪，澄波瑩滑碧琉璃。","神龙端向潭中睡，何事能容网罟垂。"]},{"t":"狮子峰","f":"七言绝句","c":["奇石腾拿竹树苍，奋髯矫首据崇冈。","山深怪底无豺虎，端畏溪头百兽王。"]},{"t":"观音岩","f":"七言绝句","c":["铢衣珠珞宝花冠，宴坐翛然山水间。","应为武夷泉石好，不殊海岸补陀山。"]},{"t":"兜担石","f":"七言绝句","c":["仙人戏睹翠蛾眉，空有花馀照夕晖。","云月娟娟风袅袅，尚疑玉质在帘帏。"]},{"t":"三女石","f":"七言绝句","c":["粲粲三英傍碧溪，玉肌云鬓晓参差。","想因巫峡行云日，记得湘江解佩时。"]},{"t":"学堂岩","f":"七言绝句","c":["仙官读彻蕊珠篇，几案岩中自寂然。","昆阆图书藏策府，谁言孤陋解成仙。"]},{"t":"船场岩","f":"七言绝句","c":["仙艇何年插翠微，云篷烟棹尚依依。","凌虚欲鼓天边柁，唤取双龙背负飞。"]},{"t":"鸡窠岩","f":"七言绝句","c":["磔磔天鸡啼晓烟，仙家风景镇芳妍。","自从彩翼飞仙后，只有遗栖寄岭巅。"]},{"t":"大小藏岩","f":"七言绝句","c":["玉棺插遍两岩傍，石罅开如小洞房。","鍊就阳魂归紫府，空馀灵骨此中藏。"]},{"t":"仙迹石","f":"七言绝句","c":["当年天姥戏溪边，二石遗踪膝宛然。","却笑茂陵缑氏迹，只凭方士口中传。"]},{"t":"大小二廪石","f":"七言绝句","c":["仙家何事亦赢粮，廪石团团峙道傍。","应驾斑龙耕紫石，深储芝玉廪中藏。"]},{"t":"鼓楼岩","f":"七言绝句","c":["洞天击鼓集群仙，石作高楼锁翠烟。","万籁不鸣霜月晓，鼕鼕犹听鼓声传。"]},{"t":"丹灶","f":"七言绝句","c":["金鼎丹成透碧天，尚留丹灶在层巅。","一丸五色光腾夜，乞取从教作散仙。"]},{"t":"仙掌","f":"七言绝句","c":["玉指纤纤烟霭中，挥云映日掌微红。","只疑华岳留踪后，更向闽山映碧峰。"]},{"t":"三层峰","f":"七言绝句","c":["三层灵峰气象豪，喷云泄雨不崇朝。","悬崖峭壁无人到，只恐峰头是碧霄。"]},{"t":"画鹤","f":"七言绝句","c":["谁画千年老令威，丹青今古照清辉。","玄裳朱顶苍崖畔，岂忆冲天万里飞。"]},{"t":"禅庵岩","f":"七言绝句","c":["虎啸猿啼月满天，山僧宴坐正安禅。","不知只履归何处，尚有庵岩名字传。"]},{"t":"仙机岩","f":"七言绝句","c":["云去仙机杼轴空，报章何日已成功。","天孙织就烟霞锦，吹落溪山夕照中。"]},{"t":"魏王峰","f":"七言绝句","c":["危峰孤峭与天通，犹有当时羽化踪。","仙驭自随鸾鹤远，玉楼金锁白云封。"]},{"t":"虎啸岩","f":"七言绝句","c":["昔年雕虎啸幽岩，千里清风皱碧潭。","虎去岩空风自远，一林花雨落毵毵。"]},{"t":"钓台石","f":"七言绝句","c":["钓石峨峨枕碧溪，仙人于此亦垂丝。","想当月白风清夜，正是寒鱼食饵时。"]},{"t":"试剑石","f":"七言绝句","c":["鍊气为金铸剑成，且将顽石试青萍。","光铓郁郁冲牛斗，斩尽妖魔若发铏。"]},{"t":"折笋岩","f":"七言绝句","c":["玉府锵锵玉笋林，谁将移种翠岩阴。","斓斑犹带当时箨，照水笼烟几百寻。"]},{"t":"仙接石","f":"七言绝句","c":["天风吹折碧琅玕，神化茫茫接岂难。","凤髓鸾胶天上有，世人休作等闲看。"]},{"t":"柴岭","f":"七言绝句","c":["林花不逐岁寒凋，半岭烟光媚远霄。","须信仙家风景好，四时峰岫紫岧峣。"]},{"t":"车钱峰","f":"七言绝句","c":["尘缘洗尽便神仙，泉石幽奇即洞天。","我欲云崖结茅屋，侍从天姥借车钱。"]},{"t":"毛竹洞","f":"七言绝句","c":["洞生毛竹绿猗猗，枝干扶疏满洞垂。","传是群仙游息地，蔽藏不许世人知。"]},{"t":"睎真馆","f":"七言绝句","c":["小溪诘屈巧萦回，行到睎真景更奇。","路转山回疑不见，此中凝望却参差。"]},{"t":"仙橘","f":"七言绝句","c":["岩畔阴森橘树垂，青青亦有岁寒姿。","我来恨在秋风后，不见霜包结实时。"]},{"t":"仙竹","f":"七言绝句","c":["阴崖翠竹自檀栾，瘦节疏枝特地寒。","虽未化龙归洞府，正宜和月扫天坛。"]},{"t":"泛舟至睎真馆遇雪 其一","f":"七言律诗","c":["云散天开一饷中，依前飞雪落层空。","琼花巧缀岩端树，玉屑飘随洞里风。","溪浅且游仙掌石，云深不见幔亭峰。","斯游清绝平生少，图画方知未是工。"]},{"t":"泛舟至睎真馆遇雪 其二","f":"七言律诗","c":["行到清溪六曲头，森然峰岫照人幽。","雪花拂水轻轻舞，石濑依岩浅浅流。","不尽清光常在目，未穷幽兴且回舟。","追寻欲遍神仙窟，须向他时卜再游。"]},{"t":"访李道士 其一","f":"七言绝句","c":["青山中有一道士，独卧烟霞昼掩扉。","踏雪叩关知意重，拥炉相与话真机。"]},{"t":"访李道士 其二","f":"七言绝句","c":["诛茅独占溪一曲，时有白云来伴宿。","自言身在此山中，暮暮朝朝看不足。"]},{"t":"纪旧梦","f":"七言绝句","c":["清梦先曾到武夷，玉峰积雪倍幽奇。","小舟游罢寻归路，恰似翛然梦觉时。"]},{"t":"宿栖真馆夜雪大作诘旦遂行","f":"七言律诗","c":["一夜武夷三尺雪，岩壑无声闻竹折。","云峰烟岫望都迷，玉树瑶林寒更发。","山中道士毛骨奇，劝我留宿山前斋。","轻装冒雪非得已，仙赏更待他年来。"]},{"t":"题栖真馆三十六韵","f":"五言古诗","c":["武夷古洞天，奇峰三十六。","一溪贯群山，清浅萦九曲。","溪边列岩岫，倒影浸寒绿。","翩如鸾凤翔，矫若虬龙蹙。","楼观耸岧峣，屏帏互重复。","蜕仙骨遗金，游女肌削玉。","鸡栖层岩巅，船插断崖腹。","学馆存几案，仙机馀杼轴。","蓝光瑩澄潭，虹影挂飞瀑。","翠竹荫天池，苍苔封石屋。","绘禽顶长丹，遗迹指如掬。","峨峨天柱峰，幔亭连翠麓。","传闻武夷君，尝此会仙俗。","飞桥几千丈，绝顶亘山足。","障以翠云屏，藉以紫霞褥。","瑶樽倾沆瀣，玉豆脯麟鹿。","仙妃奏宾云，金鼓间丝竹。","酒酣歌夕晖，叹息光景促。","曾孙谁复在，往事空遗躅。","至今风月夜，笙箫响虚谷。","地灵饶泉石，山润秀草木。","坐使七闽人，荫此仙灵福。","嗟予真散材，性爱山水酷。","仙经与地志，名字久已熟。","薄宦方区区，仙赏宜碌碌。","神游先梦寐，幽觌寄图录。","宁知因谪宦，乃得厌所欲。","沿溯穷幽深，应接劳耳目。","开襟豁怀抱，壮观慰幽独。","却邀白云归，伴此岩下宿。","夜寒梦魂清，晓发轻装速。","仙游须再来，何当谢羁束。"]},{"t":"赠舅氏吴子和","f":"七言律诗","c":["契阔从来叹岁阴，幸因谪宦款清襟。","犯颜逆耳事已往，问舍求田意转深。","岂有声名惊海宇，且忻山水共登临。","渭阳情重知何赠，玉佩琼琚称我心。"]},{"t":"自建阳泛舟至建安","f":"七言律诗","c":["一叶轻舠漾碧流，却怜舟子解操舟。","急滩乱石疑难渡，短楫轻桡反自由。","去国飘零同泛梗，凌波超忽逐飞鸥。","建溪百里才终日，过尽千岩万壑幽。"]},{"t":"建溪再得雪乡人以为宜茶","f":"七言律诗","c":["闽岭今冬雪再华，清寒芳润最宜茶。","泛瓯欲斗千金价，著树先开六出花。","圭璧自须呈瑞质，旗枪未肯放灵芽。","传闻龙饼先春贡，已到钧天玉帝家。"]},{"t":"天宁老齐珏录庆馀师开堂疏见示","f":"七言绝句","c":["一别闽山三十年，重来相见两依然。","烦师录示当时语，犹喜曹溪一派传。"]},{"t":"梅花二首 其一","f":"七言律诗","c":["寒梅昨夜泄春光，标格依然压众芳。","袅袅露枝团玉白，轻轻烟蕊簇金黄。","瑶妃谪堕溪村寂，雪片飘残月径香。","却笑汉宫争宠女，竞将娇额学新妆。"]},{"t":"梅花二首 其二","f":"七言律诗","c":["数枝玉雪小溪滨，先得阳和一点春。","冷艳幽姿难与并，暗香疏影孰为邻。","广平不害心如铁，和靖须知句有神。","亦对寒芳动诗兴，却嫌标格太清真。"]},{"t":"剑浦道中二首 其一","f":"七言律诗","c":["宿雾霏霏隐翠岚，傍溪幽石自巉岩。","樵歌递响来危径，渔网连舟集小潭。","野渡无人閒寂寂，林花著雨落毵毵。","谁知逐客凄凉意，岁宴南迁剑浦南。"]},{"t":"剑浦道中二首 其二","f":"七言律诗","c":["此去平津路匪遥，岭云溪雨自萧萧。","山深泻涧泉长响，地暖凌寒草不凋。","放逐却教穷水石，登临因得狎渔樵。","谁怜泽畔人憔悴，更把骚辞赋大招。"]},{"t":"自建安陆行至剑浦","f":"七言律诗","c":["闻道延平黯淡滩，舟行至此惨愁颜。","千金素佩垂堂戒，九折宁辞去路艰。","涉险虽知凭信义，藏幽须信足神奸。","劳生自取那惆恨，只羡飞云自在閒。"]},{"t":"剑潭","f":"七言古诗","c":["当时神剑埋丰城，郁郁光气冲斗星。","千年古狱斸幽扃，下得至宝双青萍。","雌雄不知谁与名，拭以异土聊发铏。","龙文星彩愈晶荧，正昼无影魑魅惊。","雄飞霄汉随雷霆，雌跃渊水归延平。","没人下瞰风涛生，天矫化作虬龙形。","茂先博识非无凭，神物终合信有徵。","沈沈潭影含虚明，宝气久秘必复呈。","会当探取搜元精，佩服坐能驱百灵。","奸谀膏血纷膻腥，与尔相携游太清。"]},{"t":"双溪阁","f":"七言律诗","c":["凌虚高阁枕双溪，四出飞檐鸟翼齐。","山锁烟光青合匝，水分丁字碧凄迷。","蟠虬旧化张公剑，翥凤今留鲁国题。","放逐因能穷胜赏，登临那惜醉如泥。"]},{"t":"沙阳","f":"五言古诗","c":["沙阳虽僻左，风土冠闽城。","谁知乱山里，有此膏壤平。","邑屋号华丽，溪山倍澄明。","七峰转月色，十里无滩声。","民俗素康阜，士夫多俊英。","食饶鱼稻美，荫有松竹清。","筦库职易办，尘劳念尤轻。","萧然飘泊迹，忘此羁旅情。","忽忽岁改律，欣欣木向荣。","何当脱拘缚，春亩得躬耕。"]},{"t":"平津晚望","f":"七言律诗","c":["春入沙阳花满林，七峰倒影碧沈沈。","饥鸢掠水盘旋久，戏鸭浮溪演漾深。","风景只添流落恨，烟光遥锁别离心。","浙西三月无消息，始信家书抵万金。"]},{"t":"余抵沙阳之夕民居延火几爇官局因念以论水得罪复以火惊殊可笑叹戏成此诗","f":"七言律诗","c":["囊封论水谪天涯，才到沙阳火复随。","本为玄冥遭放逐，却因回禄更惊疑。","生辰端是穷申未，学易何曾悟坎离。","烂额焦头那足惜，只愁蓬迹久飘移。"]},{"t":"除夜","f":"七言律诗","c":["年来三百六十日，忽忽过尽唯今宵。","天涯远谪罪未解，家问久缺心无聊。","强倾浊酒慰愁独，坐对寒灯尤寂寥。","钟鸣漏尽不成寐，世事又属明年朝。"]},{"t":"元日","f":"七言律诗","c":["去年元日朝明堂，对立玉皇香案傍。","今年元日谪沙阳，独在天涯家一方。","君恩未报已飘泊，亲老欲养徒徬徨。","东风回首帝乡远，白云望断吴天长。"]},{"t":"立春日","f":"七言律诗","c":["春风吹到海南边，气候浑如二月天。","幡胜戴来聊应节，鼓箫鸣处已祈田。","花梢柳眼争明媚，溪色山光愈翠鲜。","生菜春盘谁与送，玉人纤手自婵娟。"]},{"t":"春词二十首 其一","f":"七言绝句","c":["一树梨花傍小轩，结根幽寂更芳妍。","东君有意怜流落，故遣瑶姿堕目前。"]},{"t":"春词二十首 其二","f":"七言绝句","c":["晚来急雨作轻寒，只恐梨花落点残。","唤起小童窗外看，玉妃何事泪栏干。"]},{"t":"春词二十首 其三","f":"七言绝句","c":["花开好鸟晓关关，惊觉幽窗小梦残。","宿酒未醒慵起早，透帘红日上三竿。"]},{"t":"春词二十首 其四","f":"七言绝句","c":["萧萧槛外翠琅玕，瘦节疏枝特地寒。","谁谓幽居太寥闲，此君长此结清欢。"]},{"t":"春词二十首 其五","f":"七言绝句","c":["春光淡荡一番新，花气氛氲恼杀人。","只恐花飞春又老，须将酩酊对芳辰。"]},{"t":"春词二十首 其六","f":"七言绝句","c":["清晨开卷坐幽窗，深注炉烟一缕香。","汲水养花颜色好，向人端似炫新妆。"]},{"t":"春词二十首 其七","f":"七言绝句","c":["春日迟迟午睡浓，梦魂飞过浙江东。","无端花底间关舌，唤起搔头两鬓蓬。"]},{"t":"春词二十首 其八","f":"七言绝句","c":["寂寂春林杜宇啼，劝人只道不如归。","我今归思何须劝，借尔翩翻两翅飞。"]},{"t":"春词二十首 其九","f":"七言绝句","c":["春色困人浑似酒，花枝照眼恰如人。","东君若解怜愁客，莫使花飞减却春。"]},{"t":"春词二十首 其十","f":"七言绝句","c":["漠漠轻烟度短墙，春寒料峭怯罗裳。","惜春只怕多风雨，云影披离漏日光。"]},{"t":"春词二十首 其十一","f":"七言绝句","c":["幽禽百啭舌如簧，院宇深深花木香。","飘泊伤春惟泥酒，不知林外已斜阳。"]},{"t":"春词二十首 其十二","f":"七言绝句","c":["谁使鸣禽自在啼，感春端似惜芳时。","一枝暂寄休饶舌，静处须防挟弹儿。"]},{"t":"春词二十首 其十三","f":"七言绝句","c":["春来南国蔼韶光，百卉嫣然竞早芳。","语燕啼莺将婉娈，游蜂舞蝶已颠狂。"]},{"t":"春词二十首 其十四","f":"七言绝句","c":["青鸟飞来动槛花，翠衿绀趾哢交加。","向人自解传消息，疑是来从阿母家。"]},{"t":"春词二十首 其十五","f":"七言绝句","c":["微月笼云黯淡明，忽闻索索雨来声。","可怜窗外梨花老，一夜飘残雪片轻。"]},{"t":"春词二十首 其十六","f":"七言绝句","c":["聒聒鸣鸠唤雨来，萧萧寒响滴空阶。","不知逐客伤春恨，多少残英点翠苔。"]},{"t":"春词二十首 其十七","f":"七言绝句","c":["飘风骤雨饷时间，堕蕊飞花满地殷。","自是群芳将结实，非关风雨故摧残。"]},{"t":"春词二十首 其十八","f":"七言绝句","c":["桃花零落逐风飞，地上红多枝上稀。","春色陡然归艳杏，梢头还欲衒芳菲。"]},{"t":"春词二十首 其十九","f":"七言绝句","c":["南方春早花亦早，烂熳开尽枝头红。","记得上林当此际，游人殊未探芳丛。"]},{"t":"春词二十首 其二十","f":"七言绝句","c":["一年春事遽如许，千里旅愁何似生。","浊酒饮馀惟五合，残书读尽忽三更。"]},{"t":"用韵赋梅花三首 其一","f":"七言古诗","c":["寒梅几树开前村，靓妆绰约归仙魂。","横斜影落石溪浅，皓洁色洗烟岚昏。","幽香暗动松竹径，清格自羞桃李园。","穷冬万里霜雪积，独得一点阳和温。","冰姿最宜夜月白，玉彩更炫朝霞暾。","明妃失意去朔漠，阿娇无宠扃长门。","芳容寂寂谁复顾，雅意耿耿今何言。","天涯相对且相乐，为尔吸尽黄金樽。"]},{"t":"用韵赋梅花三首 其二","f":"七言古诗","c":["草木冻死山中村，惟有梅花能返魂。","孤根不怕雪霜苦，冷艳似笑风云昏。","披芳独占岁寒地，擢秀肯待春风园。","溪边寒影自的的，月里皓色还温温。","飘零疏雨夕烟瞑，厌浥清露晨光暾。","玉妃游戏隘昆阆，缟衣飞出瑶台门。","幽姿耿介不可狎，欲问所以难为言。","嗅花嚼蕊更奇绝，侑我一醉玻璃樽。"]},{"t":"用韵赋梅花三首 其三","f":"七言古诗","c":["云山缥缈烟水村，嫣然顾我惊离魂。","凝情不语自脉脉，旅愁易感方昏昏。","我家梁溪富泉石，雪里数株开北园。","天涯相见一笑粲，玉色不减当时温。","为君清夜不成寐，月落已见东方暾。","会栽千树遍绿野，岂羡五柳垂衡门。","临风三嗅长太息，欲辩此意还忘言。","何当归去老三径，携幼入室酒盈樽。"]},{"t":"再赋一首","f":"七言古诗","c":["十年不踏江南村，想像梅花劳梦魂。","岂惟捧心笑西子，只恐举步迷东昏。","繁英恍讶群玉府，堕蕊悄愁金谷园。","冰肌自饮晨露白，粉质不浴骊汤温。","我行闽岭喜入眼，皓彩照耀咸池暾。","烟凝云惨更愁绝，积雪欲堆袁安门。","天香国艳世无匹，何用苦死教能言。","吹残楼角真可惜，莫厌秉烛临芳樽。"]},{"t":"吴慎微邓志宏同游陈氏园","f":"五言古诗","c":["我本惜春人，常恐春色老。","沙阳渺天南，春到一何早。","群芳忽烂漫，自觉被春恼。","招邀适名园，景物得幽讨。","灿灿桃李妍，娟娟松竹好。","虚室自含风，回塘已生草。","酌酒对芳菲，论文慰怀抱。","瑰奇窥李杜，寒色笑郊岛。","软语既温温，高谈方浩浩。","二子若骅骝，轻车驾长道。","而我正飘蓬，摧残已枯槁。","家在天一涯，情若风中翿。","幸然得相从，豁我忧心捣。","青春能几时，落花看又扫。","宁辞金罍空，坐使玉山倒。","世事可两忘，悠悠信苍昊。"]},{"t":"邓纯彦家兰盛开见借一本 其一","f":"七言绝句","c":["谁道幽兰是国香，山林僻处更芬芳。","从今借得佳人佩，伴我春堂昼梦长。"]},{"t":"邓纯彦家兰盛开见借一本 其二","f":"七言绝句","c":["特地闻时却不香，暗中芬馥度微芳。","寂然鼻观圆通处，深院无人春昼长。"]},{"t":"邓纯彦家兰盛开见借一本 其三","f":"七言绝句","c":["喷了清香开了花，却归盆槛付公家。","来春花发香尤好，预借幽根茁露芽。"]},{"t":"邓纯彦家兰盛开见借一本 其四","f":"七言绝句","c":["纤纤碧叶浅黄花，暗淡香飘物外家。","培壅莫教摧露下，春风岁岁长灵芽。"]},{"t":"次韵陈介然幽兰翠柏之作 其一 幽兰","f":"五言古诗","c":["幽兰出深林，得上君子堂。","置之顾盼地，蔼蔼振馀光。","春风茁其芽，暗淡飘天香。","刈防岂无用，授梦方荐祥。","纫佩美屈子，披风快襄王。","秋高白露下，摧折增感伤。","愿与菊同瘁，羞随莸并长。","收根归旧林，肯改无人芳。"]},{"t":"次韵陈介然幽兰翠柏之作 其二 幽兰","f":"五言古诗","c":["温风茁幽兰，采掇置中堂。","孤根亦何有，借此轩墀光。","耿耿不自惜，凄微泛馀香。","萧然山林姿，讵是邦家祥。","譬犹美芹子，乃以荐君王。","弃置固其宜，零落谁复伤。","赋诗慰寂寞，念子故意长。","愿言同心人，去去扬清芳。"]},{"t":"次韵陈介然幽兰翠柏之作 其一 翠柏","f":"五言古诗","c":["翠柏方岁寒，独立群木外。","不为众所知，此理实难会。","惜哉结根浅，未使极高大。","天风动虬枝，萧瑟起清籁。","傥无斤斧残，会拂千丈黛。","空馀霄汉志，不逐雪霜改。","委弃老空山，浩荡付玄宰。"]},{"t":"次韵陈介然幽兰翠柏之作 其二 翠柏","f":"五言古诗","c":["崇冈有翠柏，擢干烟霭外。","托非不得地，据此群山会。","青青岁寒姿，自许百围大。","舞月散清影，号风振虚籁。","谁云根如石，已见色参黛。","幽人挺高怀，顾我颜不改。","知音自昔难，多财为尔宰。"]},{"t":"次韵邓志宏梅花","f":"七言古诗","c":["空山极望皆黄苇，欲挽天河聊一洗。","溪边的皪见梅花，冷蕊疏枝澹烟水。","安得健步移我堂，清夜桂魄来孤光。","人寰尘土飞不到，鼻观寂寂闻天香。","吾衰文思久不起，见子新诗端可喜。","落英坐使笑天桃，结实定知非苦李。","年来踪迹堕空濛，与子追随邈未穷。","琢磨妙句觑天巧，为我一振诗家风。"]},{"t":"上元日二首 其一","f":"七言绝句","c":["去年玉辇侍端门，灯满鳌山讶晓暾。","寂寞沙阳山水里，也将膏火照黄昏。"]},{"t":"上元日二首 其二","f":"七言绝句","c":["应为飘零有故侯，竞将灯火簇溪楼。","田夫野妇盈衢巷，怪我还能与共游。"]},{"t":"墨戏六首 其一 拳蠹","f":"五言绝句","c":["屈折金石瘦，偃蹙虬龙怒。","萧然少生意，端为根中蠹。"]},{"t":"墨戏六首 其二 枯折","f":"五言绝句","c":["岁晚风号寒，琅玕半吹折。","虽残栖凤枝，终抱凌霄节。"]},{"t":"墨戏六首 其三 宿枝","f":"五言绝句","c":["疏筠轻带粉，老叶饱经霜。","试问枝头实，何年集凤凰。"]},{"t":"墨戏六首 其四 新叶","f":"五言绝句","c":["解箨能几日，成阴不待春。","天然为谁笑，风露一枝新。"]},{"t":"墨戏六首 其五 引根","f":"五言绝句","c":["土润引新萌，虬鞭独处行。","此君人不厌，何惜满林生。"]},{"t":"墨戏六首 其六 迸笋","f":"五言绝句","c":["养就箨龙儿，斓斑角未齐。","斧斤休纵手，会看拂云霓。"]},{"t":"六竹外尚有偃风顶雨二本留故家志宏欲之而未得戏作绝句附卷末庶几异日悉归志宏也","f":"七言绝句","c":["六样根茎妙入神，两枝风雨更清新。","此君族类须收拾，莫使飘零叹失身。"]},{"t":"再用陈园韵示邓志宏","f":"五言古诗","c":["青松更雪霜，始见枝干老。","挺然节操士，安用致身早。","吾衰习禅观，颇觉得无恼。","每于文字间，未免尚穷讨。","遇物空吟哦，愧乏句语好。","有时肆狂言，自哂太草草。","儒生舍翰墨，无与寄幽抱。","富贵非所愿，神仙渺云岛。","宁知万卷中，养此一气浩。","子若汗血驹，振辔千里道。","我如铩翮鸿，毛羽半摧槁。","适然相值遇，岂异宛丘翿。","新诗迭唱酬，险韵类虚捣。","文章虽末技，尘语贵除扫。","勉哉扛鼎力，回此狂澜倒。","此外复何为，穷通付旻昊。"]},{"t":"惜花","f":"七言绝句","c":["瓶水养花花已老，零落春风寒不扫。","从教几案积残红，尚有馀香慰衰槁。"]},{"t":"乘兴游邓季明园池邀志宏同会再赋陈园韵","f":"五言古诗","c":["幽人筑小圃，自乐不知老。","闻名虽已熟，相见苦不早。","忘怀倾盖间，什我羁旅恼。","春风入芳林，乘兴聊一讨。","嘉葩寒未开，美木晴更好。","飘零桃与杏，残红委烟草。","急令招小阮，谈笑款清抱。","披襟步方池，散策穷远岛。","翛然适我情，忘此归志浩。","人生暂寄身，宠辱何足道。","舐痔得车多，未可骄黄槁。","一杯且相属，起舞不须翿。","文楸响玉子，更试兵家捣。","羸形乍泉涨，猛势惊电扫。","应怜客素痴，屡劝罚觥倒。","归待月华生，清光满春昊。"]},{"t":"招陈几叟小饮","f":"七言律诗","c":["开樽欲约玉川子，致鲤先遣长须奴。","春时海燕光涎涎，风暖城乌尾毕逋。","幸有异书并古字，可无白饭与青刍。","虚堂隐几共谈笑，应信今吾非故吾。"]},{"t":"志宏以墨戏见遗并贶古风次韵答之且归其画","f":"七言古诗","c":["老坡墨戏吾最许，雨叶风枝无点土。","幽怀寄此管城颖，妙质森然会稽楮。","要须胸次竹先成，故使落笔前无古。","披图但爱凌云姿，作赞愧乏惊人语。","嗟予迂阔与世疏，酷嗜栽培如老圃。","筑园会与种千竿，开国便胜封万户。","遗予此画意已勤，夺人之好道所禦。","封题依旧送书房，得画何如得竹愈。"]},{"t":"再用奴字韵呈几叟","f":"七言律诗","c":["平生志尚在丘壑，肯学卫霍追匈奴。","绵上之田方欲隐，草堂之灵休谢逋。","富贵于人何翅梦，理义悦我真如刍。","晚交夫子谈道妙，应笑连叔惊肩吾。"]},{"t":"以墨戏归志宏复有诗来次韵答之","f":"七言古诗","c":["玉局老仙人共许，秀骨于今已黄土。","人间无复见文章，空馀戏墨归囊楮。","子能藏蓄真好事，便可秘惜传千古。","试将短句赞幽姿，却对此君难下语。","年来懒惰百事废，欲把锄犁逐农圃。","会栽脩竹满园池，为引清风到庭户。","子诗往复句益奇，发我狂吟那可禦。","超然对竹更吟诗，此病未知谁得愈。"]},{"t":"再次韵","f":"七言古诗","c":["落笔萧森遽如许，墨为根茎纸为土。","眉山作此共言好，譬犹字法称虞褚。","世人画竹不画意，谩舍丹青欲侔古。","胸中干叶本天成，心手应时那可语。","此君于我定有缘，每念移根栽小圃。","开图忽见数株新，却怪龙孙入吾户。","年来几欲断吟哦，照眼还成自难禦。","发缄又复读佳篇，诗癖遥知犹未愈。"]},{"t":"志宏复有诗来再赋两篇为报念其往复之无已也故寓意卒章以止之 其一","f":"七言古诗","c":["平生爱竹端自许，欲种千竿满吾土。","岂知好物不须多，只费东坡数番楮。","酒酣弄笔写寒姿，一洗丹青空万古。","我今观画已萧然，矧对吟风如共语。","渊明荒径便抛官，仲子辞官归灌圃。","终年端坐饱太仓，更欲此君长傍户。","亦知两者固难兼，无那幽怀终不禦。","纵教富贵欲何为，不若归来栽竹愈。"]},{"t":"志宏复有诗来再赋两篇为报念其往复之无已也故寓意卒章以止之 其二","f":"七言古诗","c":["数君妙质来何许，生气森森如得土。","依然对此未忘情，亦欲怀之恨无楮。","宿枝新叶自清妍，蠹拳枯折尤奇古。","已将金玉照双眸，更得珠玑编好语。","男儿学古贵根源，馀力游兹文翰圃。","沈思六艺见同归，纵览百家知异户。","浩然养气塞天渊，沛若江河知孰禦。","却怜彫斲愁肺肝，但莫苦吟当自愈。"]},{"t":"读李白集用奴字韵","f":"七言律诗","c":["谪仙英豪盖一世，醉使力士如使奴。","当时左右悉谀佞，惊怪恇怯应逃逋。","我生端在千载后，祭公只用一束刍。","遗编凛凛有生气，玩味无斁谁如吾。"]},{"t":"春雨","f":"五言律诗","c":["春晚雨声碎，天深云影低。","萧萧度远岫，脉脉涨前溪。","芳润归花蕾，清寒作燕泥。","池塘梦生草，碧色已凄迷。"]},{"t":"春意","f":"五言律诗","c":["春鸟窥绿窗，踏落庭前花。","美人为之笑，鬓脚风中斜。","不惜花踏残，只愁鸟惊去。","姹娅背人飞，林深无觅处。"]},{"t":"平津閤晚雨","f":"五言律诗","c":["暮雨带风急，春云乱眼低。","凄凉倚虚閤，湍激瞰回溪。","烟远桃花浪，山寒锦障泥。","江乡何处是，天阔望中迷。"]},{"t":"春昼书怀","f":"七言律诗","c":["春院沈沈昼掩关，坐看云起面前山。","静中图史尤多味，身外功名已厚颜。","匣砚细磨鸲鹆眼，茶瓯深泛鹧鸪斑。","簿书粗了无馀事，更有何人似我閒。"]},{"t":"春雪 其一","f":"七言律诗","c":["怪底春来煖太深，忽惊雪片堕层阴。","廉纤带雨初犹薄，散漫随风遽不禁。","光炫峰峦皆玉色，寒侵花木欲灰心。","沙阳逐客家何在，拥鼻凄凉但越吟。"]},{"t":"春雪 其二","f":"七言律诗","c":["东君也解惜芳容，故把冰花密密封。","索索响寒窗外竹，亭亭戴白岭头松。","只惊满眼飘风絮，不觉濒溪卧玉龙。","身在天涯归未得，浇愁直欲倒千钟。"]},{"t":"食笋蕨","f":"七言绝句","c":["太官饱食厌膻腥，却喜沙阳有竹萌。","山蕨迩来尤脆美，一杯聊试煮坡羹。"]},{"t":"学草书","f":"七言绝句","c":["平生行事见真书，草圣空惭点画疏。","今日试临寒食帖，却疑羲献不难如。"]},{"t":"次韵志宏见示春雪长句","f":"七言古诗","c":["百花烂漫如冶容，颇讶陡然春色浓。","那知忽作三尺雪，草木洗尽群芳空。","六英飘舞片片好，谁与刻削嗟神工。","溪山恍在玉壶里，楼观飞出瑶台中。","却怜极目皆皓素，不复零落伤残红。","幽人栩栩应梦蝶，落絮漠漠方黏蜂。","虚堂兀坐清入骨，欲期汗漫游鸿濛。","剡溪访戴久寂寞，安得一御泠然风。","年来端恐诗道穷，幸予佳句时争锋。","客愁已剧更赋雪，半夜吟苦天地白。"]},{"t":"雪霁","f":"七言律诗","c":["梦残钟鼓报新晴，虚幌遥看晓日升。","云外崔嵬犹负雪，石间清浅欲销冰。","春归花草蜂寻侣，巢寄檐楹燕语朋。","貂敝不禁寒料峭，客愁惟藉酒凭陵。"]},{"t":"次韵陆敦礼留题皇华驿二首 其一","f":"七言律诗","c":["貂裘端恐敝缁尘，勇向明时乞得身。","却拥紫荷来握节，遥知白鹿已随轮。","棣华辉映蕃宣地，篇什流传放逐人。","只恐晋江难久驻，为将直道福生民。"]},{"t":"次韵陆敦礼留题皇华驿二首 其二","f":"七言律诗","c":["宫漏初残唱晓鸡，周庐同守禁城扉。","龙墀密簉鹓鸾羽，玉殿先瞻日月衣。","青琐笑谈情已厚，皂囊章奏意何稀。","拥旄昼绣方如意，也念飘零未得归。"]},{"t":"溪涨 其一","f":"七言绝句","c":["中宵骤雨驾惊雷，逗晓盘涡毂浪来。","端恐溪神似河伯，望洋向若始知咍。"]},{"t":"溪涨 其二","f":"七言绝句","c":["雨过浑流涨晓溪，茫茫烟水拍春堤。","凄凉柱史凭虚阁，犹忆都城水自西。"]},{"t":"志宏以牡丹酴醾见遗戏呼牡丹为道州长且许时饷酴醾作二诗以报之 其一 牡丹","f":"七言古诗","c":["我昔驱车游洛阳，正值名圃开花王。","嫣然万本斗妍媚，彫槛绰约罗红妆。","风枝似响湘浦佩，露苞如浴骊山汤。","乍惊照眼国色好，更觉扑鼻春风香。","鞓红檀点玉版白，细叶次第舒幽房。","玉奴纤指尚馀捻，鹤翎坐恐随风翔。","就中品格最奇特，共许魏紫并姚黄。","千金不惜买一醉，少年浑欲花底狂。","归来试作牡丹谱，未服秉笔惟欧阳。","自从游宦多感伤，况此远谪闽山傍。","谛观世味如嚼蜡，惜花未免犹膏肓。","亦知春色到庭户，不见此花如未尝。","子于何处得一本，赠我意厚诚难忘。","戏言剑浦此为最，聊试呼作道州长。","化工彫刻无厚薄，地气培植非其乡。","虽云单叶不入品，无那富艳踰群芳。","愿言爱惜勿嘲诮，且醉玉斝酬韶光。"]},{"t":"志宏以牡丹酴醾见遗戏呼牡丹为道州长且许时饷酴醾作二诗以报之 其二 酴醾","f":"七言古诗","c":["残阴未许春光泄，喷作沙阳三尺雪。","摧伤花卉尽枯槎，惟有酴醾寒更茁。","幽人早起傍园林，独喜枝头琼蕊缀。","应怜逐客正凄凉，折赠殷勤慰愁绝。","清香馥郁坐中飘，汲水养之殊未歇。","和烟带露愈芬芳，更许幽丛时为撷。","愁霖连日作轻寒，寂寂禅扉方昼闭。","春风骀荡好幽寻，安得连拳挂雌霓。"]},{"t":"志宏见和再次前韵 牡丹","f":"七言古诗","c":["半夜疏钟来景阳，美人梳洗随君王。","天然意态已倾国，何用苦死催严妆。","朱颜半酡宁著酒，玉肤自滑非临汤。","铅华固美岂真色，兰麝虽馥非天香。","我观牡丹正如此，勾栏横槛为雕房。","乍惊神女峡中见，只恐弄玉云间翔。","檀心点点晕深紫，金蕊簇簇摇金黄。","坐令杂花为婢妾，解使蜂蝶成颠狂。","临风袅袅更妍好，浑如舞袖踏春阳。","芳根最是洛中盛，安得千本栽砌傍。","惜花惟怕春色老，此癖谁与针其肓。","沙阳春晚始一见，如有异味争先尝。","蜡封剪处持送我，念子此意何时忘。","禅关兀坐无与语，迟迟昼景方舒长。","对花把酒不知醉，醒后还复悲殊乡。","佳篇酬和慰落寞，清丽欲与花争芳。","吟哦愈苦诗愈好，去去惜此窗前光。"]},{"t":"志宏见和再次前韵 酴醾","f":"七言古诗","c":["寒过春光还漏泄，酴醾架上花如雪。","轻盈皓色讶梅开，芬馥清香胜兰茁。","龙须初引翠蔓长，玉质全看素英缀。","结成幽洞自深沈，荫此芳醪更奇绝。","铜瓶只浸两三枝，香在根尘都不歇。","幽人赠我意已勤，却愧终朝烦采撷。","子美惟愁花欲飞，渊明自爱门常闭。","寻芳须趁春未残，更喜晴天垂彩霓。"]},{"t":"次韵招志宏见过","f":"七言律诗","c":["旰起禅房只杜门，忽思嘉客共论文。","连山雾雨密难解，隐耳雷霆惊乍闻。","我向图书端作蠹，子今胸抱欲吞云。","春堂谈笑能相就，为把沈烟细细焚。"]},{"t":"再赋酴醾赠志宏","f":"七言古诗","c":["春入酴醾如愤泄，翻空万点枝头雪。","浓花嫩蕊满柔柯，应笑蓬葭春亦茁。","东君端的衒工夫，故把琼酥巧妆缀。","含风触处便氛氲，带月看时更清绝。","幽香移入小斋中，独比馀花最难歇。","子应怜我惜春光，刺手钩衣几番撷。","却嗟草木本无情，亦解随时自开闭。","对花一醉更翻书，醉里犹能读为霓。"]},{"t":"题陈氏隐圃佚老堂二十韵","f":"五言古诗","c":["处世如大梦，悟者能有几。","钟鸣漏已尽，耽著不知止。","贤哉颍川公，才老即谢事。","悬车筑园池，归作隐君子。","大块方逸我，顺之聊复尔。","燕居二十年，坐进端为此。","委形虽物化，妙湛本无死。","我来恨不及，犹喜识其嗣。","鬓眉皓已霜，眸子炯如水。","头著白纶巾，萧散真晋士。","传家有高风，何必拾青紫。","衡门久不开，荒径为我洗。","相携步方塘，春渌涨清泚。","修篁间苍松，新槐杂嘉卉。","断桥堆露箨，危架引烟蕊。","荫庭桂团团，叠涧石齿齿。","萧森无俗姿，旷远含古意。","慰我放逐情，翛然百忧弭。","缅怀前人风，安得九原起。","相过不厌频，追随从此始。"]},{"t":"余赋佚老堂志宏见和复用前韵成一篇呈兴宗","f":"五言古诗","c":["人生期百年，得老亦无几。","超然高世士，急流贵勇止。","挂冠神武门，不与王侯事。","驱车返田庐，出关随父子。","宁知千载后，夫子亦云尔。","虚堂号佚老，游息长在此。","心閒齐物我，漏尽谢生死。","遗德蔼清芬，承家有贤嗣。","行年踰六十，遇物如止水。","岂惟诗家流，端是林下士。","闭关园日涉，不种红与紫。","满庭松桂香，月露浩如洗。","风篁自萧萧，池溜方泚泚。","知我却叩门，锄榛出芳卉。","杞菊初长苗，棠梨半含蕊。","清谈款襟抱，忘此德与齿。","境幽人复佳，发我斐然意。","作诗挂楹间，拙恶何时弭。","邓侯亦可人，佳句实予起。","抱膝更长吟，芜音惭四始。"]},{"t":"清明日","f":"七言律诗","c":["忆昔叨尘寓帝京，春光淡荡值清明。","赐来新火传红蜡，煮就香糜和白饧。","游女踏青寻苑草，戏童引线送风筝。","沙阳寂寞都无此，卧看山云听水声。"]},{"t":"上巳日","f":"七言律诗","c":["暮春祓禊集簪裾，锡燕昆明咏乐胥。","宝马骁腾随鼓吹，綵舟曼衍戏龙鱼。","闽山放逐家何在，帝里风光乐自如。","嘉节只添迁客恨，宽恩何日赋归欤。"]},{"t":"晏起","f":"七言古诗","c":["清明已过初短宵，春气困人如浊醪。","院深人静不知晓，虚堂一枕方陶陶。","觉来红日高三丈，竹影扶疏风叶响。","披衣散发久逍遥，髣髴枕痕犹颊上。","却思昔簉鹓鹭班，每听朝鸡长惨颜。","戴星侵月未为苦，冲风冒雨长艰难。","何如谪堕溪山里，钟鼓不闻春睡美。","先生梦觉本来齐，更与睡乡重作纪。"]},{"t":"戒酒","f":"五言古诗","c":["吾初不解饮，涓滴莫下咽。","自从游宦来，稍稍颇称善。","譬犹怯懦士，习惯亦能战。","作气欲吞敌，贾勇乃求殿。","迂愚撄重衅，飘泊旅异县。","怀家路迢迢，惜春花片片。","浇愁欲千钟，燕客卑九献。","浩如鲸吸川，无那壶浮箭。","欢然偶过量，浅狭诚易见。","噎呕九藏翻，昏瞀两目眩。","宿酲味尤恶，累日不欲膳。","吾生如浮沤，急景若奔电。","学道贵清虚，为文欲精鍊。","胡为事杯杓，无乃废笔砚。","先生一石醉，待诏三升恋。","枕曲与藉糟，自污何足羡。","从今梁溪翁，无复醉乡愿。"]},{"t":"岩桂","f":"七言古诗","c":["闽山气候真不常，浪蕊浮花浑欲狂。","团团岩桂著春雨，擢秀不待秋风凉。","微舒嫩叶玉剪碧，巧缀碎颗金排黄。","木如犀理自坚致，喷作十里旃檀香。","沙阳满眼皆此树，安得白露零清商。","芳根端可伴真隐，他日移植梁溪傍。"]},{"t":"志宏送岩桂并惠长篇求予赋诗次韵答之","f":"七言古诗","c":["我来闽岭值春月，坐见园林花竞茁。","殷红枝上破燕脂，嫩白稍头开玉雪。","平生苦吟缘爱奇，对花岂忍都无诗。","愧将拙句写天巧，但把浊酒酬春晖。","适来岩桂花尤好，乱缀黄英向青昊。","非时似欲斗群芳，草木无情亦相恼。","栟榈送花来觅句，端恐梁溪得归去。","谪官且作九年期，家在天涯那复顾。","何时万里吹秋风，清香伴此金芙蓉。","临风一醉百忧散，看子挥毫如彩虹。"]},{"t":"春暮平津晚望","f":"七言律诗","c":["风回雨霁已春残，景色苍茫杳霭间。","芳草渡头看绿树，白云飞处见青山。","莺啼燕语愁肠断，亲老家遥泪点斑。","却笑腐儒何所用，征商偷得半时閒。"]},{"t":"寄诸弟","f":"七言律诗","c":["自取飘零不复云，索居终日念离群。","送书未见来黄耳，陟岵惟知望白云。","素发偏亲乌鸟急，青春诸季棣华分。","天涯只有思家切，须使音声不辍闻。"]},{"t":"寄内","f":"七言律诗","c":["南迁道远不相携，锦字还嗟雁到迟。","玉臂云鬟同夜月，绣屏金鸭独香帷。","诸儿应解勤修习，稚女遥怜弄喔咿。","何日得归同隐志，孟光举案定齐眉。"]},{"t":"夜坐三绝句 其一","f":"七言绝句","c":["春夜沈沈气倍清，残编读彻忽三更。","金釭挑尽空搔首，又听檐间雨滴声。"]},{"t":"夜坐三绝句 其二","f":"七言绝句","c":["平生最喜夜看书，人静心閒乐有馀。","识尽古人兴废事，何如一枕梦华胥。"]},{"t":"夜坐三绝句 其三","f":"七言绝句","c":["中宵风雨透窗纱，独坐无聊却念家。","三月浙江无信息，寒灯何事结成花。"]},{"t":"夜坐观斗","f":"七言古诗","c":["帝车运转天沈沈，杓携龙角魁枕参。","斡旋造化岂终极，斟酌元气分阳阴。","物随南北自生死，时系俯仰成古今。","摄提大角顺所指，其馀万象徒森森。","舜观玑衡齐七政，致治不独薰风琴。","后来方士诚幻怪，罡步禬禳难究寻。","闽山春月多雾雨，夜霁天影高而深。","七星错落挂北户，芒寒色正方照临。","我来瞻仰但再拜，颇见天地照回心。","酒浆不挹西柄揭，讵敢更作诗人箴。"]},{"t":"志宏送千叶莺粟走笔代简","f":"七言古诗","c":["世传莺粟如纸花，品目不为人所嘉。","那知亦解吐繁艳，深红浅白凌朝霞。","一窠千叶类芍药，传种本自何人家。","栟榈乞得不敢惜，长须走送声呀呀。","杜门宴坐观内典，方丈寂寂如毗耶。","散花侍女一笑粲，居士默然惟啜茶。"]},{"t":"季明之子登第戏成小诗并纪岩桂之异","f":"七言律诗","c":["怪底春山桂开早，仙籍浮香远相告。","固知钟爱在贤郎，谁谓笔根无显报。","亲宾来贺如云奔，车马煌煌于氏门。","七杯燕客吾未与，应欲特开东阁樽。"]},{"t":"再赋志宏千叶莺粟","f":"七言古诗","c":["春深百草争开花，天香国色世共嘉。","谁令莺粟亦妍好，濯濯似举风中霞。","一畦同种偶千叶，巧思端属东君家。","年来居士已忘物，对花聊复一笑呀。","色空本是不二法，何用自生分别耶。","更思崖蜜煮牛乳，甘滑满瓯全胜茶。"]},{"t":"罗畴老同游栖云院瞻礼新藏","f":"五言古诗","c":["宝峰古丛林，深寂云所栖。","中有大宝藏，涌海蟠蛟螭。","庄严极精丽，金碧光陆离。","诸天渺宫殿，地轴森铁围。","雷音出妙响，震破群生疑。","天人所瞻仰，神物应护持。","吾闻金仙氏，变化难思惟。","毫端见宝刹，芥子藏须弥。","能于一尘里，法轮常转移。","谁将创物智，设此妙圆机。","佛语菩萨语，收拾靡有遗。","八万四千偈，转一弹指时。","功多用力少，权实相因依。","伟哉象教力，天造非人为。","无量大居士，精进心不疲。","夙植众德本，爰得真依归。","咄嗟檀施开，成此一段奇。","相携结胜缘，洗我既往非。","获闻第一义，刮眼资金篦。","超然脱尘垢，清净真摩尼。"]},{"t":"闻七弟叔易登科","f":"五言古诗","c":["吾家世儒业，教子惟一经。","迩来四十载，父子三成名。","忆昔尘忝初，非才厕群英。","胪传被殊渥，姓氏落寰瀛。","天子亲识擢，屡对云龙庭。","玉音每褒谕，必及吾亲宁。","同朝大明宫，搢绅以为荣。","君恩太山重，欲报鸿毛轻。","迂愚得放逐，不复叹飘零。","尔今又登第，相去才九龄。","勤劳酬素志，烜赫振家声。","箕裘端不坠，义方益芬馨。","季弟亦乡选，来年试春卿。","云鸿继高举，桂苑同飞鸣。","子壮可起家，予衰欲归耕。","勉哉脩远业，正值时休明。"]},{"t":"戏成短歌从志宏求芍药","f":"七言古诗","c":["东风不隔沙阳僻，嫩蕊浓花自春色。","栟榈也是可怜人，每送梁溪慰愁寂。","迩来芍药已盛开，供花未到吾须觅。","赋梅岂害广平刚，乞醯更觉微生直。","为将烂熳数枝红，伴我淋漓一丸墨。"]},{"t":"志宏供芍药且以诗来再赋前韵","f":"七言古诗","c":["谁道心闲缘地僻，梦里何尝有空色。","小窗一枕觉来时，燕语莺啼春寂寂。","忽思春尽芍药开，赋诗试与幽人觅。","短篇才去花已来，却愧诗词太狂直。","嫣然数朵玉楼春，何似江南称落墨。"]},{"t":"次韵罗丈留宝峰长老之作","f":"七言绝句","c":["至行孤高金不坚，犀颅鹤骨自巉然。","宝峰即是如如体，何用归休更觅禅。"]},{"t":"罗畴老所藏李伯时画马图二首 其一 蕃马","f":"七言古诗","c":["边人牧马如牧羊，群族散置初无伤。","妙哉龙眠笔有眼，作此冀北才而臧。","素纨盈尺十二匹，骨相毛物皆非常。","青骢紫燕五色满，骍骐骝骆骃骊黄。","旁行侧睨复回顾，矫首奋鬣嘶风霜。","背驰正立尽变态，意气磊落如腾骧。","想当盘礴初运思，工与造物争毫芒。","此中念虑讵可熟，至言发药诚难忘。","从此绝笔不画马，但写妙相依圆光。","斯人于今又黄土，斯画可宝宜珍藏。"]},{"t":"罗畴老所藏李伯时画马图二首 其二 御马","f":"七言古诗","c":["房星之精下天驷，产此骐驎奉天子。","龙媒徕自大宛城，汗血生从渥洼水。","那知妙手居合淝，笔端能出神俊姿。","顾视清高气深稳，志意俶傥精权奇。","兰筋秀骨连钱直，细毛萧捎丰颊臆。","金鞿络首牵奚官，自中伏波铜马式。","一疋驻立一疋行，坐看千载风云生。","鸾旗在前属车后，虽有绝足何由呈。"]},{"t":"从志宏求芭蕉","f":"五言律诗","c":["小圃初宜夏，灵蕉日日新。","轻风摇凤尾，疏雨湿青巾。","结荫留嘉客，移根许散人。","轩中拙居士，默对欲观身。"]},{"t":"松架","f":"七言律诗","c":["羁旅随缘即道场，采松结架障斜阳。","摧残自带青青色，森爽犹传细细香。","佛氏解将华作界，骚人爱把药为房。","我游法藏酬初志，宜得苍官助荫凉。"]},{"t":"再赋芭蕉","f":"五言律诗","c":["带雨移根润，惊雷展卷新。","清阴浸白氎，碧色照乌巾。","戒酒杯翻叶，挥风扇傍人。","幽姿随处好，休问不坚身。"]},{"t":"次韵志宏赠丹霞师","f":"七言律诗","c":["倾盖相逢亦有缘，那堪心契更同年。","六根净处三生现，一点通时万法全。","莲社子能知旧侣，香山我亦学癯仙。","丹霞妙悟思良觌，千偈澜翻看涌泉。"]},{"t":"葺西轩已毕工奉呈志宏成彦","f":"七言律诗","c":["华藏千函得纵观，庄严聊使道场安。","巧遮斜日青松架，旋植新花红药栏。","弹指宝楼开处速，游心法界到时宽。","含容万象犹馀地，须作毗卢丈室看。"]},{"t":"次韵畴老赠丹霞三篇并寄丹霞以代简书 其一 送次丹霞归瑞光岩韵","f":"五言绝句","c":["太虚元湛寂，妙用起云雷。","若解明如镜，何须冷似灰。"]},{"t":"次韵畴老赠丹霞三篇并寄丹霞以代简书 其二 送次丹霞归瑞光岩韵","f":"词","c":["不能汲水机圆，自笑翻羹手捩。","愿从明眼高人，为看三生宝地。"]},{"t":"次韵畴老赠丹霞三篇并寄丹霞以代简书 次自警示丹霞韵","f":"五言古诗","c":["佛法如沧溟，深广初无底。","欲以蠡测之，望洋颡已泚。","我生乃虚幻，瀛渤一沤起。","安得具眼人，为发无生理。","丹霞古禅伯，一派曹溪水。","出岫或云行，遇坎亦渊止。","谛观古文诗，相识佳句里。","闻风欲见之，踊跃不能已。","丰岩距平津，飞锡片时耳。","愿将雪澡心，试听风生齿。"]},{"t":"移花","f":"七言绝句","c":["幽人怜我葺幽轩，为植名花满槛前。","须信人穷天未厌，炎晖变作养花天。"]},{"t":"志宏送石菖蒲乃菖阳也作此诗以戏之","f":"七言古诗","c":["石上菖蒲何所拟，虬然连络龙蛇尾。","寸馀九节瘦根茎，能辅五脏坚发齿。","清泉白石养案间，璀璨芬芳诚可喜。","子于何处得此本，叶大根粗恐非是。","乞邻岂误进菖阳，遗我还将比芹子。","物虽非是意已勤，且置盆中浸寒水。"]},{"t":"兴宗许借盆荷以诗索之","f":"七言律诗","c":["隐圃清和夏景初，小盆荷芰已扶疏。","借公瓦沼开花种，伴我松轩晏坐馀。","断取当如妙喜国，庄严且作化人居。","秋风幻出芙蕖后，来去须观本一如。"]},{"t":"志宏见和西轩诗再赋前韵","f":"七言律诗","c":["休将内外别游观，一处安时在处安。","画虎若成那类狗，牧羊已熟不须栏。","芥瓶历历光明现，华藏重重境界宽。","笑指庭前花树子，为言欲作么生看。"]},{"t":"次符读书城南韵","f":"五言古诗","c":["騄骥有骏足，调御始服舆。","天资已高迈，淬砺资群书。","敏学复好问，端由方寸虚。","超然适正道，克慎在厥初。","百家见异户，六艺知同闾。","博观而妙柬，奥义将灿如。","纤缴下云鹄，沈钩出渊鱼。","精思理难遁，笃志道匪疏。","溉根食其实，浚源导成渠。","反已类学射，求心犹放猪。","精英谢糟粕，光景走蟾蜍。","寸阴宝尺璧，旨味胜浮蛆。","是中苟得趣，何适不可居。","问言何以然，得之在学欤。","譬犹大农家，丰年多蓄储。","人皆升斗窘，已独仓箱馀。","自饱以及众，博施诚乐且。","文章乃馀事，笔墨为耕锄。","当为丹山凤，勿作黔中驴。","本末固有序，未菑那得畬。","致身霄汉上，登降白玉除。","朱云既折槛，辛毗亦牵裾。","爱君当以诚，危言岂邀誉。","自古富贵者，磨灭同丘墟。","何如任直道，用舍随卷舒。","不能乃自弃，君子其疾诸。","愿言力学人，去去无踌躇。"]},{"t":"志宏供笋以诗报之","f":"七言律诗","c":["琅玕为竹铁为鞭，长就新萌本类拳。","味旨不须甜说蜜，肤腴更觉软胜绵。","锦绷与脱重重缚，玉版来参的的禅。","知子供予端有意，欲教蔬食学神仙。"]},{"t":"早起","f":"七言律诗","c":["平时懒惰只随缘，日照堂东尚栩然。","华藏欲游须勇猛，穗帷虽好莫留连。","收将枕上黄粱梦，印取心中大觉仙。","从此寓轩须早作，魔军未破可安眠。"]},{"t":"黄道夫惠纸","f":"七言律诗","c":["文房嘉楮制敲冰，遗我千番得未曾。","敢比蛮笺修五凤，愿将绮语赞三乘。","金花乍觉毫端滑，玉版尤宜墨点凝。","只恐多言空费纸，更将文吊剡溪藤。"]},{"t":"吴亲寄瓷枕香垆颇佳以诗答之 瓷枕","f":"七言律诗","c":["远投瓦枕比琼瑜，方暑清凉惬慢肤。","瑩滑色侵蕲竹簟，玲珑光照博山垆。","便便何必书为笥，栩栩方将蝶梦吾。","枕上片时聊适志，黄粱未熟到东吴。"]},{"t":"吴亲寄瓷枕香垆颇佳以诗答之 瓷垆","f":"七言律诗","c":["华藏初游愿力坚，宝垆已现佛陀前。","神通何似维摩诘，熏习聊同白乐天。","沈水香焚烟缕细，卷云花透月轮圆。","愧烦远示将何用，聊伴虚堂晏坐禅。"]},{"t":"邓成彦供茉莉以诗答之","f":"七言律诗","c":["芳花遗我比琼瑰，惭愧幽人自壅培。","名字曾于佛书见，色香今入寓轩来。","旋妆彫槛修清供，更促繁英使早开。","须信庄严资众力，道场化作雨华台。"]},{"t":"平津阁望雨","f":"七言律诗","c":["平津景物晚依依，正是梅黄麦秀时。","云气遮山来骤雨，水痕侵石涨湍溪。","蒹葭带渚披离叶，松柏连山鼓舞枝。","迁客不堪流落恨，凭高北望意凄洏。"]},{"t":"次韵题乐全庵赠邓季明","f":"五言古诗","c":["寓形天壤间，自适乃其至。","放怀得山林，肯逐市朝醉。","举世竞纷华，谁识静中意。","澄清谢泥滓，淘汰见精粹。","游心无何乡，养此浩然气。","猗欤乐全翁，于世寡所嗜。","筑庵以自居，方丈含大地。","请问庵中人，其乐何由全。","万物备我身，不以人灭天。","南亩丰可饱，北窗凉可眠。","尚友古之人，圣贤存简编。","有时自种植，百卉争芳妍。","宾来聊一醉，醉中亦逃禅。","鸡鹜自扰扰，独鹤方云骞。","嗟予幸相见，一见即忘年。","但愧闻道晚，敢怀著鞭先。","何当归梁溪，耒耜买一廛。","卜居学夫子，相望两萧然。"]},{"t":"次韵题棣华堂","f":"七言律诗","c":["沙阳地僻有幽人，三乐高怀自壮辰。","雏凤已闻栖郤桂，棣华更祝寿庄椿。","家馀美酿时觞客，手植名花日赏春。","借问市朝耽恋者，何如云水自由身。"]},{"t":"陈兴宗供茉莉","f":"七言律诗","c":["幽人萧散省诸缘，也解栽花满槛前。","羞把天姿争媚景，故将清格占炎天。","毗耶遣化来香积，隐圃移根入寓轩。","多谢庄严修妙供，愿熏芬馥散无边。"]},{"t":"季明惠含笑花其香满室以诗报之","f":"七言律诗","c":["奇葩为我摘芳条，一笑嫣然特地娇。","花露玉颜诚巧倩，叶堆云鬓愈妖娆。","韬藏妙质踰三月，喷泄清香在一朝。","更把綵丝缠绿萼，肯教芳馥片时销。"]},{"t":"萤火","f":"七言律诗","c":["雨过禅房夜气清，湿萤无数自宵行。","光穿竹树来还去，影照池塘灭复明。","飞学流星疑有意，出因腐草本无情。","暂时熠耀休凭夜，敢傍长空晓日征。"]},{"t":"泛碧斋诗","f":"七言律诗","c":["画斋初泛碧溪浔，十里津平叠翠岑。","拍岸烟波梅雨细，连天芳草岭云深。","愧烦断取西湖景，暂慰倾思北阙心。","好是清霄山吐月，水光天影共沈沈。"]},{"t":"次韵志宏见赠拙轩","f":"七言古诗","c":["梁溪之拙天下绝，六年出入黄金阙。","太官珍膳厌膻肥，谪堕沙阳甘笋蕨。","胸中空洞何所有，羞逐缁尘事奔走。","鹪鹩本是栖一枝，鲋鱼何用求升斗。","翻羹触讳拙谁如，悻悻还惭浅丈夫。","小轩燕处聊自榜，方丈迥觉含空虚。","簿书粗了多暇日，坐看日光摇霁隙。","百年销没向此中，金玉满堂何所益。","不如便作逍遥人，富贵于我如浮云。","欲知内外孰轻重，何翅鸿毛与万钧。","平生习气未能已，更续春秋修旧史。","马迁忍耻托空文，欲洗前非徒费水。","虞卿归隐亦著书，笔墨自可为欢娱。","心闲意到时一扫，何用寸寸参釐铢。","扩然无事还面壁，禅悦为床法为食。","月光照破客尘空，那有丝毫挂欣戚。","栟榈好学今所无，返从拙者来问途。","拙翁已拙更何说，万里清风一轮月。"]},{"t":"题吏隐轩","f":"七言古诗","c":["纷纷吏事何时已，随扫随生畏首尾。","那知动静不相关，安用杜门并洗耳。","曾侯作轩治丞事，雁鹜成行亦衣紫。","偷閒扫溉哦其间，壁记当须倩韩子。","榜之吏隐名者谁，梁溪拙翁前柱史。","萧然一室自可人，况有明窗兼净几。","隐中涵养得佳趣，致远自应从兄起。","王良伯乐世岂无，騕袅骅骝日千里。"]},{"t":"寄陆敦礼二首","f":"七言律诗","c":["晋河太守况如何，日对溪山醉绮罗。","肯念旧僚今逐客，强倾浊酒只悲歌。","闻说长桥跨海涯，碧天影浸白虹垂。","自嗟羁束无因到，乞取君谟大字碑。"]},{"t":"闻仲辅弟自陈便亲得南康军逍遥观","f":"七言律诗","c":["宦游方壮已抽身，始验从来懒是真。","未看昂霄摩远翮，且将戏綵慰偏亲。","我当放逐离群日，尔作逍遥自在人。","恩贷何时听从便，庐山同作远公宾。"]},{"t":"重午","f":"七言律诗","c":["谁将佳节号天中，阳极阴生五自重。","角黍但能娱幼稚，綵丝那得制蛟龙。","千年沉汨英灵在，万里浮菖习俗同。","逐客有家归未得，满怀离恨寄南风。"]},{"t":"志宏遗枯梅产芝","f":"七言律诗","c":["子家积庆芝自生，紫云为叶金为茎。","世间美瑞子不有，分以遗我鸿毛轻。","煌煌秀色照轩槛，犹带雨露凄芳馨。","当留几案永为好，他日煮食驱三彭。"]},{"t":"读四家诗选四首 其一 子美","f":"五言古诗","c":["杜陵老布衣，饥走半天下。","作诗千万篇，一一干教化。","是时唐室卑，四海事戎马。","爱君忧国心，愤发几悲咤。","孤忠无与施，但以佳句写。","风骚到屈宋，丽则凌鲍谢。","笔端笼万物，天地入陶冶。","岂徒号诗史，诚足继风雅。","使居孔氏门，宁复称赐也。","残膏与剩馥，沾足沽丐者。","呜呼诗人师，万世谁为亚。"]},{"t":"读四家诗选四首 其二 永叔","f":"五言古诗","c":["庐陵间世才，妙手归大匠。","文章振古风，独立无与两。","诗篇尤藻丽，句法含万象。","平夷谢雕镌，醇厚如酝酿。","温温廊庙姿，不作穷愁相。","平生蹈难危，利口困谗谤。","终焉自光明，学者共师仰。","每诗必言归，耕钓箕颍上。","但欲风波息，岂是事高尚。","收身及未老，六一聊隐放。","九原如可作，非公复谁向。"]},{"t":"读四家诗选四首 其三 退之","f":"五言古诗","c":["昌黎文章伯，乃是圣人耦。","传道自孟轲，渊源极师友。","雄词障百川，伟论挂众口。","馀事付诗篇，雅健古无有。","尤工用险韵，妥贴等妍丑。","毅然倔强姿，挥此摩天手。","立朝著大节，去作潮阳守。","驱扫云雾开，约束鲛鳄走。","位虽不称德，妙誉垂不朽。","譬犹观泰山，群岭皆培塿。","又如众星中，错落仰北斗。","籍湜何足云，齐名岂其柳。"]},{"t":"读四家诗选四首 其四 太白","f":"五言古诗","c":["谪仙乃天人，薄游人间世。","词章号俊逸，迈往有英气。","明皇重其名，召见如绮季。","万乘尚僚友，公卿何介蒂。","脱靴使将军，故自非因醉。","乞身归旧隐，来去同一戏。","沈吟紫芝歌，缅邈青霞志。","笑著宫锦袍，江山聊傲睨。","肯从永王璘，此事不须洗。","垂天赋大鹏，端为真隐子。","神游八极表，捉月初不死。"]},{"t":"夜坐观书","f":"七言绝句","c":["铜漏丁丁杂雨声，夜凉兀坐已三更。","十年奔走成何事，依旧韦编对短檠。"]},{"t":"读李长吉诗","f":"五言古诗","c":["长吉工乐府，字字皆雕锼。","骑驴适野外，五藏应为愁。","得句乃足成，还有理致不。","呕心古锦囊，绝笔白玉楼。","遗篇止如此，叹息空搔头。"]},{"t":"读孟郊诗","f":"五言古诗","c":["我读东野诗，因知东野心。","穷愁不出门，戚戚较古今。","肠饥复号寒，冻折西床琴。","寒苦吟亦苦，天光为沈阴。","退之乃诗豪，法度严已森。","雄健日千里，光铓长万寻。","乃独喜东野，譬犹冠待簪。","韩豪如春风，百卉开芳林。","郊穷如秋露，候虫寒自吟。","韩如锵金石，中作韶濩音。","郊如击土鼓，淡薄意亦深。","学韩如可乐，学郊愁日侵。","因歌遂成谣，聊以为诗箴。"]},{"t":"足成梦中","f":"七言绝句","c":["本来佛法无多子，正觉菩提弹指超。","谁信曹溪一滴水，流归法海作全潮。"]},{"t":"纸笔墨尽戏成","f":"七言律诗","c":["我生飘泊苦西东，四子相逐半世中。","越楮如云随散灭，绛玄终日困磨砻。","秃怜毛颖频遭斥，静爱陶泓解困穷。","一笑寓轩无所有，本来文字相皆空。"]},{"t":"梅雨","f":"七言律诗","c":["小麦青青梅正黄，连山雾雨湿溪乡。","轻丝袅袅摇空界，重滴涓涓响暮廊。","结集郁蒸来海峤，驱排愁恨到禅房。","寓轩居士心如铁，默坐惟闻茉莉香。"]},{"t":"初见荷花","f":"七言律诗","c":["雨过芙蕖满曲塘，端疑翠盖拥新妆。","风翻圆碧田田叶，露浥深红苒苒香。","根出淤泥成妙净，气侵虚阁愈清凉。","开花不待秋风起，景物依然类浙乡。"]},{"t":"志宏以家所生新芝遗予并以诗来次韵报之","f":"七言古诗","c":["紫芝多产白玉峰，服食益寿增明聪。","人间采茹未易得，怅望古曲来悲风。","那知远谪见奇物，子家端是庆所钟。","煌煌三秀岂难并，玉干云叶方成丛。","嘉祥美瑞不自惜，掇以遗我诚由中。","甘芳胜菌滑胜乳，能杀三尸驱九虫。","童颜瞭视驻可久，堕发落齿生应重。","嗟予迂疏与世阔，得食此物谁之功。","商山傥可追四皓，淮南安用寻八公。","骖鸾控鹤吾未暇，千里白云聊与同。"]},{"t":"畴老修撰所藏华岳衡岳图 华岳","f":"七言古诗","c":["往年跨马观羌戌，道历太华西临雍。","伟哉造化巧凝结，元气孕此金芙蓉。","平原陡起三万仞，峻屏却略罗秋空。","巍然雄尊镇西极，众山班列如朝宗。","天池潋滟喷山顶，泻作瀑布飞长虹。","亭亭仙掌摩碧落，晓日照耀五指红。","巨灵赑屃运神力，导河擘华留其踪。","烟寒风远张超谷，霞駮雾开毛女峰。","希夷故隐今尚在，白云依旧时东封。","回头一别二十载，不意见之图画中。","生绡六幅挂清昼，隐耳飒飒闻松风。","山中草木旧相识，恍如梦到云台宫。","神游绝巘窥玉井，欲取莲藕根株通。","好奇何必似韩子，悬崖侧足悲途穷。","从公传此岳真相，永结清好无时终。"]},{"t":"畴老修撰所藏华岳衡岳图 衡岳","f":"七言古诗","c":["五岳分奠如循环，作镇南服惟衡山。","炎方荒绝亘沧海，天付雄柄司神奸。","祝融腾掷倚霄汉，群峰逦迤犹堂坛。","赞襄一气泄云雨，蟠据千里来荆蛮。","屹然天地物最钜，造化凝结良艰难。","恭闻兹岳魏夫人，羽驾白日游山樊。","翛翛云气变异色，笙竽声杂环佩珊。","神仙恍惚未易测，落花流水空潺潺。","退之倔强古亦少，故取窜谪窥孱颜。","精神默祷若有应，驱扫氛翳开烟鬟。","乃知正直神所与，露奇呈巧初不悭。","嗟予平生好山水，欲以两足穷跻攀。","恨兹羁束未能往，幽觌眇然图画间。","何当身逐雁同到，已觉心与云俱閒。","轩辕弥明傥未死，相与游戏超尘寰。"]},{"t":"与邑官会凝翠阁","f":"七言古诗","c":["屹然高阁虚且通，溪山增秀来薰风。","皆云闽境似此少，岂但为最沙阳中。","栋楹显敞制度巧，饰以黝白非青红。","七峰倒景蘸层碧，十里平津流向东。","连山松桧郁葱茜，一溪烟雨寒冥濛。","沈沈月彩照清夜，漠漠云影摇苍穹。","眼光到处色皆翠，凝结至今劳化工。","几年落寞顾眄地，拈出始知观览雄。","开筵置酒共临赏，正暑景物生秋容。","画船笳吹助清咽，津岸击鼓声逢逢。","世间万事非偶尔，成此一段传无穷。","我归三子子归我，毕竟假合谁之功。","人生会合自可乐，且须吸尽玻瓈钟。","他时追忆如梦寐，一笑胜游回首空。"]},{"t":"偶题二首 其一","f":"七言律诗","c":["金仙实语教观空，老氏微言戒知足。","生前能著几两屐，安用胡椒八百斛。","此身犹自是蘧庐，身外何须宝金玉。","一衣一食便有馀，从此梁溪须窒欲。"]},{"t":"偶题二首 其二","f":"七言绝句","c":["退之呵佛乃知佛，王莽崇儒岂信儒。","救弊自须烦诋毁，即真安用假诗书。"]},{"t":"寄吴元中给事","f":"七言律诗","c":["千里同风一念间，琳宫筦库等为閒。","高怀自遂全三乐，懵学于今见一斑。","顾我望云惟陟岵，羡公戏彩日承颜。","何时恩许归终养，因得扁舟事往还。"]},{"t":"寄顾子美提举","f":"七言律诗","c":["闻说年来亦失官，高怀应作等閒看。","傥来本自非吾有，既往何须更返观。","问舍梁溪欣共里，寄声闽岭慰南冠。","请公学取安心法，一点安时在处安。"]},{"t":"绝句","f":"七言绝句","c":["断云飞雨过溪来，檐溜萧萧泻暮阶。","一饷清凉驱热恼，可怜襟抱向谁开。"]},{"t":"次韵罗修撰古风","f":"五言古诗","c":["衡岳临清湘，欲往吾无航。","侧身长太息，心逐雁南翔。","洪河擘太华，欲往吾无马。","何当御风游，挥手与世谢。","公家藏二图，尤物伴閒暇。","那知造化工，寓此粉墨假。","一见慰我心，试使画工写。","峥嵘峻极姿，惨澹生笔下。","旧游得窥寻，真赏寄持把。","轻云出层峰，飞瀑落高罅。","川原蔼林芿，山崦露台榭。","幽讨穷双眸，驻立劳两胯。","图成挂虚堂，秋色忽改夏。","清风扫凉朝，明月炚深夜。","恍然疑断取，无乃资幻化。","作诗聊谢公，更辱报章洒。","清新鄙元白，风流追屈贾。","气象岳争雄，讽玩手忘舍。","观图更得诗，端如饱脍炙。","什袭藏箧中，光铓照林野。"]},{"t":"罗修撰宠示龙兴老碑刻","f":"七言律诗","c":["龙兴道与右文亲，眼照沙阳肯许人。","师唱宗风非鼓笛，公谈实相托冠巾。","已曾见了何须再，特地拈来却未真。","公案分明在碑刻，不烦师子更频呻。"]},{"t":"五月三日夜坐达旦谩成","f":"七言古诗","c":["凉风振野星河翻，煌煌启明夜将阑。","孤灯照我不成寝，兀坐更将图史翻。","蠹穿编简眼昏瞀，彫琢肺肾声嘶酸。","胡为疲极浪自苦，中有至乐难为言。","窥寻古意偶有得，何翅九奏闻钧天。","拨书就枕还自笑，聊此游戏终吾年。"]},{"t":"季明送南中花木","f":"七言律诗","c":["悟道方知色即空，乐全深得种花功。","愿从真隐师为圃，敢意芳根与乐丛。","陶令欲归三径老，海神更借一帆风。","梁溪异日凭栏处，把酒看花定忆公。"]},{"t":"苦热行","f":"七言古诗","c":["南方苦暑殊中州，金遇火伏相拘囚。","飞鸢跕跕草木愁，疑在炉冶遭蒸烰。","六龙中天停厥辀，火云突兀烧高丘。","炎风如焚汗翻油，祝融嘘呵不肯休。","赤脚踏冰邈难求，返视絺绤犹狐裘。","行人病暍喘车牛，虽处广厦非所庥。","我欲登彼白玉楼，侧身西望心悠悠。","何当万里来清秋，其帝少昊神蓐收。","飒然风露洗我忧，凉生暑退火西流。","四时代谢如环周，及兹又作徂年谋。","人生寒暑为寇雠，何异疟疠脂髓搜。","有力负走藏壑舟，朱颜绿发安可留。","以静胜躁聊优游，何必远期汗漫游。"]},{"t":"次韵志宏戏兴宗耳疾之作","f":"五言古诗","c":["有病自当医，无垢何须洗。","六解一亦亡，动容皆中礼。","谛观新卷叶，成此清净耳。","悟道得圆通，教体真在此。","虚含十方界，遐迩初无里。","铿然助发机，妙响非外宄。","天人种种声，和会归一已。","奈何物蔽之，问药安可止。","通以智慧刀，濯以功德水。","是病速须除，慎勿听邓子。"]},{"t":"夜坐闻笛","f":"七言绝句","c":["栉栉银云点太清，一天风露月华明。","数声何处吹横笛，引起离家去国情。"]},{"t":"同罗畴老邓季明燕凝翠阁泛碧斋","f":"七言律诗","c":["法界惟心在处安，胜游须信得时难。","云峰远并山峰碧，天影深摇溪影寒。","去国不知流落恨，亲仁且尽笑谈欢。","夜凉风露生舟楫，皓月遥升白玉盘。"]},{"t":"六月十八日同陈兴宗邓成彦志宏早会凝翠阁晚游泛碧斋","f":"五言古诗","c":["高阁凝虚翠，虚斋泛碧川。","七峰连秀色，万户锁晴烟。","风物悲游子，登临集众贤。","伊蒲修净供，香雾缭芳筵。","嗜酒陶元亮，狂吟白乐天。","嫩菱披紫角，新荔擘红圆。","文字真清饮，溪山结胜缘。","画桥横螮蝀，绣岭卧蜿蜒。","落日生气霭，移舟信溯沿。","星河光耿耿，风露气涓涓。","山吐三更月，人游半夜船。","乱萤行熠耀，宿鹭立联拳。","尽兴忘归棹，衔杯约倒莲。","乘槎疑犯汉，御气欲登仙。","但有诗千首，何妨谪九年。","深惭二三子，陪我亦萧然。"]},{"t":"十六日泛舟","f":"五言律诗","c":["小雨破残暑，移舟佳致多。","烟岚远增翠，云水暮相和。","散绮霞依日，摇金月委波。","胜游非易得，不饮欲如何。"]},{"t":"七峰诗序 朝阳峰","f":"七言绝句","c":["先得朝阳一段红，何年鸣凤集梧桐。","归舟行到湾环处，知是沙溪第一峰。"]},{"t":"七峰诗序 碧云峰","f":"七言绝句","c":["落日衔山隐半轮，桑榆残照起游氛。","佳人怅望何时见，万里平凝合碧云。"]},{"t":"七峰诗序 妙高峰","f":"七言绝句","c":["叠嶪层峦枕碧流，七峰此地最奇幽。","登临若会妙高意，便识德云真比丘。"]},{"t":"七峰诗序 真隐峰","f":"七言绝句","c":["杳霭青松映白云，地灵境寂好栖神。","结庐占尽溪山景，安得超然真隐人。"]},{"t":"七峰诗序 桂华峰","f":"七言绝句","c":["桂华岁岁吐秋风，香满溪城十里中。","怪底士夫多折得，移根初自广寒宫。"]},{"t":"七峰诗序 凝翠东峰","f":"七言绝句","c":["两峰凝翠对飞檐，缺处青岑出远尖。","暮雨朝云时点缀，何须画栋与珠帘。"]},{"t":"七峰诗序 凝翠西峰","f":"七言绝句","c":["翠峰高阁两相宜，独倚阑干注目时。","休问江山非故国，且将爽气慰梁溪。"]},{"t":"七峰诗序 太史溪","f":"七言绝句","c":["平溪渌静见游鱼，十里无声若画图。","但道曾经太史爱，不须污染目为愚。"]},{"t":"次韵志宏泛碧斋会连饮三罚爵","f":"七言律诗","c":["占得溪山作散仙，更欣佳客许邀延。","醉红岂解胜文字，举白还能乐圣贤。","序饮我方追柳子，赋诗子已过刘颠。","乱云细细无情致，不放银蟾上碧天。"]},{"t":"次韵志宏见示 其一","f":"七言律诗","c":["胡马依风亦北嘶，云鸿随候且南飞。","奏刀久爱庖丁善，鼓瑟聊同曾点希。","举世浑如蚁穴梦，何人解契箭锋机。","我观法界皆真宅，不必吾家始是归。"]},{"t":"次韵志宏见示 其二","f":"七言律诗","c":["谪从天上堕人寰，惟有清风夜款关。","皓月一轮窥笔砚，白云千里映溪山。","我因拙误无方治，子以才鸣有意攀。","须信全齐千驷景，未如陋巷一瓢颜。"]},{"t":"次韵湖阴曲","f":"七言古诗","c":["绣鞍玉勒黄金鞭，跃马直入无玉钱。","绕营三匝人不识，天风翻动旌旗鲜。","贼臣昼寝苍黄起，梦里阳乌光照水。","追风铁骑去非迟，真主那从贼中死。","宝鞭传玩日凄凄，行远不闻天马嘶。","千金安用试虎口，将帅何如思鼓鞞。","西南大星寒有铓，画衣绣衮垂平章。","九重宫殿锁春色，岂如万里秦城长。"]},{"t":"次韵东坡四时词四首 其一","f":"七言律诗","c":["玉栏花发惟愁落，风捲柳绵穿绣幕。","绕池烟草碧成茵，夹竹露桃红破萼。","美人半醉软香肌，不语凭栏知恨谁。","莫把春愁自销损，且唱樽前金缕衣。"]},{"t":"次韵东坡四时词四首 其二","f":"七言律诗","c":["深院沉沉清昼永，画屏玉枕冰肌冷。","辘轳惊起宝钗横，香篆浮烟帘幕静。","翠眉不为捧心颦，鬓乱妆残约略匀。","情似杨花无定处，可怜金谷堕楼人。"]},{"t":"次韵东坡四时词四首 其三","f":"七言律诗","c":["梧桐叶脱苔滋绿，绮窗寂寂风敲竹。","笑将红扇扑流萤，戏剪碧荷装宝屋。","深沉玉宇夜长扃，风露凄凉可一庭。","步月清霄携手处，谁家笛作断肠声。"]},{"t":"次韵东坡四时词四首 其四","f":"七言律诗","c":["参横叶落阑干角，夜气侵人觉衣薄。","香醪只怕玉樽空，残灯旋剔金釭落。","梦回酒醒听啼鸦，起看霜晴日衬霞。","笑道红梅夜来发，临阶自摘一枝花。"]},{"t":"将游栟榈二首 其一","f":"七言律诗","c":["栟榈百里远沙溪，水石称为小武夷。","千古碧潭涵夜月，两涯翠巘拂朝霓。","猿猱饮涧联修臂，棕木连云擢老枝。","天下幽奇多僻远，只疑造物恶人知。"]},{"t":"将游栟榈二首 其二","f":"七言律诗","c":["栟榈闻说自栟榈，且往观之盍问途。","我向烟霞已成癖，子于水石更能娱。","古来胜地因人重，他日清游载酒俱。","会把丹青传画取，归来与对武夷图。"]},{"t":"荔枝词集句","f":"词","c":["开元天子万事足，惟惜当年光景促。","昭阳殿里第一人，十幅红绡围夜玉。","梦中同蹑凤凰翎，归作霓裳羽衣曲。","沉香亭北倚阑干，缓歌慢舞凝丝竹。","回眸一笑百媚生，尽日君王看不足。","崩腾献荔枝，百马死山谷。","一骑红尘妃子笑，婕妤传诏才人索。","绛纱囊里水精丸，不是人间香味色。","渔阳鼙鼓动地来，血污游魂归不得。","明眸皓齿今何在，金盘玉箸无消息。","汉主山河锦绣中，三十六宫土花碧。","不见玉颜空死处，泪痕血点垂胸臆。","片段荔枝筐，此心炯炯君应识。"]},{"t":"畴老见示荔枝绝句次韵","f":"七言绝句","c":["炎月南闽丹荔子，绛绡微皱裹明珠。","金盘数颗已堪赏，何况莆阳十万株。"]},{"t":"陈兴宗和示耳聋诗颇佳再次其韵","f":"五言古诗","c":["天公有眸子，犹把明河洗。","况我聪与明，听乐而视礼。","是心有天游，神用寄双耳。","良哉观世音，圆通端自此。","世人竭耳力，所听不踰里。","闻性含虚空，物蔽乃为宄。","区区假药医，不若求诸己。","虚室既生白，吉祥自止止。","潇洒隐圃翁，灵台湛如水。","须识本来人，莫认贼为子。"]},{"t":"尝新橄榄二绝句 其一","f":"七言绝句","c":["岂无崖蜜十分甜，竞爱清严解变甘。","堪笑区区弃捐者，半途回味始知惭。"]},{"t":"尝新橄榄二绝句 其二","f":"七言绝句","c":["蠲痾毒药宁便舌，逆耳忠言却利行。","世上但能珍橄榄，那知言药更甘清。"]},{"t":"松架敝以新枝易之","f":"七言律诗","c":["日曛雨濯半飘零，旋采虬枝荫广庭。","风动细香还泛泛，露滋新叶更青青。","虽惭剪伐劳斤斧，犹胜烧燃竞爝萤。","凉夜苍龙尚吟啸，坐看明月入重扃。"]},{"t":"偶作","f":"七言律诗","c":["休问梁溪何所为，应缘日用且随时。","朝看藏典聊遮眼，夜阅韦编未觉疲。","独酌飘零一杯酒，狂吟敏捷百篇诗。","困来打睡饥来饭，游戏神通谁得知。"]},{"t":"晚虹","f":"七言律诗","c":["小雨初收杳霭中，日华照作美人虹。","五重绚彩萦层汉，数幅轻绡飏远风。","饮涧未应占美恶，干阳何必问雌雄。","桑榆暮色苍然至，隐隐犹拖半段红。"]},{"t":"白鹭","f":"七言绝句","c":["白鹭孤飞映碧峰，皎如片雪落轻风。","徊翔意态虽容与，心在清波寸鬣中。"]},{"t":"以蜜渍荔枝寄远","f":"七言律诗","c":["远谪南闽食荔枝，始知图记不予欺。","欲将千颗封题去，无那三朝色味移。","蜜渍仅能存典则，日乾愈更失珍奇。","欲知妙质为何似，甘露明珠绛縠皮。"]},{"t":"石轮鱼","f":"七言律诗","c":["广寒宫阙夜不锁，蟾蜍飞下清溪涯。","爬沙厥状虽可怪，脆美一脔亦莫加。","颇笑退之嘲蛤蚧，还同子厚甘虾蟆。","晚凉雨霁小池满，两部鼓吹空哇哇。"]},{"t":"次韵丹霞宗本长老见寄古风","f":"五言古诗","c":["帝居郁沉沉，梧桐植朝阳。","愧将燕雀翼，参彼鹓鸾行。","含香待黼座，秉笔立明光。","谁知汲黯戆，忽作朱云狂。","襆被出都门，濯缨走沧浪。","饱闻瑞光岩，道席久振芳。","识高行复苦，皎月照严霜。","醍醐有妙味，薝卜无馀香。","愿闻第一义，洗我浩劫茫。","闭关不肯出，未许窥高墙。","徒将非舌语，远寄烦宣扬。","秋风动樵水，何日思褰裳。"]},{"t":"次韵丹霞录示罗畴老唱和诗四首 其一 和古风","f":"五言古诗","c":["快哉善知识，能以种种喻。","我今亦乐说，渐修与顿悟。","顿如草木芽，荄核已完具。","又如大明镜，色像悉陈露。","渐如鸡哺雏，羽翼劳覆护。","又如苗成实，非一朝夕故。","邈然孤峰顶，邂逅适相遇。","历历亲见之，非是梦而寤。","却来共谈说，妙契那复遌。","精勤假修习，即得无生趣。","清净摩尼珠，初无尘垢污。","圆成一滴水，岂殊千里霔。","妙药须对治，能起膏肓痼。","欲观皎日轮，当去漫天雾。","铁轮顶上旋，不复有惊怖。","劫火洞燃时，自有安身处。","了兹一大事，馀外复何顾。","庭前柏树子，古庙香炉去。","孤云与独鹤，何往不可寓。","返观生死海，便是涅槃路。","普化示全身，达磨携只屦。","證道坐菩提，降魔成露布。","乃知费千谈，不若行一步。","丹霞真道人，愿力极坚固。","眼从慧中得，法乃佛亲付。","疋马与单枪，纵横自驰骛。","愿见缘未合，临风增景慕。","何以写予怀，继此龙津句。"]},{"t":"次韵丹霞录示罗畴老唱和诗四首 其二 和太华庵闻牡丹芍药花香","f":"七言绝句","c":["嘉卉多生佛氏宫，一经鼻观便圆通。","妙香来处非和合，岂在根尘吸染中。"]},{"t":"次韵丹霞录示罗畴老唱和诗四首 其三 和舫斋观鱼","f":"七言绝句","c":["鳞鬣从容戏碧漪，拈槌击拂更无疑。","闻经听法都休说，自是鱼中有导师。"]},{"t":"次韵丹霞录示罗畴老唱和诗四首 其四 和小庵晏坐","f":"七言绝句","c":["一缕铜炉沉水烟，庵中晏坐孰为禅。","灵山法会何曾散，莲社高风尚宛然。"]},{"t":"题丹霞晏坐轩","f":"七言律诗","c":["白云深处开虚室，晏坐非禅亦非律。","须观任四威仪中，皆悉具六波罗密。","超然处处坐道场，善哉步步能踏实。","我今此义亦妄言，请师往问维摩诘。"]},{"t":"次韵江滋秀才见寄","f":"七言律诗","c":["拙直从知慕古风，吾衰不复梦周公。","心如葵叶虽终日，身逐溪流且向东。","华藏千函游佛界，黄粱一枕悟仙翁。","何当放浪尘埃外，回首沧洲兴未穷。"]},{"t":"罗畴老录示和丹霞绝句五首次韵 其一","f":"七言绝句","c":["丹霞只在笑谈中，明月清风万里同。","欲识德云真面目，却须行到妙高峰。"]},{"t":"罗畴老录示和丹霞绝句五首次韵 其二","f":"七言绝句","c":["非佛非心须在我，即心即佛亦从渠。","本来心佛都无有，幻化聊将示四衢。"]},{"t":"罗畴老录示和丹霞绝句五首次韵 其三","f":"七言绝句","c":["扬眉下喝亦皆空，此性初无瞽与聋。","若信见闻非耳目，瞽聋却解振宗风。"]},{"t":"罗畴老录示和丹霞绝句五首次韵 其四","f":"七言绝句","c":["晃耀灵光真有体，从横妙用本无踪。","须弥芥子非虚语，事理从来本自融。"]},{"t":"罗畴老录示和丹霞绝句五首次韵 其五","f":"七言绝句","c":["片云出岫当何在，独鹤摩空自识回。","若会去来无二相，丹霞应肯下岩来。"]},{"t":"次韵种果绝句","f":"七言绝句","c":["分枝擢干倏花开，长养初从寸许栽。","欲识菩提能结果，灵根端自个中来。"]},{"t":"寄题丹霞雨花轩","f":"七言律诗","c":["小轩幽邃敞岩峦，密雨飞来更可观。","瀑布千寻落峰顶，喷珠万点散檐端。","休言幻化成空果，且喜炎蒸作昼寒。","轩内生公常说法，天花乱坠响珊珊。"]},{"t":"次韵志宏见示山居二首 其一","f":"七言律诗","c":["千仞青山一草堂，萧然远去利名场。","夜凉愈觉风月好，雨过惟闻松桂香。","野寺春朝喧鸟雀，田家日夕下牛羊。","因公录示山居作，使我归休意转忙。"]},{"t":"次韵志宏见示山居二首 其二","f":"七言律诗","c":["知章本是四明狂，珥笔聊依日月光。","谪宦未从南亩乐，傲时自爱北窗凉。","溪山胜处陪诗社，文字空中见法王。","何必更求难老术，得閒身世自舒长。"]},{"t":"七夕 其一","f":"七言绝句","c":["银河清浅界烟霄，欲渡何须乌鹊桥。","今我去家千里远，却怜牛女会今宵。"]},{"t":"七夕 其二","f":"七言律诗","c":["云潢斜界耿秋空，灵匹相过此夕中。","璀璨珠星连璧月，凄凉玉露坠金风。","三秋景物随时好，万里瓜花习俗同。","乞巧未能从柳子，送穷聊欲效韩公。"]},{"t":"十三夜有小偷迨晓而获志宏戏以诗来次其韵","f":"七言律诗","c":["夜半偷儿亦可怜，乘虚欲负壑中船。","银杯羽化方搜箧，绣被风飘遽返毡。","妄意室中真有道，夺从虎口岂徒然。","贪夫一笑心为咎，举体空能发爱涎。"]},{"t":"垓下","f":"七言古诗","c":["鸿沟已画天下分，汉王未肯空回军。","诸侯大会壁垓下，戈甲耀日如屯云。","夜闻四面楚歌起，天命人心知去已。","拔山盖世霸图空，却叹当时骓不逝。","帐中美人身姓虞，悲歌起饮聊踟蹰。","数行泪下竟别去，仓皇不得同驰驱。","明眸皓齿为黄土，草木含愁照今古。","依然听曲自低昂，岂忆平生离别苦。"]},{"t":"秋日","f":"七言律诗","c":["人言一叶已知秋，万叶凋零愈更愁。","蝉噪风林朝嘒嘒，虫吟露草夜啾啾。","溪山信美非吾土，诗酒多情解客忧。","极目江乡何处是，月华依旧照西楼。"]},{"t":"次韵和李太白感秋","f":"五言古诗","c":["秋风从西来，敲我庭下竹。","夜凉月窥樽，清光如可掬。","风月岂故人，万里慰愁独。","披衣从之游，更欲邀共宿。","泠然洗我心，耿耿安用卜。","三十八年非，庶以不远复。","俯仰天地间，平生皆可覆。","一醉梦还家，黄粱犹未熟。"]},{"t":"秋暑戏题","f":"七言律诗","c":["少昊行秋尚炽然，祝融何事苦侵权。","欲呼屏翳来清道，却恨羲和懒著鞭。","盐米相仍无日了，图书拨置且閒眠。","个中自有清凉地，不在中间及两边。"]},{"t":"七月二十四日泛舟","f":"五言律诗","c":["秋暑殊未已，泛舟成胜游。","日斜云影乱，风迥水光浮。","鹭起暮山碧，蝉吟高木幽。","销愁图一醉，醉眼更多愁。"]},{"t":"次韵志宏秋晓见示古风二首 其一","f":"五言古诗","c":["庭户晓萧骚，寒声起疏苇。","凄然惊客梦，秋色浩如水。","南方苦炎热，羁旅困泥滓。","及兹风露凉，又复悲宋子。","散策东篱下，佳菊有新蕊。","美人渺何在，明月共千里。","缁尘敝紫貂，锦字寄黄耳。","欲赋秋风辞，烟云愁落纸。"]},{"t":"次韵志宏秋晓见示古风二首 其二","f":"五言古诗","c":["苦热喜新凉，萧萧响黄苇。","雨馀山吐辉，沙没溪涨水。","天高气澄明，太清无秽滓。","泠然欲御风，一访赤城子。","笑读香霞篇，时餐金蛾蕊。","逝将游蓬瀛，弱水三万里。","咄嗟无羽翰，相望徒劳耳。","不如且赋诗，蛇蚓动盈纸。"]},{"t":"秋雨","f":"七言律诗","c":["飒然风雨作新凉，卧听檐声气韵长。","驱扫炎蒸逐流火，招邀秋月到虚堂。","日边梦断甘飘泊，泽国音稀堕渺茫。","犹喜北窗灯可近，简编为释九回肠。"]},{"t":"读韩偓诗并记有感 其一","f":"五言古诗","c":["唐室昔不竞，天纲遂陵迟。","阉竖擅朝政，奸雄肆觎窥。","天子遭迫胁，翠盖蒙尘飞。","矢石集黄屋，四郊皆鼓鼙。","群凶虽殄灭，国命亦已移。","韩子司翰苑，实被昭宗知。","忠言虽屡贡，颠厦诚难支。","谪官旅南土，召复不敢归。","当时白马驿，从横卿相尸。","投之浊流中，至今耆旧悲。","夫子乃幸免，祸福良难期。","假道寓沙阳，空门知所依。","虽踰二百载，犹传赠僧诗。","邑令真好事，作记刊丰碑。","文辞虽浅陋，事实颇可追。","读之三叹息，吊古情悽洏。","寄声藏去者，擅有将奚为。"]},{"t":"读韩偓诗并记有感 其二","f":"七言绝句","c":["词臣谪去堕天南，诗墨从来榜寺檐。","好事不须收拾去，世间遗集有香奁。"]},{"t":"志宏复示秋意五篇次韵和之 其一","f":"五言古诗","c":["秋风到枕前，策策鸣窗苇。","起看山吐月，残夜楼明水。","皎月与我心，清净两无滓。","玉露滴烟霄，飘然杂桂子。","姮娥应笑人，仳离放红蕊。","乘风游广寒，三十亿万里。","宫阙不胜寒，九奏感人耳。","不如且世间，浩歌书著纸。"]},{"t":"志宏复示秋意五篇次韵和之 其二","f":"五言古诗","c":["秋色一夜改，白露漙苍苇。","冠屦变凄清，如濯沧浪水。","慢肤素多汗，执热结成滓。","振衣得新凉，俨若侍君子。","起观庭中花，露叶耿烟蕊。","景物但可人，溪山即吾里。","浮生驹过隙，百年一瞬耳。","惟有古圣贤，高名在毫纸。"]},{"t":"志宏复示秋意五篇次韵和之 其三","f":"五言古诗","c":["秋风振回溪，宿鹭起汀苇。","孤飞一片雪，寒影落烟水。","羽毛可为仪，皓洁绝埃滓。","心迹两翛然，邈若佳公子。","却栖碧山岑，瑶树发琼蕊。","岂知黄鹄心，一举眇千里。","翔集太液池，彼此皆戏耳。","丹青虽善画，为我拂水纸。"]},{"t":"志宏复示秋意五篇次韵和之 其四","f":"五言古诗","c":["秋风入虚堂，凄微带烟苇。","堂中拙居士，湛然如止水。","默坐观是心，自觉无纤滓。","不知读何经，但说舍利子。","心清闻妙香，天花散芳蕊。","含容河沙界，方寸知几里。","神光常在目，妙响不离耳。","处处获圆通，谁云钻故纸。"]},{"t":"志宏复示秋意五篇次韵和之 其五","f":"五言古诗","c":["秋兴殊未极，秋溪可杭苇。","顺流欲东行，一观沧溟水。","洗我万古愁，胸中瑩无滓。","又欲归梁溪，候门有稚子。","携幼酒盈樽，泛此东篱蕊。","躬耕复著书，茗饮追甫里。","听子场屋声，入我山林耳。","文字惊世人，一日传万纸。"]},{"t":"题寓轩","f":"七言律诗","c":["秋到寓轩殊不恶，满庭爽气有馀清。","架松著雨须髯奋，盆沼因风鳞甲生。","葵向日光金盏侧，荷翻露颗玉盘倾。","焚香默坐无人会，自觉诸缘次第轻。"]},{"t":"江月五首 其一","f":"五言律诗","c":["一更山吐月，金篆缭轻澜。","清光满四海，独向沙阳看。","桂魄缘空迥，云峰醮影寒。","姮娥谩愁思，相对漏声残。"]},{"t":"江月五首 其二","f":"五言律诗","c":["二更山吐月，风露霭清夜。","待月泛兰舟，停桡碧峰下。","樽罍兴未穷，枕簟凉可藉。","言携二三子，吊古相与话。"]},{"t":"江月五首 其三","f":"五言律诗","c":["三更山吐月，羁客方独起。","起游溪上阁，胜景乃如此。","露满七峰松，烟笼一川水。","奔走尘埃间，顾未之知耳。"]},{"t":"江月五首 其四","f":"五言律诗","c":["四更山吐月，夜静月尤明。","玉梳挂碧落，银汉自从横。","寥泬群动息，溪中有舟行。","吾家渺何在，极目望江城。"]},{"t":"江月五首 其五","f":"五言律诗","c":["五更山吐月，禅室正清幽。","星河光破碎，钟鼓起高楼。","展转不成梦，冷落还悲秋。","五咏继苏子，谁为商声讴。"]},{"t":"玉局有眉子石砚歌予来沙阳独携一圆砚乃眉子石也戏次其韵","f":"七言古诗","c":["美人多恨颦双眉，眼波秋水增清奇。","天然此石巧相似，儒生作砚声酸嘶。","横云惨淡远山碧，犹带深闺画时色。","金坚玉润月轮圆，笑杀世间铜雀渴。","十年提挈随拙翁，相携谪堕溪山中。","窗明几净日相对，风露夜永灯光红。","毛颖陈玄用功处，发秃肌销留不住。","与君长此结幽欢，我自多言子无语。"]},{"t":"次韵虢国夫人夜游图","f":"七言古诗","c":["金鞍玉勒连钱骢，车如流水马如龙。","遗簪堕珥碎珠翠，蜜炬夜入蓬莱宫。","曲江宫殿春蒲柳，玉盘犀箸传纤手。","坐中绰约尽天人，锦茵云幕清无尘。","赐名大国动光彩，马嵬回首空啼痕。","我欲题诗吊千古，丧国亡家皆此路。","嫣然一笑倾人城，皓齿明眸真女虎。"]},{"t":"次韵俞祖仁寒翠亭翠字韵","f":"五言古诗","c":["爱奇走山林，蜡屐穷幽閟。","萧然岩壑趣，乃在经行内。","缅怀谪仙人，名湖自张谓。","至今郎官湖，邈与岘山对。","我游古兰若，殿阁烟霞外。","眷兹道傍亭，胜境久翳昩。","洗开松竹林，寒色霭苍翠。","戏题榜间名，笔墨聊自恣。","时方春雨馀，涧水正横溃。","泉声落亭前，散作珠点碎。","景物岂殊昔，因之不遐弃。","佳哉二三子，诗酒作文会。","留连不忍去，吟哦薄昏晦。","我咏诗中言，端有亭上味。"]},{"t":"次韵志宏见示寒翠亭之作","f":"五言古诗","c":["虚亭枕山麓，万籁如笙箫。","佳哉松竹林，飒然风露秋。","我题亭上名，过客为少留。","所嗟结搆小，未称山光浮。","缅怀琅琊亭，醉翁昔曾游。","今我聊复尔，一洗胸中愁。","数子真好事，佳句相与搜。","会当同胜会，及此月如钩。"]},{"t":"题陈公叙舫斋","f":"五言古诗","c":["一心寓百骸，是身已虚舟。","寄形天壤间，大块日夜浮。","矧兹数椽屋，结搆溪山幽。","假以舫为名，谛观有异不。","行藏本一体，渊止同川流。","萧然斋中人，悟此复何求。","但闻泉石美，景物方清秋。","安得造其上，一与龟鱼游。"]},{"t":"邓成彦以寒字韵长句来次韵答之","f":"七言古诗","c":["蓬莱东隔沧溟宽，我欲游之恨无翰。","崆峒西峙冰雪积，崛起万仞良难攀。","不如随寓忻所惬，放逐爱此沙阳山。","苍松拂云雨溜溜，古涧凿石泉潺潺。","远峰三叠碧玛瑙，脩竹个个青琅玕。","烟霞缥缈巧妆缀，极目秀色如可餐。","就中此亭更幽绝，泠然爽气洗我肝。","命名题字聊一戏，坐觉景物增清寒。","子为胜游真得侣，纤月正挂青云端。","诗篇雕琢愁肺肾，笔力渐阔生波澜。","当观佳致本来有，拈出便作一倍看。","百壶何必事狂饮，一斗自足资幽欢。","夜乘小艇鼓归棹，平溪十里初不关。","更须风露稍凄冷，相约同自亭中还。"]},{"t":"和志宏见示亭字韵","f":"五言古诗","c":["今日苦不乐，驾言适林坰。","散策寻远寺，披襟坐虚亭。","云木上窈窕，涧泉泄清泠。","千山自岑寂，一目皆葱青。","嗟我得数子，不复叹飘零。","扫虑味禅悦，茹蔬谢荤腥。","时为亭上游，散发缓我形。","騄骥行振足，倦鸟思归翎。","何当返梁溪，教子名添丁。","林泉益自得，华发从星星。"]},{"t":"秋虫","f":"五言律诗","c":["白霜降百草，候虫寒自吟。","不知抱何恨，唧唧无停音。","歘尔惊客梦，悽然感离心。","羁臣肠欲断，岂事雍门琴。"]},{"t":"中秋望月次玉局翁韵二首 其一","f":"五言古诗","c":["明月如玉盘，飞上青霄东。","徘徊斗牛间，照我禅室中。","爽气霭亭户，清光透帘栊。","我虽不解饮，敢辞玉樽空。","举酒对明月，起舞聊相从。","身世两翛然，如游广寒宫。","夜久风露冷，草根吟候虫。","咽咽不能已，岂自鸣其穷。","天涯多雾雨，好景诚难逢。","哦诗不成寝，颇类鱼噞喁。"]},{"t":"中秋望月次玉局翁韵二首 其二","f":"五言古诗","c":["皎皎月华白，寥寥秋气清。","念我方远客，步月亭中行。","风露感我心，凄然入重扃。","谁家弄横笛，巧作断肠声。","独酌一壶酒，对此千里明。","人生但自适，何必四者并。","醉眼视万物，扰扰如浮萍。","得丧何须道，譬犹阴与晴。","节义太山重，富贵鸿毛轻。","我心与明月，照见万古情。"]},{"t":"又次韵中秋长句","f":"七言古诗","c":["凉风吹空明月高，清光万里见秋毫。","银云栉栉方解駮，河汉掩映如波涛。","须臾扫尽无多子，天影悠悠碧于水。","冰轮正午久停鞭，群动寂然声不起。","谛观此月真跳丸，山河倒影犹蛇蟠。","桂华耿耿巳澄洁，秋气凛凛增清寒。","前年望月都城汴，只恐中霄风雨变。","一杯相属有情亲，侧耳歌楼闻鼓板。","今年望月沙阳山，照我心如铁石坚。","美人千里共明月，遥想闺中只独看。","空庭步月更幽好，白露漙漙湿烟草。","开编况对古圣贤，发愤忘忧不知老。","男儿本自甘贱贫，富贵名传能几人。","题诗对月到日出，锦囊何似庞眉客。"]},{"t":"和陶渊明归田园六首 其一","f":"五言古诗","c":["我家梁溪傍，门对九龙山。","山中有幽趣，游息可忘年。","陆子泉最甘，次之即龙渊。","馀波作梁溪，可溉万顷田。","公垂读书堂，古屋尚数间。","我欲隐山下，诛茅占其前。","疏泉凿池沼，植竹来云烟。","纵目望震泽，策杖登山巅。","神游八极表，心迹两超然。","更结莲社侣，远追竹林贤。"]},{"t":"和陶渊明归田园六首 其二","f":"五言古诗","c":["秋风动梁溪，何日理归鞅。","放逐正拘囚，寤寐劳梦想。","新诗聊慰今，旧事那追往。","缅怀故山居，杞菊苗应长。","挂冠神武门，便欲学疏广。","躬耕南亩云，实报无卤莽。"]},{"t":"和陶渊明归田园六首 其三","f":"五言律诗","c":["落叶不可数，枝间绿将稀。","节物一如此，感叹何时归。","庭闱眇千里，箧藏老莱衣。","从兹就閒旷，勿使吾心违。"]},{"t":"和陶渊明归田园六首 其四","f":"五言古诗","c":["寂灭乃可乐，纷华何足娱。","百年会有尽，富贵同邱墟。","不如早抽身，卜此山林居。","手植松与桂，青青三万株。","幅巾坐其下，萧散谁如吾。","衣食粗饱暖，身在即有馀。","归依金仙氏，妙契端不虚。","借问名利者，还有此乐无。"]},{"t":"和陶渊明归田园六首 其五","f":"五言律诗","c":["膝横五弦琴，试鼓南风曲。","寄傲北窗下，便觉此生足。","开怀酒一壶，寓意棋一局。","既使风扫门，还将月为烛。"]},{"t":"和陶渊明归田园六首 其六","f":"五言古诗","c":["贫者无置锥，富者连阡陌。","嗟予亦何幸，伏腊粗能适。","但使岁事丰，便足给朝夕。","人生几何时，倏如驹过隙。","惟当适我心，安能供物役。","著书聊寄怀，底之或可绩。","吾身虽不遇，吾言期有益。"]},{"t":"次韵和渊明饮酒诗二十首 其一","f":"五言古诗","c":["是心本纯白，利害俶扰之。","陶然到醉乡，还此未扰时。","古人重酒德，妙意端在兹。","嗟予数杯量，径醉不复疑。","既得醉中趣，安用杯常持。"]},{"t":"次韵和渊明饮酒诗二十首 其二","f":"五言律诗","c":["醉中忘万物，一视渊与山。","坠车神不惊，庄周非寓言。","是乡岂华胥，逸乐不记年。","谁能造其域，勿为薄俗传。"]},{"t":"次韵和渊明饮酒诗二十首 其三","f":"五言古诗","c":["世俗愈浇薄，惟酒陶真情。","如何遁世士，更以酒自名。","嗟我方远谪，慷慨念平生。","酌此一壶酒，宠辱那复惊。","醉中露天机，往往以诗鸣。"]},{"t":"次韵和渊明饮酒诗二十首 其四","f":"五言古诗","c":["骏足有远步，逸翮无卑飞。","羁絷因罗网，惨澹终年悲。","得酒且欢喜，醉乡真所依。","路稳良易到，时和可忘归。","不复梦周公，甚矣吾其衰。","惟当饮醇酎，此志慎勿违。"]},{"t":"次韵和渊明饮酒诗二十首 其五","f":"五言古诗","c":["独酌有真趣，何须歌管喧。","既醉谢羁束，不知冠屦偏。","扶挟烦侍女，颓然倾玉山。","方游无何乡，命驾殊未还。","醒来念前乐，欲辩诚难言。"]},{"t":"次韵和渊明饮酒诗二十首 其六","f":"五言律诗","c":["异论相矛盾，儒墨竟谁是。","仲尼虽大圣，宁免叔孙毁。","得酒当痛饮，忘形相汝尔。","采芝白云中，愿学园与绮。"]},{"t":"次韵和渊明饮酒诗二十首 其七","f":"五言古诗","c":["风露飒秋色，东篱菊有英。","泛此忘忧物，宽我羁旅情。","故人饷佳酝，樽空还自倾。","云外鸿雁度，堂中蟋蟀鸣。","忽忽岁将暮，聊复乐此生。"]},{"t":"次韵和渊明饮酒诗二十首 其八","f":"五言古诗","c":["我本田野人，萧然岩壑姿。","麋鹿喜丰草，鹪鹩安一枝。","误学霸王略，肯吐陈平奇。","世故乃如此，拙谋何所为。","宾至且饮酒，吾身岂长羁。"]},{"t":"次韵和渊明饮酒诗二十首 其九","f":"五言古诗","c":["嘉葩含团香，气至辄自开。","置之白玉堂，可慰君子怀。","少有高世心，壮年此志乖。","君门植梧桐，参彼鸾凤栖。","谋身一何拙，堕此百尺泥。","却笑东方生，取容事诙谐。"]},{"t":"次韵和渊明饮酒诗二十首 其十","f":"五言古诗","c":["四方有定位，醉中初不迷。","立志既尔尔，岂复中道回。","珥笔螭殿坳，谪官鲸海隅。","庭闱在千里，山川阻脩途。","梦中欣得还，亦复劳驰驱。","觉后谋一醉，三杯即有馀。","何当听从便，返我梁溪居。"]},{"t":"次韵和渊明饮酒诗二十首 其十一","f":"五言古诗","c":["三径渊明居，一区子云宅。","吾生诚易足，处静期息迹。","负郭千亩田，种秫当八百。","酿为瓮盎春，悠然举大白。","于世复何求，安用长太息。"]},{"t":"次韵和渊明饮酒诗二十首 其十二","f":"五言古诗","c":["饮酒资红裙，其乐未为至。","欢然文字饮，兴逸不知醉。","放怀溪山间，雅饮亦其次。","裸裎岂是达，温克乃足贵。","醉乡谁不到，未必能知味。"]},{"t":"次韵和渊明饮酒诗二十首 其十三","f":"五言古诗","c":["樽俎为舟车，游此醉乡境。","但愿未死前，常醉不用醒。","醒来寓翰墨，万事劳总领。","譬犹锥处囊，脱出终露颖。","虎豹岂犬羊，文章自彪炳。"]},{"t":"次韵和渊明饮酒诗二十首 其十四","f":"五言古诗","c":["吾年行四十，意气非少时。","世故茫不识，惟好古人词。","篇章自娱悦，适意良在兹。","此外付之拙，直道不复疑。","黄卷千万言，圣贤岂吾欺。","世事皆分定，饮酒姑安之。"]},{"t":"次韵和渊明饮酒诗二十首 其十五","f":"五言古诗","c":["萌心皆拙谋，游世用直道。","乐天吾何忧，发愤不知老。","惟有杯中物，可以慰枯槁。","三杯颊生红，便觉颜色好。","曲生端可友，金玉非吾宝。","醉中亦慨然，志节还表表。"]},{"t":"次韵和渊明饮酒诗二十首 其十六","f":"五言古诗","c":["少年学神仙，日诵琼笈经。","交梨与火枣，丹鼎期必成。","呼吸存夜气，宴坐至五更。","岂知糟曲中，醉乡即黄庭。","玉池滟生肥，天鼓常自鸣。","酩酊欲仙去，超然离世情。"]},{"t":"次韵和渊明饮酒诗二十首 其十七","f":"五言律诗","c":["霜林陨寒叶，淅淅随西风。","拙翁感节物，颓然坐轩中。","独酌一樽酒，不知穷与通。","栖鸟忽惊去，子岂曾伤弓。"]},{"t":"次韵和渊明饮酒诗二十首 其十八","f":"五言古诗","c":["人以谪而穷，我因谪而得。","博考圣贤书，独立愈不惑。","世道迭污隆，时命有通塞。","驾言游醉乡，疑是华胥国。","漠然无是非，于此可以默。"]},{"t":"次韵和渊明饮酒诗二十首 其十九","f":"五言古诗","c":["结发观国光，壮年跻膴仕。","怀恩重泰山，欲报轻小己。","幸立不讳朝，缄默诚可耻。","晨趋玉陛前，暮谪闽山里。","飘零若萍梗，此志谁复纪。","行藏岂异途，川流与渊止。","不如饮美酒，世态何足恃。"]},{"t":"次韵和渊明饮酒诗二十首 其二十","f":"五言古诗","c":["举世人事伪，惟酒存天真。","饮多不如少，饮醨不如醇。","借问何以然，每醉意每新。","笑指黄金罍，是中可逃秦。","糠秕铸尧舜，万世同埃尘。","二豪侍坐侧，议论徒慇勤。","我读古人书，独与渊明亲。","北窗傲羲皇，桃源将问津。","膝横无弦琴，头著漉酒巾。","我醉君且去，为已非为人。"]},{"t":"桃源行","f":"七言古诗","c":["武陵溪水流潺潺，渔舟鼓枻迷溯沿。","溪穷路尽恍何处，桃花烂漫蒸川原。","花间邑屋自连接，云外鸡犬声相喧。","衣裳不同俎豆古，见客惊怪争来前。","杀鸡为黍持劝客，借问世上今何年。","自从秦乱避徭役，子孙居此因蝉联。","不知汉祖以剑起，况复魏晋称戈鋋。","慇勤留客不肯住，落花流水空依然。","渊明作记真好事，世人粉饰言神仙。","我观闽境多如此，峻溪绝岭难攀缘。","其间往往有居者，自富水竹饶田园。","耄倪不复识官府，岂惮黠吏催租钱。","养生送死良自得，终岁饱食仍安眠。","何须更论神仙事，只此便是桃花源。"]},{"t":"隐圃岩桂盛开兴宗屡以为供赋长篇以谢其意并简志宏","f":"七言古诗","c":["沙阳岩桂虽云多，不若隐圃为骈罗。","结根盘据极高大，荫庭一亩才数科。","青葱翠盖俯轩槛，夭矫苍虬交枝柯。","森森密叶碧如玉，扑扑细蕊黄于鹅。","风传剩馥尚酷烈，月散清影长婆娑。","幽香岂止到十里，妙质端恐移金波。","不随春景斗妍媚，直与秋色争清和。","芳鲜似欲伴佳菊，冷落更觉怜衰荷。","幽人爱此自培植，林下不知双鬓皤。","为予折赠诚有意，欲遣鼻观通禅那。","吾衰万事付之懒，不饮奈此秋光何。","径须造诣谋一醉，莫待花落沾庭莎。","妙香吸引入肺腑，吐作佳句同吟哦。"]},{"t":"四花四首 其一 芙蓉","f":"七言绝句","c":["浥露披风浩莫收，嫣然秀色照清秋。","佳人日暮来何处，翠袖红妆相对愁。"]},{"t":"四花四首 其二 金灯","f":"七言绝句","c":["叶卷须虬朵朵圆，化工如解刻雕然。","金灯玉柱归天上，何事生来小槛前。"]},{"t":"四花四首 其三 红蕉","f":"七言绝句","c":["但见风来摇翠尾，那知露下濯红英。","色空须信元同体，谁把丹青与染成。"]},{"t":"四花四首 其四 鸡冠","f":"七言绝句","c":["花蕊成冠巧学鸡，刻雕谁谓染胭脂。","晓来得雨犹鲜好，却似昂然欲斗时。"]},{"t":"从邓季明求菊花","f":"五言古诗","c":["乐全治幽圃，种花如种田。","秋来菊有花，亦复争芳妍。","璀璨碧玉蕾，散作黄金钱。","风静香自远，露寒色争鲜。","乃知万物性，皆欲全其天。","九日忽已近，渊明思悠然。","愿移东篱下，植此西轩前。","我有一壶酒，泛之可延年。","不嫌盘箸薄，同作饮中仙。"]},{"t":"灯花","f":"五言律诗","c":["禅室方清夜，寒灯自结花。","那知人有喜，且慰客思家。","琐碎星铓密，红圆玉粒斜。","为传千里信，安稳到天涯。"]},{"t":"秋日有感","f":"五言古诗","c":["秋水澹澄澈，秋山郁嵯峨。","我游溪山亭，山空水增波。","感此物华暮，风林摇落多。","惟有青青松，独立不改柯。","乔然傲霜霰，岁晏将如何。"]},{"t":"秋思十首 其一","f":"五言律诗","c":["朝来秋色高，西山有爽气。","开轩远相望，自得静中意。","那知宋玉悲，肯洒杨朱泪。","逍遥天地间，俯仰可无愧。"]},{"t":"秋思十首 其二","f":"五言律诗","c":["夜永秋气凉，泠然入窗牖。","照眼一编书，开怀一壶酒。","念身幸无恨，齿发犹未朽。","富贵如浮云，于我亦何有。"]},{"t":"秋思十首 其三","f":"五言律诗","c":["南方秋节晚，九月始凄清。","草木忽摇落，坐使客心惊。","橐籥无暂息，机缄殊不停。","未能超物外，慷慨念平生。"]},{"t":"秋思十首 其四","f":"五言律诗","c":["露下秋草衰，蒹葭亦苍苍。","森然岩中桂，十里飘天香。","深林静杳冥，无人自芬芳。","采掇满禅室，闲中气味长。"]},{"t":"秋思十首 其五","f":"五言律诗","c":["秋云澹无依，皛皛映寒日。","卷舒谁使之，聚散在倏忽。","出岫本无心，行空宁有质。","功成归何方，妙用藏于密。"]},{"t":"秋思十首 其六","f":"五言律诗","c":["秋风晚萧索，凄然遂成林。","百谷欲成实，见此造物心。","清凉入户牖，天光为沈阴。","禅房有羁客，抱膝正长吟。"]},{"t":"秋思十首 其七","f":"五言律诗","c":["秋风动禾黍，泛泛凄芳馨。","散策步田野，欣此百谷成。","林下父老醉，云间鸡犬声。","丰年诚可乐，安得遂吾生。"]},{"t":"秋思十首 其八","f":"五言律诗","c":["秋月照我心，清光奈愁何。","回薄万古恨，月愁应更多。","独饮不成醉，溯月空长歌。","安得一丸药，高奔伴姮娥。"]},{"t":"秋思十首 其九","f":"五言律诗","c":["古后有明训，霜降休百工。","草木日摇落，蟋蟀鸣堂中。","岂不感时节，念此岁复穷。","劳生真一梦，飘泊随西东。"]},{"t":"秋思十首 其十","f":"五言律诗","c":["百卉秋具腓，先陨惟梧桐。","岂无贞洁者，独立青霜中。","艳艳篱下菊，青青岭头松。","与君为德友，相好永无穷。"]},{"t":"邓成彦病以诗来问所以治病者作诗答之","f":"七言古诗","c":["四大假合初不真，筋脉缠络相依因。","□□□□类芭蕉，须叟变灭如浮云。","风寒暑湿起众疾，痛楚展转劳吟呻。","医工对治巧用药，分别佐使甘酸辛。","须知病者谁受病，其中必有不病人。","于斯荐取自调伏，沈痾消散如埃尘。","本来面目只一体，安用更分精与神。","欲识其中不病者，即是毗卢清净身。"]},{"t":"兴宗志宏见和岩桂长篇再赋前韵奉呈","f":"七言古诗","c":["月中有桂光更多，扶疏一轮枝干罗。","天风飘下广寒子，岂与凡种同其科。","四时不改碧玉叶，满庭自擢青铜柯。","森然众木共培植，无异野鹤群鸡鹅。","秋来隐圃风露冷，喷花看蕊尤婆娑。","圃中自有隐君子，心与世远恬无波。","对花度此九秋色，不以物外伤天和。","西邻栟榈更好古，妙年欲制芰与荷。","连墙请谒不知倦，宜尔鬓发忘其皤。","天生逸才当有用，委弃寂寞理则那。","吾衰尚有惜花意，零落奈此馨香何。","却思梁溪有小圃，只恐松竹荒寒莎。","未能归去老三径，且把诗句从公哦。"]},{"t":"九日","f":"七言律诗","c":["常年九日必题诗，况此飘零海一涯。","黄菊未开青蓓蕾，白醪聊吸碧玻瓈。","登山但极孤云目，整帽还羞短发篦。","弟妺奉亲倾寿斝，茱萸遍插定吾思。"]},{"t":"菊花开日即重阳二首 其一","f":"五言律诗","c":["南方气候殊，佳月即中秋。","昨者月既望，萧萧风雨愁。","安得一轮玉，清光满溪楼。","酌酒自起舞，与之相献酬。"]},{"t":"菊花开日即重阳二首 其二","f":"五言律诗","c":["南方气候殊，有菊即重阳。","九日今已近，青蕊未可尝。","安得黄金花，泛此白玉觞。","会当烂漫开，为插满头香。"]},{"t":"次韵杜子美九日蓝田崔氏庄","f":"七言律诗","c":["远谪须知怀抱宽，节逢九日亦追欢。","手挼青蕊看浮盏，蜡剪黄花戏插冠。","淅淅斜风飞败叶，萧萧细雨作轻寒。","天涯只是思亲切，更把家书再四看。"]},{"t":"和陶渊明采菊东篱下二首 其一","f":"五言古诗","c":["九日但孤坐，悄然无世喧。","菊花殊未开，始知气候偏。","开轩寓远目，相对惟青山。","昏鸦已接翅，独鹤何时还。","且尽杯中物，此外无足言。"]},{"t":"和陶渊明采菊东篱下二首 其二","f":"五言古诗","c":["小雨湿丛菊，何当喷金英。","嚼蕊亦可人，萧然慰我情。","羁旅念家远，浊酒还独倾。","云表雁初过，草根虫自鸣。","岁晏将如何，一醉豁平生。"]},{"t":"寓轩用竹为窗隔以禦西风戏成小诗纪其事示志宏","f":"五言古诗","c":["昔我自帝所，远谪来沙阳。","由春以涉夏，及此秋气凉。","节物日凄紧，白露结为霜。","行当入室处，聊复葺我堂。","伐竹制窗牖，朴素无青黄。","西风屏寒色，短日来孤光。","草木已零落，但闻菊蕊香。","超然适燕处，便足傲羲皇。","释氏戒恋著，一宿寄枯桑。","今我日必葺，于道无乃荒。","彼以著故戒，无著何所妨。","譬犹梦中境，离著可两忘。","傥能达此理，随寓皆道场。"]},{"t":"传画美人戏成","f":"七言古诗","c":["美人颜色娇如花，鬒发光翳朝阳鸦。","玉钗斜插翠眉蹙，岂亦有恨来天涯。","画工善画无穷意，故把双眸剪秋水。","丹青幻出亦动人，况复嫣然能启齿。","年来居士心如灰，草户金锤击不开。","纵教天女来相试，虚烦云雨下阳台。"]},{"t":"传画忠义图","f":"五言古诗","c":["君臣以道合，言出心莫逆。","膏泽下于民，美化施无极。","中世此道衰，言如水投石。","义士以死争，直谏或有益。","折槛制留今，断鞅事存昔。","当车血污轮，伏蒲涕沾席。","昭然贯日诚，屹尔回天力。","谁将丹青手，图此忠义迹。","传之置坐隅，能使懦夫激。","斯人不复见，壮哉古遗直。"]},{"t":"四皓","f":"七言绝句","c":["皓发庞眉四老翁，商山采尽紫芝丛。","安刘毕竟成何事，空堕留侯巧计中。"]},{"t":"高祖","f":"七言绝句","c":["落魄刘郎仗众谋，无心将将却成优。","谁言大度能容物，旧怨还封羹颉侯。"]},{"t":"得家信报淮南飞蝗渡江入浙岁事殊可忧感而赋诗","f":"七言绝句","c":["闻说飞蝗起自淮，势如风雨渡江来。","我家岁事何须虑，只恐人言不是灾。"]},{"t":"九月十四夜月蚀","f":"七言律诗","c":["碧落遥升白玉盆，云何中夜黯然昏。","初疑半被微云掩，浸恐全无巨吻吞。","惨淡乍看蟾魄出，扶疏更喜桂华存。","妖蟆磔死犹馀罪，此外群星尽可原。"]},{"t":"读刘向传","f":"七言绝句","c":["昼观书传夜观星，感愤陈辞出至诚。","梓柱指明王氏切，优柔不断岂能行。"]},{"t":"题李伯时画老子出关图","f":"七言律诗","c":["请说常无众妙门，当时关尹意何勤。","青牛西去连沙漠，紫气东来见瑞氛。","妙法不离三十辐，至言都在五千文。","世人不解宗慈俭，只欲长生蹑白云。"]},{"t":"题入定僧持法师画像","f":"七言律诗","c":["形若龙蛇千岁蛰，神如日月四时新。","岂知鸡足山中客，元属莲华社里人。","岭上祖师提只履，烟中普化露全身。","拘拘守定乾皮袋，毕竟如何始是真。"]},{"t":"题富郑公画像","f":"词","c":["天骄自昔难羁縻，凭陵中夏侵北垂。","秦城万里堑山谷，汉女远嫁为阏氏。","赫然武帝事征伐，天下骚动士马疲。","古来制禦无上策，本朝镇抚诚得宜。","祖宗守边有良将，胡骑远遁不敢窥。","澶渊之役起仓卒，当时众议何其危。","莱公庭争乃亲讨，貔虎百万从六飞。","弩机暗发虏酋殒，震怖屈膝祈完归。","欢盟从此到今日，生灵休息诚赖之。","中间桀骜邀岁赐，悬河之辩亦莫支。","笃生郑公为民社，一言剖决遂不疑。","莱郑之功实终始，配入太庙铭鼎彝。","我生后公不及识，再拜图像涕泗洟。","安得如公之人在廊庙，坐使德泽渐烝黎。"]},{"t":"明妃曲","f":"七言古诗","c":["昭君自恃颜如花，肯赂画史丹青加。","十年望幸不得见，一日远嫁来天涯。","辞宫脉脉洒红泪，出塞漠漠惊黄沙。","宁辞玉质配夷虏，但恨拙谋羞汉家。","穹庐腥膻厌酥酪，曲调幽怨传琵琶。","汉宫美女不知数，骨委黄土纷如麻。","当时失意虽可恨，犹得千古诗人誇。"]},{"t":"九月十五日夜同陈兴宗邓志宏登凝翠阁观月","f":"七言律诗","c":["溪阁临虚面势宽，凉天佳月共追欢。","渔舟忽动水光碎，桂魄未高山影寒。","色染林峦烟漠漠，气侵笑语露漫漫。","须知此景人间少，更泛兰桨远处看。"]},{"t":"是夜复乘泛碧斋至北溪口观新桥与兴宗志宏分题予得泛字","f":"五言古诗","c":["秋高气倍清，夜静舟初泛。","露华浩如洗，月色寒可鉴。","林峦与邑屋，左右入轩槛。","晶荧星影摇，崷崒山光蘸。","风微烟羃羃，溪远波湛湛。","端疑客乘槎，坐使云河犯。","观梁且停桡，恋月愁系缆。","景幽费摹写，思妙造古淡。","吾方久于此，胜赏岂云暂。","愿同二三子，险韵时得探。"]},{"t":"志宏得碧字以诗来次其韵","f":"五言古诗","c":["明月照清溪，影落千寻碧。","轻风皱微澜，荡漾摇金色。","相携理桂楫，及此万籁寂。","天空露气寒，栖鸟正缩瑟。","何人起秋思，数弄月中笛。","坐使迁客情，悽然感去国。","清游得英俊，胜赏饱泉石。","岂殊在吾家，亲戚欬于侧。","赋诗各言怀，险韵对勍敌。","归来气未衰，开匣看三尺。"]},{"t":"兴宗得斋字以诗来次其韵","f":"五言古诗","c":["佳月霭秋色，翛然感予怀。","言携二三友，泛此溪中斋。","风露生万里，屋木凭两涯。","凄微烟雾合，芬馥天香来。","恍若度云汉，奔月游瑶台。","灏气集肺腑，洒濯无纤埃。","沉沉夜寥阒，回舟兴悠哉。","澄波静如练，何异浮江淮。","但恨景物美，实难赋咏才。","斯文当共勉，天意属吾侪。"]},{"t":"凝翠晚望五绝句 其一","f":"七言绝句","c":["白蘋红蓼满汀洲，淅淅西风古渡头。","寒日无情又西下，清溪不语水东流。"]},{"t":"凝翠晚望五绝句 其二","f":"七言绝句","c":["桂香泛泛满秋风，十里沙溪一望中。","景物随时慰牢落，羁臣那解感飘蓬。"]},{"t":"凝翠晚望五绝句 其三","f":"七言绝句","c":["日轮隐隐落西山，尚有残阳木杪间。","暮暮朝朝成底事，可怜飞鸟自知还。"]},{"t":"凝翠晚望五绝句 其四","f":"七言绝句","c":["林中轻素起寒烟，两两飞鸥傍钓船。","心在江湖归未得，晚来幽独更悽然。"]},{"t":"凝翠晚望五绝句 其五","f":"七言绝句","c":["白云点破乱山青，影落寒溪晚更明。","谁谓天涯无雁到，雍雍初听两三声。"]},{"t":"秋意二首 其一","f":"七言绝句","c":["萧萧南浦白云秋，枫叶芦花相对愁。","何必更穷千里目，乱山凝碧满溪楼。"]},{"t":"秋意二首 其二","f":"七言绝句","c":["清霜夜落梧楸树，脱叶惊风陨如雨。","一番扫尽一番新，策杖闲将黄叶数。"]},{"t":"和唐人张为秋醉歌","f":"五言古诗","c":["秋风愈凄紧，感此梁溪翁。","烟水出砂石，风霜脱梧桐。","岁晏无与欢，步屧携苍筇。","俯视槛中菊，仰瞻峰顶松。","有酒聊自适，旋滴真珠红。","长鲸吸百川，坐使玉樽空。","念古壮气激，怀家归兴浓。","陶然不知醉，如堕烟雾中。","醉魂眇安往，梦渡江水东。","髣髴生六翮，飘忽腾双龙。","醒来无所见，溪冷山重重。","纱窗透残月，瓦枕来疏钟。","起视夜将阑，星河粲玲珑。","乘风欲轻举，骨肉疑都融。","却思向来醉，岂离方寸地。","长醉不用醒，萧然谢名利。"]},{"t":"读陆龟蒙散人歌三复而悲之赋诗以卒其志","f":"七言古诗","c":["江湖散人气节奇，布衣韦带霜鬓垂。","有田甫里多水潦，阖门百指长号饥。","躬耕粗足输赋税，时赴嘉客同襟期。","西风笠泽起秋色，菰蒲初熟鲈鳜肥。","扁舟乘兴不知晚，笔床茶灶常相随。","著书丛杂自编录，巧怪不择文与诗。","那能枉道窃爵禄，但欲乱世全妻儿。","胸中岂无佐时略，却笑诸郎殊不知。","当年富贵尽磨灭，惟有夫子传于斯。","三高名配范与李，散人虽散元非痴。"]},{"t":"岩桂再开尤盛汲水养之其香满室堕蕊几案间灿然可爱嗅玩因为赋小诗","f":"七言律诗","c":["桂华十里凌霜空，再开愈觉秋光浓。","幽人赠我不知数，芬馥飘满禅房中。","蔌蔌风枝堕烟蕊，璀灿金英沾案几。","不须扫去任飘零，从使清香在毫纸。"]},{"t":"游栖云寺","f":"五言古诗","c":["清晓戒徒御，出郊为胜游。","霜林半摇落，肃穆天地秋。","散策陟峻岭，凭高瞰清流。","禅居得兰若，迥觉林泉优。","露草凄更碧，风松郁相缪。","山空钟磬响，地胜池台幽。","竹色森不改，桂香泱漭浮。","经行岂莲社，景物如虎丘。","流水人寂寂，归云晚悠悠。","惜哉光景促，妙赏难淹留。","却步出山径，犹回恋山眸。","登临兴未尽，更理溪中舟。"]},{"t":"自西津乘泛碧斋归邑小雨","f":"七言律诗","c":["乱山深处翠光浮，山寺归来泛彩舟。","十里峰峦凝翠霭，一溪烟雨洒清秋。","渔灯照水明还暗，野桂飘香散不收。","只向画中求好景，不知身在画中游。"]},{"t":"是日闻报御笔许牵复有感","f":"七言律诗","c":["闻有佳音自日边，羁臣感极却悽然。","矜愚本自加三宥，作赋休云谪九年。","戏膝但能纡彩服，侍香那复望青毡。","恩隆天地当何报，击壤为氓老一廛。"]},{"t":"画荔枝图","f":"七言古诗","c":["南闽荔枝名四方，非因谪官那得尝。","丁香为核玉为叶，绛绡为壳冰为瓤。","烱如明珠出老蚌，灿如艳女披红裳。","膜凝云母本来薄，液贮甘露初不浆。","剖擎颇讶水晶滑，咀嚼但觉琼瑶香。","贡馀虽幸得一饱，无那品目多难详。","丹青巧为拂绢素，数种磊落皆其良。","牛心最大蚶壳褊，虎皮斑駮龙牙长。","火山早依炎气熟，中元晚待秋风凉。","色奇更变江家绿，味旨尤称十八娘。","葡萄结实极繁盛，硫黄著子何芬芳。","若将牡丹与比并，好把陈紫同姚黄。","虽云香味不可画，悦目自足垂虚堂。","饫餐更得画归去，须信远谪元非狂。"]},{"t":"丛菊数日来颇有开意戏题","f":"五言律诗","c":["爱菊如渊明，凭栏惜花晏。","朝来有开意，嫩蕊肥欲绽。","愿承玉露漙，一吐金英粲。","临风嗅馨香，为尔发三叹。"]},{"t":"得了翁书并寄石芝云其味初淡中苦已而发甘鲜有此味者感而赋诗","f":"七言古诗","c":["海日气射苍崖根，石上生枝乾藓文。","构梯采掇资好事，中有至味难为言。","岂惟食淡兼攻苦，嚼蜡茹荼多欲吐。","清甘徐发齿颊间，漱以寒泉如饮乳。","幽人赠我意已深，一掬可比千黄金。","世间此味知者鲜，往往既吐还追寻。","我欲持之献君子，自古至言多逆耳。","愿于苦处辨忠良，若待回甘真晚矣。"]},{"t":"次韵和归去来集字十首 其一","f":"五言律诗","c":["少负丘壑志，误婴轩冕荣。","刚肠难隐忍，懒性倦将迎。","学佛欣自得，谪官知物轻。","悠悠势利子，千古见交情。"]},{"t":"次韵和归去来集字十首 其二","f":"五言律诗","c":["壮志已衰落，颓然成懦夫。","编须休虎穴，曳尾且龟涂。","松菊犹可理，田园将欲芜。","亲朋悦情话，浊酒在觞壶。"]},{"t":"次韵和归去来集字十首 其三","f":"五言律诗","c":["轩冕岂足恋，田园诚可欢。","村村自花柳，物物寄游观。","旧事不复忆，吾生良易安。","南窗审容膝，归去学鲵桓。"]},{"t":"次韵和归去来集字十首 其四","f":"五言律诗","c":["闻说诏初下，预知归有期。","趣装行去矣，俟命且安之。","出处宛如梦，去来惟有诗。","为传千里信，先报棣华知。"]},{"t":"次韵和归去来集字十首 其五","f":"五言律诗","c":["旷荡推新泽，迂疏念昔非。","休为贾生赋，且治老莱衣。","报国抚长剑，怀亲歌式微。","凭高望吴越，千里白云飞。"]},{"t":"次韵和归去来集字十首 其六","f":"五言律诗","c":["寤寐在亲所，得归欣载奔。","綵衣犹在笥，素发已垂门。","遣兴诗千首，忘忧酒一樽。","归欤理三径，松菊故应存。"]},{"t":"次韵和归去来集字十首 其七","f":"五言律诗","c":["归去复归去，溪山满眼前。","公垂馀旧馆，鸿渐有甘泉。","结宇依青嶂，开池浸碧天。","馀波到山下，更溉万家田。"]},{"t":"次韵和归去来集字十首 其八","f":"五言律诗","c":["薄责思已厚，听归初不留。","昔来聊坎止，今去亦川流。","图史自可乐，亲朋相与游。","樽中常有酒，此外复何求。"]},{"t":"次韵和归去来集字十首 其九","f":"五言律诗","c":["旧隐北山北，结庐犹可寻。","曾传种松法，当遂采芝心。","有酒且觞客，无弦何用琴。","一生几量屐，慎勿废登临。"]},{"t":"次韵和归去来集字十首 其十","f":"五言律诗","c":["处世若大梦，吾生感行休。","何须缚轩冕，且复傲林丘。","云木千岩秀，烟波万壑流。","忘机齐物我，鱼鸟与君游。"]},{"t":"送罗惇诗赴举","f":"七言律诗","c":["计偕西去不容迟，暂聚还分与愿违。","丹桂一枝应俯拾，青云万里看横飞。","我方谪宦陪鸠杖，子欲成名戏綵衣。","努力争先龙虎榜，发挥家学慰庭闱。"]},{"t":"从人于柳木得芝一本面径尺馀体圆而攲正类荷叶惜其生于僻远不得与奏牍为赋此诗","f":"七言律诗","c":["草木何为亦发祥，灵芝三秀向沙阳。","成丛已茁枯梅上，盈尺还生卧柳傍。","叶若圆荷方泻露，色如紫椹更飘香。","惜哉地去长安远，不使公卿草贺章。"]},{"t":"将去沙阳留别邓季明诸公","f":"七言律诗","c":["一载沙阳信有缘，宽恩许去却依然。","碧斋翠阁已如梦，明月清风长自妍。","溪上客舟横一叶，箧中诗卷剩千篇。","诸公别后应思我，茗饮时时到寓轩。"]},{"t":"畴老修撰见示七峰吟因成七言十韵律诗以叙别","f":"七言古诗","c":["谪堕闽山款栋闳，日亲高义慰平生。","忘年许结看经社，乘兴时参在野旌。","三径高怀穷水石，七峰佳气入轩楹。","舫斋谈笑龟鱼惯，翠阁吟哦卷轴成。","方幸游从陪杖屦，敢将踪迹叹蓬萍。","宽恩宥罪千钧重，小艇浮溪一叶轻。","北阙未应容接武，东皋从此遂躬耕。","宁亲幸惬区区志，去德还深恋恋情。","般若光中无聚散，毗卢海里任从横。","愿公更展垂天翼，拭目鹏抟九万程。"]},{"t":"自沙阳乘泛碧斋至洛阳口","f":"五言古诗","c":["罪大昔来谪，恩宽今许归。","碧斋还泛泛，翠阁已依依。","箫鼓转山曲，旌旗摇夕晖。","馀霞方散乱，倦鸟亦归飞。","颇悟邯郸梦，还寻莱子衣。","耄倪嗟得去，朋友惜相违。","讵有甘棠爱，徒知蘧玉非。","劳生成底事，归老钓鱼矶。"]},{"t":"留题双溪阁书呈南剑守谢少卿","f":"七言古诗","c":["华构何年玉斧修，规摹宏丽属贤侯。","治成不废登临乐，望远宜穷水石幽。","千里烟云瞻北阙，四时风景冠南州。","山如蟠踞成龙虎，剑有雌雄射斗牛。","天倚笔峰排玉笋，仙留篆石浸银钩。","二川俯瞰丁为字，万室傍连蜃结楼。","樽俎幸容陪胜赏，笙歌更觉助清游。","朝云暮雨滕王阁，明月清风白鹭洲。","梦草惠连留句法，游山安石继风流。","尚能执笔从公赋，却恨归鞍不可留。"]},{"t":"黄道夫约游南山无名庵谒包法师","f":"七言绝句","c":["碧山盘屈白云凝，竹径通幽水石清。","门对演仙千古在，道人何事学无名。"]},{"t":"奉酬陈之元教授见赠次韵","f":"七言古诗","c":["谪官因得穷林泉，陶写聊复资诗篇。","青岑叠叠山满眼，碧波湛湛溪涵天。","南连海峤饶雾雨，北望吴越凄风烟。","感怀触目还得句，但可娱戏那敢传。","譬犹候虫与时鸟，自鸣自已真偶然。","岂知飘落广文耳，饰以妙语烦雕镌。","与公平生未相识，一见倾心谁与易。","沙阳百里阻游从，注目寒空暮云碧。","朅来邂逅慰所思，况得新诗飞霹雳。","我今归去隐梁溪，远迹江湖养愚直。","看公白日上青霄，九万扶摇不劳力。"]},{"t":"谢德夫约游开平寺","f":"五言律诗","c":["出郭山村僻，寻真殿阁幽。","双溪馀赏兴，五马故来游。","钟梵含古思，林泉销客愁。","归欤碧云合，罗绮满兰舟。"]},{"t":"谢守送别至黯淡寺","f":"七言律诗","c":["送远劳为黯淡行，西风斜日袅双旌。","舟如一叶波涛舞，滩作半天风雨声。","修竹拂云青蓊郁，圆峰对阁翠峥嵘。","如公高义今人少，行客空馀恋德情。"]},{"t":"长滩驿次韵陆惇礼留题二绝句 其一","f":"七言绝句","c":["文彩飘飖青琐郎，朝班同望赭袍光。","岭云深处观题句，使我幡然念帝乡。"]},{"t":"长滩驿次韵陆惇礼留题二绝句 其二","f":"七言绝句","c":["当年狂直叩龙墀，谪堕闽山省旧非。","须信宽恩若天地，才周岁律已容归。"]},{"t":"题黄亭驿","f":"七言绝句","c":["云山一带碧崔嵬，迎我南迁又北回。","岁籥才周两经历，此行端为武夷来。"]},{"t":"武夷行","f":"七言古诗","c":["忆昨退朝门下省，槐影扶疏清昼永。","琐窗一枕梦仙山，觉来毛骨犹清冷。","谪官道出武夷山，风景翛然似梦间。","碧溪九曲山万叠，况值密雪妆烟鬟。","宽恩今日容归去，笑指洞天寻旧路。","霜晴日暖白云深，遥望幔亭天一柱。","羽人导我游仙溪，翠壁苍崖晚更奇。","浩歌快饮纵回棹，星月耿耿风凄凄。","晓来换骨岩中看，玉润金坚馀片片。","三姝骈立映彤霞，二水交流萦素练。","征鞍欲去更从容，仙境灵迹岂易逢。","他日追思不可到，梦魂还过七闽中。"]},{"t":"泛游仙溪","f":"七言律诗","c":["去年游仙满溪雪，今年游仙一船月。","武夷已擅天下奇，雪月相辉更幽绝。","前生定在此山中，缘熟重游六六峰。","惭愧真仙借光景，恨无道骨与仙风。"]},{"t":"别武夷途中偶成寄观妙法师","f":"七言律诗","c":["道妙观来物物通，武夷仙境幸相逢。","溪流玉雪三三曲，山锁云霞六六峰。","去路归鞍方眷恋，淡烟疏雨正蒙茸。","羡师日在神仙窟，回首岩峦紫翠重。"]},{"t":"寄题观妙师阁皂山旧隐观云轩","f":"七言律诗","c":["独搆幽轩福地阴，飞云对面起青岑。","但知映日能成色，谁信崇朝解作霖。","苒苒行云宁有迹，霏霏出岫本无心。","道人默坐观舒卷，至理应符妙意深。"]},{"t":"崇安令朱邈公达送示武夷图因成绝句","f":"七言绝句","c":["秀气蜿蜒作武夷，岩峦窈窕白云飞。","再游未尽平生兴，六幅生绡画得归。"]},{"t":"自分水岭过江南","f":"七言律诗","c":["行尽闽山万屈盘，江南形势陡然宽。","山平水远望不尽，木落草枯霜始寒。","醉里讴吟聊自适，梦中往复本非难。","谁言春信年年早，笑指江梅试折看。"]},{"t":"铅山约高无咎同游石井","f":"七言绝句","c":["岩洞嵌空凿翠崖，一泓云液贮琼瑰。","幽人须信耽泉石，茗饮相招特特来。"]},{"t":"自铅山迂路至吴园","f":"五言律诗","c":["迂路入江南，寒烟锁翠岚。","清晨游石井，薄暮宿了岩。","月冷不成梦，鸡号还整骖。","吴园才数舍，去去指龙潭。"]},{"t":"吴园","f":"七言绝句","c":["当时亲迎到吴园，屈指重来十七年。","身世恍然如一梦，从今归去老林泉。"]},{"t":"留题月岩","f":"七言律诗","c":["广寒宫殿寄幽岩，忌满非缘玉斧戡。","皓魄半轮横道左，清光千古照江南。","阴精凝结元无质，神化胚胎岂易探。","好是月华生碧落，扶疏桂影远相参。"]},{"t":"宿黄藤驿","f":"五言律诗","c":["古驿号黄藤，休鞍夜已灯。","溪寒水清浅，山瘦石棱层。","豪客路方阻，岁寒阴始凝。","开怀惟仗酒，独酌醉瞢腾。"]},{"t":"弋阳道中","f":"七言律诗","c":["南去北来皆岁暮，流年苒苒过光阴。","江南须信风烟好，浙右方虞寇盗深。","云外山深横笔格，月中滩响叠琴心。","卧龙三顾今寥落，抱膝空为梁甫吟。"]},{"t":"望龟峰","f":"七言古诗","c":["饶阳景物犹武夷，岩石崛起多瑰奇。","此峰厥状更诡异，举首曳尾如灵龟。","穹隆曝甲正霜晓，蹒跚引气当晴晖。","故知造化巧凝结，欲问所以良难推。","我疑龙伯钓溟渤，六鳌连引背负归。","中途遗一尚赑屃，直欲赴海冠峨巍。","又疑清江使河伯，波涛相失留于斯。","化为巨石峙千古，虽欲钻灼无由施。","茫茫神怪不可诘，但使风景增清辉。","我来闽岭厌山水，见此还复伸双眉。","颇嗟行役不果到，侧身西望生长悲。"]},{"t":"鸣山驿次韵蔡君谟续梦作","f":"七言绝句","c":["一梦神游紫府天，觉来身寄驿亭眠。","何须怅望吹箫女，独跨青鸾入翠烟。"]},{"t":"宿安仁云锦堂","f":"七言律诗","c":["一宿溪边云锦堂，烟村浮动野梅香。","沙平水澹近江浦，天阔山遥多夕阳。","北陆寒凝风眇眇，东吴音断意茫茫。","片言无补空来往，赢得萧条两鬓霜。"]},{"t":"馀干","f":"七言律诗","c":["岁寒迂路过江乡，叹息飞蓬堕渺茫。","云锦洞深烟水远，琵琶洲转暮滩长。","田园归去荒三径，金鼓传闻震一方。","极目东吴何处是，断霞轻霭落残阳。"]},{"t":"晚行","f":"五言律诗","c":["岁杪旅怀恶，驱车残照中。","暮云千里碧，落日半轮红。","掠水起行雁，隔林闻远钟。","休鞍僧舍闲，皓月又生东。"]},{"t":"题安国寺翠玉亭呈平老","f":"七言律诗","c":["兰若何年种碧瑜，凌霄高节笑楸梧。","渭川谩说三千亩，杜牧宜誇十万夫。","月舞清阴金影碎，风敲幽韵玉音敷。","烦师长养休斤斧，试问江南有此无。"]},{"t":"题仁义驿岁寒堂范文正公所植六松","f":"七言律诗","c":["江驿森森六本松，蜿蜒枝干走虬龙。","烟滋鳞甲苍颜老，云惹须髯美荫浓。","独立雪霜君子操，曾因风雨大夫封。","不栽桃李追时好，叹息前贤意可宗。"]},{"t":"闻浙东方寇大作道路不通迂路由江南以归有感二首 其一","f":"五言古诗","c":["理装适吴会，避寇由江滨。","宁知治安世，乃作途穷人。","风涛岂不险，舟楫尚可因。","失身入畏涂，难以理义陈。","平生笑子美，逃乱走踆踆。","如今翻自笑，亦须谋此身。","此身何足惜，上有高年亲。","骨肉几百口，干戈已相邻。","以我此日心，知彼无辜伦。","安得济川舟，载之适通津。","徙置安乐土，不知战斗尘。","已矣可奈何，愿为太平民。"]},{"t":"闻浙东方寇大作道路不通迂路由江南以归有感二首 其二","f":"五言古诗","c":["东南久无备，盗贼起不虞。","揭竿与荷锄，皆是耕田夫。","谁为捕逐者，得官缘苞苴。","不读一行字，况复知孙吴。","厥初既轻敌，屡北辄睢旴。","屯兵非不多，一扫不复馀。","虎兕出于柙，是谁之过欤。","凶焰陵郡县，良民遭戮屠。","坐令腹心地，化为豺豕区。","除恶当务早，滋蔓良难图。","王师何日出，努力观庙谟。"]},{"t":"童子驿见梅花 其一","f":"七言绝句","c":["天滑云腴凝不流，岁寒迂骑过南洲。","黄昏孤馆沈吟处，赖有江梅慰客愁。"]},{"t":"童子驿见梅花 其二","f":"七言绝句","c":["江南为客见江梅，似为行人特特开。","数点枝头凝玉雪，隔窗和月送香来。"]},{"t":"偶题 其一","f":"五言律诗","c":["霜风响枯林，旷野惨寒色。","川路阻且长，客子方远适。","东吴眇何在，仰羡归飞翼。","惟有溪边梅，犹能慰愁寂。"]},{"t":"偶题 其二","f":"七言绝句","c":["水落潮乾人取途，西风索索响黄芦。","沙头惊起数行雁，恰似旧藏芦雁图。"]},{"t":"题建德县开化寺","f":"七言律诗","c":["路绕江南烟水村，梅花的皪正销魂。","峰峦影里过山邑，鼙鼓声中念故园。","残腊未曾看雪舞，劲风何事扫云屯。","拙翁自笑平生拙，欲叩天阍更一言。"]},{"t":"题紫岩驿","f":"七言律诗","c":["稚年曾向此途行，半世重来若泛萍。","山径车声欣路坦，江村市合厌鱼腥。","连天霜草萧萧白，蟠岭云松郁郁青。","久旅怀家归尚远，暮烟残照宿邮亭。"]},{"t":"赠池守张闳道","f":"七言律诗","c":["绣衣执法出霜台，邂逅还如特特来。","华省旧曾陪笑语，清溪今复接樽罍。","喜公笔有江山气，顾我心如世味灰。","天下苍生待经济，坐看蟠蛰起春雷。"]},{"t":"同天宁聪老游齐山次杜牧之韵","f":"七言律诗","c":["东风初起白云飞，禅客相邀步翠微。","童稚旧游如梦到，江山今幸假途归。","岩峦窈窕笼轻霭，鸥鹭翩翻舞夕晖。","归觐庭闱询往事，箧中先整老莱衣。"]},{"t":"题弄水亭","f":"七言律诗","c":["萧条秋浦景如秋，谁信猿声使客愁。","烟树森森连远峤，水田漠漠集飞鸥。","高楼吹角增离恨，古驿停骖忆旧游。","亦欲题诗江祖石，谪仙遗迹最风流。"]},{"t":"自池口登舟","f":"七言律诗","c":["水落溪乾不可舟，春潮理棹浅沙头。","多风烟浪鳞鳞起，欲雪江云苒苒浮。","涉险物情终共畏，临流归兴浩难收。","波神借我风帆便，鼓柁清江汗漫游。"]},{"t":"江行十首 其一","f":"五言律诗","c":["理棹适江干，初欣眼界宽。","日蒸江气白，风约橹声寒。","蒋诩谋新径，钟仪只旧冠。","浮云休蔽日，直北是长安。"]},{"t":"江行十首 其二","f":"五言律诗","c":["春江彻底清，沙尾见潮生。","朝气嘘成雾，南风战作晴。","岸移看树远，船稳信波平。","览尽江山胜，还悲万古情。"]},{"t":"江行十首 其三","f":"五言律诗","c":["渺渺春江稳，融融午睡腴。","梦回双橹急，望极片帆孤。","皱水风还逆，维舟日欲晡。","云中有行雁，苒苒下平芜。"]},{"t":"江行十首 其四","f":"五言律诗","c":["春光摇画鹢，江影浸长天。","浪势随潮急，涡痕逐橹圆。","避风依岛屿，防寇问人烟。","深念还愁绝，高歌且醉眠。"]},{"t":"江行十首 其五","f":"五言律诗","c":["江阔水云暮，风高舟楫停。","落帆归别浦，宿雁集回汀。","霜苇萧萧白，烟岚朵朵青。","夜来江色静，寒浴一天星。"]},{"t":"江行十首 其六","f":"五言律诗","c":["朝来问风信，五两向南飞。","旅泊添春恨，舟行与愿违。","瓶梅空的的，岸柳已依依。","寂寞江南路，那知自此归。"]},{"t":"江行十首 其七","f":"五言律诗","c":["春江望不极，惨淡起层阴。","烟雨濛濛湿，云涛渺渺深。","怀家千里意，报国一生心。","叹息知音少，空为梁甫吟。"]},{"t":"江行十首 其八","f":"五言律诗","c":["晚泊铜陵口，烟村八九家。","岸沙崩浪响，江雨带风斜。","泛泛浮波雁，捎捎接翅鸦。","无情东注水，对尔叹年华。"]},{"t":"江行十首 其九","f":"五言律诗","c":["杳杳楚天阔，悠悠江浦清。","便风帆腹满，顺水橹腰轻。","烟澹山逾碧，云高雨易晴。","无心问渔父，浊酒慰平生。"]},{"t":"江行十首 其十","f":"五言律诗","c":["春到江波绿，潮来浦溆深。","晓风看五两，家信抵千金。","笑读谪仙句，病为庄舄吟。","世途游历遍，归去老山林。"]},{"t":"游五松山观李太白祠堂","f":"五言古诗","c":["大江东南流，鼓柁江水上。","薄游五松山，获见谪仙像。","呜呼天宝间，治乱如反掌。","兵戈暗中原，豪杰多长往。","谪仙当此时，逸气隘天壤。","脱身来江东，缥渺青霞赏。","作诗几千篇，醉笔笼万象。","迄今有遗祠，识者共瞻仰。","嗟予岂后裔，愚拙谁复尚。","珥笔玉殿螭，谪官闽岭瘴。","荷恩许生还，冒险理归桨。","于焉觌仙风，足以慰遐想。","愿言继清芬，何由揖英爽。"]},{"t":"舟中读书有感","f":"七言律诗","c":["渺渺波涛淅淅风，此身忽在大江东。","浮家泛宅云烟里，思古伤今图史中。","盗贼从来能伺衅，治安自昔戒除戎。","我今惟愿兵戈息，归作梁溪老钓翁。"]},{"t":"铜陵阻风","f":"五言律诗","c":["春色到江渚，梅花正断魂。","风波留远棹，烟雨湿寒村。","雁过传遗响，潮来没旧痕。","凄凉一樽酒，愁绝与谁论。"]},{"t":"题护法寺瑛老默堂","f":"七言绝句","c":["维摩丈室何年设，满目江山自风月。","道中试露默中机，千偈澜翻本无说。"]},{"t":"次韵和瑛老颂","f":"七言绝句","c":["默堂前对五松山，敌面机锋一瞬间。","禅客相逢休拟议，草鞋价直欲谁还。"]},{"t":"自铜陵行四十里风复作泊江北岸地名散潭属淮南 其一","f":"七言律诗","c":["襟带江淮一望间，夕阳舣棹散潭湾。","波涛汹涌暮天阔，鸥鹭飘飖渔艇閒。","风壮又还依北渚，云深不复见南山。","浙河千里何时到，过去飞鸿不可攀。"]},{"t":"自铜陵行四十里风复作泊江北岸地名散潭属淮南 其二","f":"七言律诗","c":["镜中渐觉鬓丝多，半世劳生可奈何。","极望不来青足鸟，满江更起白头波。","扬帆贾客风前笛，撒网渔人月下歌。","自断此生甘寂寞，毗耶归作老维摩。"]},{"t":"自铜陵行四十里风复作泊江北岸地名散潭属淮南 其三","f":"七言律诗","c":["平生性酷爱江山，今日江山满目前。","明月清风人寂寂，淡烟轻霭露涓涓。","波声撼岸连淮壤，雁阵惊寒入楚天。","慨念往来成底事，一杯浊酒且安眠。"]},{"t":"春睡 其一","f":"七言绝句","c":["半生游宦鬓毛霜，依旧图书对晓窗。","卯酒一杯春日暖，卧听鸣橹下清江。"]},{"t":"春睡 其二","f":"七言绝句","c":["居士终朝只念归，日行百里尚嫌迟。","小窗春梦分明到，叹息啼乌唤觉时。"]},{"t":"夜泊繁昌","f":"五言律诗","c":["系缆繁昌口，清江夜渺然。","寒星随浪闪，孤月向人圆。","汉渚乘槎客，云川控鲤仙。","何须论往事，且泛碧波船。"]},{"t":"试九华朱觐墨","f":"七言律诗","c":["九华山顶老松烟，名重初因玉局仙。","样古法精圭并制，胶清煤馥玉同坚。","试将毛颖轻轻染，须遣陶泓细细研。","居士年来无恋著，惟于三子欲逃禅。"]},{"t":"未至芜湖四十里阻风","f":"七言律诗","c":["一夜寒云凝不开，北风吹雨带潮来。","涛翻天末银山涌，浪打沙头霹雳摧。","心在浙西音断绝，身留江左意徘徊。","无聊独酌开怀抱，赖有窗间数点梅。"]},{"t":"草宰执书论方寇事戏成","f":"五言古诗","c":["江浙巨盗起，东南皆震惊。","王师殊未出，赤子若为情。","试赠绕朝策，愿飞燕将城。","非因肉食鄙，只欲庙谟成。","汲黯复妄发，终军思请行。","怀亲寸心急，报国一身轻。","曹刿亦问战，申胥还乞兵。","群公佐天子，努力剪鲵鲸。"]},{"t":"上元舟中有感","f":"五言古诗","c":["前年扈清跸，玉辇临端门。","鳌山綵构耸，露台歌吹喧。","去年谪沙阳，旅泊亦游观。","士女隘衢巷，灯火满溪山。","今年过江南，舣舟烟水湾。","风高不可进，极目云涛翻。","蜜炬照独酌，红炉凌夜寒。","感事心欲折，强歌声无欢。","坐看江边月，飞上青云端。","清光不改旧，对我还团栾。"]},{"t":"夜坐 其一","f":"七言绝句","c":["春夜沈沈灯影明，卷书兀坐忽三更。","不知船外风多少，但听满江波浪声。"]},{"t":"夜坐 其二","f":"七言绝句","c":["波涛漠漠雨纷纷，夜泊江南烟水村。","慨念平生都不寝，可怜心事向谁论。"]},{"t":"至芜湖闻贼陷钱塘复为官军所得有感 其一","f":"七言绝句","c":["督府繁华一扫空，须知狂寇计非庸。","庙堂若为苍生计，早筑高坛拜卧龙。"]},{"t":"至芜湖闻贼陷钱塘复为官军所得有感 其二","f":"七言绝句","c":["巨盗乘虚起浙东，猖狂如在笑谈中。","钱塘犹喜官军复，破贼须从此立功。"]},{"t":"自芜湖江行至采石 其一","f":"七言绝句","c":["万顷春江彻底清，天风不动镜泓澄。","画船安稳摇空翠，疑在琉璃地上行。"]},{"t":"自芜湖江行至采石 其二","f":"七言绝句","c":["江水春来绿似蓝，临流高石翠巉岩。","波恬舟稳已堪喜，况是清风借一帆。"]},{"t":"阻风泊慈湖夹焚香默祷有长鱼跃波而江豚出没舟人大惊抵暮风便因命解舟乘月泛禁江一夕至金陵盖数百里作二绝以纪其事 其一","f":"七言绝句","c":["江豚出没白波中，十丈神鱼跃晚空。","知是阳侯怜我拙，故教来助一帆风。"]},{"t":"阻风泊慈湖夹焚香默祷有长鱼跃波而江豚出没舟人大惊抵暮风便因命解舟乘月泛禁江一夕至金陵盖数百里作二绝以纪其事 其二","f":"七言绝句","c":["露气漫漫欲结霜，扁舟夜下秣陵江。","烟波如席月如昼，快意倒尽黄金缸。"]},{"t":"同李似之游蒋山","f":"五言古诗","c":["北风阻行舟，驾言游蒋山。","相携得良友，谈笑穷跻攀。","松林静杳冥，殿阁罗烟鬟。","宝公骨已冷，白塔孤云间。","乘高望长空，极目波涛翻。","东南正戎马，戈甲照江干。","与子适相遇，偷此半日闲。","怀古六朝远，道旧一笑欢。","忆昨赐对初，接武玉殿班。","螭坳珥史笔，每惭追继难。","迂疏与世违，谪官堕瓯蛮。","宽恩幸脱去，假道来江关。","邂逅两萍梗，飘泊惊风幡。","回首顾浙河，不知涕泗潸。","著鞭愿努力，世路方多艰。"]},{"t":"颂示勤老","f":"七言绝句","c":["平生闻说蒋山勤，今日相逢过所闻。","还似泉公唤居士，一声吹散满天云。"]},{"t":"次韵奉酬李似之见赠","f":"七言律诗","c":["吾宗才气世无双，用与时行舍亦藏。","殿陛同瞻龙衮绣，螭坳继染御炉香。","紫荷持橐将清禁，贝叶翻经见宝坊。","仄席正思经济手，伫观趣召侍颙昂。"]},{"t":"金陵怀古四首 其一","f":"七言律诗","c":["六代兵戈王气销，山围故国自周遭。","豪华散灭城池古，人物摧残丘冢高。","阜转蟠龙翔宝塔，洲分白鹭涌云涛。","悠悠世事都如梦，且对金樽把蟹螯。"]},{"t":"金陵怀古四首 其二","f":"七言律诗","c":["六代繁华三百年，我来吊古一悽然。","景阳钟断鸡空唱，玉树歌沈月自圆。","潮没旧痕生晚浦，柳摇新色媚晴天。","高楼上尽穷双目，千里江山绕槛前。"]},{"t":"金陵怀古四首 其三","f":"七言律诗","c":["六代兴亡江上城，倦游还向此中行。","龙蟠虎踞空形势，并废台荒为战争。","云气霏霏春雨急，烟波渺渺暮潮平。","商人不识前朝恨，短笛还为激烈声。"]},{"t":"金陵怀古四首 其四","f":"七言律诗","c":["六代当年恨最长，兵戈陵灭故城荒。","非关霸气多消歇，自是人谋未允臧。","王谢风流今寂寞，江山形胜亦凄凉。","我来正值兴戎马，慨念东南更惨伤。"]},{"t":"登钟山谒宝公塔","f":"五言律诗","c":["宝公真至人，鸟爪金色身。","杖携刀尺拂，语隐齐梁陈。","我登钟山顶，白塔高嶙峋。","再拜礼双足，聊结香火因。"]},{"t":"题定林院","f":"七言绝句","c":["行过钟山到定林，青松一径白云深。","三间古屋昭文馆，那有沉迷富贵心。"]},{"t":"题八功德水","f":"七言绝句","c":["石作方池紫翠崖，湛然定水贮琼瑰。","何须功德标为八，万行圆成自此来。"]},{"t":"题偃秀轩","f":"七言律诗","c":["青葱秀色一轩中，俯瞰梁朝万本松。","顶蹙风云疑偃盖，枝蟉雨露若蟠龙。","四时郁郁宁彫叶，千载亭亭不改容。","却笑宗人生岱岳，佞秦先得大夫封。"]},{"t":"得家信报避寇海陵","f":"七言律诗","c":["怪底灯花夜夜红，朝来家问始相通。","田园已在危疑际，骨肉幸安飘泊中。","子美无家寻弟妹，渊明有酒引儿童。","我今已胜少陵老，稚子候门淮水东。"]},{"t":"自金陵江行未至长芦阻风 其一","f":"七言绝句","c":["倏忽风云接地阴，扁舟系缆暮江浔。","波涛何必深为阻，万里归来一寸心。"]},{"t":"自金陵江行未至长芦阻风 其二","f":"五言律诗","c":["七日风不止，归心何似生。","烟添暮山色，风撼满江声。","淮楚已非远，波涛殊未平。","坐看云解駮，犹喜晚来晴。"]},{"t":"过长芦","f":"七言绝句","c":["达磨当时一苇杭，栖栖暗度白沙江。","不知双履归何处，吸尽西江属老庞。"]},{"t":"游长芦见众僧已披剃","f":"七言绝句","c":["圆顶方袍复旧仪，欣欣便觉众情熙。","可怜尽堕狙翁术，暮四朝三元不知。"]},{"t":"次韵和渊明形影神三首 其一 形赠影","f":"五言古诗","c":["大块已载我，何如未生时。","气变芒芴间，七窍谁凿之。","百骸与九藏，假合以成兹。","与子非故交，从我如相期。","屈伸及动止，契合初不思。","常恐随物化，念此情凄洏。","我生梦幻中，变灭不复疑。","安得永相保，听我悲来辞。"]},{"t":"次韵和渊明形影神三首 其二 影答","f":"五言古诗","c":["纡馀非我妍，濩落非我拙。","与子两相依，生来无间绝。","俯仰随顾指，岂是事容悦。","因光长周旋，处阴暂暌别。","况复同物化，子坏我亦灭。","冥冥长夜台，念之五情热。","愿子卫生经，无使精脑竭。","千载永相从，彭殇孰优劣。"]},{"t":"次韵和渊明形影神三首 其三 神释","f":"五言古诗","c":["人生若大梦，积微以成著。","少壮得老死，一念即非故。","二子异金石，松萝暂依附。","胡为羡久生，切切儿女语。","有形会当灭，是影无实处。","惟我谢客尘，妙湛乃常住。","不入造化机，岂堕阴阳数。","回光试反照，凡圣悉皆具。","不减亦不增，谁毁复谁誉。","超然外死生，卓尔无来去。","周行万物表，独立初不惧。","二子非吾徒，安用多忧虑。"]},{"t":"次韵李似之秋居杂咏十首 其一","f":"五言古诗","c":["达人有大观，曲士多自束。","忘真供物役，终岁惟仆仆。","所以梁溪翁，归来蓺松菊。","寒泉友龟鱼，丰草侣麋鹿。","清风为扫门，明月相照烛。","世故悉弃捐，吾方乐于独。"]},{"t":"次韵李似之秋居杂咏十首 其二","f":"五言古诗","c":["亭亭南山松，下荫千里道。","结根既得地，秀色亦何好。","岁寒霜霰苦，独立君子操。","如何慷慨士，百虑绕中抱。","寸心多感伤，摇摇若旌纛。","逝将归江湖，更拜散人号。"]},{"t":"次韵李似之秋居杂咏十首 其三","f":"五言古诗","c":["乌鹊故巢心，鸿雁稻梁谋。","梁溪十亩园，岁晚营菟裘。","自我去泉石，岁律才一周。","安知巨盗起，千里来蜂蟊。","老稚适淮东，旅泊如寄邮。","已矣复何言，吾生感行休。"]},{"t":"次韵李似之秋居杂咏十首 其四","f":"五言古诗","c":["鼓鼙思将帅，戡乱属豪杰。","吾儒贵全才，冠履仍佩玦。","憬彼乘间盗，萌蘖傲霜雪。","锄恶当务本，使众宜以悦。","一扫巢穴空，毋俾蚁猬结。","安得李临淮，念此五情热。"]},{"t":"次韵李似之秋居杂咏十首 其五","f":"五言古诗","c":["禅悦知道腴，寂乐忘世喧。","自从游宦来，常恐岁月捐。","愿从善知识，超然同晤言。","心清闻妙香，不必炉中烟。","竹实自鸾凤，腐鼠从乌鸢。","典籍亦可弃，鱼兔非蹄筌。"]},{"t":"次韵李似之秋居杂咏十首 其六","f":"五言古诗","c":["取饭遣化人，散花有天女。","维摩一方丈，安用室百堵。","况我麋鹿姿，本非冠冕伍。","脱身归梁溪，蓑笠钓烟雨。","结交有风月，扫念无寒暑。","巨盗傥削平，此志良自许。"]},{"t":"次韵李似之秋居杂咏十首 其七","f":"五言古诗","c":["两曜真跳丸，百年如转轴。","富贵能几何，飘若云过目。","惟有金仙书，可以静中读。","冷暖初自知，运用要当熟。","仲尼贵毋我，老氏欲为腹。","悟真奚必多，半偈亦云足。"]},{"t":"次韵李似之秋居杂咏十首 其八","f":"五言古诗","c":["我行大江滨，举头见钟山。","清风自南来，长啸宇宙宽。","邂逅适相遇，取友平生端。","恋恋故人意，怜此范叔寒。","世路方多虞，期子慎所安。","他时来访我，陋巷一瓢颜。"]},{"t":"次韵李似之秋居杂咏十首 其九","f":"五言古诗","c":["朝市不可留，山林有佳趣。","结庐无人境，散策时远步。","手携葛翁杖，足蹑祖师屦。","一笑浮世空，欻若草头露。","幻身粗饱煖，此外复何虑。","休问东陵瓜，且种梁溪芋。"]},{"t":"次韵李似之秋居杂咏十首 其十","f":"五言古诗","c":["浮云不成雨，晶晶行晴昼。","朝蔽扶桑暾，夜掩长河宿。","回飙一扫除，戢戢见远岫。","青天与白日，四顾喜瞻搆。","愿乘六气辩，抚手磨宇宙。","冷然御风行，平昔笑禦寇。"]},{"t":"阻风舟中有感","f":"五言古诗","c":["扁舟泊枉渚，邈在大江南。","风云斗未息，波涛战方酣。","闭关坐明窗，开卷穷幽探。","气寒觉火冷，志苦思蘖甘。","深炷一炉香，默默聊自参。","半世徒扰扰，忙如未茧蚕。","又若伏枥马，未脱辔与衔。","逝将归山林，瓶锡寄一岩。","愿从祖师六，不学黄庭三。","得此无所得，超然离圣凡。"]},{"t":"喜雨","f":"七言古诗","c":["北风吹云云不开，濛濛细雨和烟来。","舟行虽阻亦可喜，润泽及物诚佳哉。","我辞闽岭遵江渚，百日皆晴未尝雨。","江淮旱暵已踰年，牟麦焦枯但黄土。","漕渠千里不复通，况复巨寇兴兵戎。","从兹一雨百事散，愿化灾疹为康丰。"]},{"t":"双凫","f":"七言绝句","c":["云涛万顷连天雨，波上双凫自容与。","风高江阔烟水寒，日暮相将何处去。"]},{"t":"雪","f":"五言律诗","c":["小雨晚成雪，冻云凝不开。","响窗初索索，积岸渐皑皑。","色与涛头并，寒资酒力排。","平生看图画，今日画中来。"]},{"t":"江上值雪戏成短歌","f":"七言古诗","c":["我来自南今几月，万里不曾看点雪。","舣舟江南烟水湾，雪作春风更奇绝。","冻云漠漠愁锁空，初闻冰霰响窗蓬。","鲛人泣下玉盘碎，珠玑乱落层霄中。","须臾雪片大如指，密洒江干浩无际。","白帝从以万玉妃，婀娜旂常堕雪水。","回风飘舞转交加，坐看汀洲铺玉沙。","已惊绿柳早飞絮，更讶黄芦还带花。","沙头凫雁自俦侣，天暝云寒去何处。","渔翁独立钓清江，披得一蓑非好句。","梁溪居士初归来，对此超然慰所怀。","家在淮东阻行色，晴天且为片时开。"]},{"t":"舟次仪真","f":"七言绝句","c":["昔年试吏得江城，一纪重来若隔生。","惆怅旧游谁可语，南园春色却多情。"]},{"t":"次韵王尧明游北寺","f":"五言古诗","c":["小雨湿残花，回风振芳草。","胜游宜及时，嘉此春物好。","萧然二三子，散策穷杳眇。","招提枕郊头，殿阁出林表。","中有王屋泉，一酌百虑澡。","踟蹰古城隅，幽径通翠筱。","嗟予阻追陪，正坐尘事绕。","衣冠方北渡，亲故幸非少。","客情终念归，回首云缥缈。","遥怜松菊荒，仰羡鹳鹤矫。","园田诚可乐，鼙鼓尚惊扰。","何当终素心，永叹忧用老。"]},{"t":"次韵王尧明三绝句 其一","f":"七言绝句","c":["春风初入牡丹枝，国色天香艳姣姬。","堪笑谪仙犹半醉，清泉沃面与题诗。"]},{"t":"次韵王尧明三绝句 其二","f":"七言绝句","c":["康时致主接英游，姚宋开元第一流。","憔悴三闾空泽畔，离骚终日念灵脩。"]},{"t":"次韵王尧明三绝句 其三","f":"七言绝句","c":["郑卫曲终才雅奏，词人赋咏本多誇。","未能句语全无颣，犹贵琼瑜不掩瑕。"]},{"t":"次韵茂载海陵寓居有感三首 其一","f":"五言律诗","c":["群盗休凭险，天弧正指狼。","犬羊徒跋扈，貔虎极精强。","寓目江山异，伤心花草香。","浙河那得此，回首一彷徨。"]},{"t":"次韵茂载海陵寓居有感三首 其二","f":"五言律诗","c":["江城飘泊久，幽径绿寒莎。","叹息青春暮，悲伤白发多。","苍生端若此，狂寇竟如何。","更起乘桴兴，沧洲万里波。"]},{"t":"次韵茂载海陵寓居有感三首 其三","f":"五言律诗","c":["不谓繁华地，还飞战斗尘。","浇愁空泥酒，极目更伤春。","怀古翻书帙，论情托友人。","谁深医国术，吾欲问甘辛。"]},{"t":"次韵王尧明喜雨古风","f":"七言古诗","c":["神化茫茫端莫测，不雨踰时忽盈尺。","谁云幽默志难通，一念周圆诚已格。","井枯河竭欲飞尘，麦秀渐渐实半娠。","翠虬潜伏杳无处，遗蝗出地方鳞鳞。","观音妙智悲慈主，为洒杨枝作甘雨。","应怜祷禬罄勤渠，致遣神人梦中语。","雨旸之数虽有时，迟速亦可精神移。","世间万法尽心造，报若影响宁难期。","不知今夕复何夕，千里风云来阵墨。","驱雷掣电雨建瓴，似赴前期初不忒。","威神自在谁复如，噀酒投颅术已疏。","有秋颇足慰民望，可喜更须烦史书。","衣冠北渡连墙堵，旅食经时念终窭。","已欣霖雨起蟠龙，更庆天兵擒猛虎。","迩来世事不挂心，惟有忧国思犹深。","安得年丰群盗息，归助击壤尧民音。"]},{"t":"送虞季然赴八宝丞","f":"七言律诗","c":["流落归来旅海涯，相从几集凤凰池。","暂欣捉麈共谈笑，还惜整骖言别离。","为禄未能忘敛板，扫厅应不废哦诗。","如公岂是徒劳者，勉继前修结主知。"]},{"t":"次韵和曾徽言登北禅寺塔","f":"五言古诗","c":["佛教入中土，贝多凡几翻。","摩腾导其流，僧伽鼓其澜。","乃建窣堵波，高标屹参天。","划如五彩虹，上与青霄干。","兹塔更奇古，层檐俯通川。","江山递隐见，万象森回环。","公子抱远韵，登临眇风烟。","仰穿龙蛇穴，旁瞰日月悬。","茫茫悉细碎，寓目疑无全。","归来吐妙句，字字劳精甄。","嗟我方屏处，胜游阻清缘。","幸窥慈恩作，如见众宝山。","宗风久寂寞，纻絮何其寒。","安得师子吼，震此龙象筵。","关弓挟白羽，櫜鞬相周旋。","当分宝塔坐，一瞬三万年。"]},{"t":"次韵徽言招饮绝句","f":"七言绝句","c":["压架酴醾翠蔓柔，经春芬馥未全收。","主人邀客醉花下，共喜王师破蔡州。"]},{"t":"读陈子直短歌三复而悲之次其韵","f":"词","c":["君不见韩昌黎，文章二百年。","又不见杜陵老，风月三千首。","号寒啼饥四壁空，谩有篇章在人口。","书生生事良易足，深林一枝河满腹。","但令藜苋可充肠，便把离骚静中读。","儒冠误身诚可怜，陈侯半世身犹邅。","斗酒初乏青铜钱，忍饥哦诗空可传。","富儿菽粟泥沙掷，不必登朝家万石。","水陆毕陈方丈食，锦绣还将被墙壁。","但资口腹为身谋，问以诗书初不识。","天公赋予真相百，彼富吾仁如黑白。","乡党宁无急义人，谁哀王孙与进食。","尝思漂母饭淮阴，何用区区论报德。"]},{"t":"次韵王尧明四旱诗 河运","f":"五言古诗","c":["漕渠如坦途，泛此往来宅。","疏川谁之功，乘木本诸益。","常疑侔沧溟，巨钓可龙伯。","那知旱暵甚，有此困涸阨。","岂无车班班，莫胜仓箱积。","譬犹一鹗飞，孰与鸷累百。","汲江劳瓮盎，祷雨费圭璧。","端为鱼鳖忧，无乃云雷斁。","安得千里波，篙师发棹歌。","愿借壮士手，为乃挽天河。"]},{"t":"次韵王尧明四旱诗 井汲","f":"五言古诗","c":["我居梁溪傍，密迩陆子泉。","漂流旅海陵，又欲买一廛。","愿言酌甘芳，为涤腥与膻。","居然值岁旱，此志无由全。","百井尽枯涸，简编匪虚传。","夜汲费烛炬，晓趋骈足肩。","一壶信千金，一饮或万钱。","逝将向井拜，飞泉为溅溅。","泓澄古镜色，吸引星光圆。","洋洋疗众渴，不竭如巨川。","井收遂勿幕，瓶盆送回旋。","饮水自可乐，安用井底眠。"]},{"t":"次韵王尧明四旱诗 酺祭","f":"五言古诗","c":["闵旱意不乐，驾言游近坰。","田父纷在野，祭酺方乞灵。","借问何以然，东皋产蝗螟。","主张有神物，薄礼羞微馨。","神歆庶灾熄，敢爱酒满瓴。","导我试往观，戢戢初插翎。","剪穗齐若刀，抱秆牢如钉。","异哉天壤间，孕此妖孽形。","群族既蕃衍，气类屯臊腥。","仲尼所不堪，纪异垂麟经。","畀火见周雅，捕瘗闻唐庭。","人力自足胜，何须诘冥冥。","聪明实依人，正直神所听。","区区觞豆间，厥德安足铭。","谁能起云师，霈雨驱疾霆。","一洗羽孽息，寥落如晨星。"]},{"t":"次韵王尧明四旱诗 雩祷","f":"五言古诗","c":["雩祭法已古，东方见苍龙。","厥后兹礼废，但祷释梵宫。","淮堧值岁旱，川涸山欲童。"]},{"t":"次韵和虞公明察院赋所藏李成山水","f":"五言古诗","c":["画史古多有，李生独宝传。","譬犹古人书，墨妙称诚悬。","尤物世难蓄，变化登云天。","流落人间者，遗迹犹绵绵。","此本更奇绝，高深自山渊。","想当槃礴时，舐笔应如椽。","楼观抱空曲，林芿霭层巅。","屹然岩石姿，润比金玉坚。","倏忽变寒暑，霏微起云烟。","高堂寓远目，如堕嵩华前。","回观旧所藏，一一可弃捐。","乃知盖代手，笔力能旋乾。","众工画山水，意匠劳雕镌。","惟兹得简易，大巧初天全。","鉴裁有精识，丹青孰争先。","何须嫫姆丑，始辨西施妍。","嗟我性迂拙，漂流方隐廛。","幸从长者游，坐使伊郁宣。","啸咏图史间，高台谢牵挛。","新诗与妙画，更使穷钻研。","愧乏色丝句，为续金声篇。","端思画中趣，秪欲休林泉。"]},{"t":"再次前韵","f":"五言古诗","c":["妙手不可遇，心匠良难传。","于中营丘生，名若日月悬。","胸次有衡霍，笔端合其天。","坐令众画史，缩手嗟材绵。","公于何处得，藏此图书渊。","昼赏不知厌，夜观烛如椽。","我昔游七闽，足踏群山巅。","最爱演仙峰，石色润且坚。","楼台与妆缀，轻素拖晴烟。","朅来见兹画，恍若复造前。","为技一至此，丹青诚可捐。","譬犹绘神骏，不必锦连乾。","阳岭郁葱茜，阴崖极镕镌。","人禽与屋木，种种法象全。","往者邈难追，后来谁复先。","新诗为发挥，与画争清研。","宝剑藏古岳，贤士隐里廛。","一朝遇鉴赏，晔若五采宣。","顾我涉道浅，游世困絷挛。","惟有古人心，刻意思精研。","兹画不可取，但诵瑶琼篇。","何须画中看，吾方老云泉。"]},{"t":"次韵曾徽言桂浆","f":"七言律诗","c":["金椀擎来碧玉浆，端令袢暑吸飞霜。","何须社瓮曲蘖法，自带广寒风露香。","清入肺肝殊有韵，甘馀齿颊固难忘。","七瓯已胜卢仝茗，似得仙人石髓尝。"]},{"t":"读王尧明赠诸弟和陶诗次韵为别","f":"五言古诗","c":["鹪巢安一枝，鹏运图南溟。","巨细自有适，坐见万物情。","昔别东都门，我方堕蛮荆。","岂知复会合，浊酒叙平生。","念子抱器业，出值时清明。","骞腾发素蕴，当使王化平。","而我志丘壑，肃肃正遐征。","窃比渊明归，逝同沮溺耕。","脱屣谢轩冕，超然无所萦。","出处良异趣，勉哉垂世名。"]},{"t":"虞公明出示序观音诗事并颂次韵","f":"七言古诗","c":["闻思大士真奇绝，俱妙形神侔玉雪。","譬如水月自清凉，能与世间除恼热。","自从證悟今几劫，定慧慈威初不灭。","解脱曾因无尽宣，圆通更假文殊说。","森然宝臂清净目，八万四千犹一吷。","依怗群生愿力坚，宴坐谛观尘世阅。","先生往时堕宪网，泽雉在樊鹰在绁。","默相虔诚赖觉慈，灼知情实蒙圣哲。","踰年海上得归来，冒险岂殊探虎穴。","精刚何翅金百鍊，忠荩端同水万折。","观音在处皆现前，不必图绘劳携挈。","此方教体在音闻，悟入此门良不拙。","更将妙语赞悲心，功德须知莫如舌。"]},{"t":"赠虞公明察院","f":"五言古诗","c":["岧峣古城隅，下为凤凰池。","凤去不复返，池水空涟漪。","傍有幽人庐，松竹森四围。","结构极爽垲，借问居者谁。","先生闻道久，昨自海上归。","食枣大如瓜，定曾见安期。","不知修何术，能夺造化机。","金鼎灿含葩，玉池滟生肥。","颠倒出龙虎，腾降分坎离。","行年五十馀，气貌如婴儿。","馀暇付图史，不废酒与诗。","高堂会宾友，落笔风雨驰。","戏事聊复尔，一笑初何为。","悬知广成子，千岁形不衰。","顾我抱迂拙，与世真相违。","徒欲睎骥騄，曾未窥藩篱。","寓居迩函丈，数造董公帷。","愿闻众妙门，成此一段奇。","胡为久闭拒，客至辄围棋。","归隐志已定，后会知何时。","铭心誓相学，发药幸教之。","他年倘有得，同驾云中螭。"]},{"t":"读钱申伯与仲弟唱和次韵见意","f":"七言古诗","c":["未忘世故似梅仙，謦欬那离狗马间。","肯信片言功若药，坐使四海安如山。","从来疗疾应须艾，宁有艾丸如许大。","扁鹊先知今岂无，和缓高谈良有在。","钱郎志气绝可人，不减风流温太真。","新诗欲嗣汲黯直，陋巷更甘原宪贫。","我有故园依北阜，松菊归来知好否。","著鞭愿子勉为先，我已摧颓瞠若后。"]},{"t":"往复诗多用佛语再次前韵示仲辅","f":"七言古诗","c":["远涉异域求金仙，岂知不离方寸间。","此门悟入真捷径，安用困苦栖穷山。","凭君试灼一炷艾，能已千痾宁四大。","病根若悟本来空，是则名为观自在。","平生见尽学道人，舍妄求真不识真。","指端明月休错认，衣里宝珠元不贫。","巍巍荡荡如山阜，长与君俱君见否。","仁者自生分别心，断际何尝有前后。"]},{"t":"题李茂举拥书堂","f":"七言律诗","c":["小堂深稳据西偏，插架牙签灿属联。","万卷新如手未触，五经嘲解腹空便。","子同蒋诩开三径，我学扬雄老一廛。","归去梁溪谋筑室，隔江相望两翛然。"]},{"t":"次韵徽言见赠","f":"五言古诗","c":["白首穷一经，此道何尝东。","陋质误识擢，珥笔宸庭枫。","胸中何所见，耿耿惟孤忠。","谪官乃自取，宠辱久矣同。","朅来旅江城，胜游幸从公。","款昵宴笑欢，顾忘身世穷。","十年倦游意，一笑回首空。","尚馀爱君心，梦绕明光宫。","夫子抱高趣，才气凛以雄。","挥毫写妙语，烨若五彩虹。","宁淹江海上，行簉鹓鹭中。","放怀且玉友，不用酟郫筒。"]},{"t":"尧明以五诗赆行辞意激昂钦玩无已辄用第五首次韵为报聊发一笑","f":"五言古诗","c":["吹台一樽酒，平昔接英游。","棘闱澹墨榜，曾见成名秋。","焉知江海上，乃复同唱酬。","子如清庙器，端俟识者收。","又如御厨珍，可用三公羞。","高志凛冰雪，妙语锵琳球。","三年未飞鸣，一举宜无俦。","我已谢世网，逝将老一丘。","愿子勉自爱，食肉鄙虎头。","名节乃难立，富贵良易求。"]},{"t":"自海陵泛江归梁溪作","f":"七言古诗","c":["清江湛湛波不兴，澄江际天如镜平。","火云突兀耸峰岫，倒影万丈摇空明。","扁舟归逐落潮急，聒耳但闻双橹声。","乃知长江无六月，水气自与风兼清。","去年狂寇起歙睦，江浙惨澹妖气凝。","百年涵养极繁盛，一日荡析屯臊腥。","衣冠北渡旅淮甸，扶老携幼纷从横。","王师出讨盛貔虎，凶渠授首封鲵鲸。","迨兹浙右稍安定，鼓拖复作东南征。","家山在望已可喜，僮仆候我应欢迎。","平畴戢戢稻秧绿，峻岭霭霭松林青。","田园有趣良足乐，轩冕无味非所荣。","苍生倘有安堵望，笑傲自可终馀龄。","只今馀孽尚充斥，努力庙算宜哀矜。","裹包兵革不复用，坐使四海还康宁。"]},{"t":"次韵上元宰胡俊明蒋山勤老唱和古风","f":"七言古诗","c":["竺教流传入中土，以相求之无自可。","达磨西来直指心，拟议之间已蹉过。","皮髓谁分深浅机，祖祢翻贻子孙祸。","钟山禅老真可人，高唱宗风震江左。","学流云集欲何为，佛祖要须自心作。","宰官倥偬牒讼间，偷暇相从还作么。","也知襟抱素相亲，更把篇章迭酬和。","词严义密读难晓，字顺文从识皆妥。","应怜孤陋方杜门，亦欲追随良未果。","故将佳句寄幽人，此意勤渠滋愧荷。","谈空摩诘无一言，听法文殊非两个。","若将情解议真如，明眼人前应看破。","世间万法互低昂，正若旋轮与推磨。","随时俯仰乃善谋，就中拙者无过我。","九折羊肠欲着鞭，万里沧溟思纵柁。","只今行年四十馀，已觉衰颓多坐卧。","平生作具何所施，尽以付之一弄火。","回光返照默自参，妙湛本然无点涴。","公方齿壮志气豪，正可立功同魏颗。","胡为亦复味禅那，坐视轩裳如絷锁。","莲社庄严清净池，丈室含容高广座。","他时共结香火缘，心期耿耿当非颇。","为余稽首问勤师，如师材德诚磊砢。","钓龙罗凤大江滨，法器谁为语无堕。","庭前倘有立雪人，我欲因风致三贺。"]},{"t":"寄许振叔显谟","f":"七言律诗","c":["我向江湖老此身，公犹拘絷作羁臣。","兰宫笑语真一梦，泽国过从今几人。","霜落洞庭橙橘熟，泉斟桑苧茗芽新。","相望百里如千里，早晚归来共钓缗。"]},{"t":"次韵仲弟古意","f":"五言古诗","c":["棣萼相荣华，鸰原同急难。","富贵何足羡，名节在所完。","吾家诸弟昆，擢秀森琅玕。","虽无金朱乐，顾有道义欢。","故人岂不多，谁念范叔寒。","卜筑九峰下，庇此拙且顽。","山光入户牖，溪水清不湍。","我屋虽无华，容膝审易安。","田畴半莨莠，念兹岁方艰。","虚室味图史，小圃蓻茝兰。","萧然寂寞滨，庶保馀龄閒。","哲弟富才业，壮志思昭奸。","勉哉振此道，吾方閒处看。"]},{"t":"次韵李似表县丞出示游西湖古风二首 其一","f":"五言古诗","c":["迂愚与世违，深渺方自屏。","萧然岩壑心，不与馀事并。","澄湖武林西，风物非尘境。","愿为境中人，此志久已定。","卜居梁溪滨，日汲陆子井。","幽梦绕湖山，妙趣神先领。","浮家苕霅间，初不费驰骋。","招携得佳友，高咏笑匡鼎。","富贵如浮云，功名真画饼。","且尽季鹰杯，更饱卢仝茗。","李侯东南来，胸次涵万顷。","作诗纪幽寻，句法言可永。","念子到山中，天地正悽冷。","青鞋踏冰霜，共赏谁复肯。","胜游子先之，吾亦行买艇。"]},{"t":"次韵李似表县丞出示游西湖古风二首 其二","f":"五言古诗","c":["李侯嗜学古，馀事皆远屏。","昂昂鸾鹄姿，岂与凡禽并。","捧檄来南州，初识浙江境。","寻盟款吾庐，不待日中定。","从容叩所得，响答如汲井。","时方罗俊乂，宁久淹簿领。","清秋雕鹗飞，大道骅骝骋。","词章尤激昂，笔力可扛鼎。","虚堂纵谈笑，霜月挂金饼。","夜阑言愈微，至味嚼佳茗。","古来会合难，岁月积俄顷。","愿子谨所之，万里路方永。","吾衰老閒旷，轩冕志已冷。","栖迟丘壑间，此兴良自肯。","他日来相遇，梁溪寻钓艇。"]},{"t":"似表复以诗来再次前韵并简似矩待制似之舍人","f":"楚辞体","c":["吾宗抱逸韵，试吏得南屏。","扫厅日哦诗，俗士驾敢并。","双溪与叠嶂，拄颊对佳境。","诸昆奉板舆，晨夕严省定。","仲氏近剖符，鍊养窥丹井。","叔兮久燕閒，禅要心独领。","何人絷骐骥，逸足未高骋。","会当归本朝，宗社重九鼎。","衰疲老山林，耕钓供饵饼。","叩门欣得朋，草草具醪茗。","追思会金陵，三载如食顷。","契阔怀晤言，川途阻修永。","临流送将归，岁晏风霜冷。","寄声昆季间，卜邻谁定肯。","天高烟雾深，且纵江湖艇。"]},{"t":"寄池阳黄季岑士曹 其一","f":"七言律诗","c":["昔年多士萃南宫，曾见雄文晔彩虹。","万里相期霄汉上，一官犹在大江东。","新诗寄远句增丽，旧事追游梦已空。","努力要津张此志，吾方寒钓五湖中。"]},{"t":"寄池阳黄季岑士曹 其二","f":"七言律诗","c":["稚年嬉戏曾游地，往岁飘零假道还。","溪水寒生江祖石，洞云深接九华山。","锦苔绿字几多在，石燕白鸥相与閒。","幕府诗人富家学，定留秀句满岩间。"]},{"t":"冬日登小阁有感呈子美提举奉议 其一","f":"七言律诗","c":["霜落风高万里枯，孤鸿窅窅下平湖。","行藏谁会倚栏意，啸咏聊为终老娱。","寒日溪山相掩蔼，暮云楼阁半虚无。","何人妙解丹青事，画作辋川烟霭图。"]},{"t":"冬日登小阁有感呈子美提举奉议 其二","f":"七言律诗","c":["绕舍松林寒不枯，烟霞深处见澄湖。","萦青缭白知谁赏，把酒裁诗可自娱。","剡曲幸非千里远，同云又复一冬无。","会当半夜溪山白，乘兴真为访戴图。"]},{"t":"送邓志宏赴试南省","f":"五言古诗","c":["杜门忧患馀，戚戚常鲜欢。","故人千里来，一笑解我颜。","念昔寓沙阳，溪山郁回环。","游从得良友，妙赏穷跻攀。","别来几何时，岁月惊飞翻。","索居无与游，衰病两鬓斑。","子充观国宾，假道叩我关。","草草具盘馔，把酒望西山。","道旧访陈迹，相对如梦间。","顾子若鸿鹄，整翮正高骞。","轩然四海心，岂惮行路难。","努力取殊第，自致青云端。","春风得意后，期子从兹还。"]},{"t":"次韵仲弟独游惠山古风","f":"五言古诗","c":["我家九峰下，跬步临胜境。","循除环佩声，满庭松桂影。","宦游阻幽寻，每若龟引颈。","十年旅京华，万里走闽岭。","归怀寄清梦，投檄期子请。","向来兵火作，此地偶无警。","馀生集百忧，负郭耕二顷。","新交浸已疏，旧学谋复整。","功名一灰灺，毁誉两蛙黾。","抱拙与世违，退缩甘远屏。","杜关绝外游，但欲俗缘省。","兹山乃故人，雅契相与永。","登临富泉石，采掇足芹荇。","下瓢酌甘芳，日汲谢瓶绠。","胡为久不到，有愧稚川井。","仲弟绝俗姿，好勇先我骋。","新诗纪清赏，得句颇彪炳。","艰难见鸰原，岁月侵晚景。","相期老丘壑，不复叹土梗。","梁溪寒可渔，蓑笠同舴艋。","宁如六一翁，终日思汝颍。","方兹筑吾庐，跧伏念前眚。","面山开小阁，制度阒深靓。","山气日夕佳，爽致当共领。","夜久霜露寒，星月光囧囧。","冷然欲御风，岂惮广寒冷。","邻钟韵更幽，皓鹤唳方儆。","深炷一炉烟，宴坐得三省。"]},{"t":"吴元中书言近不作诗以所著豳七月诗义见示因成三篇赠之 其一","f":"七言律诗","c":["旰起幽居尚闭关，忽传尺素破愁颜。","迂疏似我宜深隐，才术如公岂暂闲。","雅意未曾忘北阙，胜游今日且东山。","十年回首当时事，叹息人生似梦间。"]},{"t":"吴元中书言近不作诗以所著豳七月诗义见示因成三篇赠之 其二","f":"七言律诗","c":["底事年来不作诗，应缘思苦少人知。","凌云健笔含毫日，照眼花枝得句时。","陶冶性情端赖此，咏嘲风月漫多为。","驿筒若许陪酬唱，朱字青笺复寄谁。"]},{"t":"吴元中书言近不作诗以所著豳七月诗义见示因成三篇赠之 其三","f":"七言律诗","c":["儒生乐事信同风，端抱前言当鼓钟。","公正说诗笺七月，我方学易纬群龙。","艰难盛事原衣食，忧患馀生问吉凶。","去圣寥寥千载后，何时挥麈得从容。"]},{"t":"题伯时明皇蜀道图","f":"词","c":["君不见开元天宝同一主，治乱相翻如手举。","掔盈欲恶虽一人，变易安危原近辅。","姚宋已死九龄黜，谁使杨钊继林甫。","宫中太真专宠私，塞外番酋成跋扈。","祸胎养就不自知，漫向华清遗匕箸。","渔阳突骑破潼关，百二山河震金鼓。","翠华杳杳幸西南，赤县纷纷集夷虏。","伤心坡下失红颜，堕泪铃中闻夜雨。","山青江碧蜀道难，栈阁连空㒟相拄。","旌旗惨淡云物愁，林木阴森猿鸟侣。","戎装宫女亦善骑，皓齿明眸犹笑语。","老髯奚官驱蹇驴，负橐赍粮岂供御。","九重徼卫复谁勤，万里艰危真自取。","至尊狼狈尚如此，叹息苍生困豺虎。","千秋万岁不胜悲，玉辇金舆尽黄土。","空令画手思入神，一写丹青戒今古。"]},{"t":"送韩茂遵解元赴试南省","f":"七言律诗","c":["忧患馀生日杜关，幅巾青顾得开颜。","虚堂把酒延佳月，小阁哦诗对远山。","子学鲲鹏将海运，我同猿鹤且云闲。","都城故旧还相问，为道衰颓鬓已斑。"]},{"t":"题邵平种瓜图","f":"词","c":["君不见伯成子高让侯爵，在野终年自耕穫。","下风趋问礼徒勤，俋俋田间事无落。","又不见于陵仲子推相位，为人灌园刈葵藿。","抱瓮区区同汉阴，不糁藜羹有馀乐。","古来贤达有如此，志趣未可常情度。","力辞富贵居贱贫，凛若风霜陨轻箨。","邵平本自侯东陵，秦破国除休一壑。","当时汉祖疑酂侯，置卫增封意非薄。","众宾皆贺平独吊，一言转祸推先觉。","以兹智略佐风云，复取故封何所怍。","归来种瓜青门外，灌溉锄耘甘寂寞。","长安之东壤尤美，翠蔓离离照城郭。","秋阳正炽瓜正肥，解衣摘实如俛鹤。","儿童随立形骨清，挈笠携筐助操作。","遂令世美东陵瓜，身后高名动寥廓。","屠贩曾闻封绛灌，奴仆从来兴卫霍。","高鸟已尽良弓藏，更有韩彭辱囚缚。","何如终老守瓜畦，自饱饱他真不恶。","龙眠也是可怜人，画此端令事如昨。","世间如画画如梦，聊为作歌资一噱。"]},{"t":"寄题外氏松源绍祖亭 其一","f":"五言律诗","c":["束剑艰危际，结庐閒旷滨。","全家入青嶂，避地为黄巾。","族系归图谱，风流蔼荐绅。","云仍藉馀泽，勿替德维新。"]},{"t":"寄题外氏松源绍祖亭 其二","f":"五言律诗","c":["外族云峰畔，新亭烟水滨。","儿童旧游地，感慨易沾巾。","竹里锵鸣佩，山边缭素绅。","何当俯轩槛，一览物华新。"]},{"t":"近以诗寄许振叔承林德祖见和复次前韵寄之","f":"七言律诗","c":["甫里先生早乞身，最怜流落汉庭臣。","也知雅有绨袍意，故使同为莲社人。","佳句传来油素湿，灵文翻处贝多新。","更烦为指趋真路，旧国于今草木缗。"]},{"t":"次韵顾子美见示题曲江画像","f":"七言古诗","c":["天眷李唐能肖德，异人间出生其国。","于中贞观开元间，譬若丰年多黍稷。","曲江擢秀自妙龄，国器早被燕公识。","文词赡蔚冠后来，大册高文振鸿笔。","孤生徒步起荒陬，职秉钧衡爵侯伯。","一时推挽尽正人，谠议嘉谟咸可绩。","能于偏校识胡情，此理未可常情亿。","哥奴岂是郎官材，谁使岩廊久践历。","眉宇津津挟兔雕，酝藉居然困摧抑。","正衙造膝访相臣，岂止伶官论安叱。","天意方将启禄山，帝心那解疑仙客。","房帷阴谋独上陈，三子未冤繄巨力。","伟哉相业继姚宋，允矣威声落夷貊。","千秋金鉴奉君王，仁者之言古遗直。","咏燕论心讵免猜，赋扇陈情竟何意。","黄钟毁弃瓦釜呜，凤去鸮鸱集槐棘。","固知骨鲠易婴鳞，坐使奸谀得乘隙。","一麾出守来荆蛮，直道忘怀谢欣戚。","诗篇冥助得江山，文史终年自怡怿。","渔阳鼙鼓震长安，祸乱宁从一朝积。","翠华西幸蒙尘飞，蜀道艰难会相忆。","至言逆耳弃不收，遣祭徒劳长叹息。","古来忠谠尽如此，端欲济时如谷帛。","空令万世沧海南，崒兀高名配韶石。","于粲荔丹蕉叶黄，庙猊屹然兹血食。","身亡道立复何求，失策自与当时惜。","丹青谁为写清姿，风度严凝见颜色。","顾侯好古如古人，此本云自韶阳得。","笏囊无复使人持，奕奕蝉冠照虚壁。","象设曾闻铁作胎，英灵尚想心犹赤。","拜公遗像激懦衷，怅望天南瘴江碧。","高辞险语极揄扬，勉强追酬愧非敌。"]},{"t":"小阁晚望书怀一百韵示仲弟并简顾子美","f":"词","c":["岁晏群阴积，天高霰雪晴。","西山来爽致，小阁湛虚明。","曲槛驰孤照，微云点太清。","泛观周宇宙，旷望出枝撑。","九陇龙蛇伏，梁溪组练萦。","翠烟浮近市，碧瓦丽高甍。","湖外千岩秀，林端一带平。","松篁森荟蔚，楼观郁峥嵘。","天末氛埃敛，坤倪物象呈。","清风生户牖，秀色入轩楹。","北极星辰拱，东皋雨露赢。","寸怀舒远目，万感集孤情。","忆昨陪螭殿，终年侍玉京。","含毫青琐闼，通籍凤凰城。","奖擢知恩重，临危觉死轻。","囊书朝入奏，襆被夕徂征。","去历溪山险，归虞盗贼惊。","西江足波浪，南国满旃旌。","迂路良非策，寻家不计程。","天戈戡猰貐，庙略扫欃枪。","芜没田园在，欢呼仆隶迎。","乱离才甫定，患祸忽相婴。","风木悲摧感，祥琴惨怆声。","誓终坟墓守，望绝缙绅荣。","卜筑诚长计，栖迟岂钓名。","当为千载蛰，那作九皋鸣。","示舌羞张子，轻身笑祢衡。","盘桓且丘壑，腾踏自公卿。","未具函关驾，聊从谷口耕。","岁功方险恶，供给敢丰盈。","瘠陇饶稂莠，彪池秕稻粳。","何心谋肉食，充腹但藜羹。","孤笑弹长铗，微吟就短檠。","开编聊自慰，攻苦饱曾更。","卮酒和糟粕，盘飧杂蚌蛏。","恐须食翠柏，尚未斸黄精。","腊破冰澌解，春回草木萌。","且休吟蟋蟀，行复听鸧鹒。","献岁三朝始，初阳一气亨。","小梅舒冻蘖，疏柳茁枯茎。","帘幕还飞燕，园林又转莺。","试编居士屩，学种故侯寓。","抱瓮浇芝朮，联畦莳杜蘅。","摘甘聊共剖，钓美得同烹。","烟艇笭箵稳，云溪略彴横。","行吟携古锦，坐隐寄文枰。","据石从攲帽，临流可濯缨。","閒中端有趣，身外更无营。","古寺回峦拥，细泉幽窦倾。","带云斟晓杓，和月贮春罂。","绕径摇金碎，循除响玉琤。","由来穿蜡屐，未必羡葱珩。","借问披衣惯，何如结佩綪。","端知绶若若，不假铁铮铮。","匠石宜遗栎，山川讵舍骍。","甘为书里蠹，惮作庙中牲。","云鹄翰方铩，风鸢羽正翃。","隐沦随绮皓，菹醢叹韩彭。","坐逸真侥倖，时康孰使令。","普天期一稔，率土庆群氓。","耒耜三农出，仓箱万宝成。","馀粮饱羸瘵，大屋芘嫠?。","稚耋皆含哺，潢池不弄兵。","人咸安畎亩，吾亦乐柴荆。","已与猿猱侣，犹怀犬马诚。","忧心虽悄悄，执节信硁硁。","老去将忘世，朋来且命觥。","嘉宾期座满，陋巷或车轰。","幽鸟会心近，良辰乐事并。","黄粱菹露薤，白蟹芼霜橙。","何苦三升恋，当为五斗酲。","涧莼舒翠缕，林笋脱文绷。","池草铺新绿，亭花藉落英。","醉眠方栩栩，儿泣任喤喤。","庭树朝嘲雀，书帷夜话蜻。","心清香篆缭，耳隐梵钟鎗。","游宦从诸季，浮沉许拙兄。","棣华知晔晔，伐木亦丁丁。","操履资磨琢，论文贵讨评。","杖藜扶跛倚，药剂发聋盲。","绝倒心都醉，奔驰视只瞠。","风流怀卫玠，敏捷忆袁宏。","愿见摩天手，真成掷地玎。","戈矛万人敌，脍炙五侯鲭。","意妙操干舞，声希舍瑟铿。","味深饴醴酪，调古奏韺䪫。","文社谁襟袖，诗坛为主盟。","中书仗毛颖，发墨赖陶泓。","友直常希黯，言刚酷鄙枨。","藏刀真善割，胶柱未能筝。","数马须资策，驰车必式衡。","传家惟义训，教子谢金籯。","婚嫁何时毕，遨嬉莫我争。","浮家苕水去，乘兴剡川行。","吴殿悲游鹿，秦宫吊拱鼪。","炉峰看瀑布，缑岭听吹笙。","神岳登嵩华，仙洲指沃瀛。","冲天思御鹤，跨海欲骑鲸。","浩荡愁千古，翱翔抚八纮。","会当期若士，高揖笑浮生。"]},{"t":"唐植甫左司许出示所藏红丝砚辄成短歌奉呈并简顾子美","f":"七言古诗","c":["羲和整御升旸谷，赤云夹日如飞鹜。","晶光下射东方山，石卵含丹孕岩腹。","谁令巧匠凿山骨，截此赪坚一肪玉。","琢为巨砚形制奇，中有彤云烂盈目。","端溪美璞色马肝，黟歙珍胚纹雾縠。","岂知至宝出嵎夷，散绮浮花彩尤缛。","凤咮空闻名字佳，龙尾苦笑规模俗。","谩誇眉子斗婵娟，休认明眸类鸲鹆。","顾眄幸蒙君子知，拂拭自远尘埃辱。","火轮炫熀赤乌流，墨海奫沦玄兔浴。","千金象管雕镂精，百鍊松煤龙麝馥。","怒猊渴骥纵奔拿，春蚓秋蛇相绾束。","楮生便觉肌理妍，毛颖何尝免冠秃。","公家三世擅直声，此砚提携资简牍。","力侔天地掌中回，胆落奸谀笔端戮。","固宜秘玩不轻示，神物护持无辄黩。","窗明几净斋阁深，日暖风清霭松竹。","试将墨妙写新诗，落笔烟云叹神速。","矧公早年曾饵丹，龟鹤精神鬓毛绿。","久卧商山茹紫芝，行度天门骑白鹿。","猗兰玉树富阶庭，黄卷青缃剩编轴。","愿言什袭遗云仍，大笔高文永相续。"]},{"t":"次韵顾子美提举许雪中见过之作","f":"七言古诗","c":["残腊苦寒情味恶，万里风云欣雪作。","夜积端愁坤轴倾，晓望却惊天界扩。","玉龙鳞甲卧群山，水海波澜凝巨壑。","谢家儿女自多才，笑咏飞花度罗幕。","金炉未觉兽炭温，锦帐犹讶貂裘薄。","书生饥甚况复寒，坐听朱弦折临狱。","松孤竹老念山林，甲冷戈寒悯沙漠。","岂思龙尾贺千官，且叠琴心舞双鹤。","瑶林玉树粲回环，勿谓轩庭全冷落。","拥门但作袁安卧，命驾谁思子猷乐。","溪山如画真自知，金玉满堂端不博。","烦公携具款我门，注目遥空登晚阁。","冻吟犹作号寒声，此病欲医那有药。","公家故自富香醪，我亦安能辞巨杓。","醉看万事雪销凝，妙观圆成不须学。"]},{"t":"次韵邵子非见赠之作","f":"七言律诗","c":["持竿相与钓鲸鱼，叹息平生术已疏。","嬉戏尚能追旧事，穷愁聊复著新书。","昂霄耸壑公行尔，拂石眠云我自如。","卜筑相望才一水，未应岁晚恨离居。"]},{"t":"次韵子美寄彦章同游惠山之作","f":"七言古诗","c":["结庐寂无车马喧，雀罗可设深扃门。","北窗一枕半成梦，剥啄叩户惊心魂。","故人见过适我愿，相与携手游山樊。","春风桃李已零落，孟夏草木行滋繁。","下瓢共酌陆子井，策杖更步公垂园。","山肴野蔌助清赏，此心非子将谁论。","人生聚散如露电，访旧叹息无多存。","区区得失何足较，瑟僩但期终不谖。","嗟予夙昔志四海，远游欲学飞鸿轩。","南征曾上帝子阁，暮雨朝云相吐吞。","西山积翠多爽气，大江萦练方东奔。","十年回首如梦到，旧事今复闻公言。","迩来百念已灰冷，但愿痛饮穷朝昏。","新交渐鲜俗缘久，省要更觉情怀敦。","山中蕙帐不落寞，无复怨鹤啼惊猿。","平生有意师老氏，以退为进卑为尊。","致君泽物付公等，我乃送老溪前村。","置之此事勿复道，且须吸尽黄金樽。"]},{"t":"蒋山佛果师为缘事来而此土方饥戏赋是诗以发一笑","f":"七言古诗","c":["钟山禅老天骨奇，丛林晏座如孤罴。","诸方宗仰第一义，说法舌作霹雳飞。","年来为众建广厦，胸中结构良峨巍。","修梁巨栋资喜舍，瓶锡不惮东南驰。","飞腾道俗走檀越，堆积金贝罗珠玑。","此方旱潦异常岁，百里稚耋方流离。","析薪鬻子给朝夕，阖境半作婴儿啼。","坐看缘事莫措手，却欲反著僧伽梨。","未闻兰若泣龙象，好把信施赒寒饥。","向来收拾大宝聚，随手散尽真慈悲。","惟师具眼得空观，稛载岂愁华橐归。","吾言可听勿惆怅，无价宝珠元在衣。"]},{"t":"次韵叶少蕴内翰丈霅川上买得弁山石林二首 其一","f":"七言律诗","c":["翰林风度世间无，炯若清冰置玉壶。","暂向霅川谋小隐，未应鲁国舍真儒。","平泉草木何须记，杜曲桑麻幸可图。","我亦新沾散人号，浮家正欲老江湖。"]},{"t":"次韵叶少蕴内翰丈霅川上买得弁山石林二首 其二","f":"七言律诗","c":["视草金銮不记年，却将心事付林泉。","归居盘谷真良策，买得愚溪定夙缘。","隔竹闻声鸣佩玉，挥毫落纸散云烟。","欲誇水石无穷趣，故把新诗得得传。"]},{"t":"近约周仲居同游阳羡以私故不果见寄笱蕨因成此诗","f":"七言律诗","c":["胜游尚尔阻跻攀，自愧閒中亦未閒。","多谢幽人分笋蕨，宛同春日到云山。","洞天上下烟霞里，溪水回环图画间。","暂过岂能穷妙赏，结庐终欲老疏顽。"]},{"t":"次韵顾子美见示久雨三首 其一","f":"五言律诗","c":["一春常苦雨，入夏尚悭晴。","云物频舒卷，轩窗乍晦明。","下田嗟涨溢，高岸惜颓倾。","蔓草无情思，芟除又发生。"]},{"t":"次韵顾子美见示久雨三首 其二","f":"五言律诗","c":["朝来疑欲霁，云气复如蒸。","泥潦疲驰骤，晨昏错寝兴。","及时初可喜，失节反堪憎。","安得西山出，层楼共一登。"]},{"t":"次韵顾子美见示久雨三首 其三","f":"五言律诗","c":["中夏犹裌衣，泽国信殊候。","连阴不复开，似欲无晴昼。","涓涓檐间滴，駃駃渠中溜。","苍生环堵完，遑恤吾庐漏。"]},{"t":"寄毛达可内翰并录送魏公别录 其一","f":"七言律诗","c":["縠水柯山蕴秀奇，精忠深结冕旒知。","玉堂视草久推重，金椀书名犹恨迟。","廊庙未应忘泽物，江山且复助题诗。","慇勤寄录韩公事，好为斯民更筑基。"]},{"t":"寄毛达可内翰并录送魏公别录 其二","f":"七言律诗","c":["迂愚聊复隐清时，幽事相关只自知。","满地落花看鹤舞，一轩春雨对僧棋。","闲中日月真销得，物外烟霞渐可期。","坐致时康赖公等，不须深遁采商芝。"]},{"t":"莼菜","f":"七言律诗","c":["渺渺春湖水拍天，紫莼千里正联绵。","初抽荷蕊半含露，旋摘龙须尚带涎。","盐豉欲调难并美，鲈鱼兼忆讵非贤。","自怜不是知机士，饱食空能上钓船。"]},{"t":"送李泰发吏部赴官阳朔 其一","f":"七言律诗","c":["意气相期会面前，谪官邂逅两萧然。","谁怜兰省鹓鸾友，去作桂林山水仙。","直道事人宁免黜，拙谋于我欲争先。","宽恩下逮宜非久，来买梁溪二顷田。"]},{"t":"送李泰发吏部赴官阳朔 其二","f":"七言律诗","c":["阳朔溪山冠百蛮，羡君远宦得跻攀。","声名已落寰区内，忠信自行夷貊间。","山作剑铓攒峻拔，水如罗带巧回环。","此生又作南征计，好把轻绡寄一斑。"]},{"t":"寄李泰发吏部","f":"七言古诗","c":["我生禀赋愚且屯，昔游帝所知何因。","狂言妄发取谴废，屏迹分甘麋鹿群。","公于何许知姓字，迂趾访我梁溪滨。","平生倾盖意气合，谈笑便觉襟怀亲。","如公材识迈伦等，缓步自当居要津。","胡为亦复作此态，出语辄已惊臣邻。","扁舟归探会稽穴，单骑去指苍梧云。","岭南风土不全恶，阳朔山水古所珍。","郎官出宰乃故事，绝徼万里皆吾民。","布宣德泽被蛮邑，犷俗可使风还淳。","古来节士志沟壑，笑视生死同埃尘。","甘心刀锯蹈鼎镬，徇国讵免危其身。","圣朝宽大幸无比，窜谪未久多蒙恩。","辕驹仗马恋刍豆，何用局促声长吞。","堂堂基业甚宏远，岂使扶助无良臣。","勉旃行矣伫旋旆，乘兴且访山阴人。"]},{"t":"同翁士特小饮中隐堂","f":"七言律诗","c":["三伏炎蒸画舸回，蓬门聊复为君开。","松篁荫翳樽中渌，杖履逍遥池上台。","小雨乍随云影散，好风还逐月光来。","虚堂夜久群嚣息，枕簟相从亦快哉。"]},{"t":"士特见和复次前韵","f":"七言律诗","c":["丘园命驾未应回，三径还同蒋诩开。","盘谷初能容蕙帐，钧天无复梦瑶台。","稚年尚忆嬉游处，老境相从归去来。","幸有西山供醉眼，不妨吟望思悠哉。"]},{"t":"同士特游惠山再次前韵","f":"七言律诗","c":["九峰秀色照溪回，古寺峥嵘殿阁开。","漱玉泉声锵石洞，郁蓝天影抱琼台。","亲宾情话真难得，岩壑幽寻岂易来。","且复淹留同一醉，未应遄棹念归哉。"]},{"t":"题周孝侯庙","f":"词","c":["周侯高节冠千古，志气刚明乃如许。","剑斩长桥戟尾蛟，刺杀南山雪毛虎。","归来一听闾里言，折节宁辞远游苦。","学成名立世共惊，徇国忘身乃其所。","至今血食荆溪滨，庙猊崇深日箫鼓。","我来再拜仰遗像，思古伤今怅谁语。","君不见淮阴跨下已亡奇，哙等何羞与为伍。"]},{"t":"余乙巳春赴奉常召如京师五月四日至京口同似表叔易游北固甘露寺","f":"七言律诗","c":["招提殿阁郁嵯峨，占得江山气象多。","一水下临萦素练，两山对峙叠青螺。","乍欣心目到空阔，坐看风云相荡摩。","景物自新人自老，旧游追忆奈愁何。"]},{"t":"雨中渡杨子江书怀呈似表叔易","f":"七言律诗","c":["波光澹澹橹声圆，风软潮平利涉川。","浩渺云涛连海峤，空濛烟雨湿楼船。","江山雄伟冠天下，景物瑰奇绕目前。","远迹禹功须我辈，感时怀古一悽然。"]},{"t":"同似表叔易置酒平山堂","f":"七言律诗","c":["暂停征棹此从容，叹息前贤结构雄。","心眼乍随天宇阔，笑谈不觉酒樽空。","江光隐见轩楹里，山色虚无烟雨中。","种柳仙翁何处去，年年疏翠自春风。"]},{"t":"过召伯埭游斗野亭次司谏孙公韵","f":"五言古诗","c":["星斗照淮楚，绿野如砥平。","兹亭结构小，景物有馀清。","我来值袢暑，霁雾褰高甍。","登临得佳友，坐使怀抱倾。","方塘杨柳合，极望菰蒲生。","仰德思谢傅，吊古伤芜城。","浊酒聊共酌，小鳞鲜可烹。","抱拙卧江海，胡为复此行。","区区萤爝光，何补日月明。","稽古得车马，平生笑桓荣。"]},{"t":"途中书怀","f":"七言律诗","c":["去国飘零伴一星，误恩还许谒承明。","已甘松菊老三径，岂有材猷厕九卿。","晚景故惭题柱客，壮怀多谢弃繻生。","片帆自逐南风起，遇坎乘流且么行。"]},{"t":"新开河食鳜鱼戏成","f":"七言古诗","c":["平湖渺漫烟苍苍，菰蒲擢秀新荷香。","渔舟演漾出深浦，舟中鲜鳜肥而臧。","传呼就买不论价，得钱留鱼鱼眼光。","细鳞哆口传鬐鬣，斓斑点黑微涂黄。","巨盆汲水养馀息，拨剌奋尾犹洋洋。","付庖荐酒择困者，挥刀切玉芼桂姜。","曲生风味已酝藉，得此更使不可忘。","松江之鲈不足忆，银色讵数绵州鲂。","惜哉行役难驻棹，一饱未许杯盘常。","雨蓑烟笠乃吾事，安得独钓青茫茫。"]},{"t":"泗上瞻礼僧伽塔","f":"五言古诗","c":["汤汤淮泗滨，实为至人居。","至人骨已冷，灵响初不渝。","巍然窣堵波，金碧耀云衢。","突兀三百尺，势欲凌霄虚。","乃知天人师，宜有神明扶。","忆昔岁乙未，奉亲由此途。","开关瞻晬容，端相不可诬。","清秋日当午，为现摩尼珠。","蝉联宝铎间，悬缀如流苏。","万目共瞻睹，稚耋驩惊呼。","重来念旧事，感叹涕潸如。","再拜礼双足，如师真丈夫。"]},{"t":"汴上有感","f":"七言律诗","c":["不踏隋池今几日，重来空叹二毛侵。","黄流浑浑帆樯影，绿岸森森榆柳阴。","雨霁鸠鸣呼妇急，晓凉蝉噪感人深。","区区往返何为者，谁识先贤用舍心。"]},{"t":"宝剑联句","f":"五言古诗","c":["造化炉锤巧，山溪矿镤良。","精金付欧冶，妙手铸干将。","淬砺呈锋锷，飞腾辨耿光。","青黄司火候，爪发助祈禳。","桃氏几时献，龙文难久藏。","鳞皴识松理，乙屈认鱼肠。","黯黯青蛇色，炎炎赤帝祥。","提携起三尺，驾驭牧群狼。","弹铗悲冯子，誇镡悟赵王。","神功归不试，利用运无旁。","赠客千金直，方人百鍊钢。","还须玉具饰，何用蒯缑装。","讵使妖腰喜，当容节士狂。","纯卢非妩媚，巨阙太坚刚。","郁勃冲牛斗，蛇蜒接混茫。","畴能宝于越，俱议刻艅艎。","抆拭资神土，珍藏閟宝房。","斩蛟诚壮勇，剸象见铦铓。","韩信归高祖，朱云赐尚方。","雄材元倚仗，佞胆已飞扬。","浑脱公孙舞，缦胡庶士伤。","吴钩能曲折，蜀汉有文章。","六赐恩何厚，三名怨未偿。","先知吼蛟兕，摩钝凛冰霜。","犬子尝思击，猿公莫敢当。","翁归备文武，季路戒彊梁。","疾视真何事，要盟或可臧。","镵天隳彗孛，适野走徬徨。","麾拂飞雷电，轩昂变雨旸。","刺强同匕首，定乱岂长枪。","叔向排当御，昭王畏拙倡。","买牛今欲老，铸鏄岁方穰。","徐国留吴札，鸿门蔽顶庄。","拄颐真贵盛，击柱妄披猖。","曜攒山妖见，秦兴水怪彰。","万人犹可敌，一吷未应扬。","不动惊公胜，为誇异伯阳。","断匜犹未妙，穿屋始非常。","止水涵晶瑩，疏星点角芒。","聊须为武备，何必事戎行。","要并宗臣履，休同小盗裳。","冲星怜杜子，斫地叹王郎。","不假蒙须便，真成刃手创。","新硎如可发，故物未应忘。","黠虏称兵急，王师击鼓镗。","氛埃期扫荡，心胆为开张。","未斩楼兰级，那销黔首疮。","几回开匣罢，但欲引杯长。","聊复防身佩，毋为跃水亡。","报君吾志毕，以尔倚扶桑。"]},{"t":"山药","f":"七言律诗","c":["山家为我斸青冥，养就仙芝指掌明。","风味自应殊紫芋，功名初不减黄精。","藤盘欲荐冰霜质，石鼎先闻风雨声。","辟谷留侯正归去，淡然悠久见交情。"]},{"t":"煨芋","f":"词","c":["今夕何夕夜未央，天寒拥炉更漏长。","缩肩环坐有饥色，呼童取芋灰为塘。","蹲鸱得火良易熟，脱落皮毛如紫玉。","迭煨迭进争相先，笑语颇喧知实腹。","锦里先生亦不贫，家园收拾动千斤。","凶年自可活妻子，美好不减岷江滨。","邺侯昔游衡岳左，懒瓒食馀贻半个。","我今归去隐家山，岂复从人觅残颗。","臞儒奉养亦已微，一饱便吟煨芋诗。","君不见齐公夜半意不嗛，易牙煎熬燔炙和调五味而进之。"]},{"t":"食蟹","f":"七言古诗","c":["秋风萧萧芦苇苍，野岸郭索纷成行。","持矛被甲正雄健，意气正欲行无旁。","朝魁执穗似有礼，拥剑敌虎何其强。","野人篝火夜采拨，束缚赴鼎如驱羊。","樽前风味若无敌，芼以橙橘尤芬芳。","流膏斫雪快一饱，咀嚼海错皆寻常。","丹枫夜落吴天霜，䆉稏欲熟千畦黄。","梁溪白蟹正可钓，雏鸡浊酒肥且香。","先生归去营口腹，老饕未许他人当。","家山渐近意渐适，思归岂独鲈鱼乡。"]},{"t":"九月五日对菊小饮简申伯叔易","f":"七言古诗","c":["渊明爱此九日名，对菊无钱可留客。","杜陵烂醉作生涯，青蕊空嗟未堪摘。","我今鼓柁适长淮，坐见幽丛烂熳开。","自从多病久不饮，又尔一洗黄金罍。","东南节物诚已早，翠叶金花为谁好。","三径荒芜尔尚存，未觉出山同小草。","世间万事皆可忘，且须泛此酬秋光。","平生最爱老坡语，菊花开日即重阳。"]},{"t":"小饮即事呈申伯","f":"七言律诗","c":["夜凉同咏古人诗，新月娟娟照酒卮。","一醉且忻军寇退，扁舟似与菊花期。","衔杯乐圣真吾事，泛宅浮家漫尔为。","归去云山最深处，隔江千里幸相思。"]},{"t":"玉华宫用杜子美韵","f":"五言古诗","c":["阿房但遗基，铜爵亦飘瓦。","兹宫制何朝，栋宇妙天下。","溪山最清绝，画手不可写。","于今黍离离，客过泪如洒。","乃知营宫殿，徒以业力假。","起灭犹浮沤，聚散齐一马。","如何世间士，天运欲持把。","此理贯古今，宜有知之者。"]},{"t":"九月八日渡淮","f":"七言古诗","c":["长淮渺渺烟苍苍，扁舟初脱隋渠黄。","平生见此为开眼，况复乞身还故乡。","嗟余涉世诚已拙，径步不虞机阱设。","空馀方寸炳如丹，北望此时心欲折。","楚天清晓作轻寒，黄芦着霜声正乾。","川回金碧隐窣堵，风远钟磬闻龟山。","橹声呕轧归何处，笑指江皋寻旧路。","松菊荒芜欲自锄，盗贼颠翻非所惧。","蟹螯菊蕊风味遒，且须为尽黄金舟。","世间种种如梦电，此物能消万古愁。"]},{"t":"九日与申伯叔易小饮","f":"七言律诗","c":["上客相从称玉觞，楚天杳杳湛清光。","紫茱黄菊有佳色，白蟹赪鳞聊共尝。","自哂三朝为逐客，常于九日旅殊方。","十年往返成何事，赢得萧萧满鬓霜。"]},{"t":"章华宫用张籍韵","f":"七言古诗","c":["楚王初建章华时，脩梁巨栋如云垂。","诸侯共落相长鬣，示汰往往逃而归。","当年左史箴王阙，祈招之诗为之发。","固宜便嬖意相当，肯使俊乂居周行。","宫中门户如莲房，锦茵绣幕春风香。","娥媌曼睩肌雪霜，侍燕承娱夜未央。","金石间作侑玉觞，兕觥不复称公堂。","志窥九鼎轻天王，翠被豹舄垂琼珰。","乾溪之辱岂其寿，峻宇雕墙湎于酒。"]},{"t":"次韵季弟善权阻雪古风","f":"七言古诗","c":["岁晏江南三尺雪，奕奕瀌瀌遂连月。","意浓岂是天纲疏，势重便疑坤轴折。","溪行小艇碎琼瑶，自胜缟带随车辙。","暝投兰若寄僧房，更觉千岩鸟飞绝。","忆昔宣和全盛年，嘉瑞应期来自天。","千官朝贺未央里，仰视龙尾垂蜿蜒。","珠树瑩煌青琐闼，玉花浮动苍龙阙。","但将歌舞赏清妍，肯信山河会分裂。","自从国步多艰难，胡骑长驱窥汉关。","阴风惨淡随杀气，见雪翻使摧心颜。","古来治理初无别，中国浸强胡浸灭。","坐令和气变阳春，肉食于今未宜忽。","迂愚放逐恩已宽，敢惮道远貂裘寒。","空馀炯炯寸心赤，中夜不寐忧千端。","素发飘萧头已满，百年光景行将半。","未知梦幻此生中，几回看雪光凌乱。","会当扫动豺狼穴，国耻乘时须一雪。","酒酣拔剑斫地歌，心胆开张五情热。","中兴之运我期皇，江汉更洒累臣血。"]},{"t":"善权即事十首 其一","f":"七言律诗","c":["荆溪移棹雪漫漫，皓色连空眼界宽。","练带萦回迷罨画，玉屏崷崒失铜官。","风飘珠蕊来玄圃，槎泛银潢到广寒。","安得丹青似摩诘，生绡写作画图看。"]},{"t":"善权即事十首 其二","f":"七言律诗","c":["十日荆溪雪未晴，敲冰聊作善权行。","最怜击碎琼瑶片，欲爱长闻环佩声。","百仞岩端仙梵过，千株松下老僧迎。","斯游自觉平生少，颇怪淹留景太清。"]},{"t":"善权即事十首 其三","f":"七言律诗","c":["雪著溪山澹复浓，行舟疑在玉壶中。","云藏半岭深难见，冰塞长川邈未通。","赖有僧房容假榻，未应尘迹叹飘蓬。","劳生梦幻成何事，万古闲愁一笑空。"]},{"t":"善权即事十首 其四","f":"七言律诗","c":["山崦溪湾三四家，竹篱茅舍暮烟斜。","仙村自种田田玉，梅径疑开处处花。","近渚冰销迷浴鹭，远村烟暝数栖鸦。","年年值雪长为客，对此悽然感岁华。"]},{"t":"善权即事十首 其五","f":"七言律诗","c":["小童又报雪花飞，深炷炉烟欲起时。","淅沥乍闻经竹叶，飘萧初看著松枝。","南人共讶何曾见，北顾深颦有所思。","牢落无言自搔首，却惊华发顿成丝。"]},{"t":"善权即事十首 其六","f":"七言律诗","c":["一夜凝寒雪意浓，禅房睡美不闻钟。","起看银色三千界，更忆瑶台十二重。","戴白苍官尤觉好，折腰青士若为容。","暮晴透出寒蟾色，为照溪头群玉峰。"]},{"t":"善权即事十首 其七","f":"七言律诗","c":["连日风云匝地阴，玉花飞舞满烟岑。","竹窗夜色棋方适，书幌朝寒酒倍斟。","幸有高人同胜赏，不妨佳处得幽寻。","庭前暗积知多少，自策筇枝探浅深。"]},{"t":"善权即事十首 其八","f":"七言律诗","c":["山空鸟雀傍檐楹，景邃惟闻钟鼓声。","懒瓒但知煨紫芋，少陵何处斸黄精。","江南寇盗休无赖，塞北烟尘迄未平。","太息浮生端值此，不如无念契无生。"]},{"t":"善权即事十首 其九","f":"七言律诗","c":["霁色初开雪未融，坐来风撼落长松。","林芿趫捷缘饥鼠，洞壑深沉蛰老龙。","致远未须金騕袅，凭高且看玉芙蓉。","丰年最有田家乐，雪屋何妨入夜舂。"]},{"t":"善权即事十首 其十","f":"七言律诗","c":["朝来鸟雀报新晴，乍喜窗间日影明。","糁径杨花浑寂寞，倚檐冰柱漫峥嵘。","早梅向暖垂垂发，好鸟知时得得鸣。","从此阳光渐舒畅，放回春色满江城。"]},{"t":"投金濑有感","f":"七言古诗","c":["楚王听谗诛五卿，招呼二子同就烹。","子胥弯弓见使者，义不戴天非惜生。","操瓢乞食困江表，曷尝一日忘郢城。","溧水之阳遇真识，壶浆箪食欣相迎。","当时追捕尚尔急，杀身灭口意岂轻。","霸吴何止服句践，破楚遂以鞭荆平。","倒行逆施道虽远，复仇摅愤圣所称。","却来访旧欲报德，叹息玉质随流萍。","投金浅濑亦何有，聊以寓意通精诚。","哀穷进食类漂母，解剑挂墓同延陵。","古人已矣不可见，空有史笔垂声名。"]},{"t":"题成士瑴所藏辋川雪图","f":"七言古诗","c":["朔风飞雪何漫漫，群山大半埋云端。","蓝田丘壑不易得，更把云雪妆林峦。","茅斋竹屋架岩巘，轩楹面势随所安。","素华淅沥洒空翠，逼耳似闻声正乾。","层崖冻冱石欲裂，飞瀑不碍双流湍。","长松落落有生意，连臂下饮惟玄猿。","椒园柳浪眇安在，髣髴犹认芙蓉沜。","乘危跨蹇者谁子，竦肩缩袖何其寒。","祇应诗句独有得，不减灞桥风雪间。","幽人一去久寂寞，寒藤滋蔓谁能删。","生绡数幅写绝景，空有图画今人看。"]},{"t":"次季弟韵赋梅花三首 其一","f":"七言律诗","c":["冷蕊疏枝烟水滨，江南此地又逢春。","年年行路常为客，的的寒花解笑人。","雪里暗香来鼻观，风前高格见天真。","谁言对尔销愁得，一段清愁特地新。"]},{"t":"次季弟韵赋梅花三首 其二","f":"七言律诗","c":["年年青女久横陈，赖有江梅漏泄春。","孤洁如亲隐君子，风流似对谪仙人。","雅期兰蕙香非远，解笑松华色未真。","开罢枝头著青实，故教桃李一番新。"]},{"t":"次季弟韵赋梅花三首 其三","f":"七言律诗","c":["群芳冻死未招魂，谁使梅花独占春。","愿折繁华凭驿使，为传幽思恼诗人。","心驰魏阙惭商鼎，路入章江忆子真。","莫道广平心似铁，赋辞得得与清新。"]},{"t":"宿黄柏村馆","f":"五言律诗","c":["客馆可人意，敢怀行路劳。","轩窗面苍翠，棋酒助嬉遨。","雨过竹声碎，风摇云影高。","人生随处适，何必赋离骚。"]},{"t":"寓宁国县圃中桃李杂花盛开感而赋诗 其一","f":"七言律诗","c":["春光不为干戈薄，花县纵观桃李开。","可惜繁华劳剪刻，莫教风雨便残摧。","溪山有意相辉映，蜂蝶多情自往来。","应笑逐臣心似铁，客中扶病亦登台。"]},{"t":"寓宁国县圃中桃李杂花盛开感而赋诗 其二","f":"七言律诗","c":["乍雨乍晴三月节，半开半合百花枝。","伤心春望不堪远，感事泪痕长欲垂。","塞北但知随水草，江南何事插旌麾。","上林无限莺花老，应怪来游凤辇迟。"]},{"t":"咏草","f":"七言律诗","c":["梦觉池塘碧草萋，风摇烟湿已菲菲。","绵联山色不知远，惆怅王孙何日归。","微质亦知烦雨露，寸心终欲报春晖。","芳根纵腐犹能化，舞蝶流莺到处飞。"]},{"t":"休宁县驿舍初见杨花","f":"七言绝句","c":["山馆风光随分好，方塘碧长萋萋草。","杨花摇荡入疏帘，又是一年春色老。"]},{"t":"黟歙道中士人献牡丹千叶面有盈尺者为赋此诗","f":"七言古诗","c":["平生爱花被花恼，每见牡丹常绝倒。","自从丧乱减风情，两年不识花枝好。","迩来谪堕烟雨中，行色日与春光浓。","今夕何夕见粲者，颇类寿安千叶红。","岂知黟歙深山里，乃有此花端若此。","不论玉板与鹤鸰，可亚姚黄并魏紫。","嫣然见我如感伤，似诉处此非其乡。","吾衰多病不解饮，对尔叹息空持觞。","人言老境花如梦，献此慇勤情已重。","蜡封瓶贮可多时，惆怅洛阳今不贡。"]},{"t":"自鄱阳泛江至星子","f":"五言古诗","c":["我行黟歙间，山陇如黏蚝。","涧水互萦绕，路石何硗嶅。","深谷四无景，峻岭干云霄。","朝行岚气合，暮宿怪禽号。","吾虽一险夷，无乃徒御劳。","及兹夏潦涨，弭节俯江皋。","试命具舟楫，聊以释烦嚣。","巨浸与天永，东流日滔滔。","来樯与去棹，倏忽驰千艘。","进舟枕席间，舟子巧所操。","江山递隐见，景物资游遨。","颇同谪仙人，醉著宫锦袍。","长啸倚柁楼，轩然咏离骚。","心随八极远，身逐秋鸿高。","风帆擘巨浪，大橹驾云涛。","百里须臾间，千里不崇朝。","快哉可以贺，把酒持蟹螯。"]},{"t":"彭蠡","f":"七言古诗","c":["神禹治水江为最，逦迤逶蛇钟作汇。","泓澄不独阳鸟居，浩荡端使群川会。","群川已会江不湍，朝宗到海东南安。","烟收云敛望不尽，眼界始知天宇宽。","世传扬澜并左蠡，无风白浪如山起。","我今谪官此中行，何事恬然风浪止。","阳侯也自可怜生，不学世人皆世情。","好风已借一帆便，霁色更增双眼明。","晚来画舸鸣六橹，超忽千山如脱兔。","波心突兀见星宫，云际峥嵘望庐阜。","世间此景良不多，洞庭三峡真么么。","共浮大白期一醉，对此不饮当如何。"]},{"t":"游落星寺","f":"七言古诗","c":["一气升沉谁所肇，陨星为石古不少。","群川会处渺无涯，坠此精坚镇江表。","坐令释子开梵宫，栋宇规摹浮玉小。","窈窕楼台四面通，汹涌波涛千柱㒟。","我来端是好幽奇，一叶飘然陵漭渺。","初疑牛女在银潢，更讶灵槎经毕昴。","星房月殿夜沉沉，水色天容秋杳杳。","恍如清梦到天门，欲驾飙轮憩蓬岛。","尘世喧嚣那易得，幻境去来何日了。","心閒境寂付幽人，衲被蒙头任昏晓。"]},{"t":"韩德全以小舟相迓于落星寺下","f":"七言律诗","c":["故人一别两寒暑，雁断鱼沉杳何所。","那知迎我落星傍，一叶凌波听掀舞。","胸中耿耿初自若，身世悠悠乃如许。","且须酌酒浇肺肝，慎勿开口论今古。"]},{"t":"晚出南康游庐山","f":"五言古诗","c":["舍舟星子渚，遂作庐山游。","空濛杳霭间，十里松桂秋。","草木吐香润，泉石交横流。","乃知山中物，一一皆其尤。","岚逼空翠湿，峰高紫烟浮。","心闲云出岭，眼净龙还湫。","月壑夜窈窕，风林晚飕飗。","稍闻钟磬声，迥觉梵宇幽。","平昔念清赏，孰云今乃酬。","似非人间境，须向物外求。","顾揖虽不暇，吟哦浩难收。","聊将诗纪行，一洗他年愁。"]},{"t":"过玉涧道人草堂","f":"五言古诗","c":["道人妙弹琴，能作醉翁操。","人亡琴亦亡，颇为识者悼。","草堂玉涧边，芜没已秋草。","穗帐鹤惊空，药杵香馀捣。","竹光净如洗，桂子寒不扫。","松风肃泠泠，犹想琴声好。"]},{"t":"五老峰","f":"七言古诗","c":["五峰秀出如五老，须发苍然长美好。","问之不肯道姓字，俨若子房从四皓。","商山采芝亦已久，汉庭辟谷何其早。","优游相与定储皇，携手江湖共幽讨。","化为峰石寄山巅，下视尘寰真电扫。","衣冠想像犹伟然，容貌至今初不槁。","祗应明月见当时，间有白云来问道。","逝将筑室近峰前，岁晚相依得相保。"]},{"t":"罗汉寺","f":"五言律诗","c":["梵宫台殿古，松桂碧参天。","玉涧碎寒石，金池开小莲。","循渠穷水脉，策杖到岩巅。","渐入庐山境，从参五味禅。"]},{"t":"自罗汉院欲游寻真观雨作不果遂次栖贤闻寻真景物尤美留为异日不穷之赏赋诗纪之","f":"七言古诗","c":["羽人之宫邻五老，杖屦欣然事幽讨。","那知一夜雨翻盆，山路难行愁滑倒。","世间违意常八九，万事皆然宁自保。","山灵岂是秘幽奇，欲结清欢故相恼。","传闻景物冠庐山，小殿飞楼更精巧。","古潭摇荡明月光，绿萝青松覆烟草。","屏风九叠云锦张，古来诗句谪仙好。","山中道士不出门，玉杵金丹手亲捣。","我方放浪谢冠裳，未觉山林迹如扫。","真游傥有不尽缘，容我他年来访道。"]},{"t":"栖云庵","f":"五言律诗","c":["禅老幽栖地，云峰尺五天。","江湖萦缟带，世界廓青莲。","说法三乘外，藏身万象巅。","潜虬蟠不去，应听祖师禅。"]},{"t":"三峡桥","f":"七言古诗","c":["我昔曾作云安行，道逢除书还玉京。","至今遗恨不一到，与听三峡流泉声。","此来又谪武昌去，庐山当道欣所经。","栖贤寺前小三峡，拭目便觉增双明。","黄牛明月坐中见，瞿塘艳滪森相迎。","山寒草木郁葱茜，逼耳似闻猿狖鸣。","悬崖乱石互回转，震吼正坐不得平。","珠跳云沸巧潨射，晴昼雨雹驱雷霆。","壮哉造化融结此，故使水石相喧轰。","妙音流出无尽藏，乃与衲子门庭争。","飞桥赑屃跨虚碧，面对五老峰峥嵘。","我来云物为开霁，当暑万壑松风生。","提携更得二三子，杖履不辜丘壑情。","垂瓶得水不敢漱，老坡旧约今寻盟。"]},{"t":"万杉寺散珠亭","f":"七言绝句","c":["一派飞泉落坐隅，跳波沸石散成珠。","道人谛看空濛际，颗颗圆明定有无。"]},{"t":"诸刹皆以石渠道水有至十馀里者感之赋诗","f":"五言古诗","c":["庐阜秀江南，凝结尽云母。","泉源乃云腴，甘冽固其所。","悬为瀑布垂，蹙作龙鸾舞。","交流涧谷中，厥味皆钟乳。","僧坊有能事，致远劳汲取。","凿石为通渠，计里不计步。","回环绕山麓，高下映檐庑。","蜿蜿虹腰转，溜溜螭头吐。","沛然饮濯馀，灌溉及园圃。","谁将创物智，作此济众祖。","暂劳逸则永，心一力乃举。","岂惟小物然，万事尽如许。","吾道何其衰，寤寐慨思古。"]},{"t":"谷帘泉","f":"七言古诗","c":["甘泉多自名山出，世品谷帘为第一。","淄渑之水不易辨，臆说讵敢评得失。","庐山深处为谷帘，度岭穿云费时日。","道人裹饭时一到，敲火烹茶资野逸。","坐令仆隶致瓶罂，是非诚否良难诘。","世间知味定何人，食蔗多谓甜于蜜。","居然真伪相混殽，往往循名因去实。","何似家山陆子泉，石缝迸出苍龙渊。","山中空洞乳满腹，一派下作梁溪源。","清甘著舌久不散，持以瀹茗增芳妍。","华堂石甃与覆护，好事汲取肩相骈。","有时置酒饮其上，醉涤肺腑尘烦蠲。","缄题寄远无伪者，贵贱均饮初不偏。","彼如幽人在空谷，此若佳客临风前。","未须细较味优劣，且问所处谁为贤。"]},{"t":"余幼尝一到庐山再游已三十年矣感怀二首 其一","f":"七言律诗","c":["梦想庐山三十秋，却因谪宦得重游。","禅林处处逢清赏，山路人人识故侯。","绝岭半将云幕覆，飞泉长作玉虹流。","平生丘壑真吾志，一洗胸中万斛愁。"]},{"t":"余幼尝一到庐山再游已三十年矣感怀二首 其二","f":"七言律诗","c":["香炉峰顶紫烟凝，三峡桥边雪浪惊。","不为迂疏成远谪，岂能萧散个中行。","云霞映带松萝色，殿阁深严钟磬声。","回首世缘真梦幻，故应长此寄浮生。"]},{"t":"开先寺漱玉亭","f":"词","c":["未游漱玉亭，先诵东坡诗。","手持芙蕖跳下清泠中，疑非谪仙不能为此词。","后翁三十年，我亦游于斯。","飞桥已堙没，故迹多推移。","空馀高岩与深谷，落日惨淡松风吹。","白龙依旧出青峡，散沫下作清涟漪。","古来陵谷会迁变，况乃景物资人为。","云间滟滟吐寒月，清光不减翁当时。","相望一世发孤笑，坐使万古生长悲。"]},{"t":"瀑布","f":"五言古诗","c":["我昔游太华，矫首望仙掌。","瀑布如悬河，斗落五千丈。","空濛雨雹飞，澒洞岩壑响。","及观庐山瀑，未觉快清赏。","飞泉出山腰，半派隐层嶂。","沈吟谪仙词，其或过所奖。","传闻山之巅，峰岫列屏障。","银河落九天，喷薄殊异状。","倒挂三石梁，无乃在此上。","逝将随羽人，裹足一同往。","怀哉不可得，空积青霞想。"]},{"t":"简寂观","f":"五言律诗","c":["高士不可见，云乡空旧居。","烟岚飞瀑外，露石礼星馀。","松老未归鹤，沼深清见鱼。","何人得丹诀，应有枕中书。"]},{"t":"归宗寺四咏 其一","f":"七言绝句","c":["孤峰秀拔翠峣岧，峰顶虚无是紫霄。","从此上宾朝帝所，直须稳跨玉龙腰。"]},{"t":"归宗寺四咏 其二","f":"七言绝句","c":["溪流宛转若翔鸾，翠色涵虚特地寒。","底事舞馀窥碧沼，袛应误作镜中看。"]},{"t":"归宗寺四咏 其三","f":"七言绝句","c":["右军真是墨中仙，到处成池岂尽然。","祗有此间疑可信，白云书法至今传。"]},{"t":"归宗寺四咏 其四","f":"七言绝句","c":["光射苍岩石镜屏，我来一现岂无情。","谁云显晦知时节，长伴空山寒月明。"]},{"t":"偶成","f":"七言律诗","c":["洞霄吏上紫霄峰，漱玉亭游玉局翁。","人物风流何可并，山林趣舍略相同。","是非论定千年后，身世尘劳一梦中。","我是骑鲸谪仙裔，赤鲩相逐御清风。"]},{"t":"灵汤","f":"七言绝句","c":["石甃灵汤列道周，玉池金屋未相侔。","涤尘时有幽人到，不与骊山共一流。"]},{"t":"客言庐山往年之盛今不逮远矣戏成此诗","f":"七言律诗","c":["福地禅林海内无，盛衰亦与世缘俱。","祗应泉石不知老，长伴烟云得自娱。","种杏仙家今寂寞，献花衲子亦乾枯。","我生颇恨来游晚，也胜不来空看图。"]},{"t":"圆通寺与觉老步月","f":"七言绝句","c":["石耳峰前松桧香，月华天影夜茫茫。","道人试道依溪水，何似曹溪一派长。"]},{"t":"子弟辈游天池余以病不果往","f":"七言律诗","c":["云山积翠倚穹苍，仙圣灵踪写上方。","瑞像世传藏锦绣，神光人说似清凉。","心安是处皆欢喜，眼正无时非吉祥。","我病未能寻胜境，慇勤为爇一炉香。"]},{"t":"戏赠东林圭老","f":"七言律诗","c":["我游庐阜南山北，师住二林东院西。","试问远公求作佛，何如陶令醉如泥。","苦邀名山同莲社，笑送幽人过虎溪。","千载风流久寥落，更烦拈出与提撕。"]},{"t":"西林寺","f":"五言古诗","c":["东林大禅苑，殿阁杰以雄。","西林乃律居，僧房小玲珑。","泉流庭庑间，宛转如鸾龙。","花竹深窈窕，松萝郁青葱。","纵观鲁公书，远揖峭直风。","馀碑虽峥嵘，一扫凡马空。","安得数椽地，介居二林中。","当有远公流，策杖时相从。"]},{"t":"道出庐阜偶值崧老右丞同游东西二林蒙示佳篇辄次来韵","f":"七言律诗","c":["迂疏又复谪南州，假道江山得胜游。","杖履欣逢长者辙，笑谈同访远公流。","风摇杉桧惊寒梦，烟锁峰岚绕翠楼。","回首中原意萧瑟，此生飘泊任云浮。"]},{"t":"太平观道士植瑞香于檐庑间可爱颇恨不及其花时为赋小诗","f":"五言古诗","c":["道人心境闲，种花白云乡。","交柯碧珊瑚，薿薿众叶光。","弱质资灌溉，孤根怯清霜。","治畦檐庑间，晏温借朝阳。","我来恨太晚，不见花吐房。","想像正开时，淡紫兼微黄。","濯濯炫秀色，霏霏㒟天香。","空馀风露枝，璀璨绕回廊。","地灵草木润，长与兰蕙芳。","明年花更好，矫首遥相望。"]},{"t":"白公草堂","f":"七言律诗","c":["乐天平生不可及，谪官乃作庐中集。","香炉峰下结草堂，石屏纸帐随时给。","维摩丈室亦何有，天女散花空结习。","何须江上听琵琶，泫然泪滴青衫湿。"]},{"t":"琵琶亭","f":"七言古诗","c":["去年假道浔阳城，扁舟夜泊琵琶亭。","却忆当时醉司马，送客江头秋月明。","今年谪官又重到，扫地乃缘蜂寇经。","轩楹回首已不见，况欲更闻弦索鸣。","西风萧萧芦苇响，月色下照江波清。","秪应风月长不老，坐阅尘世犹流萍。","我生多病苦忧患，未能忘世那忘情。","移船相近夜悄悄，侧听疑有檀槽声。"]},{"t":"过渊明故居","f":"五言古诗","c":["舍棹湓浦城，税驾柴桑里。","缅怀靖节翁，衡宇兹避世。","乞食虽甚贫，折腰肯为米。","陶然傲羲皇，独得醉中意。","三径不愿馀，五斗聊自诔。","优游晋宋间，俯仰无可愧。","若人骨已朽，凛凛有生气。","斜川尚环流，层城亦秀峙。","如何高世士，庙貌乃颓圮。","谁将一觞酒，荐此菊与杞。","朗咏归来辞，感叹成坐起。"]},{"t":"德安食枇杷","f":"五言律诗","c":["故人饷卢橘，烟雨江上村。","芳津流齿颊，核细肌丰温。","谁为黄金弹，偏宜白玉樽。","返源旋味处，寂寞自无言。"]},{"t":"云居勤老以书见邀不果往戏作此颂寄之","f":"词","c":["吾师脱浮玉，振锡来云居。","江边波浪已远去，山顶风雷应晏如。","我来问津师草草，咫尺云岑怅难到。","师既拗折柱杖不出山，我亦把定缰绳不下道。","试将此意示丛林，抚掌呵呵同绝倒。"]},{"t":"午暑憩潭田精舍老僧求询其曾游方否云以少尝一到分宁感而赋此","f":"五言律诗","c":["修江深寂处，兰若寄高邱。","松竹有古意，云山无世愁。","老僧头已白，邻邑幼曾游。","自哂何为者，半生踰百州。"]},{"t":"闻子规","f":"七言律诗","c":["江南四月五月时，空山月夜啼子规。","劝我不如归去好，我方远谪何时归。","中原杳杳暗锋镝，纵使得归何所益。","不如且住碧山中，为凭青鸟通消息。"]},{"t":"戏赋墨画梅花","f":"七言古诗","c":["道人画手真三昩，力挽春风与游戏。","露枝烟蕊忽嫣然，自得工夫畦径外。","由来黑白无定姿，浓淡间错相参差。","炯如落月耿寒影，翳若宿雾含疏枝。","群芳种种徒繁缛，脱略丹青尤拔俗。","妙质聊资陈氏煤，幽姿好伴文生竹。","世呼墨竹为墨君，此花宜称墨夫人。","铅华不御有馀态，世间颜色皆非真。","年来妙观齐空色，天花时露真消息。","试烦幻出数千枝，不费梁溪一丸墨。"]},{"t":"兜率寺","f":"五言律诗","c":["随意寓禅房，小轩风露凉。","山幽云傍户，林迥月窥床。","竹色晓增翠，桂花秋欲香。","无人知此意，天影碧茫茫。"]},{"t":"玉溪寺","f":"五言律诗","c":["玉溪何日寺，古佛亦尘埃。","高阁云初卷，小池莲半开。","竹风清枕簟，松露滴莓苔。","寂寞溪边路，幽人自往来。"]},{"t":"过苦竹岭二首 其一","f":"五言律诗","c":["绝岭横鸟道，江湖从此分。","沈吟洞庭野，怅望具区云。","去住本非我，别离空念群。","子归啼苦竹，肠断不堪闻。"]},{"t":"过苦竹岭二首 其二","f":"五言律诗","c":["今日江湖境，双眸岭上明。","山光随地好，秋气逼人清。","陇水初分处，云鸿欲别情。","离群古来有，叹息未休兵。"]},{"t":"次通城送季言弟还锡山二首 其一","f":"七言律诗","c":["半载相从作远游，物华苒苒又新秋。","江南山水共清赏，湖外风烟成独留。","家远为传安稳信，时艰增重别离忧。","渚宫此去无他地，怅望自登黄鹤楼。"]},{"t":"次通城送季言弟还锡山二首 其二","f":"七言律诗","c":["陆离长佩切云冠，泽畔行吟且纫兰。","我已安心为逐客，子今何事亦抛官。","江湖鸿雁初寥落，风雪鹡鸰相急难。","归去家山见诸季，为言努力且加餐。"]},{"t":"季言送余至湖外欲往无为挈其姊旅榇归锡山悯其勤赠此一绝","f":"七言绝句","c":["送我谪官迁姊殡，人生如汝亦劳哉。","他时寄骨西江上，烦汝还须得得来。"]},{"t":"寄王周士绝句二首 其一","f":"七言绝句","c":["偶然一病便休官，万石岩中处已安。","底事书来犹剩语，也知习气扫除难。"]},{"t":"寄王周士绝句二首 其二","f":"七言绝句","c":["年来百念冷于灰，梦到江湖又一回。","从此故人音问近，洞庭秋色雁初来。"]},{"t":"寓居通城僧舍东轩池莲盛开竹庵圭老有意见过戏赠此篇","f":"七言律诗","c":["道人庵外万竿竹，何似小池千叶莲。","月白风清谁共此，心闲境寂两翛然。","好抛筠粉娟娟净，来看荷珠的的圆。","飞锡傥能真过我，直须趁取晚霜前。"]},{"t":"张子公以圆鉴见寄作诗报之","f":"五言古诗","c":["我观大圆鉴，瑩澈靡瑕垢。","清光溢寒蟾，碧井窥古甃。","冰池绝埃尘，玉璧无肉好。","不知何年铸，款识杂篆籀。","冷然照肝胆，况烛须眉秀。","英英张公子，辍赠意独厚。","使我正衣冠，更以别妍陋。","嗟予罹百忧，半世困驰骤。","苍浪齿发衰，已觉成老丑。","幸兹置宽闲，闭户念往咎。","冠攲与佩落，颠倒散襟袖。","平生遭谤谗，白黑坐分剖。","逝将杜德机，渐可塞智窦。","岂徒齐美恶，端欲一昏昼。","鉴焉何所施，无乃虚授受。","聊持戏凤匣，藏此蟠螭纽。","精光秘不露，犹使魑魅走。","讵逃鹦鹉形，时作蛟龙吼。","君看方寸间，此物谁蔽覆。","灵台湛虚明，广博含宇宙。","纤毫莫凝结，万象悉笼囿。","宁随古今移，不逐面目皱。","人人各具足，一一谢雕镂。","无尘安用拂，表里自通透。","诸佛亦何为，四智此为首。","祖师持出游，法器久已就。","那将清净眼，更入烦恼蔀。","随缘梦幻中，坐阅蛮触斗。","本来妙明心，一念證无漏。","持此还寄君，试问承当否。"]},{"t":"早起","f":"七言律诗","c":["秋晓凄然枕簟凉，小窗残月尚临床。","追寻梦境烟云散，起傍荷花风露香。","慨念关河心黯黯，谛观身世意茫茫。","樽中有酒聊须醉，造物于人自叵量。"]},{"t":"有感","f":"七言律诗","c":["三年再谪堕江湖，何啻经行万里馀。","环绕真同循磨蚁，羁穷更类局辕驹。","自怜许国心犹壮，却笑谋身术巳疏。","二圣未还民未靖，尚思痛哭奏囊书。"]},{"t":"小塘","f":"七言律诗","c":["谁使精庐凿小塘，坐令天女试新妆。","风摇翠盖珊珊响，露裛红衣冉冉香。","棋罢雨声来绝巘，梦回月影上脩廊。","我生本自无根蒂，触处为家殊未央。"]},{"t":"飞云","f":"五言律诗","c":["飞云游碧虚，夭矫龙蛇势。","因风态无穷，抱日色增丽。","飘然欲安归，出岫非本意。","为霖竟何成，跂望增叹喟。"]},{"t":"读留侯传有感","f":"词","c":["秦人失鹿解其纽，群雄竞逐死谁手。","天方注意隆准公，故使留侯作宾友。","圯上老人亲授书，言从志合真其偶。","捕取项籍如婴儿，指麾诸将犹猎狗。","运筹决胜帷幄中，楚汉存亡良已久。","谁言刘季田舍翁，秪听人言本无有。","但能信用子房谋，何妨抱持戚姬日饮酒。"]},{"t":"东轩夜坐","f":"七言律诗","c":["苒苒流年催白头，此生那向此淹留。","天高露下物华肃，月澹风清僧宇幽。","河底光芒萤照水，草间悲怨蚓吟秋。","夜凉人闲家千里，别是羁臣一段愁。"]},{"t":"浴罢追和东坡韵","f":"五言古诗","c":["华发短且稀，无事兰汤沐。","及兹秋暑阑，头垢资一浴。","平生冠裳汗，往咎不可复。","聊将清泠泉，濯此空洞腹。","荒山薪易采，巨斛水良足。","融融气通肤，烂烂光溢目。","枵然勺用瓢，何必池甃玉。","呼童为爬背，自胜飞燕沃。","振衣絺绤凉，晞汗风前竹。","却来就绳床，一枕睡初熟。","忘世安用愁，抛书且休读。","梦中期汗漫，万里归一瞩。","吾生真寄耳，来者亦何卜。","沛然乘天游，无心且缘督。"]},{"t":"次韵谪居三适 旦起理发","f":"五言古诗","c":["未能运河车，上溯泥丸宫。","鬓发忽已华，飒若冒雪松。","清晨起自理，濯此万里风。","萧萧栉齿快，淅淅气脉通。","呼儿助千遍，缓手无匆匆。","我生本疏懒，误堕轩冕中。","野马就羁靮，何如雾生鬃。","握发谅未能，散发聊与同。","金丹变鬒色，缘合亦易逢。","逝将弄云海，一访安期公。"]},{"t":"次韵谪居三适 午窗坐睡","f":"五言古诗","c":["涉世几灭顶，欲为多掣肘。","功名如浮云，于我亦何有。","惟兹华胥国，风土谙已久。","坐中可断取，聊试维摩手。","昏昏一卷书，兀兀三杯酒。","飘然到其乡，自觉乐而寿。","嗟我蒲柳姿，未老先已朽。","何尝慕管萧，但欲师广受。","未能脱羁束，洗濯愈瑕垢。","已矣姑两忘，蘧蘧学庄叟。"]},{"t":"次韵谪居三适 夜卧濯足","f":"五言古诗","c":["养生贵养足，不假衾与裯。","温温斗水间，可以解我忧。","月露夜寂寂，风雨寒飕飕。","呼童具盆汤，足若双蜺投。","老来嗜坐卧，突兀鹰在韝。","有时起游行，恍讶烟云浮。","自从饱涤濯，此病良已瘳。","虚堂日千转，轻捷如沐猴。"]},{"t":"怀季言弟并简仲辅叔易","f":"五言古诗","c":["我昔谪沙溪，尔送至虎丘。","相携观剑池，共坐苍崖陬。","霜寒草木衰，肃肃天地秋。","慷慨论世故，岂复知离愁。","中间谪云安，尔病家山留。","独与仲及叔，分携浙江头。","潮声来海门，风雨助飕飕。","银涛蹙天起，泛此一叶舟。","及玆谪武昌，尔复从我游。","回环溪壑间，渺若双沙鸥。","长江快清旷，庐阜探奇幽。","行尽江南山，始次湖外州。","传闻浙郡兵，盗用官库矛。","夜深赤白丸，杀吏起相雠。","怀家动归心，触热遽还辀。","作别今几时，此情浩难收。","块处谁共语，把酒无与酬。","凭高欲望远，独上黄鹤楼。","吴越天杳杳，风烟晚悠悠。","顾嗟祢处士，坐困鹦鹉洲。","胡虏气方横，盗贼起如蟊。","中原腤锋镝，江汉屯貔貅。","尔归议迁徙，已有定论不。","黄屋尚飘泊，吾敢怀燕休。","但愿复相见，一解无穷忧。","泫然念苍生，岂为吾身谋。"]},{"t":"次韵张子公见寄二首 其一","f":"七言律诗","c":["处世何殊梦里人，大千沙界几回巡。","万缘尽处方为我，一念生时已是尘。","幻境是谁从出没，舌根何物辨甘辛。","安心须到无心地，始契如来清净身。"]},{"t":"次韵张子公见寄二首 其二","f":"七言律诗","c":["功名身外两悠悠，有意功名已可羞。","与世浮沉非我意，观时进退岂人谋。","不能为国辟百里，祗欲归耕老一畴。","祸福死生皆默定，初非舍去亦非求。"]},{"t":"余久不饮酒雨过晚凉悠然独酌戏成此篇","f":"七言律诗","c":["崎嵚历落真可笑，飘泊流离初不羞。","苍髯华发老张镐，火色鸢肩穷马周。","身长九尺安所用，命酒一斗聊销忧。","醉中起舞颇自得，慷慨不知风雨秋。"]},{"t":"叶落","f":"七言律诗","c":["铿然一叶已惊秋，况复纷纷巧见投。","振槁不禁风淅淅，催寒长共雨飕飕。","洞庭波起初微脱，云梦霜高浩不收。","舞砌穿帷不须扫，萧骚从伴逐臣愁。"]},{"t":"去岁寓长沙游道林岳麓真天下绝景也今相去不远无因再游赋诗见意","f":"七言古诗","c":["衡山之陬湘水滨，道林岳麓天下少。","蟠冈复岭相掩重，石磴松门递萦绕。","经行多在烟霭间，台殿半开云木杪。","衲僧宴坐禅寂馀，朝磬暮钟清杳杳。","凭高旷望楚天阔，志气已逐飞鸿矫。","橘洲枫浦指顾中，俯视更觉长沙小。","风樯浪舶千艘屯，丹楼粉堞百雉缭。","苍茫晓色散平川，点缀残霞映疏蓼。","从来篇翰谁最优，沈宋杜韩争表表。","古今尘迹散烟云，独有斯文传不了。","隔年清赏回首空，斯欲再游真漭渺。","苍梧九疑云漠漠，青草洞庭风袅袅。","有时幽梦一到之，觉来枕席清秋晓。","人间万事不由人，安得忘情逐猿鸟。"]},{"t":"五哀诗 楚三闾大夫屈原","f":"五言古诗","c":["楚怀听秦诳，身作咸阳鬼。","当时屈原争，坐困椒兰毁。","襄王复不悟，远作江南徙。","行吟沅湘间，形槁颜色悴。","著书称离骚，风雅齐厥理。","鸱鸮况小人，鸾凤喻君子。","眷眷不忘君，一篇三致意。","纫兰采杜若，冠佩空自伟。","举世混浊中，谁与同乐此。","忠臣会遇难，千古共一轨。","人情疏鲠亮，物能使软美。","存亡反覆间，悔及良晚矣。","嗟嗟屈子心，芳洁畴与比。","日月可争光，尘垢安能滓。","聊从太史卜，肯逐渔父醉。","甘葬鱼腹中，怀沙汨罗水。","千秋身后名，芬馥同茝芷。","夫岂椒兰徒，据势长不死。"]},{"t":"五哀诗 汉梁王太傅贾谊","f":"五言古诗","c":["贾生公辅器，弱冠游汉廷。","高论帝王略，妙极理乱情。","出意对诏令，惊倒诸老生。","从容画筹策，籍籍飞英声。","是时汉初定，颇杂秦霸称。","力还治古制，物物与正名。","改朔易服色，庶几礼乐兴。","仪章悉草具，舆议当公卿。","岂知绛灌徒，谮毁如建瓴。","天子疏不用，谪去长沙城。","翩然渡湘水，投书吊屈平。","弃鼎宝康瓠，铅刀钝青萍。","微言岂悼屈，聊复以自评。","长沙地卑湿，安得寿且宁。","及观鵩鸟赋，颇觉生死轻。","晚奉宣室对，夜半前席听。","文帝岂易遇，所言略施行。","虽不位卿相，儒者良已荣。","梁王坠马死，泣涕亦伤生。","受任乃如此，孤忠本精诚。","奈何君臣义，浇薄返不明。","缅怀古人心，使我气拂膺。"]},{"t":"五哀诗 汉处士祢衡","f":"词","c":["祢生抱逸韵，乃是古之狂。","负才颇傲物，齿少气方刚。","怀刺游许下，漫灭竟摧藏。","肯从屠沽儿，借面与吊丧。","伟哉孔文举，国宝借路傍。","上书荐一鹗，欲使观翱翔。","振翼云汉间，永垂虹蜺光。","飞兔与腰袅，灭没不可望。","观其慰辞荐，器识岂易量。","平生轻魏祖，纵口成否臧。","召令为鼓吏，阅试当改装。","蹀?初散步，掺挝作渔阳。","声节既悲壮，容态随低昂。","岑牟与单绞，裸袒易故裳。","却来坐军门，画地声琅琅。","曹瞒黠如鬼，嗜杀犹虎狼。","缩手不敢动，送与刘及黄。","娱宾赋鹦鹉，节奏陵笙簧。","援笔不加点，粲然已成章。","高才竟为累，兰麝空馀香。","至今鹦鹉洲，葭苇秋苍苍。","丑哉杀士名，千古不可忘。"]},{"t":"五哀诗 唐中书令褚遂良","f":"五言古诗","c":["贞观萃群英，实为太平基。","褚公初侍书，遂以鲠亮知。","谏疏屡献纳，对扬竭论思。","翩如丹山凤，来为箫韶仪。","飞鸟自依人，此言已堪嗤。","更云谮刘洎，厥理尤足疑。","贤者虽已矣，可以此心推。","薰莸难共器，枭鸾不同栖。","故令敬宗辈，污染成瑕疵。","我观永徽间，武氏盗政机。","祸端始床第，几使国祚移。","当时河南公，力诤伏丹墀。","顿首愿还笏，丐身田里归。","义气动人主，回天初庶几。","鄙哉英公绩，一言遂成非。","坐令牝鸡晨，啄丧靡有遗。","元勋顾命老，远窜湘江湄。","茫然不复召，讵忆抱颈时。","卑湿所不堪，须发尽成丝。","至今潭府帖，志士生长悲。"]},{"t":"唐工部员外郎杜甫","f":"五言古诗","c":["子美以诗鸣，今古无对手。","当时谪仙人，长句颇先后。","精深律切处，故自非其偶。","而况郊岛徒，何敢窥户牖。","有如登岱宗，众山皆培塿。","又如观武库，剑戟靡不有。","高辞媲丘坟，古意篆蝌蚪。","苍苍雪中松，濯濯风前柳。","云烟纷卷舒，雷电划奔走。","澹然众态俱，沾丐随所取。","平生忠义心，多向诗中剖。","忧国与爱君，诵说不离口。","饥寒窘衣食，容貌村野叟。","自以稷契期，此理人胜不。","中兴作谏臣，戎马方践蹂。","上疏救房琯，亦足知素守。","一跌不复振，造物意岂苟。","欲使穷吟哦，专志如矇瞍。","辛苦盗贼中，妻子或颠仆。","布衾冷似铁，晨爨乏升斗。","冒雪斸黄精，呼儿理鱼笱。","萧条秦陇间，不废诗千首。","依严遂入蜀，幕府备宾友。","草堂浣花溪，颇复事南亩。","乱离又飘泊，累若丧家狗。","云安曲米春，巫峡风土陋。","扁舟下瞿唐，留滞湖湘久。","家事竟何成，丹诀空系肘。","凄凉耒阳县，醉死竟坐酒。","虽烦微之铭，不返鄠杜柩。","谁将樽中渌，一酹泉下朽。","诗篇垂琳琅，长作蛟龙吼。"]},{"t":"黄陵庙","f":"七言律诗","c":["湘妃庙貌枕江湄，不见当年鼓瑟时。","玉佩风摇云冉冉，翠帷烟湿草离离。","凄凉清泪留班竹，寂寞深林叫子规。","断简遗编杳难考，无人为立退之碑。"]},{"t":"望九疑","f":"七言律诗","c":["洞庭渺漭芦苇秋，九疑联绵烟霭浮。","重瞳一去不复返，苍梧云物空疑愁。","两阶干羽久寂寞，千古夷夏相仇雠。","安得垂衣转琴轸，薰风为解吾民忧。"]},{"t":"去岁道巴陵登岳阳楼以望洞庭真天下之壮观也因诵孟浩然气蒸云梦泽波撼岳阳城之句追古今绝唱用以为韵赋诗十篇 其一","f":"五言律诗","c":["登楼窥洞庭，沧波渺无际。","波间起飞龙，惨澹带云气。","云雷倏变灭，天水共澄霁。","矫首望君山，镜面青螺髻。"]},{"t":"去岁道巴陵登岳阳楼以望洞庭真天下之壮观也因诵孟浩然气蒸云梦泽波撼岳阳城之句追古今绝唱用以为韵赋诗十篇 其二","f":"五言律诗","c":["地枕江湖阔，秋来多郁蒸。","山城少见日，雾雨长冥冥。","今夕定何夕，月华风露清。","于此兴不浅，栏干聊复凭。"]},{"t":"去岁道巴陵登岳阳楼以望洞庭真天下之壮观也因诵孟浩然气蒸云梦泽波撼岳阳城之句追古今绝唱用以为韵赋诗十篇 其三","f":"五言律诗","c":["秋色到极浦，层空霭行云。","长剑抚玉珥，欲降云中君。","桂旗澹偃蹇，风驭何缤纷。","淹留岂予愿，沐浴空兰薰。"]},{"t":"去岁道巴陵登岳阳楼以望洞庭真天下之壮观也因诵孟浩然气蒸云梦泽波撼岳阳城之句追古今绝唱用以为韵赋诗十篇 其四","f":"五言律诗","c":["此身堕江湖，恍若在清梦。","梦中亦何为，思古亦长恸。","心驰关塞远，目与飞鸿送。","贾客不知愁，凄然笛三弄。"]},{"t":"去岁道巴陵登岳阳楼以望洞庭真天下之壮观也因诵孟浩然气蒸云梦泽波撼岳阳城之句追古今绝唱用以为韵赋诗十篇 其五","f":"五言律诗","c":["江湖渺无涯，怅然怀震泽。","地分吴楚远，天共云水白。","鲈鱼正堪脍，蟹螯亦可擘。","何日归去来，秋风思迁客。"]},{"t":"去岁道巴陵登岳阳楼以望洞庭真天下之壮观也因诵孟浩然气蒸云梦泽波撼岳阳城之句追古今绝唱用以为韵赋诗十篇 其六","f":"五言律诗","c":["西风木叶脱，洞庭水层波。","蘋芷满洲渚，有怀忧思多。","眇眇帝子愁，欲降山之阿。","兰蒸奠桂酒，浩唱闻九歌。"]},{"t":"去岁道巴陵登岳阳楼以望洞庭真天下之壮观也因诵孟浩然气蒸云梦泽波撼岳阳城之句追古今绝唱用以为韵赋诗十篇 其七","f":"五言律诗","c":["湖光如镜平，风雨一摇荡。","蜿蜒舞翠蛟，汹涌叠银浪。","帆樯走阵马，势出霄汉上。","吾生幸可惜，何事鱼腹葬。"]},{"t":"去岁道巴陵登岳阳楼以望洞庭真天下之壮观也因诵孟浩然气蒸云梦泽波撼岳阳城之句追古今绝唱用以为韵赋诗十篇 其八","f":"五言律诗","c":["濯足洞庭波，秋高翠增岳。","美人渺何在，使我怀抱恶。","悠悠江湖深，坐阻关山邈。","采兰亦寄之，终朝不盈握。"]},{"t":"去岁道巴陵登岳阳楼以望洞庭真天下之壮观也因诵孟浩然气蒸云梦泽波撼岳阳城之句追古今绝唱用以为韵赋诗十篇 其九","f":"五言律诗","c":["重湖望不极，秋色蔼残阳。","洲渚云沙白，菰蒲霜叶黄。","飞帆适沅澧，回雁过潇湘。","楚客经行处，依然兰芷香。"]},{"t":"去岁道巴陵登岳阳楼以望洞庭真天下之壮观也因诵孟浩然气蒸云梦泽波撼岳阳城之句追古今绝唱用以为韵赋诗十篇 其十","f":"五言律诗","c":["江湖秋日暮，远客若为情。","宿舸沙边缆，征鸿云外声。","星河摇倒景，鼓角起江城。","去国同王粲，登临百感生。"]},{"t":"促织","f":"七言绝句","c":["促织哀吟不自劳，草根床下夜萧骚。","我为逐客宜无寐，何事齁齁至日高。"]},{"t":"秋风二首次子美韵 其一","f":"七言律诗","c":["秋风淅淅吹南山，胡骑凭陵窥汉关。","金舆玉辇幸沙漠，两载于今犹未还。","中原道路尽豺虎，择肉渐觉来荆蛮。","运筹帷幄策安在，毋事推注移文间。"]},{"t":"秋风二首次子美韵 其二","f":"七言律诗","c":["秋风淅淅吹客衣，日光奄奄寖已微。","自我行吟楚泽畔，三月不通家问稀。","清霜冷落岁将暮，仆御借问何时归。","我今萍梗任飘泊，怀土却悟从来非。"]},{"t":"次韵艾宣画四首 其一 竹鹤","f":"七言绝句","c":["磊落胎仙谁最宜，此君节操凛霜威。","琴心试与弹三叠，从看婆娑舞羽衣。"]},{"t":"次韵艾宣画四首 其二 黄精鹿","f":"七言绝句","c":["黄精苗盛雪初融，叠叠峰峦紫翠重。","岩前双鹿卧底事，秪应眷日长新茸。"]},{"t":"次韵艾宣画四首 其三 杏花白鹇","f":"七言绝句","c":["春入群芳此最妍，露枝烟蕊袅成团。","不知闲客来何处，独傍花枝仔细看。"]},{"t":"次韵艾宣画四首 其四 莲龟","f":"七言绝句","c":["红妆翠盖晓参差，水面浮游有戏龟。","谁道千年解巢叶，也知曳尾已多时。"]},{"t":"西风行","f":"五言古诗","c":["西风陨高梧，秋暑退残热。","岂不欣微凉，寤叹惊急节。","岁华聿云暮，露气繁霜结。","干戈随凝阴，虏骑壮胜铁。","边防久凋残，河洛据戎羯。","中原无长城，何以限逸越。","传闻今年春，关辅已蹀血。","强兵健马区，乘间肆陵蔑。","况兹柔脆乡，岂复劳龁齧。","江汉非不深，天险为人设。","要害无重兵，一苇自可绝。","恬然不为备，庙算岂有说。","翠华果何从，大计宜早决。","缅怀沙漠寒，矫首望汉月。","杳无鸿雁来，宁不野鼠掘。","何时金凤辇，复返苍龙阙。","群生有安堵，国耻稍一雪。","努力肉食谋，傍观心已折。"]},{"t":"画草虫八物 蚊","f":"五言绝句","c":["所志惟一饱，聚声如雷车。","秋来腹长饥，扑扑喙作花。"]},{"t":"画草虫八物 蝇","f":"五言绝句","c":["情态真可憎，画成因误墨。","薨薨乱鸡鸣，惨惨变白黑。"]},{"t":"画草虫八物 蜂","f":"五言绝句","c":["杪忽腰如壶，联绵窠若屋。","毋轻怀袖间，防此虿尾毒。"]},{"t":"画草虫八物 蝶","f":"五言绝句","c":["粉翅摇春晖，翩翾自来往。","勿贪花草香，触此饥蛛网。"]},{"t":"画草虫八物 螳螂","f":"五言绝句","c":["飘飘绿衣郎，怒臂欲当辙。","君王求勇士，嘉尔能仗节。"]},{"t":"画草虫八物 蜻蜓","f":"五言绝句","c":["双睛碧珠瑩，四翅青罗薄。","但知逐飞蚊，不复顾黄雀。"]},{"t":"画草虫八物 蟪蛅","f":"五言绝句","c":["戚戚鸣岁暮，不知有春秋。","肯信鲲与鹏，同作逍遥游。"]},{"t":"画草虫八物 络纬","f":"五言绝句","c":["露下草根冷，戛然长悲鸣。","谁知两股间，能作无穷声。"]},{"t":"读二疏传","f":"七言古诗","c":["都门供张设祖道，冠盖如云声浩浩。","送车百两知为谁，太傅少傅同归老。","道傍观者为泣下，贤哉大夫能自保。","酒酣礼毕辞决去，脱若林泉放鱼鸟。","当时宣帝重法律，视遇公卿同隶皂。","杨恽所坐秪语言，赵韩之诛亦草草。","故令二傅动归心，未必筋骸果衰稿。","父子相随出汉关，归来自觉故乡好。","黄金散尽宴亲宾，日治酒殽供洒扫。","肯将田宅遗子孙，清白传家最堪宝。","寂寥千载想风流，知止不辱何其早。"]},{"t":"著迂论有感","f":"五言古诗","c":["长笑梁溪翁，平生有馀拙。","于今欲行古，无乃亦痴绝。","施之廊庙间，放步足已跌。","下帷更潜思，又复广陈说。","从来坐言语，得谤今未歇。","曾不少创惩，譊譊祇强聒。","惟堪覆酱瓿，讵足议往辙。","掉头谓不然，此理君未察。","立言与行事，垂世初不别。","身穷言乃彰，贻范有前哲。","周文拘羑里，易象乃成列。","仲尼道不行，褒贬代赏罚。","屈原困椒兰，泽畔采薇蕨。","离骚体风雅，光可争日月。","虞卿罢赵相，梁魏颇屑屑。","世亦传春秋，端为穷愁设。","圣贤垂简编，往往因愤发。","避谤不著书，陆子良已黠。","区区祸福间，何足议宏达。","泛览古人心，一一可坐阅。","大略观规模，微情析毫发。","幽光发干将，潜慝戮饕餮。","会有知我人，玩味为击节。","安知千载后，观乐无季札。","岂能继潜夫，粗可仿荀悦。","子云方草玄，解嘲何可缺。"]},{"t":"建炎行","f":"五言古诗","c":["金寇初犯阙，太岁在丙午。","殊恩擢枢廷，愧乏涓埃补。","两河未奠枕，杖钺出宣抚。","乞身缘谤谗，窜谪旅湘溆。","明年丁未夏，被命尹天府。","颇闻环京畿，四面尽豺虎。","金汤虽可恃，忧在人不禦。","见危思致命，入援裒义旅。","旌麾亘江湄，畏景触隆暑。","忽传元帅檄，果有城破语。","銮舆幸沙漠，妃后辞禁籞。","皇孙与帝子，取索及稚乳。","礼文包旂裳，乐器载笋簴。","金缯罄公私，技巧到机杼。","空馀宗庙存，无复荐簋簠。","凄凉苍龙阙，寂寞玉华庑。","畴能供衔粟，谁与献肥羜。","无从执羁靮，安得生翅羽。","号恸绝复苏，洒泪作翻雨。","继闻宣赦书，宝位居九五。","神明有依归，率土尽呼舞。","皆言汤武姿，勇智天所与。","向来使贼营，英气詟骄虏。","建牙出危城，帝命缵鸿绪。","不然艰难中，何以脱猰貐。","兹雠不戴天，兄弟及父母。","尝胆思报吴，枕戈惩在莒。","齐侯何足称，句践不须数。","周汉获再兴，宣光定神武。","愿言觐行在，玉色亲黻黼。","丹诚遂披陈，秘策得宣吐。","谋身虽拙计，许国心独苦。","片言傥有合，丐骨归垄亩。","飞帆过金陵，鼓柁适淮浦。","遥传告大廷，命相比申甫。","顾兹斗筲器，何以动尧禹。","深惟特达知，感慨激肺腑。","如何日月光，可以萤爝助。","舍舟行汴堤，驱车赴延伫。","伤心兵火馀，民物亦凋瘐。","中使乘驲来，茶药宠赐予。","拜恩丘山重，坐使瘵疠愈。","行行近南都，戈甲震金鼓。","将佐迎路傍，往往多旧部。","冠盖如云屯，赐燕金果圃。","谢免径造朝，泪落湿殿础。","初称宗社危，天地同愤怒。","次陈国多难，实启中兴主。","末言樗散材，初不堪梁柱。","鼎颠将覆餗，栋桡必倾宇。","况兹扶颠危，正赖肱与股。","大舜举皋陶，小白相仲父。","耕莘与钓渭，端不乏伊吕。","惟当博询访，考慎作心膂。","封章屡恳辞，帝曰莫如女。","往作砺与舟，不复容伛偻。","叩额宸扆前，臣敢论伪楚。","易姓建大号，厥罪在砧斧。","奈何坐庙堂，乃与臣等伍。","更效老猎师，十事听裁处。","天子亮精诚，一一皆可许。","因陈禦戎策，用此敢予侮。","河外须救援，屏蔽资捍拒。","问谁可驱策，因荐亮与所。","京师当一到，九庙陈鼎俎。","却为巡幸计，不可去中宇。","南阳光武兴，形势亦险阻。","西通关陜区，东与江淮距。","三巴及岭海，宝货可运取。","据要争权衡，黠虏谋必沮。","募兵益貔貅，买马增牧圉。","号令新帜旗，仗械饬干橹。","军容久不振，整顿就规矩。","潢池盗弄兵，群恶相啸聚。","偏师命剪除，快若猫捕鼠。","馀寇悉款降，分隶归籍簿。","蒐裒将帅材，赏罚颇有序。","经营年岁间，庶可事大举。","灭敌还两宫，雪耻示千古。","却隆太平基，不愧宗与祖。","岂知肘腋间，乃有椒兰妒。","含沙初射影，聚毒阴中蛊。","规模欲破碎，谋议渐龃龉。","固知鲠峭姿，自不敌媚妩。","恨无回天力，剔此木中蠹。","安能破铜山，但志燃郿坞。","时危敢尸禄，抗疏愿引去。","涕泗对冕旒，非不恋轩宁。","君臣以义合，无使赭舂杵。","帝度不可留，乃听上印组。","扁舟返东吴，却理梁溪橹。","多言更萋菲，贝锦成罪罟。","尚荷皇天慈，薄谴居鄂渚。","我来雪霏霏，及此岁将暮。","崎岖山谷间，避寇如避弩。","行尽江南山，始踏湖北土。","风烟愁浩荡，鸿雁拆俦侣。","沉吟白云飞，怅望黄鹤翥。","晴川俯汉阳，葭菼满鹦鹉。","家山渺安在，幽梦到别墅。","三年再谪官，缭络万里路。","浮游幻境中，尘迹叹仰俯。","翠华尚蒙尘，吾敢念门户。","但嗟机会失，事势契先误。","今年寇益横，春夏蹂京辅。","万骑略秦关，馀毒被陈汝。","五陵气葱葱，中原郁膴膴。","弃置不复论，弥望皆莽卤。","旌旃满江淮，寇钞连齐鲁。","六飞竟何从，秋晚尚江浒。","何时包干戈，礼瑞奠璜琥。","斯民安田畴，馀谷栖廪庾。","四方道路通，舟车走商贾。","吁嗟乎苍天，乃尔艰国步。","譬犹大厦倾，著力事撑柱。","居然听颓覆，此身何所措。","又如抱羸瘵，邪气久已痼。","不能亲药石，乃复甘粔籹。","膏肓骨髓间，性命若丝缕。","安得和缓徒，举手为摩拊。","驯致海宇康，苍生有环堵。"]},{"t":"中秋望月有感寄叔易季言并简仲辅弟","f":"七言古诗","c":["前年河内中秋月，玉帐初寒铁衣滑。","羽书狎至不成眠，坐伴清光到明发。","是时季弟在幕中，病隔纱窗共谈说。","出师未捷身已危，继被宸章召还阙。","去年中秋寓宋都，金针篆字看除书。","夜同叔弟坐月下，仰望赤气环斗枢。","经营两河初就绪，斥罢将帅良非图。","陵晨廷争不可得，上还印绶归东吴。","今年谪官旅湖外，又值中秋有佳气。","纤云四卷天无河，月色满庭如泼水。","缅怀诸季会合难，但与阿宗相劳慰。","举杯邀月应笑人，处处相逢万馀里。","我生端遇国步艰，出入将相三年间。","功名富贵亦何有，慨念四海悲汍澜。","心驰沙漠关塞远，身堕江湖风露寒。","不须更问世间事，但愿对月身常闲。"]},{"t":"张子公再得湖倅因书寄之","f":"七言律诗","c":["吴兴别去久飘蓬，清梦时游苕霅中。","十里荷开生色画，四围波泛水晶宫。","喜君再拥朱轓贰，顾我今成白发翁。","傥幸宽恩听归去，定须相访五湖东。"]},{"t":"胶山兰若幽胜予寓梁溪久而未之到闻翁士特携家居其间赋诗见意","f":"五言古诗","c":["闻道胶山寺，幽深过惠山。","僧房穿窈窕，石溜落孱颜。","地僻车马绝，山空松桂环。","钟声清霭外，刹影白云间。","旅泊君得计，飘流吾念还。","时危暂安适，景胜且跻攀。","耿耿寸心赤，萧萧双鬓斑。","抢攘悯瓯越，寂寞堕荆蛮。","风月三千首，轩裳五两纶。","戎车伤浩荡，綵服羡斑斓。","天地旌麾满，江湖鸥鹭闲。","何时共樽酒，世路正多艰。"]},{"t":"十六夜月二首 其一","f":"五言律诗","c":["清光殊未减，碧落绝纤尘。","绛阙飞金镜，银潢渡玉轮。","霏霏烟霭灭，湛湛露华新。","倚幌人千里，遥知翠黛颦。"]},{"t":"十六夜月二首 其二","f":"五言律诗","c":["嫦娥长不老，宫殿复新秋。","丹桂欲飘子，素蟾相对愁。","林寒枝绕鹊，江迥水明楼。","逐客几弦望，又看成玉钩。"]},{"t":"读诸葛武侯传","f":"七言古诗","c":["天下兵戈正云沸，伏龙凤雏那可致。","掉头自作梁甫吟，垄上躬耕方得意。","将军汉裔真英雄，惠然三顾草庐中。","心期吻合论世故，如鱼得水云从龙。","指麾顾眄定巴蜀，抗魏连吴分鼎足。","受遗乃在永安宫，叹息君臣难继躅。","南征五月深渡泸，上疏北伐遵遗谟。","连年动众扰关辅，数战未必非良图。","大星夜坠惊营垒，壮志雄谋嗟已矣。","至今鱼腹浅沙中，八阵依然照江水。"]},{"t":"秋夜有怀二首 其一","f":"五言律诗","c":["草木又摇落，关河方阻深。","龙庭空入梦，雁足不传音。","黄伞游何处，苍生思至今。","娟娟江汉月，空照逐臣心。"]},{"t":"秋夜有怀二首 其二","f":"五言律诗","c":["坐失金汤险，摇摇翠盖飞。","空闻八骏御，不见六龙归。","天地干戈满，潇湘鸿雁稀。","汉宫秋夜月，依旧照彤闱。"]},{"t":"崇阳道中作四首 其一","f":"五言律诗","c":["我行江南春，初见农事作。","及兹旅湖外，秋稻半已穫。","隔林闻晚舂，藁秸积篱落。","童稚亦熙熙，田家有馀乐。"]},{"t":"崇阳道中作四首 其二","f":"五言律诗","c":["溪清石齿齿，山远木苍苍。","落日烟景暮，西风粳稻香。","茂林归鸟雀，平隰下牛羊。","月露浩如洗，凄然欲结霜。"]},{"t":"崇阳道中作四首 其三","f":"五言律诗","c":["承平无事久，万里尽农桑。","谁使干戈起，坐令民物疮。","关河成阻绝，京洛亦凄凉。","尚喜江湖外，斯民游乐康。"]},{"t":"崇阳道中作四首 其四","f":"五言律诗","c":["连年兵甲兴，犹幸东南稔。","食足无叛民，闾里得安枕。","传闻江淮间，蝗旱今犹甚。","努力事燮调，未寒心已凛。"]},{"t":"宿岩头寺","f":"七言律诗","c":["天气沉阴迫季秋，通城早发宿岩头。","催寒小雨松桂湿，出岫孤云嵌洞幽。","瓶锡真还行脚债，钳锤罕遇点胸俦。","夜深云散千峰月，注目寒空独倚楼。"]},{"t":"寓崇阳西山定林院有感二首 其一","f":"五言律诗","c":["踰年去天阙，长是寓僧庐。","云水志方适，轩裳情已疏。","午风吹茗椀，夜月照床书。","忘我兼忘世，此生真有馀。"]},{"t":"寓崇阳西山定林院有感二首 其二","f":"五言古诗","c":["清霜初入候，落叶半辞柯。","岁晏遽如许，时艰将若何。","关山空岁月，江汉自风波。"]},{"t":"岩桂二首 其一","f":"五言律诗","c":["汲水养岩桂，最怜风露香。","黄花金琐碎，碧叶玉光铓。","却忆七闽路，有怀中隐堂。","相看久不厌，气味自难忘。"]},{"t":"岩桂二首 其二","f":"五言律诗","c":["远地见佳木，依然如故人。","难当禅客意，为折数枝新。","自耐风霜早，不惭兰蕙春。","慇勤置瓶水，寂寞伴闲身。"]},{"t":"次韵郑教授见寄","f":"七言古诗","c":["泛梗飘萍逐水流，故人书到正霜秋。","扶颠拯溺多迂论，问舍求田更拙谋。","辇道凄凉沙碛外，钩陈寂寞楚江头。"]},{"t":"灌溪三咏 其一 灌溪","f":"七言绝句","c":["道人卓锡使泉飞，一派清甘满石陂。","谁识灌溪真境界，也知只见沤麻池。"]},{"t":"灌溪三咏 其二 妙峰庵","f":"七言绝句","c":["结庵雄踞妙高峰，孤秀巉然万境通。","不见德云空住处，却须相遇别峰中。"]},{"t":"灌溪三咏 其三 清凉境界","f":"七言绝句","c":["松萝荫翳色苍苍，盛夏南风草木香。","普愿众生无热恼，不应身独占清凉。"]},{"t":"题青龙兴化禅院方丈","f":"七言律诗","c":["廓然丈室湛虚明，地僻山空万象清。","滴翠老杉清净色，锵金流水妙圆声。","慇勤禅客邀迎厚，寂寞宰官身世轻。","野鹤孤云无不可，会须还作二龙行。"]},{"t":"闻山东盗所谓丁一箭者拥数万众临江破黄州官吏皆保武昌江湖间骚然未知备禦之策感而赋诗","f":"五言古诗","c":["时危贵权谋，盗贼本王臣。","招徕驾驭之，自足张吾军。","蜂虿固有毒，犀象亦可驯。","恩威傥得所，摩拊还其淳。","光武制铜马，曹公用黄巾。","资其战大敌，且以苏良民。","去年议招抚，乃以此义陈。","置司未阅月，来者如屯云。","奈何力沮罢，坐使复纷纷。","传闻中原寇，铁马动成群。","虎兕出于柙，玉石同其焚。","京辅困抄掠，遂及江湖滨。","东南久平定，郡县无城闉。","天堑非不险，谁与守要津。","古来重镇地，控扼非其人。","小敌已震惧，大者当何云。","人谋自回遹，天意讵不仁。","安得回阳辉，一令四海春。"]},{"t":"得诸季书报薛克寅范茂载胡仲俨皆物故感怆有作","f":"五言律诗","c":["新故继凋丧，初非因荷戈。","波惊川阅水，霜早叶辞柯。","世上故人少，录中新鬼多。","浮生端若此，伤感意如何。"]},{"t":"山居四感 斗雀","f":"七言绝句","c":["翩翾啅噪绕高檐，粒食枝栖安用贪。","怒斗不知缘底事，败毛轻毳落毵毵。"]},{"t":"山居四感 战蚁","f":"七言绝句","c":["欲雨山云四面垂，空庭蚁战久相持。","只应薄伐檀萝国，正是槐安献捷时。"]},{"t":"山居四感 噪蝉","f":"七言绝句","c":["修竹茂林山寺幽，蝉声如沸满清秋。","吸风饮露无求世，嘒嘒何为噪不休。"]},{"t":"山居四感 吟蛩","f":"七言绝句","c":["月露凄清湿草根，寒蛩偏向夜深闻。","随时感气成悲怨，不是来销逐客魂。"]},{"t":"山居四景 其一 松风","f":"七言绝句","c":["岁晚苍官鬓发青，回风披拂自悲鸣。","不容逐客多归梦，故作江湖波浪声。"]},{"t":"山居四景 其二 竹露","f":"七言绝句","c":["森然绕槛翠琅玕，瘦节疏枝特地寒。","底事叶垂浑不舞，金风零露夜漙漙。"]},{"t":"山居四景 其三 岭云","f":"七言绝句","c":["玉洁烟轻一片深，飘然出岫本无心。","孤飞远映碧天去，也解重来为作霖。"]},{"t":"山居四景 其四 窗月","f":"七言绝句","c":["月出松林已半廊，故开窗牖纳清光。","嫦娥应讶年来瘦，千首新诗书满床。"]},{"t":"山居四适 酌酒","f":"七言绝句","c":["山禽唤觉不成眠，兴若长鲸吸百川。","满酌瓷瓯当金盏，陶然便作酒中仙。"]},{"t":"山居四适 烹茶","f":"七言绝句","c":["安眠饱食更何求，只欠云腴茗一瓯。","龙凤不须誇北苑，枪旗且与试中州。"]},{"t":"山居四适 读书","f":"七言绝句","c":["平生长作蠹书蟫，老去犹资慰我心。","每到古人名节处，慨然掩卷一沉吟。"]},{"t":"山居四适 焚香","f":"七言绝句","c":["假榻禅房夜寂然，瓦炉石饼爇龙涎。","霏微缥缈根尘际，吸引方知鼻观圆。"]},{"t":"山居四卉 拒霜","f":"七言绝句","c":["道人多种木芙蓉，晓着清霜分外红。","万叶千花本何有，因空成色色成空。"]},{"t":"山居四卉 鸡冠","f":"七言绝句","c":["昂然璀璨绕阶除，端似群雄领众雏。","只有一冠无别德，谁云鲁国固多儒。"]},{"t":"山居四卉 菊","f":"七言绝句","c":["重阳旋觅菊花栽，青蕊萧疏殊未开。","我似陶潜正无酒，休将冷艳笑空罍。"]},{"t":"山居四卉 槿","f":"七言绝句","c":["步屧秋风见蕣华，疏篱灼灼绕田家。","朝开暮落君休笑，纵使多时终委沙。"]},{"t":"渊圣皇帝赐宝剑生铁花感而赋诗","f":"七言古诗","c":["靖康虏骑窥帝闉，中原惨澹生烟尘。","帝谓细柳真将军，总兵欲使挥浮云。","解赐宝剑御府珍，鱼肠盘屈松桧纹。","缕金错翠舟瑶琨，剸截犀象如羔豚。","驱逐狂寇出边垠，妖腰乱领徒纷纷。","龙吟蛟吼清夜闻，乃知此物能通神。","迩来杜门空念恩，旧事谁复可共论。","今晨开匣观龙文，铁花绣涩苍藓痕。","东南卑湿相蒸熏，坐使三尺光铓昏。","安得砺砥来峨岷，淬锋敛锷硎发新。","霜寒冰滑无皵皲，指麾尚可清妖氛。","愿提此剑平戎獯，犬羊虽众气可吞。","手斩可汗羁可敦，天旋日转还两君。","书铭却勒燕然勋，摅愤刷耻志乃伸。","壮怀聊可垂乾坤，缇绣什袭传仍昆。","卫绾之赐何足云。"]},{"t":"读东坡和渊明贫士诗寄诸子侄云重九俯迩樽俎萧然今余亦有此叹因次其韵将录寄梁溪诸弟以发数千里一笑 其一","f":"五言古诗","c":["迂疏得远谪，漂泊将何依。","区区一寸心，未报三春晖。","岁月不我与，急景惊翻飞。","方看社燕来，又见霜鸿归。","宽恩尚廪禄，未迫寒与饥。","荒山俯佳节，九月诚可悲。"]},{"t":"读东坡和渊明贫士诗寄诸子侄云重九俯迩樽俎萧然今余亦有此叹因次其韵将录寄梁溪诸弟以发数千里一笑 其二","f":"五言古诗","c":["凄凉寓僧舍，寂寞坐松轩。","虽辞万钟禄，尚未自灌园。","仲尼犹在陈，我厨晨有烟。","藜羹得一饱，滴露味自研。","寒窗写周易，更咏五千言。","儒生真可笑，饿隐称其贤。"]},{"t":"读东坡和渊明贫士诗寄诸子侄云重九俯迩樽俎萧然今余亦有此叹因次其韵将录寄梁溪诸弟以发数千里一笑 其三","f":"五言古诗","c":["何以写我意，寄之朱丝琴。","钟期久已死，千古无知音。","弃置不复弹，调家难绎寻。","东篱采青蕊，浊酒聊孤斟。","千驷所不顾，一斗诚可钦。","陶然又复醉，谁识渊明心。"]},{"t":"读东坡和渊明贫士诗寄诸子侄云重九俯迩樽俎萧然今余亦有此叹因次其韵将录寄梁溪诸弟以发数千里一笑 其四","f":"五言古诗","c":["肮脏老张镐，寂寞穷黔娄。","古人日已远，此意谁复酬。","墨翟突不黔，仲尼辙环周。","岂为一身计，实怀四海忧。","沮溺但躬耕，吾岂斯人俦。","有酒且径醉，无酒不必求。"]},{"t":"读东坡和渊明贫士诗寄诸子侄云重九俯迩樽俎萧然今余亦有此叹因次其韵将录寄梁溪诸弟以发数千里一笑 其五","f":"五言古诗","c":["佳晨迫九日，旅食寓江干。","颇同谪仙人，漂泊来铜官。","樽俎何萧条，菊蕊渐可餐。","回风吹青松，惨惨岁将寒。","但有杯中物，不愧箪瓢颜。","一觞复一咏，明月窥禅关。"]},{"t":"读东坡和渊明贫士诗寄诸子侄云重九俯迩樽俎萧然今余亦有此叹因次其韵将录寄梁溪诸弟以发数千里一笑 其六","f":"五言古诗","c":["自我去廊庙，远举如飞蓬。","徇道敢怀禄，谋身殊未工。","空馀耿耿心，不惭楚两龚。","幸然诸季贤，意气与我同。","何当恩听归，兵息道路通。","却寻惠山路，杖策得相从。"]},{"t":"读东坡和渊明贫士诗寄诸子侄云重九俯迩樽俎萧然今余亦有此叹因次其韵将录寄梁溪诸弟以发数千里一笑 其七","f":"五言古诗","c":["我家梁溪上，梦堕江湖州。","块处无与语，谁复为朋俦。","远怀作重阳，置酒临清流。","插花独我少，感物增离忧。","我亦事杯杓，阿宗相献酬。","欲寄一枝菊，川途方阻脩。"]},{"t":"次韵渊明九日闲居","f":"五言古诗","c":["天地一逆旅，于焉寓此生。","群阴惨将暮，共爱九日名。","气清霜露肃，天朗山川明。","月户蔼夜色，风林飒秋声。","东篱菊有华，可以延我龄。","采采金琐碎，泛此玉觞倾。","一醉遗万物，况复轩裳荣。","渊明骨已朽，千载同兹情。","时危丹砂远，岁晏将何成。"]},{"t":"初寒","f":"七言律诗","c":["霜早风高寒气萌，可堪独傍楚江行。","貂裘已敝苏季子，葛屦更穿东郭生。","卯酒晕红朝玉颊，夜炉燃鼎沸松声。","妻孥千里应思我，怅望牛衣此日情。"]},{"t":"蜜蜂","f":"七言绝句","c":["秋风淅淅桂花香，花底山蜂采掇忙。","但得蜜成功用足，不辞辛苦与君尝。"]},{"t":"胡笳十八拍 第一拍","f":"七言律诗","c":["四海十年不解兵，朝降夕叛幽蓟城。","杀气南行动天轴，犬戎也复临咸京。","铁马长鸣不知数，虏骑凭陵杂风雨。","自是君王未备知，一生长恨奈何许。"]},{"t":"胡笳十八拍 第二拍","f":"七言律诗","c":["黑云压城城欲摧，赤日照耀从西来。","虏箭如沙射金甲，甲光向日金鳞开。","昏昏阊阖闭氛祲，六龙寒急光徘徊。","黄昏胡骑尘满城，百年兴废吁可哀。"]},{"t":"胡笳十八拍 第三拍","f":"词","c":["千乘万骑出咸阳，百官跣足随天王。","翠华摇摇行复止，黄尘暗天道路长。","金盘玉箸无消息，色难腥腐餐风香。","晚将末契托年少，遂令再往之计堕渺茫。"]},{"t":"胡笳十八拍 第四拍","f":"楚辞体","c":["筋簳精坚胡马骄，猛蛟突兽纷腾逃。","春寒野阴风景暮，尘埃不见咸阳桥。","中原格斗且未归，陇山萧瑟秋云高。","安得壮士兮守四方，一豁明主正郁陶。"]},{"t":"胡笳十八拍 第五拍","f":"七言律诗","c":["汉家离宫三十六，缓歌慢舞凝丝竹。","铁骑突出刀鎗鸣，惊破霓裳羽衣曲。","明眸皓齿今何在，细柳青蒲为谁绿。","桃花依旧笑春风，风动落花红蔌蔌。"]},{"t":"胡笳十八拍 第六拍","f":"七言律诗","c":["忆昔霓旌下南苑，攀条弄芳畏晼晚。","只今飘泊干戈际，寒尽春生洛阳殿。","梨园弟子散如烟，白马将军若雷电。","城上春云覆苑墙，回首何时复来见。"]},{"t":"胡笳十八拍 第七拍","f":"七言律诗","c":["星宫之君醉琼浆，矫如群帝骖龙翔。","龙池十日飞霹雳，齐言此夕乐未央。","玄圃沧州莽空阔，羽人稀少不在傍。","深山穷谷不可处，托身白云归故乡。"]},{"t":"胡笳十八拍 第八拍","f":"七言律诗","c":["黄尘散漫风萧索，杀气森森到幽朔。","五十年间似反掌，瑶池侍臣已冥寞。","千崖无人万壑静，旌旗无光日色薄。","万事反覆何所无，注目寒江倚山阁。"]},{"t":"胡笳十八拍 第九拍","f":"七言律诗","c":["五陵佳气无时无，龙种自与常人殊。","一去紫台连朔漠，骨肉满眼身羁孤。","金鞭断折九马死，邂逅岂即非良图。","人间俯仰成今古，岂忆当殿群臣趋。"]},{"t":"胡笳十八拍 第十拍","f":"七言律诗","c":["人生失意无南北，去住彼此无消息。","黄蒿古城云不开，时复看云泪横臆。","猛将腰间大羽箭，一箭正坠双飞翮。","汝休枉杀南飞鸿，道路只今多拥隔。"]},{"t":"胡笳十八拍 第十一拍","f":"七言律诗","c":["天子不在咸阳宫，翠华拂天来向东。","江间波浪兼天涌，中有云气随飞龙。","干戈兵革斗未止，无复射蛟江水中。","江边老人错料事，时危惨澹来悲风。"]},{"t":"胡笳十八拍 第十二拍","f":"七言律诗","c":["渔阳突骑猎青丘，天马跋足随犛牛。","幕前生致九青兕，苦寒赠我青羔裘。","万里飞蓬映天过，岁云暮矣增离忧。","如今正南看北斗，长安不见使人愁。"]},{"t":"胡笳十八拍 第十三拍","f":"七言律诗","c":["圣朝尚飞战斗尘，椎鼓鸣钟天下闻。","岸上荒村尽豺虎，衣冠南渡多崩奔。","何时铸戟作农器，欲倾东海洗乾坤。","干戈未定失壮士，旧事无人可共论。"]},{"t":"胡笳十八拍 第十四拍","f":"七言律诗","c":["大麦乾枯小麦黄，问谁腰镰胡与羌。","汉家战士三十万，此岂有意仍腾骧。","安得突骑只五千，长驱东胡胡走藏。","近静潼关扫蝼蚁，为留猛士守未央。"]},{"t":"胡笳十八拍 第十五拍","f":"七言律诗","c":["我生之后汉祀衰，经济实藉英雄姿。","遥拱北辰缠寇盗，杳杳南国多旌旗。","伤心不忍问耆旧，垂老恶闻战鼓悲。","中夜起坐万感集，谁家捣练风凄凄。"]},{"t":"胡笳十八拍 第十六拍","f":"七言律诗","c":["雨声飕飕催早寒，岁暮穷阴耿未已。","燕山雪花大如席，寒刮肌肤北风利。","群胡归来血洗箭，阵前部曲终日死。","漫漫胡天叫不闻，日夜更望官军至。"]},{"t":"胡笳十八拍 第十七拍","f":"词","c":["时危始识不世材，成王功大心转小。","豺狼塞路人断绝，一门骨肉散百草。","江头宫殿锁千门，不知明月为谁好。","何时眼前突兀见此屋，鸡鸣问寝龙楼晓。"]},{"t":"胡笳十八拍 第十入拍","f":"楚辞体","c":["风尘澒洞昏王室，咫尺波涛永相失。","漂然时危一老翁，洒血江汉长衰疾。","笳一会兮琴一拍，青山落日江湖白。","身欲奋飞病在床，此心炯炯君应识。"]},{"t":"重阳日醉中戏集子美句遣兴 其一","f":"七言古诗","c":["青山落日江湖白，飘零已是沧浪客。","老去悲秋强自宽，青蕊重阳不堪摘。","东流江水西飞燕，传语风光共流转。","急觞为缓忧心捣，休语艰难尚酣战。","圣朝尚飞战斗尘，何用浮名绊此身。","时复看云泪横臆，晚来幽独恐伤神。"]},{"t":"重阳日醉中戏集子美句遣兴 其二","f":"七言古诗","c":["篱边老却陶潜菊，开花无数黄金钱。","且看欲尽花经眼，饮如长鲸吸百川。","只今漂泊干戈际，方外酒徒稀醉眠。","腐儒衰晚谬通籍，杜曲幸有桑麻田。","故畦遗穗已荡尽，中原君臣豺虎边。","安得务农息战斗，武陵欲问桃花源。"]},{"t":"夜寝梦游泗上观重建僧伽塔才两层塔以今春同普照王寺焚荡殆尽岂大士有意再来此土乎觉而赋诗以纪之","f":"七言古诗","c":["至人于世何所求，随缘应物初不留。","缘合则应散则休，起灭幻境如浮沤。","僧伽塔踞淮泗流，火焚水转岁几周。","国家崇奉德更优，雍熙所建无与俦。","层层金碧巧雕锼，凿石作址蟠龙虬。","檐间宝铃韵琳璆，势插霄汉神为谋。","瑞光焕发垂珠旒，青天白日烂不收。","崔巍高殿耸飞楼，千楹万柱烟云浮。","谁知兴废相绸缪，铁马驰突横戈矛。","四方群盗起如蟊，付以一炬成荒丘。","慈航济物众所庥，舍我去矣真可忧。","昨宵梦到淮上洲，窣堵再造工方鸠。","千章巨木回万牛，此岂有意重来不。","塔成大士还旧游，更扶休运三千秋。"]},{"t":"次韵渊明读山海经","f":"五言古诗","c":["清霜落乔木，翠色飒以疏。","而我正卧病，萧然寓精庐。","起坐无与欢，散帙聊观书。","心游千载间，超诣非舟车。","更酌一杯酒，荐此果与蔬。","缅怀陶渊明，雅志与我俱。","还看枕间屏，乃是归来图。","古人不予欺，岁暮将何如。"]},{"t":"余筑室梁溪之上三年而后成手植花木甚众遭值世故未尝得安居其间岁暮羁旅慨然念之因和渊明时运诗以见意","f":"词","c":["卜宅梁溪，成非一朝。","面山枕冈，远市近郊。","脩竹茂林，翠连烟霄。","松桂吐香，杞菊长苗。","旁临清流，尘缨可濯。","小阁崷然，九峰远瞩。","岂无华宇，于我自足。","兄弟埙篪，于焉相乐。","春服既成，如浴乎沂。","风乎舞雩，咏啸而归。","自我离群，潜然涕挥。","拊心念旧，电往莫追。","今夕何夕，梦还我庐。","稚子候门，两发髧如。","携幼入室，浊酒倾壶。","慨我寤叹，谁复如余。"]},{"t":"梁溪八咏 其一 中隐堂","f":"七言绝句","c":["不在山林不市朝，且将图史当渔樵。","桂花想见秋来盛，香满西风取次飘。"]},{"t":"梁溪八咏 其二 棣华堂","f":"七言绝句","c":["兄弟埙篪人所推，棣华堂里远相思。","艰难世路风霜急，正是鹡鸰原上时。"]},{"t":"梁溪八咏 其三 文会堂","f":"七言绝句","c":["亲宾情话款衡门，把酒挥毫气吐云。","何日宽思返三径，一樽重与细论文。"]},{"t":"梁溪八咏 其四 九峰阁","f":"七言绝句","c":["小阁峥嵘面九峰，暮天秀出碧芙蓉。","孔明本有躬耕志，却合归来看卧龙。"]},{"t":"梁溪八咏 其五 舫斋","f":"七言绝句","c":["画舫临流四面通，绿窗面面有清风。","年来始会虚舟意，正在江湖波浪中。"]},{"t":"梁溪八咏 其六 怡亭","f":"七言绝句","c":["缥缈危亭枕曲池，红妆翠羽自参差。","晚凉小饮谁同醉，定把圆荷当屈卮。"]},{"t":"梁溪八咏 其七 心远亭","f":"七言绝句","c":["境寂心闲物物宜，倚栏更看岭云飞。","晓猿夜鹤应思我，正好归时犹未归。"]},{"t":"梁溪八咏 其八 濯缨亭","f":"七言绝句","c":["画栋飞檐俯碧流，何时归去舣扁舟。","不须更把尘缨濯，直取冠裳裂即休。"]},{"t":"和渊明归田园居六首 其一","f":"五言古诗","c":["东吴信佳地，碧溪绕青山。","我居枕溪傍，卜筑亦有年。","山空乳满腹，迸出苍龙渊。","馀波滑无声，下灌负郭田。","秋风粳稻香，落照孤鸿间。","黄鸡与紫蟹，日满樽俎前。","酌酒燕宾友，挥毫散云烟。","常谓享此乐，可以终华颠。","岂知萦世故，扰扰不得閒。","侧身念吾庐，怅望情依然。"]},{"t":"和渊明归田园居六首 其二","f":"五言古诗","c":["一为世网婴，未遂税尘鞅。","驱驰途路间，空积溪山想。","我居今若何，岁月忽已往。","三径将荒芜，松菊日应长。","泛舟苕霅间，吾意诚已广。","时危方艰难，长恐堕渺莽。"]},{"t":"和渊明归田园居六首 其三","f":"五言律诗","c":["人生不满百，七十亦云稀。","吾年甫知命，飘泊犹未归。","江湖岁将晏，霜露沾人衣。","沧洲惠询约，坐恐此志违。"]},{"t":"和渊明归田园居六首 其四","f":"五言古诗","c":["平生爱武林，湖山良可娱。","连年兵火作，景物成丘墟。","常愿买一廛，筑室湖上居。","开轩苍翠间，手植松千株。","浮家同志和，来往得自如。","樽中酒不空，乐死不愿馀。","那知今乃尔，此怀坐成虚。","已矣何所道，万法皆本无。"]},{"t":"和渊明归田园居六首 其五","f":"五言古诗","c":["每爱贺知章，敕赐鉴湖曲。","而我不须多，数顷亦已足。","世故俛仰间，反覆若棋局。","良辰逝莫留，胜游当秉烛。","明月照芳樽，坐待东方旭。"]},{"t":"和渊明归田园居六首 其六","f":"五言古诗","c":["我昔居梁溪，梦断长安陌。","倒冠与落佩，志气良自适。","花前饮春朝，月下舞秋夕。","自从丧乱来，光景驹过隙。","无复旧情怀，扰扰为物役。","寤寐忧他人，自麻初不绩。","长啸休去来，劳生亦何益。"]},{"t":"小雨","f":"七言律诗","c":["小雨廉纤作晓寒，绕檐疏竹正檀栾。","穷愁著论墨长湿，磊块浇胸杯未乾。","庄舄显时犹越语，钟仪絷处亦南冠。","百忧万感无时了，更赋新诗强自宽。"]},{"t":"客饷新橙有感","f":"七言律诗","c":["湖外新橙也自黄，故人相赠解包香。","捣齑正鲙双鱼美，荐酒聊持一瓣尝。","湛岘旧栽千树橘，洞庭初落满林霜。","木奴供给何须道，怅望东吴云水乡。"]},{"t":"偶得双鲤付厨作鲙以荐一觞","f":"七言律诗","c":["双鲤从来丙穴东，霜刀缕切脍花红。","银丝藿叶自争巧，玉箸金盘未觉空。","德饱姜侯情已重，诗成杜老志应同。","秋风笠泽鲈尤美，何日扁舟入手中。"]},{"t":"和渊明拟古九首 其一","f":"五言古诗","c":["风霜已摇落，天气犹清和。","聊持一樽酒，自饮还自歌。","朝心愁不开，暮发白已多。","朱颜与绿鬓，飒若霜萎荷。","流年不我与，不饮如老何。"]},{"t":"和渊明拟古九首 其二","f":"五言古诗","c":["惊心如伤禽，衰质若凋柳。","百年能几时，处世安得久。","寤寐若有失，哀我泉下友。","平生不识面，况复衔杯酒。","知心乃如斯，此意岂可负。","管鲍贫时交，于古亦云厚。","范张久已亡，今人那复有。"]},{"t":"和渊明拟古九首 其三","f":"五言古诗","c":["阶祸初甚微，智者能要终。","被发祭于野，辛有知其戎。","时平足谀佞，世乱多奸雄。","坐令夷乱华，诞谩本晋风。","重华不再作，吾道何其穷。","已矣可奈何，此生如梦中。"]},{"t":"和渊明拟古九首 其四","f":"五言古诗","c":["弃置帝王宅，乃欲保一隅。","一隅岂易保，巨盗连荆舒。","眷言浙江西，有我先人庐。","兵火偶不到，聚族于焉居。","羁束未得归，田园日将芜。","江边畏群盗，岁暮当何如。"]},{"t":"和渊明拟古九首 其五","f":"五言古诗","c":["立国有常理，恩威抚要荒。","胡为决藩篱，坐使寇及堂。","凭高寓远目，中原气苍茫。","昔时冠盖地，今日争战场。","玉辇幸朔漠，金椀出北邙。","腐儒献奇策，碧衣坐称昂。","傥无济时略，何以绥四方。","苍生未苏息，慨叹情内伤。"]},{"t":"和渊明拟古九首 其六","f":"五言古诗","c":["吾怜靖节翁，食少衣不完。","弃禄缘束带，贵身遂抛冠。","箪瓢有馀乐，不惭陋巷颜。","成趣园日涉，息交户常关。","返观富与贵，一尘集毫端。","素琴久无弦，适意自可弹。","处心慕黔娄，抗志同伯鸾。","斯人骨已朽，霜霰时方寒。"]},{"t":"和渊明拟古九首 其七","f":"五言古诗","c":["古今纷变态，兹道长若兹。","处世或穷达，否泰各有时。","岂无磨与涅，贵在不磷缁。","达人乃大观，曲士多致疑。","所以古圣贤，立此垂世辞。","慇勤论出处，欲使学者思。","周公尚居东，仲尼岂余欺。","愈钝久乃利，臲卼当安之。","我亦道穷者，欲赋鸱鸮诗。"]},{"t":"和渊明拟古九首 其八","f":"五言古诗","c":["结发慕古人，绝俗期远游。","如登太山顶，志气小九州。","古今会迁变，万壑无停流。","向来富贵者，累累但荒丘。","汉唐已磨灭，况复秦与周。","惟馀节义士，可向编简求。"]},{"t":"和渊明拟古九首 其九","f":"五言古诗","c":["青松生高冈，无意斧斤采。","岁寒霜霰深，未觉柯叶改。","梁鸿既适吴，管宁亦浮海。","二子得我心，高举不相待。","士生不逢时，命矣何所悔。"]},{"t":"余来湖外家问不通者累月因和渊明停云篇以遣怀","f":"词","c":["上天停云，以阴以雨。","我之怀矣，川路修阻。","田园将芜，幼稚谁抚。","雁信来迟，鹤立以伫。","凄其以风，零雨其濛。","自去梁溪，爰止西江。","一室萧然，卧于北窗。","块独处此，人谁我从。","岂无轩裳，谁适为荣。","人之为人，亦以有情。","乱离瘼矣，弃家遐征。","知我如此，不如无生。","今夕何夕，鹊袅庭柯。","载植其尾，迭相鸣和。","发书占之，远问为多。","兆而未至，怀哉若何。"]},{"t":"霜降木落独松柏苍然颜色愈好因和渊明荣木篇以见意","f":"词","c":["采采荣木，春华于兹。","及尔素秋，风霜瘁之。","寒暑代谢，荣枯有时。","改柯易叶，翩其陨而。","苍苍松柏，擢干蟠根。","风霜虽厉，秀色长存。","君子进德，以道为门。","岁寒时艰，节义弥敦。","惟天于余，赋此拙陋。","材不趋新，学惟求旧。","黾勉夙夜，其何能富。","屡冒艰危，内省不疚。","先公有训，岂敢失坠。","敬慎威仪，圣言是畏。","铅刀虽钝，驽马希骥。","一割之功，十驾而至。"]},{"t":"和归鸟篇","f":"词","c":["翼翼归鸟，爰集于林。","近萃芳郊，远依烟岑。","眷言顾之，实获我心。","丛木茂止，憩此繁阴。","翼翼归鸟，翩然翻飞。","风高天阔，去将畴依。","云路翱翔，倦翮思归。","矰缴孔多，无使患遗。","翼翼归鸟，抚翼徘徊。","江湖缈茫，有怀故栖。","顾俦啸侣，鸣声和谐。","愿言不获，怅然伤怀。","翼翼归鸟，集于旧条。","一枝已多，岂俟高标。","敛翰息影，好音交交。","愿言终此，以休永劳。"]},{"t":"和劝农篇","f":"词","c":["天临下土，是生烝民。","耕食凿饮，乃含其真。","淳浇朴散，巧伪相因。","谁其还之，时惟圣人。","圣人立政，爰重黍稷。","设命官司，职是播植。","春勤于耕，秋乃有穑。","储其嬴馀，荒岁足食。","瞻彼中原，祁邳平陆。","春日载阳，和风肃穆。","夫耕妇馌，俦类相逐。","少壮竭力，逸此耆宿。","岂无他图，惟兹永久。","利其耒耜，十千维耦。","带月荷锄，侵星耘亩。","崇本抑末，孰敢游手。","终年厌飧，报则不贵。","千箱万仓，以副汝冀。","为酒为醴，乐此分至。","仰奉俯畜，夫复何愧。","四体不勤，丈人所鄙。","带经而耕，岂废冠履。","我思古人，希风往轨。","躬耕南阳，无使专美。"]},{"t":"秋雨初霁天高气清独游山间意欣然乐之因和渊明游斜川诗以纪其事","f":"五言古诗","c":["岁律忽晼晚，我生感行休。","雨馀秋气清，策杖成独游。","苍苍松桂合，中有清浅流。","放怀似樵者，忘机狎飞鸥。","顾我疏散姿，自合在一丘。","但恨尚羁束，块处无朋俦。","独酌谁与共，独歌谁与酬。","此独有至乐，当有知者不。","盗贼纷满眼，世故端百忧。","置之且勿道，独乐未易收。"]},{"t":"后重九半月菊始开因思东坡言菊花开日即重阳取酒为之一醉遂和渊明已酉岁九月九日之作","f":"五言古诗","c":["地偏菊开晚，乃在秋冬交。","霜中色艳艳，肯逐蓬艾凋。","感此节物殊，为尔再登高。","玉觞泛金英，举酒望层霄。","云气有佳色，此岂瞪发劳。","世态互陵灭，冰炭方凝焦。","不如醉后眠，意味真陶陶。","何论饮而寿，且以乐此朝。"]},{"t":"得梁溪家问足慰远怀因和渊明答庞参军之作","f":"词","c":["剥啄叩门，梁溪有书。","发函读之，远怀以娱。","长少童稚，咸安其居。","森然满前，如返我庐。","一书可宝，万金非珍。","契阔寤叹，乃兹相亲。","鹊不吾欺，鸣以告人。","载询仆夫，以及其邻。","嗟我诸季，鸡鸣孜孜。","左图右书，中心好之。","山川修阻，贻我以诗。","三复佳句，实慰所思。","翩翩鸿雁，暂聚亟分。","岂无他人，非我所欣。","清宵步月，白日看云。","无遐迩心，好音数闻。","昔我之来，鶗鴂将鸣。","今也岁晏，霜露载零。","言念沙漠，有怀玉京。","终夕不寐，群生未宁。","怅望东吴，慨临西风。","愿化独鹤，烟霄可冲。","敬慎威仪，惟以令终。","黄发为期，其爱尔躬。"]},{"t":"叔易得水晶笔格赋诗见寄因次其韵顷与叔易奕而胜得其铜兽炉制度甚古携行常置几案间今此格宜以赠远与炉为伴故卒章及之","f":"五言古诗","c":["武夫恶文士，每见辄不喜。","排纷须大剑，安用毛锥子。","岂知管城翁，功阀著青史。","羲之笔阵图，善战固其理。","贤哉小谪仙，好古良有以。","独怜中书君，飘泊无定止。","谁将素琅玕，实此锦绣篚。","瑶山列群峰，玉笋连厥趾。","置君丘壑间，未觉形神滓。","光联玉蟾蜍，含冻共棐几。","玲珑小九华，一一名可指。","作诗寄远人，为洗尘埃耳。","秀句与珍玩，清绝那可拟。","灿然珠玉间，尚许蒹葭倚。","我生堕江湖，放浪谢簪縰。","尘泓久寂寞，秃颖亦颓委。","当为千里赠，勿念一枰耻。","配此古兽炉，缥缈孤烟起。"]},{"t":"次韵叔易四绝句 其一","f":"七言绝句","c":["落日西风粳稻香，畦间散策月荒凉。","谁知万顷黄云熟，行客初看插绿秧。"]},{"t":"次韵叔易四绝句 其二","f":"七言绝句","c":["笑续离骚赋远游，霜寒云梦杳然秋。","何时把钓梁溪上，醉嚼蟹螯馀罢休。"]},{"t":"次韵叔易四绝句 其三","f":"七言绝句","c":["身閒且作地行仙，谪堕江湖岂偶然。","幸有惠连诗句好，不妨青纸寄新篇。"]},{"t":"次韵叔易四绝句 其四","f":"七言绝句","c":["初寒一醉万家春，尚有陶翁漉酒巾。","五牧潘葑新酿熟，开樽应忆未归人。"]},{"t":"山居四咏 其一 纸帐","f":"七言律诗","c":["洁如白叠软于毡，縠浪龟纹细结联。","雅称独攲班竹枕，最宜深炷紫沉烟。","斜风细雨吴绫暖，万草千花蜀锦鲜。","何似禅房褚夫子，日高覆帱拥衾眠。"]},{"t":"山居四咏 其二 竹枕","f":"七言律诗","c":["此君劲节傲风霜，高卧尤宜逐客床。","雅制颇同琴可荐，瑩肤端与玉争凉。","欲凭幻境成佳梦，故使通中贮秘方。","富贵功名本何有，觉来犹未熟黄粱。"]},{"t":"山居四咏 其三 地炉","f":"七言律诗","c":["小寒聊试地为炉，端为先生病更癯。","炙背愿驰金騕袅，藉床初展锦氍毹。","耸肩傍壁诗千字，爆栗烧毡酒一壶。","便拟慇勤事丹灶，朝晡称火较锱铢。"]},{"t":"山居四咏 其四 石铫","f":"七言律诗","c":["谁刳苍玉事煎烹，形制深宽洁且轻。","觱沸未看浮蟹眼，飕飗先听起松声。","龙头豕腹徒嘲诮，铁涩铜腥费挈擎。","多病文园苦消渴，煮泉瀹茗正须卿。"]},{"t":"山居遣兴四首 其一","f":"七言律诗","c":["偶向忙时乞得身，山居岑寂绝比邻。","雀罗可设门无客，酒盏频倾句有神。","隐背时烦木童子，伴眠犹有竹夫人。","苍生未定郊多垒，敢向长沮与问津。"]},{"t":"山居遣兴四首 其二","f":"七言律诗","c":["三黜先生发半华，但将笔墨作生涯。","已知晏食能胜肉，更觉安行可当车。","月好只愁无竹叶，风来自与扫岩花。","江边盗贼休窥伺，不是宣和宰相家。"]},{"t":"山居遣兴四首 其三","f":"七言律诗","c":["秋杪幽居分外清，傍檐鸟雀自和鸣。","过时黄菊浑无赖，入眼青山独有情。","酒后晕红潮玉颊，吟馀儿杖殷金声。","前村野老能棋战，时与呼来对一枰。"]},{"t":"山居遣兴四首 其四","f":"七言律诗","c":["沉阴天色半含情，小院重门昼掩扃。","一枕睡馀香未散，三瓯茶后酒初醒。","山云舒卷閒中看，竹雨萧疏静处听。","愁寂最怜霜后菊，案头乾死有微馨。"]},{"t":"赵叔?运判见示宣和御画二轴其一马举足奋迅将起其一兔正面踞地齧草皆绝去笔墨畦径间意态如生精妙入神伏观叹息感慨因赋诗二篇以赞扬宸翰且叙小臣悽愤之情云 其一 马","f":"七言古诗","c":["宣和天厩多清新，肉鬃汗血皆翔麟。","圉人牵来赤墀下，宸笔落纸亲传神。","非行非立非驰逐，独写腾身前举足。","展沙奋迅欲嘶风，骧首骖驔初喷玉。","流云飞电五花骢，庭前榻上双真龙。","始知韩干画多肉，坐使冀北群皆空。","銮舆远狩龙荒外，八骏瑶池杳何诣。","空留此马落人间，感愤暗洒累臣涕。"]},{"t":"赵叔?运判见示宣和御画二轴其一马举足奋迅将起其一兔正面踞地齧草皆绝去笔墨畦径间意态如生精妙入神伏观叹息感慨因赋诗二篇以赞扬宸翰且叙小臣悽愤之情云 其二 兔","f":"七言古诗","c":["草枯霜落秋风高，中山之兔初长毫。","天姿狡健雅善走，韩卢宋鹊纷腾逃。","帝居深沉九重里，何自得此山林意。","枯荄咀嚼如有声，缺口长须耸双耳。","宣和天子储聪明，天纵将圣尤多能。","万机閒暇戏染翰，作此东郭髦鬅鬙。","胡尘漠漠暗沙碛，属车一去无消息。","安得壮士东擒胡，鸡鸣问寝还龙德。"]},{"t":"仲辅和寄送季弟诗复次韵寄之 其一","f":"七言律诗","c":["块处江城无与游，芦花枫叶楚天秋。","萧然霜鬓伤迟暮，久矣灰心任去留。","道阻每怀千里念，时危岂为一身忧。","何年棣萼还相映，醉卧元龙百尺楼。"]},{"t":"仲辅和寄送季弟诗复次韵寄之 其二","f":"七言律诗","c":["新诗寄远慰南冠，坠露遥知饮木兰。","素爱少游乘下泽，尚怜子美缚微官。","遭罹贝锦如吾少，漂泊兵戈见汝难。","华发比年老兄弟，相思对案不能餐。"]},{"t":"王周士以幅素图万石岩见示","f":"七言律诗","c":["不须避世向桃源，自有岩中小洞天。","漱石枕流尘境外，巢云卧月玉峰前。","高怀肯顾三千石，福地真同十九泉。","小隐羡君诚得计，我方忧惴老江边。"]},{"t":"煨芋","f":"七言古诗","c":["禅房夜坐腹半饥，寒炉拨火煨蹲鸱。","冻肤傍煖渐舒畅，展转更觉鸣声悲。","毳衣脱落丰肌滑，玉软酥香不劳齧。","芳甘著颊自生津，多病文园正消渴。","吾生老矣来荆蛮，得汝聊助癯儒餐。","不学当年鬼谷子，粪土堆头拜懒残。"]},{"t":"蒸栗","f":"五言古诗","c":["风霜开栗皱，孕此赪虬卵。","嘉哉古所贽，饤饾入笾匴。","累累紫腰菱，烂烂火蚕茧。","甘腴能疗病，炎帝所编纂。","幽人夜读书，坐对铜檠短。","飕飕石鼎沸，焰焰地炉暖。","式将瓦甑炊，剖壳黄玉软。","乘饥进五六，腹已果然满。","吾尝位将相，日食万钱馔。","荒山啖芋栗，自胜太官脔。","乃知一饱馀，万品徒过眼。","聊持荐杯酒，不假玻瓈盌。","忧慨不成眠，夜寒空展转。"]},{"t":"摘鬓间白发有感","f":"五言古诗","c":["吾生足忧患，未老头已白。","鬓间垂素丝，揽镜聊一摘。","星星去虽欣，种种鲜还戚。","颇愁日增多，尽拔复何益。","追思少年时，绿发光且泽。","森然茂云松，岂谓少堪惜。","自从多病后，脱落露广额。","蒲柳姿易衰，日与风霜迫。","萧萧不胜梳，扰扰仅盈搦。","安能上指冠，常恐吹堕帻。","年来涉艰虞，更复非夙昔。","奔驰动万里，漂泊继三谪。","从横蹈危机，侈哆困烦啧。","交游莫援手，仇怨惟下石。","素标宜满头，斑鬓未为逼。","何年运河车，溯补泥丸宅。","华颠复变鬒，去作烟霞客。","憔悴楚江滨，岁晚将何获。"]},{"t":"初食金橘","f":"七言古诗","c":["江湖种橘侔洞庭，于中小者如龙睛。","珊瑚枝干碧玉叶，结实璀璨罗繁星。","客持赠我意已重，贮以翠笼尤晶荧。","气含风露更高洁，色著霜日微红青。","匀圆入手讶磊砢，甘酸流颊凄芳馨。","金丸玉齿乍破碎，中有沆瀣凝清冰。","厥包忆昔贡宫阙，潇湘远物来天扃。","争新效美不论直，万颗坐觉千金轻。","美人转赐入怀袖，归来分饷同瑶琼。","只今八骏杳安在，此物亦尔无光精。","天涯相见两寂寞，敢以陋质伤飘零。","举觞为尔成一醉，醉中不省居蛮荆。"]},{"t":"灯花 其一","f":"五言律诗","c":["独坐对黄卷，夜寒灯自花。","红深谁种莳，枝袅忽萌芽。","酒渌正盈爵，客愁方念家。","慇勤报远信，赖尔慰年华。"]},{"t":"灯花 其二","f":"五言律诗","c":["光铓长吐焰，顷刻遽开花。","玉粒乍排粟，金英初擢芽。","谪官那有喜，旅食未还家。","对尔翻惆怅，飘萧双鬓华。"]},{"t":"余来湖外临行与叔易奕而胜得铜炉制作精古爱之常置几案间感物怀人为赋此诗","f":"七言古诗","c":["古制精巧后莫拟，何年著此形模伟。","状为神兽践脩虺，蜿蜒脊胁奠厥趾。","犀兕一角昂其鼻，胸腹空洞口哆侈。","关机开阖如投匦，葭灰养火焚沈水。","霏微牙吻烟云起，提携爱玩置燕几。","慱山篆鼎讵可比，一枰何日刷前耻。","满轩风月人千里，清香一炷愁如洗。"]},{"t":"客有馈玉面狸者戏赋此诗","f":"七言古诗","c":["山林冬煖草未衰，深岩穴处狸正肥。","丰茸斑毳面妆玉，摇曳脩尾髦如犛。","夜行昼伏彼何罪，失身终堕网与机。","庖厨须尔充口腹，几欲断尾同牺鸡。","蒸炊包裹付糟滓，酥香玉软丰肤肌。","霜刀缕切腻且滑，犀箸厌饫良珍奇。","猩唇熊白不足数，披絮黄雀空多脂。","樽前风味乃如许，为尔倒尽黄金卮。"]},{"t":"冬日閒居遣兴十首 其一","f":"五言律诗","c":["岁暮碧山中，清霜日自浓。","隐床吟蟋蟀，拂槛老芙蓉。","风月成三友，家山梦九龙。","道人知睡美，将晓小鸣钟。"]},{"t":"冬日閒居遣兴十首 其二","f":"五言律诗","c":["飘泊向江城，山居境过清。","霜深犹竹色，风劲更松声。","且尽杯中物，何须身后名。","拥炉孤笑处，寒夜又三更。"]},{"t":"冬日閒居遣兴十首 其三","f":"五言律诗","c":["兰若富云松，吾生寄此中。","无心复弹剑，有恨但书空。","白菊因霜紫，青枫向日红。","晚来幽独甚，卧听竹间风。"]},{"t":"冬日閒居遣兴十首 其四","f":"五言律诗","c":["萧飒鬓丝垂，此怀谁与知。","惊心伤网缴，老眼厌旌旗。","未遂庞公隐，空馀宋玉悲。","故园何处是，搔首望天涯。"]},{"t":"冬日閒居遣兴十首 其五","f":"五言律诗","c":["宿雨乍晴天，初寒气暂暄。","梳头风满栉，曝背日临轩。","小酌无新酿，閒眠只旧毡。","忘心亦忘法，作个是安禅。"]},{"t":"冬日閒居遣兴十首 其六","f":"五言律诗","c":["深炷一炉香，孤吟夜正长。","山虚风落木，云破月窥房。","老骥志千里，越禽思故乡。","羁栖两寂寞，坐叹鬓毛霜。"]},{"t":"冬日閒居遣兴十首 其七","f":"五言律诗","c":["投老见多难，干戈日正深。","饮河胡马健，破垒汉疆侵。","大将未燕首，小臣空越吟。","龙荒两宫远，感愤泪盈襟。"]},{"t":"冬日閒居遣兴十首 其八","f":"五言律诗","c":["泽国杳何许，雁书初报安。","枝间鸟鹊喜，原上鹡鸰难。","松菊荒三径，轩裳厌一官。","黄粱何日熟，客梦正邯郸。"]},{"t":"冬日閒居遣兴十首 其九","f":"五言律诗","c":["衰病寓僧房，閒中气味长。","盘深饶芋栗，地僻懒冠裳。","坐隐乌皮几，行携古锦囊。","接篱颠倒著，不是醉高阳。"]},{"t":"冬日閒居遣兴十首 其十","f":"五言律诗","c":["僻处掩松门，知非更念恩。","庭空从雀啅，山暖觉蜂喧。","木叶静如扫，茶花开正繁。","萧条岁云暮，倚杖自忘言。"]},{"t":"食蟹","f":"七言古诗","c":["平生最爱梁溪居，溪头紫蟹几尺馀。","持矛被甲意颇横，霜后直欲陵于菟。","端然秉炬可攻取，束缚健者归庖厨。","双螯如臂自可饱，满腹膏液凝红酥。","每倾新酿为一醉，风味窃疑他所无。","那知谪堕荒山里，乃有此物供臞儒。","客云来自九江郡，分以饷我良勤渠。","轮囷初喜入盘馔，郭索想见行泥涂。","西风江岸芦苇枯，下田粳稻香且腴。","朝魁把穟屡蜕壳，宜尔怪伟胸中都。","内黄疏封何足道，左手相持真可娱。","流膏斫雪快一嚼，不复怅望思东吴。"]},{"t":"食橘","f":"词","c":["洞庭一夜天雨霜，橘林绿苞朝已黄。","远题书后三百颗，入手便觉秋风香。","黄金为肤白玉瓤，沆瀣深贮甘且芳。","雕盘初擘噀清雾，冰齿乍嚼流琼浆。","色香气味纷可喜，下视众果皆茫茫。","嗟余平生爱种此，木奴千树梁溪傍。","只今蒿艾已埋没，岂敢向日争荧煌。","蓬莱云气久寂寞，汉殿无复罗潇湘。","厥包纵有尽酸涩，剖之蠹朽安足尝。","乃知汝病是天意，坐使玉食无辉光。","荒山乃尔饫佳品，安得騕袅置锦堂。","君不见杜陵野老歌病橘，萧萧半死诚可伤。"]},{"t":"秀容菊","f":"七言律诗","c":["黄菊已槁馀微馥，白菊初开叠罗縠。","秀容丰淡却嫣然，故伴幽人慰愁独。","吾闻此种南阳多，千花万蕊争骈罗。","郁葱佳气久萧瑟，怅望菊潭今若何。"]},{"t":"许崧老见和月林堂夜坐诗复次前韵寄之","f":"五言古诗","c":["宇宙一逆旅，安用归我庐。","解装寓僧房，袤丈即有馀。","三年走万里，华发照川途。","颇思少壮乐，谈笑轻簪裾。","醉挥铁如意，击碎红珊瑚。","垂老见兵革，济时愧才疏。","及兹再飘零，敛若霜中梧。","幸从山林游，时与释子俱。","超然意有会，不必窥其书。","臞仙静退者，久要不渝初。","和我月林篇，此作久所无。","徵言思会面，岁晚苦离居。"]},{"t":"周中元赋御画骢马次其韵","f":"七言古诗","c":["蓬莱宫殿日月长，广廷汎洒如无帚。","临轩亲貌玉花骢，天骥自出天人手。","惊鸿欲起无羁皂，如闻朔风动秋草。","奋身骧首举双蹄，意态天然始知巧。","时危反掌同永嘉，胡骑飒沓陵中华。","当时宸笔散烟雾，往往流落群臣家。","雄姿倜傥精权奇，此画惟应识者知。","怅望崆峒转仙仗，忍传耆旧把天衣。"]},{"t":"送周元中游黄龙山","f":"七言律诗","c":["此身飘泊堕荆蛮，幸有幽人访我閒。","得句多从丘壑里，知音端在笑谈间。","青鞋布袜平生事，野鹤孤云到处山。","好去黄龙露消息，直须一箭透三关。"]},{"t":"题峡江萧氏思贤堂","f":"七言律诗","c":["玉笥峰边萧史居，拂云松竹散扶疏。","妙年气节慕前辈，故老风流空结庐。","幸有江山供一览，自应图史足三馀。","何时海内干戈息，借我茅斋与著书。"]},{"t":"黄雀","f":"七言律诗","c":["秋杪江天小雨馀，毕飞端为网罗须。","秪应俛啄一粒粟，故使常行万里途。","爱酒情怀多骨醉，披绵风度更肤腴。","苞苴宜入金张室，分饷何为及老夫。"]},{"t":"陈几叟以了翁所作默堂箴见示且求余言拾其遗意作四绝句 其一","f":"七言绝句","c":["维摩不二门中法，周庙三缄膺上铭。","莫道寂然无所说，须知渊默有雷霆。"]},{"t":"陈几叟以了翁所作默堂箴见示且求余言拾其遗意作四绝句 其二","f":"七言绝句","c":["言默当时俱是智，可言而默亦非真。","君看王导虽贤者，不语犹能杀伯仁。"]},{"t":"陈几叟以了翁所作默堂箴见示且求余言拾其遗意作四绝句 其三","f":"七言绝句","c":["言以多穷默取容，不如体道守其中。","道非言默所能载，毕竟两端皆是空。"]},{"t":"陈几叟以了翁所作默堂箴见示且求余言拾其遗意作四绝句 其四","f":"七言绝句","c":["钟鸣谷响孰为然，因击缘声故有言。","若会虽言本无说，从教千偈口澜翻。"]},{"t":"得报以谪降官不许同处一州自鄂渚移居澧阳有感","f":"七言律诗","c":["萍漂梗泛又迁居，叹息谋身术已疏。","愿访湘妃遗佩浦，试追汉传吊累书。","干戈满眼伤群盗，松梓连云念故庐。","泽畔行吟觉憔悴，前身疑是楚三闾。"]},{"t":"翁士特见示山字韵诗两篇复次前韵寄之 其一","f":"五言古诗","c":["未展垂天翼，聊寻避地山。","宝坊资小隐，綵服奉慈颜。","乡邑兵戈满，轩窗紫翠环。","遥知排遣处，祗在倡酬间。","离索嗟时久，诗篇喜使还。","故情尤觉重，佳句不容攀。","洒落吴笺湿，韬藏古锦斑。","开缄惊璀璨，逼耳听绵蛮。","陋质尘黄閤，高材困绿纶。","青衿同婉娈，华发怅斑斓。","顾我方遐弃，如公岂久閒。","何须叹飘泊，吾道属多艰。"]},{"t":"翁士特见示山字韵诗两篇复次前韵寄之 其二","f":"五言古诗","c":["踏遍江南土，来游湖外山。","地卑惊鵩鸟，天远忆龙颜。","淮海屯貔虎，戈矛杂佩环。","驰心万里外，回首五云间。","飒沓方多故，飘零且未还。","桃源期可问，铁锁怅难攀。","霜重丹枫落，江清锦石斑。","梦馀惊蚁垤，争极叹蜗蛮。","且隐重重几，深藏若若纶。","江篱纷掩苒，湘竹晕斑斓。","水国鼋鼍横，琳宫日月閒。","亲朋未相弃，莫使雁书艰。"]},{"t":"次韵士特试谷帘泉见怀之作 其一","f":"七言绝句","c":["桑苧尝来第二泉，翠松偃盖色相鲜。","谷帘窦乳争多少，西子南威各自妍。"]},{"t":"次韵士特试谷帘泉见怀之作 其二","f":"七言绝句","c":["片云摇曳不胜閒，行尽江南处处山。","岂解为霖泽枯槁，只思归隐碧岩间。"]},{"t":"戊申冬至日有怀诸弟时赴澧阳","f":"七言律诗","c":["缇室初回律管阳，貂裘还是旅殊乡。","可堪身向三湘远，更觉愁随一线长。","棣萼相思劳梦寐，郊禋成礼想旂裳。","羁臣与国同休戚，老眼犹期见治康。"]},{"t":"张氏二甥寄诗可喜赋此篇以赠之","f":"七言律诗","c":["每见吾甥学不休，信知积善有源流。","骅骝汗血为驹日，松柏凌霜出地秋。","努力年华成宅相，著鞭高跃破烟楼。","渭阳正续离骚赋，频寄诗来慰客愁。"]},{"t":"得梁溪家书报黄氏女生外孙","f":"七言律诗","c":["怪底朝来鹊噪门，家书远报女生孙。","须知钟庆由先德，故使遗芳衍后昆。","肌骨遥怜凝玉雪，风光自与茁兰荪。","何时归去亲怀抱，华发褒衣更觉尊。"]},{"t":"自蒲圻临湘趋岳阳道中作十首 其一","f":"楚辞体","c":["鄂渚何尝一日安，澧阳犹喜远江干。","帝妃降矣空遗佩，公子思兮欲采兰。","水带潇湘疑有雁，地连岭蜀苦无寒。","迂疏自笑谋身拙，却荷朝廷德意宽。"]},{"t":"自蒲圻临湘趋岳阳道中作十首 其二","f":"七言律诗","c":["屈伸任道复何求，去国翻成汗漫游。","处世久师齐物论，摅怀聊赋畔牢愁。","霜清日薄寒光急，云惨天高阴气浮。","袅袅西风洞庭阔，可堪更上岳阳楼。"]},{"t":"自蒲圻临湘趋岳阳道中作十首 其三","f":"七言律诗","c":["岁寒又复事南征，桂楫兰舟过洞庭。","水入重湖千里白，山连平楚数峰青。","云鸿杳杳飞何远，汀芷微微气自馨。","千古灵均英爽在，固应笑我学馀醒。"]},{"t":"自蒲圻临湘趋岳阳道中作十首 其四","f":"七言律诗","c":["三年奔走未容归，敝尽东周季子衣。","断垄连冈平野阔，扁舟短棹寸心违。","凌晨白雾沾裳湿，薄暮彤云夹日飞。","回首梁溪杳何处，翠烟空锁钓鱼矶。"]},{"t":"自蒲圻临湘趋岳阳道中作十首 其五","f":"七言律诗","c":["还驱征骑向三湘，行尽骚人放逐乡。","绿叶素荣歌橘颂，采衣姣服浴兰汤。","云中帝子旌旗降，物外桃源日月长。","便欲翛然与高蹈，故应脱屣谢轩裳。"]},{"t":"自蒲圻临湘趋岳阳道中作十首 其六","f":"七言律诗","c":["不解扬波与餔醨，又还来放楚江湄。","椒兰气味何其烈，蘅药芬芳空尔为。","宁赴湘流非我事，托怀鵩鸟乃吾师。","醉醒清浊初难共，渔父从来自不知。"]},{"t":"自蒲圻临湘趋岳阳道中作十首 其七","f":"七言律诗","c":["远谪三湘欲卜居，试从詹尹拂占书。","昂昂愿作云间鹤，泛泛宁为波底鱼。","咿喔突梯真得计，洁廉正直却成疏。","益坚节操行吾志，龟策从来自不如。"]},{"t":"自蒲圻临湘趋岳阳道中作十首 其八","f":"七言律诗","c":["更欲投书吊汨罗，西风袅袅水增波。","江分梦泽于菟远，地近芳洲杜若多。","野鸟终年从萃止，木奴千树正婆娑。","卜居更作终焉计，华发萧萧奈老何。"]},{"t":"自蒲圻临湘趋岳阳道中作十首 其九","f":"七言律诗","c":["俎豆其如军旅何，谁令瀚海起干戈。","休将直道论三黜，且把微辞续九歌。","山鬼含颦乘赤豹，湘灵解佩鼓云和。","蛮邦虽陋吾何恨，厌见旌蕤相荡摩。"]},{"t":"自蒲圻临湘趋岳阳道中作十首 其十","f":"七言律诗","c":["龙驾翩翩帝子游，我因谪宦亦淹留。","潇湘且傍鼋鼍窟，葭菼空怀鹦鹉洲。","专气愿师周柱史，著书更笑陆忠州。","变心从俗吾何敢，千古骚人共此愁。"]},{"t":"再次韵崧老见和之作时传春秋集传又欲借易说故篇中及之","f":"五言古诗","c":["胡尘暗中原，河洛皆穹庐。","衣冠竞南渡，故国靡复馀。","襄陵大岳裔，亦尔困征涂。","颠沛不忘道，呻吟曳长裾。","如公巨川舟，岂止清庙瑚。","愧我正羁束，未能踵汉疏。","幸然声气同，鸣凤栖必梧。","褰裳思琢磨，道阻不得俱。","已从借麟经，更欲窥羲书。","庶或晚闻道，洗心复其初。","湘沅骚人乡，兰芷今岂无。","回风摇蕙草，叹息空幽居。"]},{"t":"岳阳楼三首 其一","f":"七言律诗","c":["缥缈层楼俯洞庭，湖光霁色两澄明。","气蒸云梦浮天白，水合潇湘到底清。","去棹来樯云共影，断鸿孤鹜笛连声。","望中更觉君山小，一点青螺镜面平。"]},{"t":"岳阳楼三首 其二","f":"七言律诗","c":["翛然多难偶存身，又到苍茫楚泽滨。","鼓舞鱼龙张乐地，佩纫兰茝独醒人。","涉江哀郢空回首，极目伤心欲向春。","鼓枻寅缘傍枯苇，故应渔父尚垂纶。"]},{"t":"岳阳楼三首 其三","f":"七言律诗","c":["常诵飞龙邅洞庭，登楼况复把骚经。","琉璃万顷天同碧，翠黛一螺山更青。","白鸟风高方倦翮，苍鹰冬暖正舒翎。","客愁欲作长鲸吸，却笑三闾只独醒。"]},{"t":"鼠须笔 其一","f":"七言绝句","c":["鼠能为虎亦何功，用舍之间系所逢。","谁谓有皮为有礼，剪须犹得管城封。"]},{"t":"鼠须笔 其二","f":"七言绝句","c":["中山毛颖久中书，鼠辈胡为亦可俱。","寝庙穴居真得计，畏人端恐擢其须。"]},{"t":"渡江","f":"七言律诗","c":["桂枻兰旌楚泽东，碧空如水水如空。","江湖落日浮秋橘，岛屿残霞拂断虹。","世事茫然烟霭里，客愁都在橹声中。","沙头凫雁相俦侣，笑我年年逐转蓬。"]},{"t":"章华台 其一","f":"七言绝句","c":["断垄连冈云梦西，楚王宫殿尚遗基。","桂花半落垂黄橘，想见章华九月时。"]},{"t":"章华台 其二","f":"七言绝句","c":["章华夜饮晓从糜，翠被天寒雨雪霏。","马足车尘竟何往，空令子革诵招祈。"]},{"t":"华容西二十许里有墨山即离骚所谓玄石也山有大云寺寺有云母泉甘芳洁清大旱不竭唐李华有诗序之甚详其末云华贬杭州司公恩复左补阙次于岳阳江山延望思与高贤共饮云母之泉躬耕墨山之下敢违朝命以询私欲秋风露寒洞庭微波一闻猿声不觉涕下况支离多病年甫始衰愿饵药扶寿以究无生之学事乖志负火爇余心三复其言而悲之因次其韵","f":"五言古诗","c":["霜风振古林，肃肃有异声。","我登玄石山，适此氛祲清。","散策步山巅，僧庐窈而精。","石磴尽云母，晶荧璨瑶英。","涓涓幽谷泉，玉色凄芳馨。","饮者得难老，沈疴体皆平。","乃知泉源美，本自山川灵。","沈吟遐叔诗，此其浪得名。","肺腑久尘埃，于焉吸清泠。","玉池艳生肥，漱濯归黄庭。","却思陆子泉，厥味可弟兄。","白首困飘泊，丹心竟何成。","鼓枻渡潇湘，曳裾拂荆衡。","回头故山远，怆恍若为情。","区区金石坚，正赖日月明。","卷舒随用舍，未觉殊亏盈。","风高洞庭波，云瞑兰芷城。","饵药扶始衰，究心学无生。","庶几甫知命，寸田不废耕。"]},{"t":"至澧阳寓天宁僧舍有感 其一","f":"七言绝句","c":["常诵离骚澧有兰，那知谪宦憩其间。","片云只鹤风方急，只恐飘零过别山。"]},{"t":"至澧阳寓天宁僧舍有感 其二","f":"七言绝句","c":["此身又复寓精庐，丈室萧然一物无。","每见招提心即喜，前生真是老浮屠。"]},{"t":"深省轩在丈室之西余为名之","f":"七言绝句","c":["轩槛虚明丈室西，丛筠佳木翠阴垂。","游观物物皆深省，岂在闻钟欲觉时。"]},{"t":"见报以言者论六事其五皆靖康往故其一谓资囊士人上书以冀复用谪居海南震惧之馀斐然有作 其一","f":"七言绝句","c":["力小安能胜万钧，退藏深渺欲全身。","大恩不报有馀责，何必烦言浪指陈。"]},{"t":"见报以言者论六事其五皆靖康往故其一谓资囊士人上书以冀复用谪居海南震惧之馀斐然有作 其二","f":"七言绝句","c":["非才自丏罢钧衡，百念灰寒岂复萌。","刚道资囊上书者，不知谁继颍川生。"]},{"t":"见报以言者论六事其五皆靖康往故其一谓资囊士人上书以冀复用谪居海南震惧之馀斐然有作 其三","f":"七言绝句","c":["尼父乘桴居九夷，管宁浮海亦多时。","古来圣贤犹如此，我泛鲸波岂足悲。"]},{"t":"见报以言者论六事其五皆靖康往故其一谓资囊士人上书以冀复用谪居海南震惧之馀斐然有作 其四","f":"七言绝句","c":["功似赞皇犹远涉，智如鹤相亦来游。","世间万事非人力，只有安心百不忧。"]},{"t":"见报以言者论六事其五皆靖康往故其一谓资囊士人上书以冀复用谪居海南震惧之馀斐然有作 其五","f":"七言绝句","c":["苏子曾为海上仙，群龙三复绝韦编。","我今日对羲文语，却恨公书取次传。"]},{"t":"别夹山能老","f":"七言绝句","c":["相逢千偈口澜翻，已是亲曾到夹山。","猿鸟可能知祖意，飞腾青嶂碧岩间。"]},{"t":"药山三咏 其一 问道室","f":"七言绝句","c":["骨相崭岩心已安，松林谈道不胜寒。","习之不会高人意，便作天云瓶水看。"]},{"t":"药山三咏 其二 伏牛庵","f":"七言绝句","c":["侍者何须召二空，一元调伏自知风。","轩然栋宇翚飞处，何似当年茅竹中。"]},{"t":"药山三咏 其三 雷满池","f":"七言绝句","c":["英雄割据老渔师，习气难忘凿此池。","尚想兴酣高会处，投身下取酒杯时。"]},{"t":"梁山观音寺","f":"七言绝句","c":["大士当年白鹿驯，宝坊千古閟松筠。","风流帝婿膏粱客，也解来为护法神。"]},{"t":"自武陵舟行至德山","f":"五言古诗","c":["舍车泛兰舟，摇荡武陵水。","憩装古丛林，幽胜冠南纪。","当时霹雳手，掣电机在捶。","钤锤今得人，宗旨振颓委。","何须大雄殿，突兀踞巍址。","龙蛇相混杂，衲子聚千指。","齐竽一一吹，真赝见炉锤。","青葱松竹阴，积翠纷可喜。","春风一动摇，萧瑟鸣不已。","却游德岘亭，枉渚抱中沚。","襄阳今何如，风物略如此。","空怀堕泪碑，愧叹羊叔子。","坐令邹湛辈，名字随骥尾。","胡雏窥汉疆，战哭多新鬼。","王室如缀旒，寇盗结蜂蚁。","而我荷宽恩，抱衅适万里。","回头望中原，洒涕湿巾几。","海山渺安在，澒洞鲸波里。","飞仙时往来，当学长不死。"]},{"t":"益阳白鹿寺","f":"七言绝句","c":["寺枕清江荫碧梧，萧然景物类东吴。","登临忽动思归兴，不待秋风可鲙鲈。"]},{"t":"清修寺在益阳数十里间惠远之弟居之世谓之小庐山二首 其一","f":"七言绝句","c":["盘纡石磴白云间，风落岩花满路斑。","峰岭横斜自重掩，个中真是小庐山。"]},{"t":"清修寺在益阳数十里间惠远之弟居之世谓之小庐山二首 其二","f":"七言绝句","c":["傍山修竹翠檀栾，竦节疏枝碧玉寒。","安得诛茅此君侧，世间浑作梦中看。"]},{"t":"自湘乡趋邵阳以避谤不敢取道衡岳有感五首 其一","f":"七言绝句","c":["平生性僻爱溪山，偶得经行秪为閒。","叹息迂程避烦啧，坐令南岳阻跻攀。"]},{"t":"自湘乡趋邵阳以避谤不敢取道衡岳有感五首 其二","f":"七言绝句","c":["石廪巉天堆祝融，遥看山色有无中。","宽恩异日容归老，先到衡阳回雁峰。"]},{"t":"自湘乡趋邵阳以避谤不敢取道衡岳有感五首 其三","f":"七言绝句","c":["恭闻南岳魏夫人，绛节霓旌拥玉轮。","我欲他年受真诀，先从碧海涤埃尘。"]},{"t":"自湘乡趋邵阳以避谤不敢取道衡岳有感五首 其四","f":"七言绝句","c":["邺侯奇谲世难知，放浪衡湘亦避时。","懒瓒不知今在否，无心更与觅蹲鸱。"]},{"t":"自湘乡趋邵阳以避谤不敢取道衡岳有感五首 其五","f":"七言绝句","c":["退之昔谪恶溪滨，精意能开衡岳云。","我匪天穷坐人阨，试从山外望氛氲。"]},{"t":"邵阳道中云岩寺","f":"七言绝句","c":["山空小寺依嵌窦，日暖幽禽转好声。","万个琅玕一茅屋，何当此处寄浮生。"]},{"t":"清湘西山寺无量寿塔","f":"七言绝句","c":["黄花翠竹真如性，大地山河清净身。","欲识今时无量寿，不知瞻礼是何人。"]},{"t":"桂林道中二首 其一","f":"七言律诗","c":["桂林山水久闻风，身世茫然堕此中。","日暮碧云浓作朵，春深稚笋翠成丛。","仙家多住朱明洞，客梦来游群玉峰。","雁荡武夷何足道，千岩元是小玲珑。"]},{"t":"桂林道中二首 其二","f":"七言律诗","c":["时危远谪堕南峦，犹在乾坤覆载间。","瘴雨岚烟殊气候，玉簪罗带巧溪山。","桄榔叶暗伤心碧，踯躅花开满目斑。","惟有月华依旧好，清辉应与照云鬟。"]},{"t":"山月驿闻子规次韵","f":"七言绝句","c":["春枕梦回孤馆悄，世故萦心愁不了。","山深夜闲子规啼，残月满窗天未晓。"]},{"t":"道阳朔山水尤奇绝旧传为天下第一非虚语也赋二绝句 其一","f":"七言绝句","c":["溪山此地蔼佳名，雨洗烟岚分外青。","却恨征鞍太匆遽，无因一上万云亭。"]},{"t":"道阳朔山水尤奇绝旧传为天下第一非虚语也赋二绝句 其二","f":"七言绝句","c":["赋诗曾送谪仙人，垂老翻游到海滨。","梦幻去来何日了，且将病眼看嶙峋。"]},{"t":"献花铺唐相李德裕谪海南道此有山女献花因以名之次壁间韵","f":"七言绝句","c":["我亦乘桴向海涯，无人复献雨中花。","却愁春梦归吴越，茗饮浓斟薄荷芽。"]},{"t":"象州道中二首 其一","f":"七言律诗","c":["路入春山春日长，穿林渡水意徜徉。","溪环石笋横舟小，风落林花扑面香。","山鸟不知兴废恨，岭云自觉去来忙。","炎荒景物随时好，何必深悲瘴疠乡。"]},{"t":"象州道中二首 其二","f":"七言律诗","c":["竹屋茅檐三四家，土风渐觉异中华。","碧榕枝弱还生柱，红荔春深已著花。","社燕不巢南候别，塞鸿无信北音赊。","海山此去犹千里，会见安期枣似瓜。"]},{"t":"饮修仁茶","f":"七言律诗","c":["北苑龙团久不尝，修仁茗饮亦甘芳。","誇研斗白工夫拙，辟瘴消烦气味长。","江表露芽空绝品，蜀中仙掌可同行。","从容饭罢何为者，一椀还兼一炷香。"]},{"t":"自去冬不雨至今道傍井竭田多不耕有感","f":"七言律诗","c":["匝地风雷空震荡，终宵云雨竟虚无。","媮閒农具田皆废，暍死行人井半枯。","东海愆阳缘孝妇，桑林谒祷本谗夫。","忠魂昭雪奸邪逐，坐见为霖万物苏。"]},{"t":"次贵州二首 其一","f":"七言律诗","c":["青枫夹道鹧鸪啼，古郡荒凉接岛夷。","陆绩故城依石巘，葛洪遗灶俯江湄。","光风苒苒吹香草，烟雨濛濛湿荔枝。","欲作终焉卜居计，自应痀偻不吾欺。"]},{"t":"次贵州二首 其二","f":"七言律诗","c":["怀泽为邦古郁林，江边邑屋树森森。","山连八桂峰峦秀，地近重溟雾雨淫。","岁久承平消瘴疠，时危争战觉幽深。","试谋十亩膏腴地，丹荔青蕉获我心。"]},{"t":"伏读三月六日内禅诏书及传将士榜檄慨王室之艰危悯生灵之涂炭悼前策之不从恨奸回之误国感愤有作聊以述怀四首 其一","f":"七言律诗","c":["忆昔廷诤驻跸时，孤忠欲挽六龙飞。","莱公谩有亲征策，亚父空求骸骨归。","灵武中兴形势便，江都巡幸士心违。","累臣独荷三朝眷，瘴海徒将血涕挥。"]},{"t":"伏读三月六日内禅诏书及传将士榜檄慨王室之艰危悯生灵之涂炭悼前策之不从恨奸回之误国感愤有作聊以述怀四首 其二","f":"七言律诗","c":["胡骑长驱扰汉疆，庙堂高枕失提防。","关河自昔称天府，淮海于今作战场。","退避固知非得计，威灵何以镇殊方。","中原夷狄相衰盛，圣哲从来只自彊。"]},{"t":"伏读三月六日内禅诏书及传将士榜檄慨王室之艰危悯生灵之涂炭悼前策之不从恨奸回之误国感愤有作聊以述怀四首 其三","f":"七言律诗","c":["叹息奸臣术已疏，谋身误国竟何如。","马嵬不进杨钊死，关陜初临元振除。","王室威灵嗟索寞，苍生环堵未安居。","荒陬不见中原事，望断东吴一纸书。"]},{"t":"伏读三月六日内禅诏书及传将士榜檄慨王室之艰危悯生灵之涂炭悼前策之不从恨奸回之误国感愤有作聊以述怀四首 其四","f":"七言律诗","c":["建炎虚席待经纶，恩赐宸章宝墨新。","学际天人何敢尔，忠开金石庶当仁。","孔明得主规模壮，陆贽离朝谤讟频。","今日追思惭至意，御书重执泪盈巾。"]},{"t":"暮春雨中有感二首 其一","f":"七言绝句","c":["雨细梅黄荔子丹，殊方风物异江山。","客愁望极伤心处，更听钩辀云木间。"]},{"t":"暮春雨中有感二首 其二","f":"七言绝句","c":["万物焦枯谁作霖，片云成雨慰民心。","奸邪逐去精忠雪，天意方知感格深。"]},{"t":"含笑花五首 其一","f":"七言绝句","c":["一去闽山远玉颜，故人相遇有馀欢。","临风莞尔缘何事，应笑先生又失官。"]},{"t":"含笑花五首 其二","f":"七言绝句","c":["玉质犹披翡翠裳，温泉浴罢蔼天香。","回眸百媚嫣然处，羞死三千红粉妆。"]},{"t":"含笑花五首 其三","f":"七言绝句","c":["窜逐流离老病身，天涯相见意相亲。","粲然不用干金买，应记当年作赋人。"]},{"t":"含笑花五首 其四","f":"七言绝句","c":["素淡丰容不自持，养成妙质亦多时。","不知巧倩东风里，含蓄清香欲待谁。"]},{"t":"含笑花五首 其五","f":"七言绝句","c":["谓之曾诘笑何因，只笑明时窜海滨。","晋以志穷莱以直，定兼我拙作三人。"]},{"t":"荔枝五首 其一","f":"七言绝句","c":["海山仙子绛罗襦，雾縠中单白玉肤。","知我远来相劳苦，故驰先使迓中途。"]},{"t":"荔枝五首 其二","f":"七言绝句","c":["绛纱囊里水晶丸，偏得杨妃带笑看。","休道马嵬当日事，只今何处是长安。"]},{"t":"荔枝五首 其三","f":"七言绝句","c":["玉人纤指擘轻红，犹忆恩颁自汉宫。","翠笼藤盘异当日，蛮烟瘴雨正濛濛。"]},{"t":"荔枝五首 其四","f":"七言绝句","c":["荔子蛮方也自丹，不如闽岭为微酸。","玉盘磊珂三千颗，犹忆甘芳绕齿寒。"]},{"t":"荔枝五首 其五","f":"七言绝句","c":["百马崩腾耆旧悲，只今戈戟暗江湄。","自知疏拙蒙恩重，犹得南来食荔枝。"]},{"t":"茉莉花二首 其一","f":"七言绝句","c":["泠艳幽芳雪不如，佳名初见贝多书。","南人浑作寻常看，曾侍君王白玉除。"]},{"t":"茉莉花二首 其二","f":"七言绝句","c":["风露扶疏蔓翠藤，玉花剪刻见层层。","清香夜久偏闻处，寂寞书生对一灯。"]},{"t":"得梁溪书寄诸弟二首 其一","f":"七言绝句","c":["一纸书来抵万金，天涯慰我念家心。","只今王室犹如此，回首东吴涕作霖。"]},{"t":"得梁溪书寄诸弟二首 其二","f":"七言绝句","c":["荔子初丹色半青，玉肤未满已芳馨。","欲题书后三千颗，须待烟林灿若星。"]},{"t":"即事三首 其一","f":"七言绝句","c":["宾江两岸木绵飞，负郭家家熟荔枝。","瘴雨蛮烟已萧瑟，可堪梅子欲黄时。"]},{"t":"即事三首 其二","f":"七言绝句","c":["荔枝红紫已交加，龙眼新来又著花。","便欲谋居不须去，咀冰嚼雪过年华。"]},{"t":"即事三首 其三","f":"七言绝句","c":["森森榕木碧参天，夏日初闻第一蝉。","美荫羡君诚得计，何须悽怨嘒风前。"]},{"t":"移居南山寺寺有岩洞甚幽并葛稚川丹灶","f":"七言律诗","c":["倚山高阁仰觚棱，洞穴嵌空屐可登。","丹灶旧传留袐药，仙岩今已属閒僧。","数峰削玉青如髻，群木参天翠作层。","小驻未妨幽兴发，野禽嘲弄醉瞢腾。"]},{"t":"伏睹四月五日赦书銮舆反正中外大庆小臣有感斐然成章二首 其一","f":"七言律诗","c":["天眷吾皇筑旧基，未应炎德遂中微。","共欣宸极还天步，赖有群龙夹日飞。","霈泽及民寰海庆，孤忠许国寸心违。","建炎首被钧衡选，孤负明恩泪湿衣。"]},{"t":"伏睹四月五日赦书銮舆反正中外大庆小臣有感斐然成章二首 其二","f":"七言律诗","c":["误国奸邪已窜诛，天扶黼座正宸居。","少康一旅时犹在，高祖三章术未疏。","必顺人心收俊杰，自应天意助耘锄。","累臣海上空回首，愿浥沧溟洗谤书。"]},{"t":"端午日次郁林州","f":"七言律诗","c":["久谪沅湘习楚风，灵均千载此心同。","岂知角黍萦丝日，却堕蛮烟瘴雨中。","榕树间关鹦鹉语，藤盘磊珂荔枝红。","殊方令节多悽感，家在东吴东复东。"]},{"t":"恭闻诏书褒悼陈少阳赠官与一子恩泽赐缗钱五十万感涕四首 其一","f":"七言律诗","c":["哀痛纶言洒帝章，赐金赠秩事非常。","无心圣主如天地，著意奸臣极虎狼。","忠血他年应化碧，英魂今日已生光。","先生愤懑诚昭雪，九死南迁岂自伤。"]},{"t":"恭闻诏书褒悼陈少阳赠官与一子恩泽赐缗钱五十万感涕四首 其二","f":"七言律诗","c":["祖宗德泽在斯民，韦带精忠不乏人。","魏阙献言开帝听，匦函争事触龙鳞。","血沾斧越虽因我，心在宗祊岂计身。","宿草已深难一恸，临风空有涕沾巾。"]},{"t":"恭闻诏书褒悼陈少阳赠官与一子恩泽赐缗钱五十万感涕四首 其三","f":"七言律诗","c":["屡将鲠议叩枫宸，不为承恩始爱君。","谁使崔宁论卢杞，恨无庆忌救朱云。","死生一吷心应了，忠义千年笔有芬。","一介草茅言世务，从今不复数刘蕡。"]},{"t":"恭闻诏书褒悼陈少阳赠官与一子恩泽赐缗钱五十万感涕四首 其四","f":"七言律诗","c":["平昔初无半面交，危言几辨盖宽饶。","幽冥我已惭良友，忠愤君应念本朝。","故国遥看云杳杳，新阡何处草萧萧。","抚孤未遂山涛志，谁继骚人赋大招。"]},{"t":"寓郁林著易传有感 其一","f":"七言律诗","c":["谪来海峤远兵戈，精义微言得切瑳。","地入郁林怀陆绩，桴浮沧海学东坡。","圣经广大随人取，众说纷纶奈若何。","从此梁溪作诗少，用心已向六龙多。"]},{"t":"寓郁林著易传有感 其二","f":"七言律诗","c":["羲文作易仲尼传，究极阴阳本自然。","妙理欲求须得象，至言已契可忘筌。","绝编何啻须三过，知命从今加数年。","叹息时无邵康节，数该今古与谁研。"]},{"t":"次雷州","f":"七言律诗","c":["华夷图上看雷州，万里孤城据海陬。","萍迹飘流遽如许，骚辞拟赋畔牢愁。","沧溟浩荡烟云晓，鼓角凄悲风露秋。","莫笑炎荒地遐僻，万安更在海南头。"]},{"t":"中秋月色佳甚与宗之对酌天宁寺宝华堂","f":"七言律诗","c":["去年今夕寓通城，犹有新诗寄弟兄。","一自裹囊来海上，更无系帛付鸿征。","禅房酌酒夜方阒，海月窥人光更清。","起舞月中心尚壮，乘槎便欲造蓬瀛。"]},{"t":"所寓天宁方丈后有阇提花数株连月盛开玉雪可爱怅然有怀成三绝句寄吴元中 其一","f":"七言绝句","c":["未渡鲸波寇盗深，中原回首涕成霖。","清愁万斛无消处，赖有幽花慰客心。"]},{"t":"所寓天宁方丈后有阇提花数株连月盛开玉雪可爱怅然有怀成三绝句寄吴元中 其二","f":"七言绝句","c":["深院无人帘幕垂，玉英翠羽灿芳枝。","世间颜色难相似，晴雪初残未堕时。"]},{"t":"所寓天宁方丈后有阇提花数株连月盛开玉雪可爱怅然有怀成三绝句寄吴元中 其三","f":"七言绝句","c":["冰玉风姿照坐寒，炎荒相遇且相宽。","缟衣纻带平生志，正念幽人尚素冠。"]},{"t":"得家书报长子仪之房下得孙男殊慰老怀时在雷州著易传适至震卦因名之曰震孙以诗寄仪之","f":"七言古诗","c":["天涯远报茁琼枝，共说鹓雏骨相奇。","鼻祖从来种桃李，耳孙自合产兰芝。","荐雷名震因观易，他日趋庭使学诗。","无复区区如尔父，定须了了胜吾儿。","书来可想开怀抱，老去何因与弄持。","素有庞翁携隐志，未应孤负鹿门期。"]},{"t":"九日与宗之对酌怀梁溪诸季时菊花犹未结蕊于药果中得茱萸泛酒有馈山果海鲜者多素所不识赋诗见意二首 其一","f":"七言律诗","c":["此身飘泊旅天涯，九日悽然客念家。","且把红醪尝紫蟹，何须白发对黄花。","药囊赖有茱萸实，茶铫频烦薄荷芽。","山果海鲜多不识，却须传与北人誇。"]},{"t":"九日与宗之对酌怀梁溪诸季时菊花犹未结蕊于药果中得茱萸泛酒有馈山果海鲜者多素所不识赋诗见意二首 其二","f":"七言律诗","c":["父子相随万里馀，途穷端欲哭杨朱。","三年客里逢佳节，九日樽前念友于。","海上及秋吟蟋蟀，鬓边何日插茱萸。","吾生老矣谋身拙，叹息乾坤一腐儒。"]},{"t":"峤南僧罕遵戒律况向上事独琮师隐居湖岩绝不至城市超然拔俗闻余来策杖见过与语可人知为饱参衲子也询其所见盖尝从长芦了游了居长芦聚徒至千五百众道价籍甚江淮间余虽不之识然声气相合心期自亲尝辱贻问今见琮益知了之门风孤峻真楷老儿孙也退处天台琮将浮海访之因赋诗赠琮且简了公异时得归决须相随于石桥侧可以握手一笑梁溪居士云","f":"七言古诗","c":["万里谪官来海峤，眼中衲子见绝少。","方袍圆顶动成群，与俗不同秪其表。","琮师乃是雷阳人，遍历丛林参学饱。","归来卜筑瘴海滨，十里湖光岩洞小。","深居不复踏城市，宴坐惟知侣猿鸟。","惠然过我意良勤，野鹤孤云自轻矫。","风姿已含蔬笋气，语论更将藤葛绕。","黄茅深处见松筠，使我囷箱欲倾倒。","为亲聊复恋幽栖，访旧终须乘漭渺。","烦师飞锡过天台，为问了公何法了。"]},{"t":"冬至","f":"七言律诗","c":["殊方又复一阳芽，荏苒流年叹物华。","土薄葭灰难测候，气温桃树已开花。","云鸿不到音书断，鲸海无程道里赊。","赖有清心为活计，不须烂醉作生涯。"]},{"t":"海南黎人作过据临皋县惊劫傍近因小留海康十一月望闻官军破贼二十日戒行戏作两绝句 其一","f":"七言绝句","c":["海上群黎亦弄兵，征车数月旅山城。","稽留谪命兢惶甚，正坐绯巾惩沸羹。"]},{"t":"海南黎人作过据临皋县惊劫傍近因小留海康十一月望闻官军破贼二十日戒行戏作两绝句 其二","f":"七言绝句","c":["沈沈碧海绝津涯，一叶凌波亦快哉。","假使黑风漂荡去，不妨乘兴访蓬莱。"]},{"t":"次地角场以疮疡不果谒伏波庙俾宗之摄祭期以二十五日渡海一卜即吉夜半乘潮解桴星月灿然风便波平诘旦已达琼管东坡谓斯游奇绝冠平生非虚语也作二诗纪之 其一","f":"七言律诗","c":["威信昭然汉两公，旧于青史揖英风。","戈船下濑勋猷壮，马革裹尸心胆雄。","顾我迂疏成远谪，赖神正直鉴孤忠。","病躯阻造祠庭下，幽显虽殊此意同。"]},{"t":"次地角场以疮疡不果谒伏波庙俾宗之摄祭期以二十五日渡海一卜即吉夜半乘潮解桴星月灿然风便波平诘旦已达琼管东坡谓斯游奇绝冠平生非虚语也作二诗纪之 其二","f":"七言律诗","c":["夜半乘潮云海中，伏波肯借一帆风。","满天星月光铓碎，匝海波涛气象雄。","大舶凭陵真漭渺，寸心感格在精忠。","老坡去后何人继，奇绝斯游只我同。"]},{"t":"次东坡韵二首 其一","f":"七言律诗","c":["地角潮来未五更，阴云解駮作霜晴。","星河明润天容睟，风浪喧豗海气清。","粗见鲲鹏潜化理，岂无犬马恋轩声。","远游不作乘桴计，虚号男儿过此生。"]},{"t":"次东坡韵二首 其二","f":"七言律诗","c":["海上传呼夜报更，舟师欢喜得新晴。","风帆擘浪去时急，海月笼云分外清。","天影合中观妙色，潮波回处悟圆声。","从来渤海为全体，试问一沤何处生。"]},{"t":"南渡次琼管江山风物与海北不殊民居皆在槟榔木间黎人出市交易蛮衣椎髻语音兜离不可晓也因询万安相去犹五百里僻陋尤甚黄茅中草屋二百馀家资生之具一切无有道由生黎峒山往往剽劫行者必自文昌县泛海得便风三日可达艰难至此不胜慨然赋诗二首纪土风志怀抱也 其一","f":"五言古诗","c":["巨舶浮于海，长飙送短篷。","夜潮和月白，晓日跳波红。","云影摇脩浪，澜光接远空。","喜过三合流，愁远冠头峰。","雷化迷天际，琼儋入望中。","地遥横一线，山露点群鸿。","偶脱鲸鲵患，尤欣气俗同。","川原惊老眼，稚耋看衰翁。","蛮市虾鱼合，宾居栋宇雄。","人烟未寥落，竹树自葱茏。","碧暗槟榔叶，香移薄荷丛。","金花翔孔翠，綵幕问黎童。","南极冬犹暖，中原信不通。","管宁虽迹远，阮籍已途穷。","澒洞沧波里，苍茫返照东。","客愁浑不寝，鼓角五更风。"]},{"t":"南渡次琼管江山风物与海北不殊民居皆在槟榔木间黎人出市交易蛮衣椎髻语音兜离不可晓也因询万安相去犹五百里僻陋尤甚黄茅中草屋二百馀家资生之具一切无有道由生黎峒山往往剽劫行者必自文昌县泛海得便风三日可达艰难至此不胜慨然赋诗二首纪土风志怀抱也 其二","f":"五言古诗","c":["四郡环黎母，穷愁最万安。","峒氓能悯寇，泷吏岂欺韩。","草屋丛篁里，孤城瘴海端。","民居才百数，道里尚艰难。","径陆忧生蜑，乘桴畏怒澜。","飓风能破胆，疠气必摧肝。","去死垂垂近，资生物物殚。","舶来方得米，牢罄或无餐。","树芋充嘉馔，螷蠃荐浅盘。","蒌藤茶更苦，淡水酒仍酸。","黎户花缦服，儒生椰子冠。","槟榔资一醉，吉贝不知寒。","何必从詹尹，无因咏考槃。","失图嗟罪大，得此荷恩宽。","顾影同三友，谈空不二观。","中州杳何在，犹共月团栾。"]},{"t":"槟榔","f":"五言古诗","c":["疏林苍海上，结实已累累。","烟湿赪虬卵，风摇翠羽旗。","飞翔金鸑鷟，掩映箨龙儿。","濩落咍椰子，匀圆讶荔支。","当茶锁瘴速，如酒醉人迟。","蒌叶偏相称，蠃灰亦谩为。","乍餐颜愧渥，频嚼齿愁疲。","饮啄随风土，端忧化岛夷。"]},{"t":"次琼管后三日忽奉德音恩许自便感涕之馀赋诗见志 其一","f":"七言律诗","c":["此身飘堕到沧溟，谁谓君王念贾生。","黄纸再蒙题姓字，丹书特为削刑名。","山林老去何其幸，萍梗追思却自惊。","天地恩宽难报德，试从今日数归程。"]},{"t":"次琼管后三日忽奉德音恩许自便感涕之馀赋诗见志 其二","f":"词","c":["行年旧说似东坡，鲸海于今亦再过。","儋耳三年时已久，琼山十日幸尤多。","却收老眼来观国，尚冀中原早戢戈。","病废不堪当世用，感恩惟有涕霶?。"]},{"t":"郡城南曰琼台北曰语海余易之曰云海登眺有感 其一","f":"七言绝句","c":["孤城南面敞琼台，千里川原指顾开。","试向绿云深处望，海山浮动见蓬莱。"]},{"t":"郡城南曰琼台北曰语海余易之曰云海登眺有感 其二","f":"七言绝句","c":["古来云海浩茫茫，北望悽然欲断肠。","不得中州近消息，六龙何处驻东皇。"]},{"t":"北归昼渡海风便波平尤觉奇绝成五绝句 其一","f":"七言绝句","c":["澄波不动琉璃滑，一望应须万里馀。","舟行冲激浪花碎，如驭白云游碧虚。"]},{"t":"北归昼渡海风便波平尤觉奇绝成五绝句 其二","f":"七言绝句","c":["去得南风来北风，神灵只在指呼中。","老坡有语旧曾记，信我人阨非天穷。"]},{"t":"北归昼渡海风便波平尤觉奇绝成五绝句 其三","f":"七言绝句","c":["来时风浪夜喧惊，归去潮波枕席平。","非是波神有分别，故教清昼看寰瀛。"]},{"t":"北归昼渡海风便波平尤觉奇绝成五绝句 其四","f":"七言绝句","c":["纤云肆卷日方中，海色天光上下同。","身在琉璃光合里，碧空涵水水涵空。"]},{"t":"北归昼渡海风便波平尤觉奇绝成五绝句 其五","f":"七言绝句","c":["平生奔走畏江湖，暮齿来乘海上桴。","自哂井蛙真见小，望洋向若一卢胡。"]},{"t":"归次海康登平仙亭次莱公韵","f":"五言绝句","c":["碧海瞰危亭，波光混大清。","旷怀知乐此，夷险本来平。"]},{"t":"归次海康登平仙亭次莱公韵 雷庙读丁晋公所作碑","f":"七言绝句","c":["巨卵曾因霹雳开，海邦从此得名雷。","只知寇老曾迁此，作记何缘丁令来。"]},{"t":"谒寇忠悯祠堂六首 其一","f":"七言绝句","c":["亲征决策幸澶渊，南北欢盟有本原。","丞相莱公功第一，犹将孤注作谗言。"]},{"t":"谒寇忠悯祠堂六首 其二","f":"七言绝句","c":["一幸江南一蜀中，奋然廷议叱群公。","搀回天步虽良策，元是真皇听纳功。"]},{"t":"谒寇忠悯祠堂六首 其三","f":"七言绝句","c":["南阳庙坐致云云，赖有嘉言为解纷。","叹息今人不如古，久无庆忌救朱云。"]},{"t":"谒寇忠悯祠堂六首 其四","f":"七言绝句","c":["平生爱看柘枝舞，宾燕多馀密炬堆。","富贵在公真末事，谁云缘此故南来。"]},{"t":"谒寇忠悯祠堂六首 其五","f":"七言绝句","c":["海邦去海只十里，山路过山应万重。","诗谶告人元已久，未应马援坐梁松。"]},{"t":"谒寇忠悯祠堂六首 其六","f":"七言绝句","c":["凿井得泉今尚美，挂钱插竹后成林。","精忠感动无情物，不解潜销谗妒心。"]},{"t":"初发雷阳有感二首 其一","f":"七言律诗","c":["梦中曾过鬼门关，敢冀君恩听北还。","父子相随幸良厚，仆奴半死涕空潸。","风烟萧瑟黄茅瘴，山路崎岖赤脚蛮。","归去梁溪见桑梓，定抛冠佩老岩间。"]},{"t":"初发雷阳有感二首 其二","f":"七言律诗","c":["馀生幸尔脱垂涎，鸡肋安能拒老拳。","万里得归辞瘴海，三年奔命厌征轩。","采薇散发嵇中散，开灶烧丹葛稚川。","此去山林如脱兔，这回且结好因缘。"]},{"t":"琮师送至城月驿戏成两绝句以答其意 其一","f":"七言绝句","c":["衲子来参去不辞，何劳飞锡远相追。","赠师银布牢收取，便是金襕付嘱时。"]},{"t":"琮师送至城月驿戏成两绝句以答其意 其二","f":"七言绝句","c":["好住湖岩摄此心，有缘终会有知音。","梁溪老去孤峰顶，月白风清难更寻。"]},{"t":"立春日龙化道中得家问诸季已挈家渡浙江如剑川又闻江西颇有群盗啸聚遂决意由五羊趋循惠潮阳假道闽中以归偶成三篇时十二月十九日 其一","f":"七言律诗","c":["东君又换一年春，迎我来从瘴海滨。","已觉山川有佳气，更询道路得通津。","欲寻勾漏丹砂令，与访罗浮紫府人。","清梦相符缘契合，便须脱屣谢埃尘。"]},{"t":"立春日龙化道中得家问诸季已挈家渡浙江如剑川又闻江西颇有群盗啸聚遂决意由五羊趋循惠潮阳假道闽中以归偶成三篇时十二月十九日 其二","f":"七言律诗","c":["远信来时岭峤春，浮家已在浙江滨。","更传赣水方虞寇，须向闽山与问津。","万里归来寻乐土，千岩好去作閒人。","干戈未息中原暗，怅望关河胡马尘。"]},{"t":"立春日龙化道中得家问诸季已挈家渡浙江如剑川又闻江西颇有群盗啸聚遂决意由五羊趋循惠潮阳假道闽中以归偶成三篇时十二月十九日 其三","f":"七言律诗","c":["川途奔走四回春，海上经年与死滨。","子美自怜常作客，长沮应笑是知津。","艰危至死无千古，忧患如吾岂两人。","往返循环真磨蚁，已将大地等微尘。"]},{"t":"久不饮酒春日得家问喜甚与宗之对酌调马驿中速饮数觥径醉醉中和东坡醉题四首 其一","f":"五言律诗","c":["海峤无佳酿，经时不入唇。","巨觥今一醉，远问到初春。","偶脱长鲸口，来寻仲子邻。","醉中轻万里，始信浊醪神。"]},{"t":"久不饮酒春日得家问喜甚与宗之对酌调马驿中速饮数觥径醉醉中和东坡醉题四首 其二","f":"五言律诗","c":["畏病不举杯，延客秖烹茗。","浩然云海间，不醉亦不醒。","偶蒙雨露恩，渐脱瘴疠境。","曲生粗可人，相对聊酩酊。"]},{"t":"久不饮酒春日得家问喜甚与宗之对酌调马驿中速饮数觥径醉醉中和东坡醉题四首 其三","f":"五言律诗","c":["久客殊念家，归途渺江汉。","是身如浮云，罹此无穷患。","今夕定何夕，一酌千忧散。","从兹日曛酣，此意君莫间。"]},{"t":"久不饮酒春日得家问喜甚与宗之对酌调马驿中速饮数觥径醉醉中和东坡醉题四首 其四","f":"五言律诗","c":["饮少辄大醉，醉中识其真。","天地一秋毫，况此渺然身。","归休岩穴间，坐阅万态新。","去去勿复道，时清为幸民。"]},{"t":"寓琼山远华馆一夕梦游山间小堂松竹环合有道士坐堂上诵李太白送人游桃源序中有良田名池竹果森然三十六洞别为一天之语觉而异之今假道容惠当游勾漏都峤白石罗浮皆洞天也岂神者先告将有所遇耶赋诗以纪之","f":"五言古诗","c":["神清遂仙游，境寂恣遐躅。","羽人入我梦，轩户霭松竹。","高吟谪仙文，逸韵响金玉。","觉来残灯荧，倘恍犹在目。","归途历容惠，问津非素卜。","将游四洞天，就彼白云宿。","岂无葛稚川，妙论资灌沃。","试求龙虎丹，一使鬓毛绿。","斯言傥可珍，长揖谢浮俗。","却笑昌黎翁，强项宁诘曲。"]},{"t":"海上得孔雀六鹦鹉十馀携归遗童稚辈戏成二绝句 其一","f":"七言绝句","c":["凤友鸾朋出海邦，金花翠尾烂文章。","梁溪台绍今何似，归伴胎仙取次翔。"]},{"t":"海上得孔雀六鹦鹉十馀携归遗童稚辈戏成二绝句 其二","f":"七言绝句","c":["绿衣绀趾已能飞，学语交交末转时。","不是蓬莱花鸟使，携归聊与调群儿。"]},{"t":"立春后一日风雨殊有寒色偶成","f":"五言律诗","c":["竟夕北风号，春回雨已膏。","归程离海峤，旧服理绨袍。","宿瘴须寒压，清愁欲醉逃。","何当入江浙，雪片洒鹅毛。"]},{"t":"容南道中二首 其一","f":"五言律诗","c":["路入容南境，风烟自一方。","山空云苒苒，春动水茫茫。","紫府丹砂秘，幽村碧树芳。","肃然有佳致，作个是炎荒。"]},{"t":"容南道中二首 其二","f":"五言律诗","c":["闻说容南久，安知客路经。","沉沉洞天近，湛湛古湫渟。","日落峰峦翠，春回草木青。","丹砂如可问，当卜老岩扃。"]},{"t":"再赋孔雀鹦鹉二首 其一","f":"七言律诗","c":["孔雀来从海上村，参差脩尾灿金文。","素知肃穆鸾凰侣，不是喧卑鸡鹜群。","玄圃赤霄虽有志，碧梧翠竹正须君。","携持万里归吴越，怅望海山深处云。"]},{"t":"再赋孔雀鹦鹉二首 其二","f":"七言律诗","c":["学语鹦雏羽渐成，掌中取食绝猜惊。","笼宽得遂朋从志，春晓初闻客到声。","赋就襧衡文不点，杓随李白饮如鲸。","远携休叹殊方去，我亦随缘得此生。"]},{"t":"陆川道中偶成","f":"七言律诗","c":["峤南江北本来同，往返纷纷一梦中。","旧事销磨那复有，新愁缭绕亦成空。","天边山色浮浓翠，溪上云光拂淡红。","我把浮生如梦看，云山元是小屏风。"]},{"t":"南迁道郁林郡守王君示古律诗一篇北归辄成两篇以答其意 其一","f":"七言律诗","c":["山围古郡碧周遭，陆绩衣冠雅自褒。","海上来归怀麈尾，鬓间空叹长霜毛。","易书顾我耽成癖，诗笔怜君老更豪。","此去龙城幸非远，不须巨石压云涛。"]},{"t":"南迁道郁林郡守王君示古律诗一篇北归辄成两篇以答其意 其二","f":"七言律诗","c":["垂老相逢海峤间，盈编珠玉破愁颜。","清名岂籍郁林石，雅志常存仙奕山。","丘壑采薇嗟我病，弦歌为政羡君閒。","中原杳杳旌旗暗，回首春风涕一潸。"]},{"t":"过北流县八里游勾漏观留五绝句 其一","f":"七言绝句","c":["百里仙山气象雄，参差峰岫翠成丛。","云骈鹤驭今何处，丹灶依然洞穴中。"]},{"t":"过北流县八里游勾漏观留五绝句 其二","f":"七言绝句","c":["葛翁求令为丹砂，今我来从海上槎。","秪恐山灵嫌俗驾，未容归客卧烟霞。"]},{"t":"过北流县八里游勾漏观留五绝句 其三","f":"七言绝句","c":["羽人相导把霓旌，窈窕松林露气清。","不用逢迎同贵客，暂来花院听棋声。"]},{"t":"过北流县八里游勾漏观留五绝句 其四","f":"七言绝句","c":["避谤多时不到山，忽惊身在洞天间。","北归更觉君恩重，得遂清游一解颜。"]},{"t":"过北流县八里游勾漏观留五绝句 其五","f":"七言绝句","c":["洞户沉沉别有天，玉楼珠殿锁霏烟。","如何祠馆人间世，破屋荒凉紫府前。"]},{"t":"道勾漏山灵宝观窃睹两朝御书谨成古风","f":"五言古诗","c":["抱疴卧云海，夙夕负深恐。","宽恩听旋归，何啻丘岳重。","问津勾漏山，散策宝圭洞。","群峰罗翠屏，环合无缺空。","游仙契初心，幽赏恊清梦。","却来观宸章，宝气腾螮蝀。","真行杂草隶，笔势极翔动。","大小飞白书，飘洒萦舞凤。","恭惟睿智姿，多能本天纵。","妙迹藏名山，俾与万世共。","林峦增炳焕，神物劳护拥。","惜无深岩屋，荫覆示崇奉。","何当鸠良材，为葺倾压栋。","天弧不指狼，中原胡马閧。","九庙未奠居，臣子衔愤痛。","岂知炎荒中，奎画得瞻讽。","至哉慱大言，粟麦因异种。","天常及诸佛，一一资妙供。","窃于翰藻间，窥见神心用。","源流此中来，基本中兴宋。","稽首归琅函，斐然成善颂。"]},{"t":"元结尝经略容管王守作次山堂以思其人为赋此诗","f":"七言律诗","c":["华堂高敞为思元，善政相望数百年。","册府声名秀群玉，海邦岩洞有参天。","漫郎去久风流在，病客来临道里邅。","圣主中兴谁作颂，愿观老手笔如椽。"]},{"t":"客有言长沙军变向伯恭能弹治规画甚伟适得伯恭书亦道其事作韵语以寄之","f":"七言古诗","c":["长沙舞袖仅可旋，今作巨镇湖湘边。","骄兵夜探赤白丸，乘间窃发将啸翾。","不知向子有老拳，缚束健卒秖数言。","翩如鸟雀擒鹰鹯，奸腰凶领污龙泉。","弹压一境敢复喧，稚耋鼓舞喜欲颠。","归哺其饴甘晏眠，众服壮略称无前。","我归自南得之传，颇欣祖生先着鞭。","何不付与大将权，旌旗缤纷指云燕。","一鼓士气如突烟，黠虏破胆心少悛。","洒扫海内清戈鋋，使我衰病安庐田。"]},{"t":"萧懋德秀才自临江遣人致书海上遇于归途赋诗寄之二首 其一","f":"七言律诗","c":["三黜先生今得归，更携稚子访慈帏。","病牛卧垄心衰矣，脱兔投林天悯之。","万里往来环转蚁，一生谤誉舌扬箕。","著书欲赴当时约，须待江南事定时。"]},{"t":"萧懋德秀才自临江遣人致书海上遇于归途赋诗寄之二首 其二","f":"七言律诗","c":["踰年海上久安居，多谢萧郎远寄书。","不向去来生一念，已将天地作吾庐。","中洲杳杳旌旗暗，暮景骎骎齿发疏。","准拟峡江成小隐，茅斋借我定何如。"]},{"t":"罪谪海上中州亲故罕通问独虞君祖道相从湖海踰年北归同途次容南赋诗识别","f":"七言律诗","c":["饱经忧患莫如吾，暮景馀生寄一桴。","独子相从来瘴海，岂知还得共归途。","应观天下奇男子，解笑人间浅丈夫。","老去山林养衰疾，好音时与系飞凫。"]},{"t":"除夜与宗之对酌怀家","f":"七言律诗","c":["四年除夕旅殊方，海上归来路更长。","暮景飞腾催老病，馀生留滞且炎荒。","传闻寇盗纷惊扰，叹息江湖堕渺茫。","杳杳东吴家万里，椒盘谁与颂馨香。"]}]};